INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Acurioustractor/act-global-infrastructure/dev', 'dev', 'Acurioustractor', 'act-global-infrastructure', 'community', 'dev Acurioustractor act-global-infrastructure community The dev skill enables developers to start the full local development stack with optional tunnel for webhook testing, streamlining their workflow. It benefits developers working with the ACT Ecosystem mono-repo. dev Skill 是 ACT 生态系统的本地开发解决方案，提供快速命令和工作流程 dev Skill は ACT エコシステムのローカル開発ソリューションであり、クイックコマンドとワークフローを提供する dev Skill은 ACT 에코システム의 로컬 개발 솔루션으로 빠른 명령어와 워크플ロー 제공 El comando dev es una herramienta para configurar y ejecutar el ecosistema ACT de manera local, incluyendo servidor de desarrollo y pruebas de webhook. La commande dev est un outil pour configurer et exécuter l''écosystème ACT de manière locale, y compris le serveur de développement et les tests de webhook. Der dev-Befehl ist ein Tool zum Konfigurieren und Ausführen des ACT-Ökosystems auf lokaler Ebene, einschließlich Entwicklungsserver und Webhook-Tests. O dev é um skill que permite iniciar o desenvolvimento local com comando rápido e webhook de teste. Inclui recursos como start, stop e logs. Dev — это навык, который позволяет начать локальное развитие с быстрыми командами и вебхуком для тестирования ИИ Агентов. Включает функции start, stop и logs. Dev هو مهارة تمكن من بدء التطوير المحلي بأوامر سريعة واختبار الويب هوك للأدوات الذكية. يتضمن ميزات مثل التشغيل والايقاف والسجلات. how to use dev dev setup guide dev alternative dev vs docker dev install what is dev dev workflow optimization dev local development dev webhook testing dev Skill ACT 生态系统 本地开发 webhook 测试 cloudflared tunnel cron 脚本 dev 服务器 API Starts dev servers (dashboard + API) using `/dev` or `/dev start` command Supports starting everything (servers + cron scripts) with `/dev all` command Enables cloudflared tunnel for webhook testing with `/dev tunnel` command Provides status check with `/dev status` command Allows stopping all services with `/dev stop` command Offers log tailing with `/dev logs` command dev is a local development skill for the ACT Ecosystem mono-repo, providing commands for starting dev servers, cron scripts, and infrastructure.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('bsamiee/Parametric_Portal/perplexity-tools', 'community', 'bsamiee', 'Parametric_Portal', 'bsamiee/Parametric_Portal', 'perplexity-tools', 0, 0, 42, '2026-03-08T01:57:15.414Z', '2026-03-08T02:07:09.755Z', '7d61686983e9ccc890a2ed9df882f902512e2ad0869d63abf7eb06c209e78532', '{"id":"bsamiee/Parametric_Portal/perplexity-tools","name":"perplexity-tools","description":{"en":"perplexity-tools enables developers to execute Perplexity AI queries via Python CLI, utilizing specialized models for optimized response quality. It benefits developers and AI agents seeking efficient AI query execution.","zh":"Perplexity-Tools 是一款通过 Python CLI 执行 Perplexity AI 查询的工具，支持 Sonar 家族模型和自动注入的 API 密钥","ja":"Perplexity-Tools は、Python CLI を使用して Perplexity AI クエリを実行するツールです。Sonar ファミリーモデルや自動インジェクション API キーをサポートしています","ko":"Perplexity-Tools는 Python CLI를 통해 Perplexity AI 쿼리를 실행하는 도구입니다. Sonar 가족 모델과 자동 주입 API 키를 지원합니다","es":"Perplexity-tools es una herramienta que permite ejecutar consultas de IA de Perplexity mediante la CLI de Python, con modelos de la familia Sonar para una respuesta de alta calidad","fr":"Perplexity-tools est un outil qui permet d''exécuter des requêtes IA Perplexity via la CLI Python, avec des modèles de la famille Sonar pour une réponse de haute qualité","de":"Perplexity-tools ist ein Tool, das die Ausführung von Perplexity-AI-Abfragen über die Python-CLI ermöglicht, mit Modellen der Sonar-Familie für eine hochwertige Antwort","pt":"O Perplexity-Tools é uma ferramenta de IA que executa consultas via CLI Python com chave de API auto-injetada","ru":"Perplexity-Tools - это инструмент ИИ, который выполняет запросы через Python CLI с автоматической инъекцией ключа API","ar":"أدوات Perplexity هي أداة ذكاء اصطناعي تقوم بتشغيل استفسارات عبر واجهة سطر الأوامر Python مع مفتاح API المُقدم تلقائيًا"},"seo":{"title":{"en":"perp