INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('bsamiee/Parametric_Portal/perplexity-tools', 'perplexity-tools', 'bsamiee', 'Parametric_Portal', 'community', 'perplexity-tools bsamiee Parametric_Portal community perplexity-tools enables developers to execute Perplexity AI queries via Python CLI, utilizing specialized models for optimized response quality. It benefits developers and AI agents seeking efficient AI query execution. Perplexity-Tools 是一款通过 Python CLI 执行 Perplexity AI 查询的工具，支持 Sonar 家族模型和自动注入的 API 密钥 Perplexity-Tools は、Python CLI を使用して Perplexity AI クエリを実行するツールです。Sonar ファミリーモデルや自動インジェクション API キーをサポートしています Perplexity-Tools는 Python CLI를 통해 Perplexity AI 쿼리를 실행하는 도구입니다. Sonar 가족 모델과 자동 주입 API 키를 지원합니다 Perplexity-tools es una herramienta que permite ejecutar consultas de IA de Perplexity mediante la CLI de Python, con modelos de la familia Sonar para una respuesta de alta calidad Perplexity-tools est un outil qui permet d''exécuter des requêtes IA Perplexity via la CLI Python, avec des modèles de la famille Sonar pour une réponse de haute qualité Perplexity-tools ist ein Tool, das die Ausführung von Perplexity-AI-Abfragen über die Python-CLI ermöglicht, mit Modellen der Sonar-Familie für eine hochwertige Antwort O Perplexity-Tools é uma ferramenta de IA que executa consultas via CLI Python com chave de API auto-injetada Perplexity-Tools - это инструмент ИИ, который выполняет запросы через Python CLI с автоматической инъекцией ключа API أدوات Perplexity هي أداة ذكاء اصطناعي تقوم بتشغيل استفسارات عبر واجهة سطر الأوامر Python مع مفتاح API المُقدم تلقائيًا how to use perplexity-tools perplexity-tools setup guide perplexity-tools alternative perplexity-tools vs sonar perplexity-tools install what is perplexity-tools perplexity-tools python cli sonar family models perplexity ai queries Perplexity-Tools AI 工具 Sonar 家族模型 Python CLI 自动注入 API 密钥 citation tokens 深度检索 实时推理 Execute Perplexity AI queries via Python CLI Supports Sonar family models, including sonar, sonar-pro, sonar-reasoning, sonar-reasoning-pro, and sonar-deep-research API key auto-injection via 1Password Utilizes specialized models for optimized response quality Citation tokens no longer billed for sonar and sonar-pro models perplexity-tools is a specialized AI query execution tool that utilizes Python CLI and auto-injects API keys via 1Password, supporting various Sonar family models.');
