INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('salmanrrana/brain-dump/brain-dump-workflow', 'brain-dump-workflow', 'salmanrrana', 'brain-dump', 'community', 'brain-dump-workflow salmanrrana brain-dump community The brain-dump-workflow skill provides a provider-agnostic universal quality workflow designed for AI-assisted development, benefiting developers with its consolidated MCP tools and mandatory 5-step sequence. brain-dump-workflow 是一个提供者无关的通用质量工作流，设计用于 AI 辅助开发 brain-dump-workflow は、AI エージェント開発のためのプロバイダーやごとに設計されたユニバーサル品質ワークフローです brain-dump-workflow는 AI 에이전트 개발을 위한 공급자와 무관한 유니버설 품질 워크플로우입니다 El brain-dump-workflow es un flujo de trabajo de calidad universal diseñado para el desarrollo asistido por AI, con 9 herramientas de MCP consolidadas Le brain-dump-workflow est un flux de travail universel de qualité conçu pour le développement d''applications d''IA, avec 9 outils MCP consolidés Der brain-dump-workflow ist ein universeller Qualitäts-Workflow, der für die Entwicklung von AI-Anwendungen mit 9 konsolidierten MCP-Tools konzipiert wurde O brain-dump-workflow é uma solução de qualidade universal para desenvolvimento de software com AI. Ele fornece uma sequência de 5 etapas obrigatórias para garantir a qualidade do código. Brain-dump-workflow - это универсальное решение для обеспечения качества программного обеспечения, разработанного с помощью ИИ Агентов. Оно включает в себя 5-этапную последовательность для garantir качества кода. brain-dump-workflow هو حل جودة عالمي لتطوير البرمجيات باستخدام أدوات الذكاء الاصطناعي. يوفر متوالية خماسية إلزامية لضمان جودة الكود how to use brain-dump-workflow brain-dump-workflow setup guide what is brain-dump-workflow brain-dump-workflow alternative brain-dump-workflow vs competitor brain-dump-workflow install MCP tools tutorial AI-assisted development workflow universal quality workflow AI 工具开发流程 brain-dump-workflow AI 辅助开发 MCP 工具集成 提供者无关的通用质量工作流 5 步必备序列 开发效率提高 开发质量提高 Provides a 5-step sequence using MCP tools Consolidates 9 tools with action-dispatched parameters Requires passing ''action'' as the first parameter to specify operations Utilizes the workflow tool with ''a'' as the starting point Includes a system prompt with the full workflow References the canonical source in src/api/ralph.ts brain-dump-workflow is a universal quality workflow designed from the ground up with and for AI-assisted development, featuring a canonical source in src/api/ralph.ts');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Ender-Wiggin2019/elo/tfm-add-card', 'community', 'Ender-Wiggin2019', 'elo', 'Ender-Wiggin2019/elo', 'tfm-add-card', 0, 0, 42, '2026-03-08T01:57:15.416Z', '2026-03-08T02:07:14.821Z', '6818a8e57e333f2405f47d71220c16f90e523dba5d5c5d3eadd966344f149a42', '{"id":"Ender-Wiggin2019/elo/tfm-add-card","name":"tfm-add-card","description":{"en":"The tfm-add-card skill enables developers to add new cards to TFM by following a 4-step workflow. It benefits AI agent developers working with TFM.","zh":"tfm-add-card 是一个用于添加新卡片到 TFM 的技能，需要注册卡名、实现卡片、注册清单和编写单元测试","ja":"tfm-add-card は、TFM に新しいカードを追加するためのスキルです。カード名の登録、カードの実装、清単の登録、単体テストの作成が必要です","ko":"tfm-add-card는 TFM에 새로운 카드를 추가하는 데 사용되는 스킬로, 카드 이름 등록, 카드 구현, 매니페스트 등록, 유닛 테스트 작성이 필요합니다","es":"tfm-add-card es una habilidad para agregar tarjetas a TFM, siguiendo 4 pasos específicos","fr":"tfm-add-card est une compétence pour ajouter des cartes à TFM, suivant 4 étapes spécifiques","de":"tfm-add-card ist eine Fähigkeit, um Karten zu TFM hinzuzufügen, indem 4 spezifische Schritte befolgt werden","pt":"O tfm-add-card é uma habilidade que permite adicionar novos cartões ao TFM. Ele requer 4 etapas de implementação.","ru":"tfm-add-card - это навык, который позволяет добавлять новые карточки в TFM. Он требует 4 этапов реализации в ИИ Агентах.","ar":"tfm-add-card هو مهارة يسمح بإضافة بطاقات جديدة إلى TFM. يتطلب 4 مراحل من التنفيذ في أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"tfm-add-card: Step-by-Step Card Addition Guide | AI Agent...","zh":"TFM 添加卡片设置指南 - tfm-add-card","ja":"TFM カード追加セットアップガイド - tfm-add-card","ko":"TFM 카드 추가 설정 가이드 - tfm-add-card","es":"tfm-add-card: Guía de configuración para agregar tarjetas","fr":"tfm-add-card: Guide d''installation pour ajouter des cartes","de":"tfm-add-card: Einrichtungsanleitung für die Hinzufügung v...","pt":"tfm-add-card: Guia de Configuração de Cartões","ru":"tfm-add-card: Настройка Карточек в ИИ Агентах","ar":"tfm-add-card: إعداد بطاقات في أدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to add new cards to TFM with tfm-add-card. Get started with our easy-to-follow workflow and implement cards in 4 simple steps.","zh":"了解如何使用 tfm-add-card 添加新卡片到 TFM，包括注册卡名、实现卡片、注册清单和编写单元测试","ja":"TFM に新しいカードを追加する方法について学びます。カード名の登録、カードの実装、清単の登録、単体テストの作成など","ko":"TFM에 새로운 카드를 추가하는 방법에 대해 알아보세요. 카드 이름 등록, 카드 구현, 매니페스트 등록, 유닛 테스트 작성 등","es":"Aprende a agregar tarjetas a TFM con tfm-add-card, incluyendo registro de nombres y tipos de tarjetas","fr":"Découvrez comment ajouter des cartes à TFM avec tfm-add-card, y compris l''enregistrement des noms et des types de cartes","de":"Erfahren Sie, wie Sie Karten zu TFM mit tfm-add-card hinzufügen, einschließlich der Registrierung von Kartennamen und -typen","pt":"Aprenda a adicionar novos cartões ao TFM com o tfm-add-card. Siga os 4 passos para implementar cartões personalizados.","ru":"Добавьте новые карточки в TFM с помощью tfm-add-card. Следуйте 4 шагам для реализации пользовательских карточек в ИИ Агентах.","ar":"تعلم كيفية إضافة بطاقات جديدة إلى TFM باستخدام tfm-add-card. اتبع 4 خطوات لتنفيذ بطاقات مخصصة في أدوات الذكاء الاصطناعي"},"definition":{"en":"tfm-add-card is a skill that allows developers to add new cards to TFM by registering the card name, implementing the card, registering in manifest, and writing unit tests.","zh":"tfm-add-card 是一个用于添加新卡片到 TFM 的 AI 工具","ja":"tfm-add-card は、TFM に新しいカードを追加するための AI エージェントです","ko":"tfm-add-card는 TFM에 새로운 카드를 추가하는 데 사용되는 AI 에이전트입니다","es":"tfm-add-card es una habilidad para agregar tarjetas a TFM mediante la implementación de 4 pasos","fr":"tfm-add-card est une compétence pour ajouter des cartes à TFM via la mise en œuvre de 4 étapes","de":"tfm-add-card ist eine Fähigkeit, um Karten zu TFM hinzuzufügen, indem 4 Schritte umgesetzt werden","pt":"tfm-add-card é uma habilidade de código aberto que adiciona cartões personalizados ao TFM.","ru":"tfm-add-card - это открытый навык, который добавляет пользовательские карточки в TFM в ИИ Агентах.","ar":"tfm-add-card هو مهارة مفتوحة المصدر التي تضيف بطاقات مخصصة إلى TFM في أدوات الذكاء الاصطناعي"},"features":{"en":["Registers card names in src/common/cards/CardName.ts","Implements cards in src/server/cards/commission/<CardName>.ts","Registers cards in src/server/cards/commission/CommissionCardManifest.ts","Writes unit tests in tests/cards/commission/<CardName>.spec.ts","Supports CorporationCard and IProjectCard types","Requires confirmation of card name, display name, and card type"],"zh":["注册卡名在 src/common/cards/CardName.ts","实现卡片在 src/server/cards/commission/<CardName>.ts","注册清单在 src/server/cards/commission/CommissionCardManifest.ts","编写单元测试在 tests/cards/commission/<CardName>.spec.ts"],"ja":["src/common/cards/CardName.ts にカード名を登録","src/server/cards/commission/<CardName>.ts にカードを実装","src/server/cards/commission/CommissionCardManifest.ts に清単を登録","tests/cards/commission/<CardName>.spec.ts に単体テストを作成"],"ko":["src/common/cards/CardName.ts에 카드 이름 등록","src/server/cards/commission/<CardName>.ts에 카드 구현","src/server/cards/commission/CommissionCardManifest.ts에 매니페스트 등록","tests/cards/commission/<CardName>.spec.ts에 유닛 테스트 작성"],"es":["Registro de nombres de tarjetas en src/common/cards/CardName.ts","Implementación de tarjetas en src/server/cards/commission/<CardName>.ts","Registro en el manifiesto en src/server/cards/commission/CommissionCardManifest.ts","Escritura de pruebas unitarias en tests/cards/commission/<CardName>.spec.ts"],"fr":["Enregistrement des noms de cartes dans src/common/cards/CardName.ts","Mise en œuvre des cartes dans src/server/cards/commission/<CardName>.ts","Enregistrement dans le manifeste dans src/server/cards/commission/CommissionCardManifest.ts","Rédaction de tests unitaires dans tests/cards/commission/<CardName>.spec.ts"],"de":["Registrierung von Kartennamen in src/common/cards/CardName.ts","Implementierung von Karten in src/server/cards/commission/<CardName>.ts","Registrierung im Manifest in src/server/cards/commission/CommissionCardManifest.ts","Erstellung von Einheitstests in tests/cards/commission/<CardName>.spec.ts"],"pt":["Registro do nome do cartão em src/common/cards/CardName.ts","Implementação do cartão em src/server/cards/commission/<CardName>.ts","Registro no manifesto em src/server/cards/commission/CommissionCardManifest.ts","Escrita de testes unitários em tests/cards/commission/<CardName>.spec.ts"],"ru":["Регистрация имени карточки в src/common/cards/CardName.ts","Реализация карточки в src/server/cards/commission/<CardName>.ts","Регистрация в манифесте в src/server/cards/commission/CommissionCardManifest.ts","Написание юнит-тестов в tests/cards/commission/<CardName>.spec.ts"],"ar":["تسجيل اسم البطاقة في src/common/cards/CardName.ts","تنفيذ البطاقة في src/server/cards/commission/<CardName>.ts","التسجيل في الملف التأسيسي في src/server/cards/commission/CommissionCardManifest.ts","كتابة اختبارات الوحدة في tests/cards/commission/<CardName>.spec.ts"]},"keywords":{"en":["how to use tfm-add-card","tfm-add-card setup guide","tfm-add-card alternative","tfm-add-card vs TFM card implementation","what is tfm-add-card","tfm-add-card install","adding cards to TFM","TFM card development","tfm-add-card documentation"],"zh":["TFM 添加卡片","tfm-add-card","AI 工具","添加新卡片","注册卡名","实现卡片","注册清单","编写单元测试"],"ja":["TFM カード追加","tfm-add-card","AI エージェント","新しいカードを追加","カード名の登録","カードの実装","清単の登録","単体テストの作成"],"ko":["TFM 카드 추가","tfm-add-card","AI 에이전트","새로운 카드를 추가","카드 이름 등록","카드 구현","매니페스트 등록","유닛 테스트 작성"],"es":["tfm-add-card","agregar tarjetas a TFM","registro de tarjetas","implementación de tarjetas","pruebas unitarias para tarjetas","herramientas de desarrollo para TFM","agentes de inteligencia artificial para desarrollo"],"fr":["tfm-add-card","ajouter des cartes à TFM","enregistrement de cartes","mise en œuvre de cartes","tests unitaires pour cartes","outils de développement pour TFM","agents d''intelligence artificielle pour le développement"],"de":["tfm-add-card","Karten zu TFM hinzufügen","Registrierung von Karten","Implementierung von Karten","Einheitstests für Karten","Entwicklungstools für TFM","Künstliche Intelligenz-Tools für Entwicklung"],"pt":["tfm-add-card","adicionar cartões ao TFM","cartões personalizados","implementação de cartões","registro de cartões","testes unitários para cartões"],"ru":["tfm-add-card","добавление карточек в TFM","пользовательские карточки","реализация карточек","регистрация карточек","юнит-тесты для карточек в ИИ Агентах"],"ar":["tfm-add-card","إضافة بطاقات إلى TFM","بطاقات مخصصة","تنفيذ بطاقات","تسجيل بطاقات","اختبارات الوحدة للبطاقات في أدوات الذكاء الاصطناعي"]}},"owner":"Ender-Wiggin2019","repo":"elo","repoPath":"Ender-Wiggin2019/elo","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.416Z","topics":[],"category":"community","skillMd":{"name":"tfm-add-card","description":"Guide for adding a new card to the TFM (Terraforming Mars) project. Use when the user wants to create, add, or implement a new card — including project cards (IProjectCard), corporation cards (CorporationCard), or any card type. Covers CardName registration, card implementation, manifest registration, and the CardRenderer DSL.","bodyPreview":"# Add a New Card to TFM\n\n## Workflow\n\nAdding a card requires exactly 4 steps:\n\n1. **Register the card name** in `src/common/cards/CardName.ts`\n2. **Implement the card** in `src/server/cards/commission/<CardName>.ts`\n3. **Register in manifest** in `src/server/cards/commission/CommissionCardManifest.ts`\n4. **Write unit tests** in `tests/cards/commission/<CardName>.spec.ts`\n\nBefore implementing, confirm with the user:\n- Card name and display name\n- Card type: `CorporationCard` or `IProjectCard` (an","body":"# Add a New Card to TFM\n\n## Workflow\n\nAdding a card requires exactly 4 steps:\n\n1. **Register the card name** in `src/common/cards/CardName.ts`\n2. **Implement the card** in `src/server/cards/commission/<CardName>.ts`\n3. **Register in manifest** in `src/server/cards/commission/CommissionCardManifest.ts`\n4. **Write unit tests** in `tests/cards/commission/<CardName>.spec.ts`\n\nBefore implementing, confirm with the user:\n- Card name and display name\n- Card type: `CorporationCard` or `IProjectCard` (and sub-type: `ACTIVE`, `AUTOMATED`, `EVENT`. Somethings User may ask for \"蓝卡\", \"绿卡\", which means: Blue -> Active, Green -> Automated, Red -> Event)\n- Tags, cost, requirements, victory points\n- Card effect/ability (exact mechanics and numerical values)\n- Card number (XB series)\n\nIf any detail is unclear or ambiguous, **ask the user to clarify before proceeding**.\n\n## Step 1: Register Card Name\n\nAdd an entry to the `CardName` enum in `src/common/cards/CardName.ts`.\n\nCommission cards use `🌸` prefix/suffix in the display string. Find the commission card section (near line 626+) and append:\n\n```typescript\n// In the commission cards section of CardName enum:\nMY_NEW_CARD = ''🌸My New Card🌸'',\n```\n\nNaming conventions:\n- Enum key: `UPPER_SNAKE_CASE`\n- Value: `''🌸Display Name🌸''` (Chinese names are also acceptable, e.g. `''🌸城电转能🌸''`)\n\n## Step 2: Implement the Card\n\nCreate a new file in `src/server/cards/commission/`. File name uses **UpperCamelCase** (e.g. `MyNewCard.ts`).\n\n### Determine Card Type\n\nRead the card details to determine which base class to use:\n\n| Type | Base Class | Implements | When to Use |\n|---|---|---|---|\n| Corporation | `CorporationCard` | `ICorporationCard` | Cards with `startingMegaCredits`, corp-level effects |\n| Active Corp | `ActiveCorporationCard` | `ICorporationCard` + `IActionCard` | Corp cards with per-turn `action()` |\n| Project (Active) | `Card` | `IProjectCard` | Blue cards with ongoing effects or actions |\n| Project (Automated) | `Card` | `IProjectCard` | Green cards with one-time effects |\n| Project (Event) | `Card` | `IProjectCard` | Red cards with one-time effects |\n| Project w/ Action | `ActionCard` | `IProjectCard` + has `action` behavior | Blue cards with data-driven action |\n\n### Template: Corporation Card\n\n```typescript\nimport {Tag} from ''../../../common/cards/Tag'';\nimport {IPlayer} from ''../../IPlayer'';\nimport {CardName} from ''../../../common/cards/CardName'';\nimport {CardRenderer} from ''../render/CardRenderer'';\nimport {CorporationCard} from ''../corporation/CorporationCard'';\n\nexport class MyCorpCard extends CorporationCard {\n  constructor() {\n    super({\n      name: CardName.MY_CORP_CARD,\n      tags: [Tag.SCIENCE],\n      startingMegaCredits: 50,\n      // Optional: initialActionText for first action description\n      // initialActionText: ''Draw 1 card with a science tag'',\n\n      metadata: {\n        cardNumber: ''XB??'',\n        description: ''You start with 50 M€.'',\n        renderData: CardRenderer.builder((b) => {\n          b.megacredits(50);\n          b.corpBox(''effect'', (ce) => {\n            ce.effect(''description of effect'', (eb) => {\n              eb.cards(1).startEffect.megacredits(1);\n            });\n          });\n        }),\n      },\n    });\n  }\n\n  // Override for first-action corps\n  // public override initialAction(player: IPlayer) { ... }\n\n  // For effects triggered when any player plays a card:\n  // public onCardPlayedByAnyPlayer(owner: IPlayer, card: ICard, currentPlayer: IPlayer) { ... }\n\n  // For effects triggered when this corp''s owner plays a card:\n  // public onCardPlayedForCorps(player: IPlayer, card: ICard) { ... }\n}\n```\n\n### Template: Project Card (IProjectCard)\n\n```typescript\nimport {CardName} from ''../../../common/cards/CardName'';\nimport {CardType} from ''../../../common/cards/CardType'';\nimport {Tag} from ''../../../common/cards/Tag'';\nimport {CardRenderer} from ''../render/CardRenderer'';\nimport {Card} from ''../Card'';\nimport {IProjectCard} from ''../IProjectCard'';\n\nexport class MyProjectCard extends Card implements IProjectCard {\n  constructor() {\n    super({\n      name: CardName.MY_PROJECT_CARD,\n      type: CardType.ACTIVE,       // or AUTOMATED, EVENT\n      tags: [Tag.BUILDING],\n      cost: 15,\n      // victoryPoints: 1,          // static VP\n      // requirements: {tag: Tag.SCIENCE, count: 2},  // requirements\n\n      // For simple effects, use behavior instead of bespokePlay:\n      // behavior: {\n      //   production: {energy: 1},\n      //   stock: {megacredits: 3},\n      //   global: {temperature: 1},\n      //   drawCard: 1,\n      // },\n\n      metadata: {\n        cardNumber: ''XB??'',\n        // description: ''Requires 2 science tags. ...'',\n        renderData: CardRenderer.builder((b) => {\n          b.effect(''When you play a building tag, gain 2 M€.'', (eb) => {\n            eb.tag(Tag.BUILDING).startEffect.megacredits(2);\n          });\n        }),\n      },\n    });\n  }\n\n  // --- Callback methods (choose what applies) ---\n\n  // For ACTIVE cards with a player action:\n  // public canAct(player: IPlayer): boolean { return true; }\n  // public action(player: IPlayer) { return undefined; }\n\n  // For triggered effects when this card''s owner plays a card:\n  // public onCardPlayed(player: IPlayer, card: IProjectCard) { ... }\n\n  // For triggered effects when any tile is placed:\n  // public onTilePlaced(cardOwner: IPlayer, activePlayer: IPlayer, space: Space) { ... }\n\n  // For card cost discounts:\n  // public override getCardDiscount(player: IPlayer, card: ICard): number { return 0; }\n\n  // For custom VP calculation:\n  // public override getVictoryPoints(player: IPlayer): number { return 0; }\n}\n```\n\n### Common Patterns Reference\n\nSee `references/card-patterns.md` for detailed examples of common card patterns including:\n- Cards with `behavior` (declarative effects)\n- Cards with `onCardPlayed` / `onCardPlayedByAnyPlayer` callbacks\n- Cards with `onTilePlaced` callbacks\n- Cards with `canAct()` / `action()` (blue card actions)\n- Cards with `getCardDiscount()`\n- Cards with requirements\n- Corporation cards with `initialAction` and `corpBox`\n\n## Step 3: Register in Manifest\n\nEdit `src/server/cards/commission/CommissionCardManifest.ts`:\n\n1. Add import at top:\n```typescript\nimport {MyNewCard} from ''./MyNewCard'';\n```\n\n2. Add entry in the appropriate section of `COMMISSION_CARD_MANIFEST`:\n\nFor corporation cards:\n```typescript\ncorporationCards: {\n  // ... existing entries\n  [CardName.MY_NEW_CARD]: {Factory: MyNewCard}, // XB??\n},\n```\n\nFor project cards:\n```typescript\nprojectCards: {\n  // ... existing entries\n  [CardName.MY_NEW_CARD]: {Factory: MyNewCard}, // XB??\n},\n```\n\nOptional: add `compatibility` for expansion-dependent cards:\n```typescript\n[CardName.MY_NEW_CARD]: {Factory: MyNewCard, compatibility: ''turmoil''},\n```\n\n## Step 4: Write Unit Tests\n\nCreate a test file at `tests/cards/commission/<CardName>.spec.ts`.\n\n### Test Command\n\nRun tests for a single card:\n```bash\nnpx ts-mocha -p tests/tsconfig.json --reporter-option maxDiffSize=256 -r tests/testing/setup.ts tests/cards/commission/<CardName>.spec.ts\n```\n\nRun all commission card tests:\n```bash\nnpx ts-mocha -p tests/tsconfig.json --reporter-option maxDiffSize=256 -r tests/testing/setup.ts ''tests/cards/commission/**/*.spec.ts''\n```\n\n### Test Template\n\n```typescript\nimport {expect} from ''chai'';\nimport {MyCard} from ''../../../src/server/cards/commission/MyCard'';\nimport {testGame} from ''../../TestGame'';\nimport {TestPlayer} from ''../../TestPlayer'';\nimport {runAllActions, cast} from ''../../TestingUtils'';\nimport {IGame} from ''../../../src/server/IGame'';\nimport {Tag} from ''../../../src/common/cards/Tag'';\nimport {CardType} from ''../../../src/common/cards/CardType'';\nimport {Resource} from ''../../../src/common/Resource'';\n\ndescribe(''MyCard'', () => {\n  let card: MyCard;\n  let player: TestPlayer;\n  let game: IGame;\n\n  beforeEach(() => {\n    card = new MyCard();\n    [game, player] = testGame(2, {skipInitialShuffling: true});\n    player.megaCredits = 100;\n  });\n\n  it(''basic properties'', () => {\n    expect(card.cost).to.eq(15);\n    expect(card.type).to.eq(CardType.ACTIVE);\n    expect(card.tags).to.deep.eq([Tag.BUILDING]);\n  });\n\n  it(''should apply initial behavior on play'', () => {\n    player.playCard(card);\n    runAllActions(game);\n    // Assert production, stock, or other changes\n  });\n\n  // Add more tests for each card effect/ability\n});\n```\n\n### Testing Tips\n\n- Use `testGame(n, {skipInitialShuffling: true})` for deterministic setup\n- Use `runAllActions(game)` after play/actions to resolve deferred actions\n- Use `cast(input, OrOptions)` to type-check player input responses\n- Use `player.popWaitingFor()` to get pending player input\n- When setting `card.resourceCount` manually, do so **after** `runAllActions(game)` to avoid other card triggers (e.g. Decomposers) interfering\n- **Known engine limitation**: `play()` fires **before** the card is added to `playedCards`, so `onProductionGain` / other tableau callbacks won''t self-trigger during initial play (the \"including this\" pattern)\n- For corporation card tests, use `player.playCorporationCard(card)` instead of `player.playCard(card)`\n- For testing `canAct()` / `action()`, manually set up the required state (resources, cards, etc.) then call the methods directly\n\n## Key Imports Quick Reference\n\n```typescript\n// Common imports for card implementation\nimport {CardName} from ''../../../common/cards/CardName'';\nimport {CardType} from ''../../../common/cards/CardType'';\nimport {Tag} from ''../../../common/cards/Tag'';\nimport {Resource} from ''../../../common/Resource'';\nimport {CardResource} from ''../../../common/CardResource'';\nimport {CardRenderer} from ''../render/CardRenderer'';\nimport {Size} from ''../../../common/cards/render/Size'';\nimport {AltSecondaryTag} from ''../../../common/cards/render/AltSecondaryTag'';\nimport {Card} from ''../Card'';\nimport {IProjectCard} from ''../IProjectCard'';\nimport {ICard} from ''../ICard'';\nimport {IPlayer} from ''../../IPlayer'';\nimport {CorporationCard} from ''../corporation/CorporationCard'';\nimport {Board} from ''../../boards/Board'';\nimport {Space} from ''../../boards/Space'';\n```\n\n## CardRenderer DSL Quick Reference\n\n**Resources:** `megacredits(n)`, `steel(n)`, `titanium(n)`, `plants(n)`, `energy(n)`, `heat(n)`, `cards(n)`, `tr(n)`\n\n**Global params:** `temperature(n)`, `oxygen(n)`, `oceans(n)`, `venus(n)`\n\n**Tiles:** `city()`, `greenery()`, `emptyTile()`, `specialTile()`\n\n**Tags:** `tag(Tag.XXX)`, `wild(n)`, `noTags()`\n\n**Production:** `production((pb) => { pb.energy(1); })`\n\n**Layout:** `.br` (line break), `.nbsp`, `vSpace(size?)`, `text(str)`, `vpText(str)`\n\n**Effect box:** `effect(desc, (eb) => { eb.cause.startEffect.result })`\n\n**Action box:** `action(desc, (eb) => { eb.cost.startAction.result })`\n\n**Corp box:** `corpBox(''effect''|''action'', (ce) => { ce.effect(...) })`\n\n**Options:** `{all: true}` any player, `{secondaryTag: Tag.XXX}`, `{size: Size.SMALL}`\n"},"lastSynced":"2026-03-08T02:07:14.821Z","agentAnalysis":{"suitability":{"en":"Perfect for TFM Developers needing streamlined card addition workflows with TypeScript and unit testing","zh":"适合需要使用TypeScript和单元测试简化卡片添加工作流的TFM开发人员","ja":"TypeScriptとユニットテストを使用してカード追加ワークフローを簡素化する必要があるTFM開発者に最適","ko":"TypeScript와 단위 테스트를 사용하여 카드 추가 워크플ロー 단순화가 필요한 TFM 개발자에게 적합","es":"Perfecto para desarrolladores de TFM que necesitan flujos de trabajo de adición de tarjetas simplificados con TypeScript y pruebas unitarias","fr":"Parfait pour les développeurs TFM ayant besoin de flux de travail d''ajout de cartes simplifiés avec TypeScript et des tests unitaires","de":"Perfekt für TFM-Entwickler, die vereinfachte Arbeitsabläufe für die Hinzufügung von Karten mit TypeScript und Einheitstests benötigen","pt":"Perfeito para desenvolvedores TFM que precisam de fluxos de trabalho de adição de cartões otimizados com TypeScript e teste unitário","ru":"Идеально подходит для разработчиков TFM, которым требуются оптимизированные рабочие процессы добавления карт с помощью TypeScript и модульного тестирования","ar":"مثالي لمطوري TFM الذين يحتاجون إلى عمليات工作简يرة لإضافة بطاقات مع TypeScript واختبار الوحدة"},"recommendation":{"en":"Empowers agents to extend TFM functionality by registering new card names in CardName.ts, implementing cards in CommissionCardManifest.ts, and writing unit tests in .spec.ts files, leveraging TypeScript for robust card development and integration","zh":"赋予代理人通过在CardName.ts中注册新卡名、在CommissionCardManifest.ts中实现卡片以及在.spec.ts文件中编写单元测试来扩展TFM功能的能力，利用TypeScript进行强大的卡片开发和集成","ja":"CardName.tsで新しいカード名を登録し、CommissionCardManifest.tsでカードを実装し、.spec.tsファイルでユニットテストを書くことでTFMの機能を拡張するためのエージェントをエンパワーメントし、TypeScriptを使用した堅牢なカード開発と統合","ko":"CardName.ts에서 새로운 카드 이름을 등록하고, CommissionCardManifest.ts에서 카드를 구현하고, .spec.ts 파일에서 단위 테스트를 작성하여 TFM 기능을 확장하는 에이전트를 강화하며, TypeScript를 사용한 강력한 카드 개발 및 통합","es":"Habilita a los agentes a ampliar la funcionalidad de TFM registrando nuevos nombres de tarjetas en CardName.ts, implementando tarjetas en CommissionCardManifest.ts y escribiendo pruebas unitarias en archivos .spec.ts, aprovechando TypeScript para un desarrollo e integración de tarjetas robustos","fr":"Permet aux agents d''étendre la fonctionnalité de TFM en enregistrant de nouveaux noms de cartes dans CardName.ts, en implémentant des cartes dans CommissionCardManifest.ts et en rédigeant des tests unitaires dans des fichiers .spec.ts, en tirant parti de TypeScript pour un développement et une intégration de cartes robustes","de":"Ermächtigt Agenten, die Funktionalität von TFM zu erweitern, indem sie neue Kartennamen in CardName.ts registrieren, Karten in CommissionCardManifest.ts implementieren und Einheitstests in .spec.ts-Dateien schreiben, wobei TypeScript für eine robuste Kartenerweiterung und -integration genutzt wird","pt":"Habilita agentes a estender a funcionalidade do TFM registrando novos nomes de cartas em CardName.ts, implementando cartas em CommissionCardManifest.ts e escrevendo testes unitários em arquivos .spec.ts, aproveitando o TypeScript para desenvolvimento e integração de cartas robustas","ru":"Наделяет агентов возможностью расширить функциональность TFM, регистрируя новые имена карт в CardName.ts, реализуя карты в CommissionCardManifest.ts и пишущие модульные тесты в файлах .spec.ts, используя TypeScript для прочного развития и интеграции карт","ar":"يمكن एजنتات من توسيع وظائف TFM عن طريق تسجيل أسماء بطاقات جديدة في CardName.ts، وتنفيذ بطاقات في CommissionCardManifest.ts، وكتابة اختبارات الوحدة في ملفات .spec.ts، واستخدام TypeScript لتطوير بطاقات قوية وتكاملها"},"useCases":{"en":["Registering new card types like CorporationCard or IProjectCard","Implementing custom card logic in src/server/cards/commission/","Writing unit tests for commission cards in tests/cards/commission/"],"zh":["注册新类型的卡片，如CorporationCard或IProjectCard","在src/server/cards/commission/中实现自定义卡片逻辑","在tests/cards/commission/中为委托卡片编写单元测试"],"ja":["CorporationCardやIProjectCardのような新しいカードタイプを登録する","src/server/cards/commission/でカスタムカードロジックを実装する","tests/cards/commission/で委託カードのユニットテストを記述する"],"ko":["CorporationCard 또는 IProjectCard와 같은 새로운 카드 유형을 등록","src/server/cards/commission/에서 사용자 지정 카드 논리를 구현","tests/cards/commission/에서 위임 카드에 대한 단위 테스트를 작성"],"es":["Registrar nuevos tipos de tarjetas como CorporationCard o IProjectCard","Implementar lógica de tarjetas personalizadas en src/server/cards/commission/","Escribir pruebas unitarias para tarjetas de comisión en tests/cards/commission/"],"fr":["Enregistrer de nouveaux types de cartes comme CorporationCard ou IProjectCard","Implémenter une logique de cartes personnalisée dans src/server/cards/commission/","Rédiger des tests unitaires pour les cartes de commission dans tests/cards/commission/"],"de":["Registrieren neuer Kartentypen wie CorporationCard oder IProjectCard","Implementieren von benutzerdefinierter Kartiklogik in src/server/cards/commission/","Schreiben von Einheitstests für Kommissionskarten in tests/cards/commission/"],"pt":["Registro de novos tipos de cartas, como CorporationCard ou IProjectCard","Implementação de lógica personalizada de cartas em src/server/cards/commission/","Escrita de testes unitários para cartas de comissão em tests/cards/commission/"],"ru":["Регистрация новых типов карт, таких как CorporationCard или IProjectCard","Реализация пользовательской логики карт в src/server/cards/commission/","Написание модульных тестов для карт комиссии в tests/cards/commission/"],"ar":["تسجيل أنواع جديدة من البطاقات، مثل CorporationCard أو IProjectCard","تنفيذ منطق مخصص للبطاقات في src/server/cards/commission/","كتابة اختبارات الوحدة للبطاقات اللجنة في tests/cards/commission/"]},"limitations":{"en":["Requires access to TFM source code","Must follow 4-step workflow for card addition","Limited to TFM environment with specific file structure"],"zh":["需要访问TFM源代码","必须遵循4步骤的卡片添加工作流","仅限TFM环境，具有特定的文件结构"],"ja":["TFMのソースコードへのアクセスが必要","4ステップのカード追加ワークフローに従う必要がある","TFM環境に限定され、特定のファイル構造を持つ"],"ko":["TFM 소스 코드에 대한 액세스가 필요","4단계 카드 추가 워크플로를 따라야 함","TFM 환경으로 제한되며 특정 파일 구조를 가짐"],"es":["Requiere acceso al código fuente de TFM","Debe seguir un flujo de trabajo de 4 pasos para la adición de tarjetas","Limitado al entorno de TFM con una estructura de archivo específica"],"fr":["Nécessite un accès au code source de TFM","Doit suivre un flux de travail de 4 étapes pour l''ajout de cartes","Limité à l''environnement de TFM avec une structure de fichier spécifique"],"de":["Erfordert Zugriff auf den TFM-Quellcode","Muss einem 4-Schritte-Arbeitsablauf für die Kartenhinzufügung folgen","Begrenzt auf die TFM-Umgebung mit einer bestimmten Dateistruktur"],"pt":["Requer acesso ao código fonte do TFM","Deve seguir o fluxo de trabalho de 4 etapas para adição de cartas","Limitado ao ambiente TFM com estrutura de arquivo específica"],"ru":["Требуется доступ к исходному коду TFM","Должно следовать 4-шаговому рабочему процессу для добавления карт","Ограничен окружением TFM с определённой структурой файлов"],"ar":["يتطلب الوصول إلى التعليمات البرمجية المصدرية لبرنامج TFM","يجب اتباع سير عمل مكون من 4 خطوات لإضافة البطاقات","محدود بيئة TFM ببنية ملفات محددة"]},"version":4},"contentHash":"6818a8e57e333f2405f47d71220c16f90e523dba5d5c5d3eadd966344f149a42","qualityScore":42}');
