INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Ender-Wiggin2019/elo/tfm-add-card', 'tfm-add-card', 'Ender-Wiggin2019', 'elo', 'community', 'tfm-add-card Ender-Wiggin2019 elo community The tfm-add-card skill enables developers to add new cards to TFM by following a 4-step workflow. It benefits AI agent developers working with TFM. tfm-add-card 是一个用于添加新卡片到 TFM 的技能，需要注册卡名、实现卡片、注册清单和编写单元测试 tfm-add-card は、TFM に新しいカードを追加するためのスキルです。カード名の登録、カードの実装、清単の登録、単体テストの作成が必要です tfm-add-card는 TFM에 새로운 카드를 추가하는 데 사용되는 스킬로, 카드 이름 등록, 카드 구현, 매니페스트 등록, 유닛 테스트 작성이 필요합니다 tfm-add-card es una habilidad para agregar tarjetas a TFM, siguiendo 4 pasos específicos tfm-add-card est une compétence pour ajouter des cartes à TFM, suivant 4 étapes spécifiques tfm-add-card ist eine Fähigkeit, um Karten zu TFM hinzuzufügen, indem 4 spezifische Schritte befolgt werden O tfm-add-card é uma habilidade que permite adicionar novos cartões ao TFM. Ele requer 4 etapas de implementação. tfm-add-card - это навык, который позволяет добавлять новые карточки в TFM. Он требует 4 этапов реализации в ИИ Агентах. tfm-add-card هو مهارة يسمح بإضافة بطاقات جديدة إلى TFM. يتطلب 4 مراحل من التنفيذ في أدوات الذكاء الاصطناعي how to use tfm-add-card tfm-add-card setup guide tfm-add-card alternative tfm-add-card vs TFM card implementation what is tfm-add-card tfm-add-card install adding cards to TFM TFM card development tfm-add-card documentation TFM 添加卡片 tfm-add-card AI 工具 添加新卡片 注册卡名 实现卡片 注册清单 编写单元测试 Registers card names in src/common/cards/CardName.ts Implements cards in src/server/cards/commission/<CardName>.ts Registers cards in src/server/cards/commission/CommissionCardManifest.ts Writes unit tests in tests/cards/commission/<CardName>.spec.ts Supports CorporationCard and IProjectCard types Requires confirmation of card name, display name, and card type tfm-add-card is a skill that allows developers to add new cards to TFM by registering the card name, implementing the card, registering in manifest, and writing unit tests.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('callstackincubator/agent-device/agent-device', 'community', 'callstackincubator', 'agent-device', 'callstackincubator/agent-device', 'agent-device', 0, 0, 42, '2026-03-08T01:57:15.445Z', '2026-03-08T02:08:53.511Z', 'ae877420d6823029b0b2016b02ae614d86de758a5fa2a55d9dad8a4220995305', '{"id":"callstackincubator/agent-device/agent-device","name":"agent-device","description":{"en":"The agent-device skill provides a CLI to control iOS and Android devices for AI agents, enabling exploration, deterministic replay, and structured QA bug hunts. It benefits AI agent developers and testers.","zh":"agent-device是一种CLI工具，用于控制iOS和Android设备，实现AI代理的移动自动化","ja":"agent-deviceはAIエージェント用のCLIツールであり、iOSとAndroidデバイスを制御してモバイル自動化を実現します","ko":"agent-device는 AI 에이전트를 위한 CLI 도구로, iOS와 Android 디바이스를 제어하여 모바일 자동화를 실현합니다","es":"La CLI de agent-device permite a los desarrolladores controlar dispositivos iOS y Android para agente de IA. Ofrece funciones de automatización móvil y pruebas de QA","fr":"La CLI de l''agent-device permet aux développeurs de contrôler les appareils iOS et Android pour les agents IA. Elle offre des fonctionnalités d''automatisation mobile et de tests QA","de":"Die CLI von agent-device ermöglicht es Entwicklern, Geräte von iOS und Android für KI-Agents zu steuern. Sie bietet Funktionen für mobile Automatisierung und QA-Tests","pt":"O agent-device é uma CLI para controle de dispositivos móveis iOS e Android para agentes de IA, permitindo automação e depuração","ru":"Agent-device — это CLI для управления мобильными устройствами iOS и Android для ИИ агентов, позволяющая автоматизацию и отладку","ar":"agent-device هو واجهة سطر الأوامر لتحكم الأجهزة النقالة لآي أو إس وأندرويد لعمليات الاستخبارات الاصطناعية، مما يسمح بالتحكم التلقائي وتصحيح الأخطاء"},"seo":{"title":{"en":"agent-device: Mobile Automation Setup Guide | AI A