INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('callstackincubator/agent-device/agent-device', 'agent-device', 'callstackincubator', 'agent-device', 'community', 'agent-device callstackincubator agent-device community The agent-device skill provides a CLI to control iOS and Android devices for AI agents, enabling exploration, deterministic replay, and structured QA bug hunts. It benefits AI agent developers and testers. agent-device是一种CLI工具，用于控制iOS和Android设备，实现AI代理的移动自动化 agent-deviceはAIエージェント用のCLIツールであり、iOSとAndroidデバイスを制御してモバイル自動化を実現します agent-device는 AI 에이전트를 위한 CLI 도구로, iOS와 Android 디바이스를 제어하여 모바일 자동화를 실현합니다 La CLI de agent-device permite a los desarrolladores controlar dispositivos iOS y Android para agente de IA. Ofrece funciones de automatización móvil y pruebas de QA La CLI de l''agent-device permet aux développeurs de contrôler les appareils iOS et Android pour les agents IA. Elle offre des fonctionnalités d''automatisation mobile et de tests QA Die CLI von agent-device ermöglicht es Entwicklern, Geräte von iOS und Android für KI-Agents zu steuern. Sie bietet Funktionen für mobile Automatisierung und QA-Tests O agent-device é uma CLI para controle de dispositivos móveis iOS e Android para agentes de IA, permitindo automação e depuração Agent-device — это CLI для управления мобильными устройствами iOS и Android для ИИ агентов, позволяющая автоматизацию и отладку agent-device هو واجهة سطر الأوامر لتحكم الأجهزة النقالة لآي أو إس وأندرويد لعمليات الاستخبارات الاصطناعية، مما يسمح بالتحكم التلقائي وتصحيح الأخطاء how to use agent-device agent-device setup guide mobile automation for AI agents agent-device alternative agent-device vs Appium iOS and Android device control deterministic replay with agent-device agent-device install agent-device documentation agent-device CLI iOS Android 移动自动化 AI代理 AIエージェント 移动自动化工具 Supports snapshot refs for exploration Enables deterministic replay using selectors Facilitates structured exploratory QA bug hunts and reporting Allows for debug/crash flow and replay maintenance flow Provides a decision map for navigating different modes Uses canonical flows for streamlined automation agent-device is a command-line interface (CLI) tool for controlling iOS and Android devices, designed for AI agents to facilitate mobile automation and testing.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('MhL5/mhl5.vercel.app/tiptap', 'community', 'MhL5', 'mhl5.vercel.app', 'MhL5/mhl5.vercel.app', 'tiptap', 0, 0, 42, '2026-03-08T01:57:15.452Z', '2026-03-08T02:09:00.878Z', '2b4cf822e3067af2a21d142edd31a3fed6bac667136f0f7895733b3dbdcf1a34', '{"id":"MhL5/mhl5.vercel.app/tiptap","name":"tiptap","description":{"en":"Tiptap is a production-ready rich text editor for Next.js 16 portfolios, utilizing custom shadcn registry and compatible with React 19+, Tailwind v4. It benefits developers seeking advanced text editing capabilities.","zh":"Tiptap是一个production ready的富文本编辑器，支持React 19+、Tailwind v4和shadcn/ui","ja":"TiptapはProduction Readyのリッチテキストエディターで、React 19+、Tailwind v4、shadcn/uiをサポート","ko":"Tiptap는 production ready 리치 텍스트 편집기로 React 19+, Tailwind v4, shadcn/ui를 지원","es":"Tiptap es un editor de texto enriquecido que se integra con Next.js 16 y shadcn registry para crear portfolios personalizados","fr":"Tiptap est un éditeur de texte enrichi qui s''intègre à Next.js 16 et shadcn registry pour créer des portfolios sur mesure","de":"Tiptap ist ein Rich-Text-Editor, der sich in Next.js 16 und shadcn registry integriert, um individuelle Portfolios zu erstellen","pt":"O Tiptap é um editor de texto enriquecido para React, com suporte a imagens, cores e estilos de texto. Depende de React 19+, Tailwind v4 e shadcn/ui","ru":"Tiptap - это редактор текста для React, с поддержкой изображений, цветов и стилей текста. Зависит от React 19+, Tailwind v4 и shadcn/ui","ar":"Tiptap هو محرر نص متقدم لل-react، يدعم الصور والألوان وأساليب النص. يعتمد على React 19+ و Tailwind v4 و shadcn/ui"},"seo":{"title":{"en":"Tiptap: Next.js 16 Portfolio Setup Guide | AI Agent Skill","zh":"Tiptap富文本编辑器快速入门指南","ja":"Tiptapリッチテキストエディターのセットアップガイド - AIエージェント","ko":"Tiptap 리치 텍스트 편집기 설정 가이드 - AI 도구","es":"Guía de configuración de Tiptap con Next.js 16","fr":"Guide d''installation de Tiptap avec Next.js 16","de":"Einrichtungsanleitung für Tiptap mit Next.js 16","pt":"Guia de Configuração do Tiptap: Editor de Texto Enriqueci...","ru":"ИИ Агент Tiptap: Руководство по Настройке для React","ar":"دليل إعداد Tiptap: محرر نص متقدم لل-react"},"description":{"en":"Get started with Tiptap, a rich text editor with custom shadcn registry, and unlock its full potential with our expert guide - install now and elevate your p...","zh":"使用Tiptap创建下一代富文本编辑器，支持React 19+、Tailwind v4和shadcn/ui","ja":"Tiptapを使用して次世代のリッチテキストエディターを作成します。React 19+、Tailwind v4、shadcn/uiをサポート","ko":"Tiptap를 사용하여 차세대 리치 텍스트 편집기를 생성합니다. React 19+, Tailwind v4, shadcn/ui 지원","es":"Aprende a configurar Tiptap con Next.js 16 y shadcn registry para crear un portfolio personalizado","fr":"Découvrez comment installer Tiptap avec Next.js 16 et shadcn registry pour créer un portfolio sur mesure","de":"Erfahren Sie, wie Sie Tiptap mit Next.js 16 und shadcn registry einrichten, um ein individuelles Portfolio zu erstellen","pt":"Aprenda a configurar o Tiptap, um editor de texto enriquecido para React, com dependências como React 19+ e Tailwind v4","ru":"Узнайте, как настроить Tiptap, редактор текста для React, с зависимостями như React 19+ и Tailwind v4","ar":"تعرف على كيفية إعداد Tiptap، محرر نص متقدم لل-react، مع الإعتماد على React 19+ و Tailwind v4"},"definition":{"en":"Tiptap is a rich text editor designed for Next.js 16 portfolios, featuring a custom shadcn registry and compatibility with React and Tailwind.","zh":"Tiptap是一个基于React的富文本编辑器","ja":"TiptapはReactベースのリッチテキストエディター","ko":"Tiptap는 React 기반 리치 텍스트 편집기","es":"Tiptap es un editor de texto enriquecido que ofrece funcionalidades de edición avanzadas","fr":"Tiptap est un éditeur de texte enrichi qui offre des fonctionnalités d''édition avancées","de":"Tiptap ist ein Rich-Text-Editor, der erweiterte Editierfunktionen bietet","pt":"O Tiptap é um editor de texto enriquecido para React, que fornece recursos de edição avançados","ru":"Tiptap - это редактор текста для React, который предоставляет расширенные возможности редактирования","ar":"Tiptap هو محرر نص متقدم لل-react، يقدم ميزات تحرير متقدمة"},"features":{"en":["Utilizes @tiptap/react@3.16.0 for rich text editing","Compatible with React 19+ for seamless integration","Supports custom shadcn registry for enhanced portfolio customization","Includes @tiptap/extension-image for image handling","Features @tiptap/extension-color for color customization","Utilizes @tiptap/starter-kit@3.16.0 for quick setup"],"zh":["支持React 19+","集成Tailwind v4","支持shadcn/ui","快速安装（5分钟）","支持多种扩展（image、color、text-style、typography）"],"ja":["React 19+をサポート","Tailwind v4を統合","shadcn/uiをサポート","クイックインストール（5分）","多くの拡張機能（image、color、text-style、typography）をサポート"],"ko":["React 19+ 지원","Tailwind v4 통합","shadcn/ui 지원","快速 설치（5분）","다양한 확장 기능 지원（image、color、text-style、typography）"],"es":["Compatibilidad con React 19+","Integración con Tailwind v4","Soporte para shadcn/ui","Extensiones para imágenes, colores y estilos de texto","Kit de inicio para una configuración rápida"],"fr":["Compatibilité avec React 19+","Intégration avec Tailwind v4","Prise en charge de shadcn/ui","Extensions pour les images, les couleurs et les styles de texte","Kit de démarrage pour une configuration rapide"],"de":["Kompatibilität mit React 19+","Integration mit Tailwind v4","Unterstützung für shadcn/ui","Erweiterungen für Bilder, Farben und Textstile","Startkit für eine schnelle Konfiguration"],"pt":["Suporte a imagens com @tiptap/extension-image","Suporte a cores com @tiptap/extension-color","Suporte a estilos de texto com @tiptap/extension-text-style","Integração com React 19+","Integração com Tailwind v4","Dependência de shadcn/ui"],"ru":["Поддержка изображений с @tiptap/extension-image","Поддержка цветов с @tiptap/extension-color","Поддержка стилей текста с @tiptap/extension-text-style","Интеграция с React 19+","Интеграция с Tailwind v4","Зависимость от shadcn/ui"],"ar":["دعم الصور مع @tiptap/extension-image","دعم الألوان مع @tiptap/extension-color","دعم أساليب النص مع @tiptap/extension-text-style","التكامل مع React 19+","التكامل مع Tailwind v4","اعتماد shadcn/ui"]},"keywords":{"en":["how to use tiptap","tiptap install","tiptap setup guide","what is tiptap","tiptap alternative","tiptap vs quill","next.js 16 portfolio","custom shadcn registry","react 19+ compatible"],"zh":["Tiptap","富文本编辑器","React","Tailwind","shadcn/ui","快速入门","AI工具","前端开发"],"ja":["Tiptap","リッチテキストエディター","React","Tailwind","shadcn/ui","セットアップガイド","AIエージェント","フロントエンド開発"],"ko":["Tiptap","리치 텍스트 편집기","React","Tailwind","shadcn/ui","설정 가이드","AI 도구","프론트엔드 개발"],"es":["tiptap","next js 16","shadcn registry","editor de texto enriquecido","react 19+","tailwind v4","shadcn/ui","portfolio personalizado"],"fr":["tiptap","next js 16","shadcn registry","éditeur de texte enrichi","react 19+","tailwind v4","shadcn/ui","portfolio sur mesure"],"de":["tiptap","next js 16","shadcn registry","rich-text-editor","react 19+","tailwind v4","shadcn/ui","individuelles portfolio"],"pt":["tiptap","editor de texto enriquecido","react","tailwind","shadcn/ui","imagens","cores","estilos de texto","configuração do tiptap","guia de instalação do tiptap"],"ru":["tiptap","редактор текста","react","tailwind","shadcn/ui","изображения","цвета","стили текста","настройка tiptap","руководство по установке tiptap"],"ar":["tiptap","محرر نص متقدم","react","tailwind","shadcn/ui","صور","ألوان","أساليب نص","إعداد tiptap","دليل تركيب tiptap"]}},"owner":"MhL5","repo":"mhl5.vercel.app","repoPath":"MhL5/mhl5.vercel.app","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.452Z","topics":[],"category":"community","skillMd":{"name":"tiptap","description":"|","bodyPreview":"# Tiptap Rich Text Editor\n\n**Status**: Production Ready\n**Last Updated**: 2026-01-21\n**Dependencies**: React 19+, Tailwind v4, shadcn/ui (recommended)\n**Latest Versions**: @tiptap/react@3.16.0, @tiptap/starter-kit@3.16.0, @tiptap/pm@3.16.0 (verified 2026-01-21)\n\n---\n\n## Quick Start (5 Minutes)\n\n### 1. Install Dependencies\n\n```bash\nnpm install @tiptap/react @tiptap/starter-kit @tiptap/pm @tiptap/extension-image @tiptap/extension-color @tiptap/extension-text-style @tiptap/extension-typography\n```","body":"# Tiptap Rich Text Editor\n\n**Status**: Production Ready\n**Last Updated**: 2026-01-21\n**Dependencies**: React 19+, Tailwind v4, shadcn/ui (recommended)\n**Latest Versions**: @tiptap/react@3.16.0, @tiptap/starter-kit@3.16.0, @tiptap/pm@3.16.0 (verified 2026-01-21)\n\n---\n\n## Quick Start (5 Minutes)\n\n### 1. Install Dependencies\n\n```bash\nnpm install @tiptap/react @tiptap/starter-kit @tiptap/pm @tiptap/extension-image @tiptap/extension-color @tiptap/extension-text-style @tiptap/extension-typography\n```\n\n**Why this matters:**\n- `@tiptap/pm` is required peer dependency (ProseMirror engine)\n- StarterKit bundles 20+ essential extensions (headings, lists, bold, italic, etc.)\n- Image/color/typography are common additions not in StarterKit\n\n**Important**: If using Tiptap v3.14.0+, drag handle functionality requires minimum v3.14.0 (regression fixed in that release). For Pro extensions with drag handles, React 18 is recommended due to tippyjs-react dependency.\n\n### 2. Create SSR-Safe Editor\n\n```typescript\nimport { useEditor, EditorContent } from ''@tiptap/react''\nimport StarterKit from ''@tiptap/starter-kit''\n\nexport function Editor() {\n  const editor = useEditor({\n    extensions: [StarterKit],\n    content: ''<p>Hello World!</p>'',\n    immediatelyRender: false, // ⚠️ CRITICAL for SSR/Next.js\n    editorProps: {\n      attributes: {\n        class: ''prose prose-sm focus:outline-none min-h-[200px] p-4'',\n      },\n    },\n  })\n\n  return <EditorContent editor={editor} />\n}\n```\n\n**CRITICAL:**\n- **Always set `immediatelyRender: false`** for Next.js/SSR apps (prevents hydration mismatch)\n- Without this, you''ll see: \"SSR has been detected, please set `immediatelyRender` explicitly to `false`\"\n- This is the #1 error reported by Tiptap users\n\n### 3. Add Tailwind Typography (Optional but Recommended)\n\n```bash\nnpm install @tailwindcss/typography\n```\n\nUpdate your `tailwind.config.ts`:\n```typescript\nimport typography from ''@tailwindcss/typography''\n\nexport default {\n  plugins: [typography],\n}\n```\n\n**Why this matters:**\n- Provides default prose styling for headings, lists, links, etc.\n- Without it, formatted content looks unstyled\n- Alternative: Use custom Tailwind classes with `.tiptap` selector\n\n---\n\n## The 3-Step Setup Process\n\n### Step 1: Choose Your Integration Method\n\n**Option A: shadcn Minimal Tiptap Component (Recommended)**\n\nInstall the pre-built shadcn component:\n```bash\nnpx shadcn@latest add https://raw.githubusercontent.com/Aslam97/shadcn-minimal-tiptap/main/registry/block-registry.json\n```\n\nThis installs:\n- Fully-featured editor component with toolbar\n- Image upload support\n- Code block with syntax highlighting\n- Typography extension configured\n- Dark mode support\n\n**Option B: Build Custom Editor (Full Control)**\n\nUse templates from this skill:\n- `templates/base-editor.tsx` - Minimal editor setup\n- `templates/common-extensions.ts` - Extension bundle\n- `templates/tiptap-prose.css` - Tailwind styling\n\n**Key Points:**\n- Option A: Faster setup, opinionated UI\n- Option B: Complete customization, headless approach\n- Both work with React + Tailwind v4\n\n### Step 2: Configure Extensions\n\nExtensions add functionality to your editor:\n\n```typescript\nimport StarterKit from ''@tiptap/starter-kit''\nimport Image from ''@tiptap/extension-image''\nimport Link from ''@tiptap/extension-link''\nimport Typography from ''@tiptap/extension-typography''\n\nconst editor = useEditor({\n  extensions: [\n    StarterKit.configure({\n      // Customize built-in extensions\n      heading: {\n        levels: [1, 2, 3],\n      },\n      bulletList: {\n        keepMarks: true,\n      },\n    }),\n    Image.configure({\n      inline: true,\n      allowBase64: false, // ⚠️ Prevent base64 bloat\n      resize: {\n        enabled: true,\n        directions: [''top-right'', ''bottom-right'', ''bottom-left'', ''top-left''],\n        minWidth: 100,\n        minHeight: 100,\n        alwaysPreserveAspectRatio: true,\n      },\n    }),\n    Link.configure({\n      openOnClick: false,\n      HTMLAttributes: {\n        class: ''text-primary underline'',\n      },\n    }),\n    Typography, // Smart quotes, dashes, etc.\n  ],\n})\n```\n\n**CRITICAL:**\n- Set `allowBase64: false` to prevent huge JSON payloads\n- Use upload handler pattern (see templates/image-upload-r2.tsx)\n- Extension order matters - dependencies must load first\n\n### Step 3: Handle Image Uploads (If Needed)\n\n**Pattern**: Base64 preview → background upload → replace with URL\n\nSee `templates/image-upload-r2.tsx` for full implementation:\n\n```typescript\nimport { Editor } from ''@tiptap/core''\n\nasync function uploadImageToR2(file: File, env: Env): Promise<string> {\n  // 1. Create base64 preview for immediate display\n  const reader = new FileReader()\n  const base64 = await new Promise<string>((resolve) => {\n    reader.onload = () => resolve(reader.result as string)\n    reader.readAsDataURL(file)\n  })\n\n  // 2. Insert preview into editor\n  editor.chain().focus().setImage({ src: base64 }).run()\n\n  // 3. Upload to R2 in background\n  const formData = new FormData()\n  formData.append(''file'', file)\n\n  const response = await fetch(''/api/upload'', {\n    method: ''POST'',\n    body: formData,\n  })\n\n  const { url } = await response.json()\n\n  // 4. Replace base64 with permanent URL\n  editor.chain()\n    .focus()\n    .updateAttributes(''image'', { src: url })\n    .run()\n\n  return url\n}\n```\n\n**Why this pattern:**\n- Immediate user feedback (preview)\n- No database bloat from base64\n- Works with Cloudflare R2\n- Graceful error handling\n\n---\n\n## Critical Rules\n\n### Always Do\n\n✅ Set `immediatelyRender: false` in `useEditor()` for SSR apps\n✅ Install `@tailwindcss/typography` for prose styling\n✅ Use upload handler for images (not base64)\n✅ Memoize editor configuration to prevent re-renders\n✅ Include `@tiptap/pm` peer dependency\n\n### Never Do\n\n❌ Use `immediatelyRender: true` (default) with Next.js/SSR\n❌ Store images as base64 in database (use URL after upload)\n❌ Forget to add `prose` classes to editor container\n❌ Load more than 100 widgets in collaborative mode\n❌ Use Create React App (v3 incompatible - use Vite)\n\n---\n\n## Known Issues Prevention\n\nThis skill prevents **7** documented issues:\n\n### Issue #1: SSR Hydration Mismatch\n**Error**: \"SSR has been detected, please set `immediatelyRender` explicitly to `false`\"\n**Source**: [GitHub Issue #5856](https://github.com/ueberdosis/tiptap/issues/5856), [#5602](https://github.com/ueberdosis/tiptap/issues/5602)\n**Why It Happens**: Default `immediatelyRender: true` breaks Next.js hydration\n**Prevention**: Template includes `immediatelyRender: false` by default\n\n### Issue #2: Editor Re-renders on Every Keystroke\n**Error**: Laggy typing, poor performance in large documents\n**Source**: [Tiptap Performance Docs](https://tiptap.dev/docs/editor/api/editor#immediatelyrender)\n**Why It Happens**: `useEditor()` hook re-renders component on every change\n**Prevention**: Use `useEditorState()` hook or memoization patterns (see templates)\n\n### Issue #3: Tailwind Typography Not Working\n**Error**: Headings/lists render unstyled, no formatting visible\n**Source**: [shadcn Tiptap Discussion](https://github.com/shadcn-ui/ui/discussions/1729)\n**Why It Happens**: Missing `@tailwindcss/typography` plugin\n**Prevention**: Skill includes typography plugin installation in checklist\n\n### Issue #4: Image Upload Base64 Bloat\n**Error**: JSON payloads become megabytes, slow saves, database bloat\n**Source**: [Tiptap Image Docs](https://tiptap.dev/docs/editor/extensions/nodes/image#usage)\n**Why It Happens**: Default allows base64, no upload handler configured\n**Prevention**: R2 upload template with URL replacement pattern\n\n### Issue #5: Build Errors in Create React App\n**Error**: \"jsx-runtime\" module resolution errors after upgrading to v3\n**Source**: [GitHub Issue #6812](https://github.com/ueberdosis/tiptap/issues/6812)\n**Why It Happens**: CRA incompatibility with v3 module structure\n**Prevention**: Skill documents Vite as preferred bundler + provides working config\n\n### Issue #6: ProseMirror Multiple Versions Conflict\n**Error**: `Error: Looks like multiple versions of prosemirror-model were loaded`\n**Source**: [GitHub Issue #577](https://github.com/ueberdosis/tiptap/issues/577) (131 comments), [Issue #6171](https://github.com/ueberdosis/tiptap/issues/6171)\n**Why It Happens**: Installing additional Tiptap extensions can pull different versions of prosemirror-model or prosemirror-view, creating duplicate dependencies in node_modules. The unique-id extension is particularly problematic in testing environments.\n**Prevention**: Use package resolutions to force a single ProseMirror version\n\n```json\n// package.json\n{\n  \"resolutions\": {\n    \"prosemirror-model\": \"~1.21.0\",\n    \"prosemirror-view\": \"~1.33.0\",\n    \"prosemirror-state\": \"~1.4.3\"\n  }\n}\n```\n\nOr reinstall dependencies:\n```bash\nrm -rf node_modules package-lock.json\nnpm install\n```\n\n**Note**: The @tiptap/pm package is designed to prevent this issue, but extensions may still introduce conflicts.\n\n### Issue #7: EditorProvider vs useEditor Confusion (Community-sourced)\n**Error**: `SSR has been detected, please set ''immediatelyRender'' explicitly to ''false''` (when both used together)\n**Source**: [GitHub Issue #5856 Comment](https://github.com/ueberdosis/tiptap/issues/5856#issuecomment-2493124171)\n**Why It Happens**: Users commonly use EditorProvider and useEditor together, but EditorProvider is a wrapper around useEditor for React Context setup - they should not be used simultaneously.\n**Prevention**: Choose one pattern only\n\n**Incorrect Pattern**:\n```typescript\n// Don''t use both together\n<EditorProvider>\n  <MyComponent />\n</EditorProvider>\n\nfunction MyComponent() {\n  const editor = useEditor({ ... }) // ❌ Wrong - EditorProvider already created editor\n}\n```\n\n**Correct Patterns**:\n```typescript\n// Option 1: Use EditorProvider only\n<EditorProvider immediatelyRender={false} extensions={[StarterKit]}>\n  <EditorContent />\n</EditorProvider>\n\n// Option 2: Use useEditor only\nfunction Editor() {\n  const editor = useEditor({\n    extensions: [StarterKit],\n    immediatelyRender: false,\n  })\n  return <EditorContent editor={editor} />\n}\n```\n\n---\n\n## Configuration Files Reference\n\n### Tailwind Prose Styling (tiptap-prose.css)\n\n```css\n/* Apply to editor container */\n.tiptap {\n  /* Tailwind Typography */\n  @apply prose prose-sm sm:prose-base lg:prose-lg dark:prose-invert max-w-none;\n\n  /* Custom overrides */\n  h1 {\n    @apply text-3xl font-bold mt-8 mb-4;\n  }\n\n  h2 {\n    @apply text-2xl font-semibold mt-6 mb-3;\n  }\n\n  p {\n    @apply my-4 text-base leading-7;\n  }\n\n  ul, ol {\n    @apply my-4 ml-6;\n  }\n\n  code {\n    @apply bg-muted px-1.5 py-0.5 rounded text-sm font-mono;\n  }\n\n  pre {\n    @apply bg-muted p-4 rounded-lg overflow-x-auto;\n  }\n\n  blockquote {\n    @apply border-l-4 border-primary pl-4 italic my-4;\n  }\n}\n```\n\n**Why these settings:**\n- `prose` classes provide consistent formatting\n- `dark:prose-invert` handles dark mode automatically\n- Custom overrides use semantic Tailwind v4 colors\n\n---\n\n## Common Patterns\n\n### Pattern 1: Collaborative Editing with Y.js\n\n```typescript\nimport { useEditor } from ''@tiptap/react''\nimport Collaboration from ''@tiptap/extension-collaboration''\nimport * as Y from ''yjs''\n\nconst ydoc = new Y.Doc()\n\nconst editor = useEditor({\n  extensions: [\n    StarterKit.configure({\n      history: false, // Disable history for collaboration\n    }),\n    Collaboration.configure({\n      document: ydoc,\n    }),\n  ],\n})\n```\n\n**When to use**: Real-time multi-user editing (Notion-like)\n**See**: `templates/collaborative-setup.tsx` for full example\n\n### Pattern 2: Markdown Support\n\n```typescript\nimport { useEditor } from ''@tiptap/react''\nimport StarterKit from ''@tiptap/starter-kit''\nimport { Markdown } from ''@tiptap/markdown''\n\n// Load editor with markdown content\nconst editor = useEditor({\n  extensions: [StarterKit, Markdown],\n  content: ''# Hello World\\n\\nThis is **Markdown**!'',\n  contentType: ''markdown'',  // ⚠️ CRITICAL: Must specify or content parsed as HTML\n  immediatelyRender: false,\n})\n\n// Get markdown from editor\nconst markdownOutput = editor.getMarkdown()\n\n// Insert markdown content\neditor.commands.setContent(''## New heading'', { contentType: ''markdown'' })\neditor.commands.insertContent(''**Bold** text'', { contentType: ''markdown'' })\n```\n\n**When to use**: Storing content as markdown, displaying/editing rich text\n**Install**: `npm install @tiptap/markdown@3.16.0`\n**Status**: Beta (released Oct 2025, API stable but may change)\n**CRITICAL**: Always specify `contentType: ''markdown''` when setting markdown content\n\n**Recent Fixes** (v3.15.0-v3.16.0):\n- Fixed incorrect Markdown output when underline is mixed with bold/italic and ranges don''t fully overlap\n- Improved serialization for overlapping formatting marks\n- Source: [v3.16.0 Release](https://github.com/ueberdosis/tiptap/releases/tag/v3.16.0)\n\n### Pattern 3: Form Integration with react-hook-form\n\n```typescript\nimport { useForm, Controller } from ''react-hook-form''\n\nfunction BlogForm() {\n  const { control, handleSubmit } = useForm()\n\n  return (\n    <form onSubmit={handleSubmit(onSubmit)}>\n      <Controller\n        name=\"content\"\n        control={control}\n        render={({ field }) => (\n          <Editor\n            content={field.value}\n            onUpdate={({ editor }) => {\n              field.onChange(editor.getHTML())\n            }}\n          />\n        )}\n      />\n    </form>\n  )\n}\n```\n\n**When to use**: Blog posts, comments, any form-based content\n\n---\n\n## Using Bundled Resources\n\n### Scripts (scripts/)\n\nNo executable scripts for this skill.\n\n### Templates (templates/)\n\n**Required for all projects:**\n- `templates/base-editor.tsx` - Minimal React editor component\n- `templates/package.json` - Required dependencies\n\n**Optional based on needs:**\n- `templates/minimal-tiptap-setup.sh` - shadcn component installation\n- `templates/image-upload-r2.tsx` - R2 upload handler\n- `templates/tiptap-prose.css` - Tailwind styling\n- `templates/collaborative-setup.tsx` - Y.js collaboration\n- `templates/common-extensions.ts` - Extension bundle\n\n**When to load these**: Claude should reference templates when user asks to:\n- Set up tiptap editor\n- Add image uploads\n- Configure collaborative editing\n- Style with Tailwind prose\n\n### References (references/)\n\n- `references/tiptap-docs.md` - Key documentation links\n- `references/common-errors.md` - Error troubleshooting guide\n- `references/extension-catalog.md` - Popular extensions list\n\n**When Claude should load these**: Troubleshooting errors, exploring extensions, understanding API\n\n---\n\n## Advanced Topics\n\n### Custom Extensions\n\nCreate your own Tiptap extensions:\n\n```typescript\nimport { Node } from ''@tiptap/core''\n\nconst CustomNode = Node.create({\n  name: ''customNode'',\n\n  group: ''block'',\n\n  content: ''inline*'',\n\n  parseHTML() {\n    return [{ tag: ''div[data-custom]'' }]\n  },\n\n  renderHTML({ HTMLAttributes }) {\n    return [''div'', { ''data-custom'': '''', ...HTMLAttributes }, 0]\n  },\n\n  addCommands() {\n    return {\n      insertCustomNode: () => ({ commands }) => {\n        return commands.insertContent({ type: this.name })\n      },\n    }\n  },\n})\n```\n\n**Use cases**: Custom widgets, embeds, interactive elements\n\n### Slash Commands\n\nAdd Notion-like `/` commands:\n\n```typescript\nimport { Extension } from ''@tiptap/core''\nimport Suggestion from ''@tiptap/suggestion''\n\nconst SlashCommands = Extension.create({\n  name: ''slashCommands'',\n\n  addOptions() {\n    return {\n      suggestion: {\n        char: ''/'',\n        items: ({ query }) => {\n          return [\n            { title: ''Heading 1'', command: ({ editor, range }) => {\n              editor.chain().focus().deleteRange(range).setHeading({ level: 1 }).run()\n            }},\n            { title: ''Bullet List'', command: ({ editor, range }) => {\n              editor.chain().focus().deleteRange(range).toggleBulletList().run()\n            }},\n          ]\n        },\n      },\n    }\n  },\n\n  addProseMirrorPlugins() {\n    return [Suggestion({ editor: this.editor, ...this.options.suggestion })]\n  },\n})\n```\n\n**Use cases**: Productivity shortcuts, quick formatting\n\n---\n\n## Dependencies\n\n**Required**:\n- `@tiptap/react@^3.16.0` - React integration (React 19 supported)\n- `@tiptap/starter-kit@^3.16.0` - Essential extensions bundle\n- `@tiptap/pm@^3.16.0` - ProseMirror peer dependency\n- `react@^19.0.0` - React framework\n\n**React Version Compatibility**:\n- **Core Tiptap**: Supports React 19 as of v2.10.0\n- **UI Components**: Work best with React 18 (Next.js 15 recommended per [official docs](https://tiptap.dev/docs/editor/getting-started/install/nextjs))\n- **Pro Extensions**: May require React 18 - drag-handle extension depends on archived tippyjs-react without React 19 support ([Issue #5876](https://github.com/ueberdosis/tiptap/issues/5876))\n\n**Optional**:\n- `@tiptap/extension-audio@^3.16.0` - Audio support (NEW in v3.16.0)\n- `@tiptap/extension-image@^3.16.0` - Image support\n- `@tiptap/extension-link@^3.16.0` - Link support (NEW in v3, included in StarterKit)\n- `@tiptap/extension-color@^3.16.0` - Text color\n- `@tiptap/extension-typography@^3.16.0` - Smart typography\n- `@tiptap/extension-collaboration@^3.16.0` - Real-time collaboration\n- `@tiptap/extension-markdown@^3.16.0` - Markdown support (Beta)\n- `@tailwindcss/typography@^0.5.19` - Prose styling\n- `yjs@^13.6.0` - Collaborative editing backend\n- `react-medium-image-zoom@^5.2.0` - Image zoom functionality\n\n---\n\n## Official Documentation\n\n- **Tiptap**: https://tiptap.dev\n- **Installation Guide**: https://tiptap.dev/docs/editor/installation/react\n- **Extensions**: https://tiptap.dev/docs/editor/extensions\n- **API Reference**: https://tiptap.dev/docs/editor/api/editor\n- **shadcn minimal-tiptap**: https://github.com/Aslam97/shadcn-minimal-tiptap\n- **Context7 Library ID**: tiptap/tiptap\n\n---\n\n## Package Versions (Verified 2026-01-21)\n\n```json\n{\n  \"dependencies\": {\n    \"@tiptap/react\": \"^3.16.0\",\n    \"@tiptap/starter-kit\": \"^3.16.0\",\n    \"@tiptap/pm\": \"^3.16.0\",\n    \"@tiptap/extension-audio\": \"^3.16.0\",\n    \"@tiptap/extension-image\": \"^3.16.0\",\n    \"@tiptap/extension-color\": \"^3.16.0\",\n    \"@tiptap/extension-text-style\": \"^3.16.0\",\n    \"@tiptap/extension-typography\": \"^3.16.0\",\n    \"@tiptap/extension-link\": \"^3.16.0\",\n    \"@tiptap/extension-markdown\": \"^3.16.0\"\n  },\n  \"devDependencies\": {\n    \"@tailwindcss/typography\": \"^0.5.19\",\n    \"react\": \"^19.2.3\",\n    \"react-dom\": \"^19.2.3\"\n  }\n}\n```\n\n---\n\n## Production Example\n\nThis skill is based on real-world implementations:\n- **GitLab**: Uses Tiptap for issue/MR descriptions\n- **Statamic CMS**: Tiptap as default rich text editor\n- **shadcn minimal-tiptap**: 3.14M downloads/week\n\n**Token Savings**: ~71% (14k → 4k tokens)\n**Errors Prevented**: 7/7 documented errors (5 critical setup + 2 community patterns)\n**Validation**: ✅ SSR compatibility, ✅ Image uploads, ✅ Tailwind v4, ✅ Performance, ✅ React 19 compatibility\n\n---\n\n## Troubleshooting\n\n### Problem: \"SSR has been detected, please set `immediatelyRender` explicitly to `false`\"\n**Solution**: Add `immediatelyRender: false` to your `useEditor()` config\n\n### Problem: Headings/lists look unstyled\n**Solution**: Install `@tailwindcss/typography` and add `prose` classes to editor container\n\n### Problem: Editor lags when typing\n**Solution**: Use `useEditorState()` hook instead of `useEditor()` for read-only rendering, or memoize editor configuration\n\n### Problem: Images make JSON huge\n**Solution**: Set `allowBase64: false` in Image extension config and use upload handler (see templates/image-upload-r2.tsx)\n\n### Problem: Build fails in Create React App\n**Solution**: Switch to Vite - CRA incompatible with Tiptap v3. See cloudflare-worker-base skill for Vite setup.\n\n---\n\n## Complete Setup Checklist\n\nUse this checklist to verify your setup:\n\n- [ ] Installed `@tiptap/react`, `@tiptap/starter-kit`, `@tiptap/pm`\n- [ ] Set `immediatelyRender: false` in `useEditor()` config\n- [ ] Installed `@tailwindcss/typography` plugin\n- [ ] Added `prose` classes to editor container\n- [ ] Configured image upload handler (if using images)\n- [ ] Set `allowBase64: false` in Image extension\n- [ ] Editor renders without hydration errors\n- [ ] Formatted text displays correctly (headings, lists, etc.)\n- [ ] Dev server runs without TypeScript errors\n- [ ] Production build succeeds\n\n---\n\n**Questions? Issues?**\n\n1. Check `references/common-errors.md` for troubleshooting\n2. Verify `immediatelyRender: false` is set\n3. Check official docs: https://tiptap.dev\n4. Ensure `@tiptap/pm` peer dependency is installed\n"},"lastSynced":"2026-03-08T02:09:00.878Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing advanced rich text editing capabilities in Next.js portfolios.","zh":"非常适合需要在其Next.js作品集中具备高级富文本编辑功能的前端Agent。","ja":"Next.jsポートフォリオで高度なリッチテキスト編集機能を必要とするフロントエンドエージェントに最適です。","ko":"Next.js 포트폴리오에서 고급 리치 텍스트 편집 기능이 필요한 프론트엔드 에이전트에게 완벽합니다.","es":"Perfecto para agentes Frontend que necesitan capacidades de edición de texto rico avanzadas en portfolios de Next.js.","fr":"Parfait pour les agents Frontend ayant besoin de fonctionnalités de modification de texte enrichi avancées dans les portfolios Next.js.","de":"Perfekt für Frontend-Agents, die erweiterte reiche Textbearbeitungsfunktionen in Next.js-Portfolios benötigen.","pt":"Perfeito para Agentes Frontend que necessitam de capacidades avançadas de edição de texto rico em portfolios do Next.js.","ru":"Идеально подходит для агентов Frontend, требующих расширенных возможностей редактирования богатого текста в портфелях Next.js.","ar":"مثالي للوكلاء الأمامية الذين يحتاجون إلى قدرات متقدمة لتحرير النص الغني في محفظة Next.js."},"recommendation":{"en":"Empowers agents to create customizable rich text editors with support for React 19+, Tailwind v4, and shadcn/ui, enabling advanced text editing features like image and color extensions.","zh":"赋能Agent创建可自定义的富文本编辑器，支持React 19+、Tailwind v4和shadcn/ui，实现如图片和颜色扩展等高级文本编辑功能。","ja":"React 19+、Tailwind v4、およびshadcn/uiをサポートするカスタマイズ可能なリッチテキストエディタを作成し、画像や色の拡張などの高度なテキスト編集機能を実現できます。","ko":"React 19+, Tailwind v4 및 shadcn/ui를 지원하는 사용자 정의 가능한 리치 텍스트 편집기를 생성하여 이미지 및 색상 확장과 같은 고급 텍스트 편집 기능을 활성화합니다.","es":"Habilita a los agentes a crear editores de texto rico personalizables con soporte para React 19+, Tailwind v4 y shadcn/ui, lo que permite funciones de edición de texto avanzadas como extensiones de imagen y color.","fr":"Permet aux agents de créer des éditeurs de texte enrichi personnalisables avec une prise en charge de React 19+, Tailwind v4 et shadcn/ui, permettant des fonctionnalités de modification de texte avancées comme des extensions d''image et de couleur.","de":"Ermächtigt Agenten, benutzerdefinierte Rich-Text-Editoren mit Unterstützung für React 19+, Tailwind v4 und shadcn/ui zu erstellen, wodurch erweiterte Textbearbeitungsfunktionen wie Bild- und Farberweiterungen ermöglicht werden.","pt":"Habilita os agentes a criar editores de texto rico personalizáveis com suporte para React 19+, Tailwind v4 e shadcn/ui, permitindo recursos avançados de edição de texto, como extensões de imagem e cor.","ru":"Наделяет агентов возможностью создавать настраиваемые редакторы богатого текста с поддержкой React 19+, Tailwind v4 и shadcn/ui, позволяя использовать расширенные функции редактирования текста, такие как расширения изображений и цвета.","ar":"يمكّن الوكلاء من إنشاء محررات نص غني قابلة للتعديل مع دعم React 19+ و Tailwind v4 و shadcn/ui، مما يسمح بميزات تحرير متقدمة مثل امتدادات الصورة واللون."},"useCases":{"en":["Customizing text editing experiences for web applications","Integrating rich text editors into Next.js portfolios","Extending text editing capabilities with custom extensions"],"zh":["为Web应用程序自定义文本编辑体验","将富文本编辑器集成到Next.js作品集中","使用自定义扩展扩展文本编辑功能"],"ja":["Webアプリケーションのテキスト編集エクスペリエンスのカスタマイズ","Next.jsポートフォリオへのリッチテキストエディタの統合","カスタム拡張機能によるテキスト編集機能の拡張"],"ko":["웹 애플리케이션을 위한 텍스트 편집 경험 사용자 정의","Next.js 포트폴리오에 리치 텍스트 편집기 통합","사용자 정의 확장으로 텍스트 편집 기능 확장"],"es":["Personalizar experiencias de edición de texto para aplicaciones web","Integrar editores de texto rico en portfolios de Next.js","Extender las capacidades de edición de texto con extensiones personalizadas"],"fr":["Personnaliser les expériences d''édition de texte pour les applications Web","Intégrer des éditeurs de texte enrichi dans les portfolios Next.js","Étendre les capacités d''édition de texte avec des extensions personnalisées"],"de":["Anpassen von Textbearbeitungserlebnissen für Webanwendungen","Integrieren von Rich-Text-Editoren in Next.js-Portfolios","Erweitern der Textbearbeitungsfunktionen mit benutzerdefinierten Erweiterungen"],"pt":["Personalizar experiências de edição de texto para aplicações web","Integrar editores de texto rico em portfolios do Next.js","Estender capacidades de edição de texto com extensões personalizadas"],"ru":["Настройка опыта редактирования текста для веб-приложений","Интеграция редакторов богатого текста в портфели Next.js","Расширение возможностей редактирования текста с помощью пользовательских расширений"],"ar":["تخصيص تجارب تحرير النص للتطبيقات الويب","دمج محررات النص الغني في محفظة Next.js","تمديد قدرات تحرير النص باستخدام امتدادات مخصصة"]},"limitations":{"en":["Requires React 19+ and Tailwind v4","Compatibility limited to Next.js 16 portfolios"],"zh":["需要React 19+和Tailwind v4","兼容性仅限于Next.js 16作品集"],"ja":["React 19+およびTailwind v4が必要","Next.js 16ポートフォリオとの互換性に限定"],"ko":["React 19+ 및 Tailwind v4 필요","Next.js 16 포트폴리오로 호환성 제한"],"es":["Requiere React 19+ y Tailwind v4","Compatibilidad limitada a portfolios de Next.js 16"],"fr":["Nécessite React 19+ et Tailwind v4","Compatibilité limitée aux portfolios Next.js 16"],"de":["Benötigt React 19+ und Tailwind v4","Kompatibilität auf Next.js 16-Portfolios beschränkt"],"pt":["Exige React 19+ e Tailwind v4","Compatibilidade limitada a portfolios do Next.js 16"],"ru":["Требует React 19+ и Tailwind v4","Совместимость ограничена портфелями Next.js 16"],"ar":["يتطلب React 19+ و Tailwind v4","التوافق مقيد بمحفظة Next.js 16"]},"version":4},"contentHash":"2b4cf822e3067af2a21d142edd31a3fed6bac667136f0f7895733b3dbdcf1a34","qualityScore":42}');
