INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('MhL5/mhl5.vercel.app/tiptap', 'tiptap', 'MhL5', 'mhl5.vercel.app', 'community', 'tiptap MhL5 mhl5.vercel.app community Tiptap is a production-ready rich text editor for Next.js 16 portfolios, utilizing custom shadcn registry and compatible with React 19+, Tailwind v4. It benefits developers seeking advanced text editing capabilities. Tiptap是一个production ready的富文本编辑器，支持React 19+、Tailwind v4和shadcn/ui TiptapはProduction Readyのリッチテキストエディターで、React 19+、Tailwind v4、shadcn/uiをサポート Tiptap는 production ready 리치 텍스트 편집기로 React 19+, Tailwind v4, shadcn/ui를 지원 Tiptap es un editor de texto enriquecido que se integra con Next.js 16 y shadcn registry para crear portfolios personalizados Tiptap est un éditeur de texte enrichi qui s''intègre à Next.js 16 et shadcn registry pour créer des portfolios sur mesure Tiptap ist ein Rich-Text-Editor, der sich in Next.js 16 und shadcn registry integriert, um individuelle Portfolios zu erstellen O Tiptap é um editor de texto enriquecido para React, com suporte a imagens, cores e estilos de texto. Depende de React 19+, Tailwind v4 e shadcn/ui Tiptap - это редактор текста для React, с поддержкой изображений, цветов и стилей текста. Зависит от React 19+, Tailwind v4 и shadcn/ui Tiptap هو محرر نص متقدم لل-react، يدعم الصور والألوان وأساليب النص. يعتمد على React 19+ و Tailwind v4 و shadcn/ui how to use tiptap tiptap install tiptap setup guide what is tiptap tiptap alternative tiptap vs quill next.js 16 portfolio custom shadcn registry react 19+ compatible Tiptap 富文本编辑器 React Tailwind shadcn/ui 快速入门 AI工具 前端开发 Utilizes @tiptap/react@3.16.0 for rich text editing Compatible with React 19+ for seamless integration Supports custom shadcn registry for enhanced portfolio customization Includes @tiptap/extension-image for image handling Features @tiptap/extension-color for color customization Utilizes @tiptap/starter-kit@3.16.0 for quick setup Tiptap is a rich text editor designed for Next.js 16 portfolios, featuring a custom shadcn registry and compatibility with React and Tailwind.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('specture-system/specture/specture', 'community', 'specture-system', 'specture', 'specture-system/specture', 'specture', 0, 0, 42, '2026-03-08T01:57:15.462Z', '2026-03-08T02:09:15.992Z', '6666671a8a4c3f709e755338eb87877811718e5b3e2c762d8c71189dbbfb25a2', '{"id":"specture-system/specture/specture","name":"specture","description":{"en":"Specture is a spec-driven software architecture system that helps developers plan and implement changes. It benefits development teams by providing a structured approach to feature development and refactoring.","zh":"Specture是一种设计文档驱动的开发系统，通过Specs目录和YAML前置字段实现规范驱动开发","ja":"Spectureは仕様駆動型ソフトウェアアーキテクチャシステムであり、SpecsディレクトリとYAMLフロントマターを使用して開発を行う","ko":"Specture는 설계 문서駆动 개발 시스템으로, Specs 디렉토리와 YAML 전置 필드를 사용하여 개발을 진행한다","es":"Specture es un sistema de arquitectura de software basado en especificaciones que utiliza documentos de diseño en el directorio specs/. Cada especificación contiene la justificación del diseño, las decisiones y una lista de tareas de implementación.","fr":"Specture est un système d''architecture logicielle piloté par spécifications qui utilise des documents de conception dans le répertoire specs/. Chaque spécification contient la justification de la conception, les décisions et une liste de tâches d''implémentation.","de":"Specture ist ein spezifikationsbasiertes Software-Architektur-System, das Design-Dokumente im specs/-Verzeichnis verwendet. Jede Spezifikation enthält die Designbegründung, die Entscheidungen und eine Liste von Implementierungsaufgaben.","pt":"O Specture é um sistema de desenvolvimento baseado em especificações, que utiliza documentos de design para descrever mudanças planejadas","ru":"Specture - это система разработки на основе спецификаций, которая использует документы дизайна для описания запланированных изменений","ar":"Specture هو نظام هن