INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dallay/cvix/zod-4', 'zod-4', 'dallay', 'cvix', 'community', 'zod-4 dallay cvix community zod-4 is a powerful validation library for Astro and Vue projects, providing best practices for schema definitions, parsing, and error handling. It benefits developers working with complex data validation and form integration. Zod 4 是一个用于 Astro 和 Vue 项目的 schema 定义和解析工具 Zod 4 は Astro と Vue プロジェクトで使用するためのスキーマ定義と解析ツールです Zod 4는 Astro와 Vue 프로젝트에서 사용하는 스키마 정의 및 파싱 도구입니다 zod-4 es una herramienta para la validación de datos en Astro y Vue, que ofrece mejores prácticas para esquemas, parsing y manejo de errores zod-4 est un outil de validation de données pour Astro et Vue, qui propose des meilleures pratiques pour les schémas, le parsing et la gestion des erreurs zod-4 ist ein Tool für die Datenvalidierung in Astro und Vue, das Best Practices für Schemata, Parsing und Fehlerbehandlung bietet O Zod 4 oferece melhores práticas para definição de esquemas, parsing, transformações, tratamento de erros e integração com formulários em projetos Astro e Vue Zod 4 предоставляет лучшие практики для определения схем, парсинга, трансформаций, обработки ошибок и интеграции с формами в проектах Astro и Vue زود 4 يقدم أفضل الممارسات لتعريف مخططات، تحليل، تحويلات، معالجة الأخطاء وتكامل النماذج في مشاريع استرو وفيو how to use zod-4 zod-4 vs zod-3 zod-4 setup guide zod-4 astro integration zod-4 vue tutorial what is zod-4 Zod 4 Astro Vue schema 定义 数据解析 表单集成 错误处理 tree-shaking 性能优化 JavaScript 库 Supports schema definitions using z.string().email() and z.email() Provides parsing and transformations for complex data types Offers error handling and form integration for Astro and Vue projects Includes a migration guide from Zod 3 to Zod 4 for seamless upgrades Allows for tree-shaking and better performance with recommended methods zod-4 is a JavaScript library for validating and parsing data, providing a robust set of tools for defining schemas, handling errors, and integrating with popular frameworks like Astro and Vue.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('FinesseAC/windows-ai-dev-station/Code Review', 'community', 'FinesseAC', 'windows-ai-dev-station', 'FinesseAC/windows-ai-dev-station', 'Code Review', 0, 0, 42, '2026-03-08T01:57:15.466Z', '2026-03-08T02:09:26.693Z', '997cbd1f97e88dd31df3f82fc698b08ced8d2eb4379ad98b7d9c2a2118aaccfe', '{"id":"FinesseAC/windows-ai-dev-station/Code Review","name":"Code Review","description":{"en":"The Code Review skill provides a comprehensive review methodology for AI agents, ensuring correctness, security, and error handling. This skill benefits developers working with Windows 11 and AutoHotkey.","zh":"代码审查是一种保证代码质量和安全性的方法，包括检查代码的正确性、安全性和错误处理等方面","ja":"コードレビューは、コードの品質とセキュリティを保証するための方法です。正しさ、セキュリティ、エラーハンドリングなどをチェックします","ko":"코드 리뷰는 코드의 품질과 보안을 보장하는 방법입니다. 올바름, 보안, 오류 처리 등을 확인합니다","es":"La revisión de código es un proceso crucial para garantizar la calidad del software. Nuestra guía de configuración ayuda a los desarrolladores a configurar una estación de desarrollo eficaz","fr":"La revue de code est un processus crucial pour garantir la qualité des logiciels. Notre guide de configuration aide les développeurs à configurer une station de développement efficace","de":"Die Code-Überprüfung ist ein entscheidender Prozess, um die Qualität der Software zu gewährleisten. Unser Einrichtungsleitfaden hilft Entwicklern, eine effektive Entwicklungsstation zu konfigurieren","pt":"Revisão de código automatizada com AutoHotkey e scripts de automação para garantir a correção e segurança do código","ru":"Автоматизированная проверка кода с помощью AutoHotkey и скриптов автоматизации для обеспечения корректности и безопасности кода","ar":"مراجعة الكود الآلية باستخدام AutoHotkey وبرامج نصية للتحكم في ضمان صحة وسلامة الكود"},"seo":{"title":{"en":"Code Review: Comprehensive Review Checklist for AI Agents...","zh":"代码审查最佳实践指南 - AI代码审查工具","ja":"コードレビューのためのAIエージェント設定ガイド","ko":"코드 리뷰 프로토콜 설정 가이드 - AI 코드 리뷰 도구","es":"Guía de Configuración de Revisión de Código para Desarrol...","fr":"Guide de Configuration de la Revue de Code pour les Dével...","de":"Einrichtungsleitfaden für Code-Review mit AI-Tools für En...","pt":"Guia de Configuração de Revisão de Código para Desenvolve...","ru":"Настройка ИИ Агента для Проверки Код: Лучшие Практики","ar":"دليل إعداد مراجعة الكود لل.AI Tools"},"description":{"en":"Discover how to implement a robust code review protocol with our AI-Native Dev Station, featuring AutoHotkey hotkeys and MCP configs. Get started with our se...","zh":"了解代码审查的重要性和实施方法，包括正确性、安全性和错误处理等方面","ja":"コードレビューの重要性と実装方法について説明します。正しさ、セキュリティ、エラーハンドリングなど","ko":"코드 리뷰의 중요성과 구현 방법을 알아보세요. 올바름, 보안, 오류 처리 등","es":"Aprende a configurar una estación de desarrollo nativa de Windows 11 con AutoHotkey y scripts de automatización para una revisión de código eficaz","fr":"Découvrez comment configurer une station de développement native Windows 11 avec AutoHotkey et des scripts d''automatisation pour une revue de code efficace","de":"Erfahren Sie, wie Sie eine native Windows 11-Entwicklungsstation mit AutoHotkey und Automatisierungsskripten für eine effektive Code-Überprüfung konfigurieren","pt":"Aprenda a configurar uma estação de desenvolvimento nativa do Windows 11 com AutoHotkey e scripts de automação para revisão de código","ru":"Узнайте, как настроить ИИ Агент для проверки кода с помощью AutoHotkey и скриптов автоматизации в среде Windows 11","ar":"تعرف على كيفية إعداد محطة تطوير AI الأصيلة من Windows 11 مع AutoHotkey وبرامج نصية للتحكم في مراجعة الكود"},"definition":{"en":"Code Review is a systematic examination of code to detect errors, security vulnerabilities, and correctness issues, using a review checklist with criteria for correctness and security.","zh":"代码审查是一种系统化的代码检查和验证过程，用于发现和修复代码中的错误和安全漏洞","ja":"コードレビューは、コードのエラーとセキュリティホールを発見して修正するためのシステム的なコードチェックと検証プロセスです","ko":"코드 리뷰는 코드의 오류와 보안 허점을 발견하고 수정하기 위한 체계적인 코드 검사와 검증 과정입니다","es":"La revisión de código es un proceso de verificación de la calidad del software que implica la revisión del código fuente","fr":"La revue de code est un processus de vérification de la qualité des logiciels qui implique la révision du code source","de":"Die Code-Überprüfung ist ein Verifizierungsprozess der Softwarequalität, der die Überprüfung des Quellcodes beinhaltet","pt":"Revisão de código é um processo de verificação do código para garantir sua correção e segurança","ru":"Проверка кода - это процесс верификации кода для обеспечения его корректности и безопасности","ar":"مراجعة الكود هي عملية التحقق من الكود لضمان صحته وسلامته"},"features":{"en":["Correctness review using a checklist with criteria for edge cases and error handling","Security review with checks for hardcoded secrets, input validation, and SQL injection prevention","Support for AutoHotkey hotkeys and MCP configs for automation scripts","Error condition handling and logic validation for all inputs","XSS prevention using output validation and parameterized queries"],"zh":["代码正确性检查","安全性检查，包括输入验证和SQL注入防御","错误处理和边界条件检查","AutoHotkey热键和MCP配置支持","自动化脚本支持"],"ja":["コードの正しさのチェック","セキュリティチェック，入力検証とSQLインジェクション防御を含む","エラーハンドリングと境界条件のチェック","AutoHotkeyホットキーとMCP設定のサポート","自動化スクリプトのサポート"],"ko":["코드의 올바름을 확인","보안性 확인, 입력 검증 및 SQL 인젝션 방어 포함","오류 처리 및 경계 조건 확인","AutoHotkey 핫키 및 MCP 설정 지원","자동화 스크립트 지원"],"es":["Protocolo de revisión de código integral","Lista de verificación para la corrección del código","Seguridad con validación de entrada y prevención de inyección SQL","Automatización con scripts de AutoHotkey","Configuración de estación de desarrollo nativa de Windows 11"],"fr":["Protocole de revue de code complet","Liste de vérification pour la correction du code","Sécurité avec validation des entrées et prévention des injections SQL","Automatisation avec des scripts AutoHotkey","Configuration de la station de développement native Windows 11"],"de":["Umfassendes Code-Review-Protokoll","Prüfliste für die Korrektheit des Codes","Sicherheit mit Eingabevalidierung und SQL-Injektionsschutz","Automatisierung mit AutoHotkey-Skripten","Konfiguration der nativen Windows 11-Entwicklungsstation"],"pt":["Verificação de correção do código","Tratamento de condições de erro","Prevenção de injeção de SQL","Prevenção de XSS","Uso de AutoHotkey para automação","Uso de scripts de automação para revisão de código"],"ru":["Проверка корректности кода","Обработка ошибок","Предотвращение внедрения SQL","Предотвращение XSS","Использование AutoHotkey для автоматизации","Использование скриптов автоматизации для проверки кода"],"ar":["التحقق من صحة الكود","معالجة حالات الخطأ","منع الحقن SQL","منع XSS","استخدام AutoHotkey للتحكم الآلي","استخدام برامج نصية للتحكم في مراجعة الكود"]},"keywords":{"en":["how to use Code Review","what is Code Review","Code Review protocol","Code Review alternative","Code Review vs manual review","Code Review install guide","Code Review setup for Windows 11","AutoHotkey hotkeys for Code Review","MCP configs for Code Review automation"],"zh":["代码审查","AI代码审查工具","代码质量保证","代码安全性检查","AutoHotkey","MCP配置","自动化脚本","代码正确性检查","安全性检查"],"ja":["コードレビュー","AIエージェント","コード品質保証","コードセキュリティチェック","AutoHotkey","MCP設定","自動化スクリプト","コードの正しさのチェック","セキュリティチェック"],"ko":["코드 리뷰","AI 코드 리뷰 도구","코드 품질 보장","코드 보안성 확인","AutoHotkey","MCP 설정","자동화 스크립트","코드의 올바름을 확인","보안성 확인"],"es":["revisión de código","desarrollo de software","herramientas AI","AutoHotkey","scripts de automatización","estación de desarrollo nativa de Windows 11","seguridad del código","validación de entrada"],"fr":["revue de code","développement de logiciels","outils IA","AutoHotkey","scripts d''automatisation","station de développement native Windows 11","sécurité du code","validation des entrées"],"de":["Code-Überprüfung","Software-Entwicklung","AI-Tools","AutoHotkey","Automatisierungsskripte","native Windows 11-Entwicklungsstation","Code-Sicherheit","Eingabevalidierung"],"pt":["revisão de código","desenvolvimento de software","AutoHotkey","scripts de automação","segurança do código","correção do código","prevenção de erros","desenvolvedores","ferramentas de desenvolvimento"],"ru":["проверка кода","разработка программного обеспечения","AutoHotkey","скрипты автоматизации","безопасность кода","корректность кода","предотвращение ошибок","разработчики","инструменты разработки"],"ar":["مراجعة الكود","تطوير البرمجيات","AutoHotkey","برامج نصية","سلامة الكود","صحة الكود","منع الأخطاء","مطورين","أدوات التطوير"]}},"owner":"FinesseAC","repo":"windows-ai-dev-station","repoPath":"FinesseAC/windows-ai-dev-station","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.466Z","topics":[],"category":"community","skillMd":{"name":"Code Review","description":"Thorough code review with security, performance, and maintainability analysis","bodyPreview":"# Code Review Protocol\n\nA comprehensive code review methodology that catches issues before they reach production.\n\n## Review Checklist\n\n### 1. Correctness\n\n- [ ] Does the code do what it''s supposed to do?\n- [ ] Are all edge cases handled?\n- [ ] Are error conditions handled properly?\n- [ ] Is the logic correct for all inputs?\n\n### 2. Security\n\n- [ ] No hardcoded secrets or credentials\n- [ ] Input validation present\n- [ ] SQL injection prevention (parameterized queries)\n- [ ] XSS prevention (outpu","body":"# Code Review Protocol\n\nA comprehensive code review methodology that catches issues before they reach production.\n\n## Review Checklist\n\n### 1. Correctness\n\n- [ ] Does the code do what it''s supposed to do?\n- [ ] Are all edge cases handled?\n- [ ] Are error conditions handled properly?\n- [ ] Is the logic correct for all inputs?\n\n### 2. Security\n\n- [ ] No hardcoded secrets or credentials\n- [ ] Input validation present\n- [ ] SQL injection prevention (parameterized queries)\n- [ ] XSS prevention (output encoding)\n- [ ] CSRF protection where needed\n- [ ] Proper authentication/authorization checks\n- [ ] Sensitive data properly protected\n\n### 3. Performance\n\n- [ ] No obvious N+1 query issues\n- [ ] Appropriate data structures used\n- [ ] No unnecessary loops or iterations\n- [ ] Database queries optimized\n- [ ] Caching considered where appropriate\n- [ ] Memory leaks prevented (cleanup handlers)\n\n### 4. Maintainability\n\n- [ ] Code is readable and self-documenting\n- [ ] Functions are focused and not too long\n- [ ] No excessive nesting\n- [ ] Consistent naming conventions\n- [ ] Appropriate abstractions used\n- [ ] No code duplication\n\n### 5. Testing\n\n- [ ] New code has corresponding tests\n- [ ] Edge cases tested\n- [ ] Error paths tested\n- [ ] Tests are meaningful (not just coverage)\n\n### 6. Documentation\n\n- [ ] Complex logic is explained\n- [ ] Public APIs are documented\n- [ ] Non-obvious decisions are commented\n- [ ] README updated if needed\n\n## Review Output Format\n\n```markdown\n## Code Review Summary\n\n**Files Reviewed**: [list]\n**Overall Assessment**: [APPROVE / REQUEST_CHANGES / NEEDS_DISCUSSION]\n\n### Critical Issues (Must Fix)\n- [ ] Issue 1: Description - Location - Suggested fix\n\n### Important Issues (Should Fix)\n- [ ] Issue 1: Description - Location - Suggested fix\n\n### Suggestions (Consider)\n- [ ] Suggestion 1: Description - Location - Rationale\n\n### Positive Observations\n- Good practice 1: Description\n- Good practice 2: Description\n```\n\n## Severity Levels\n\n- **Critical**: Security vulnerabilities, data loss risks, crashes\n- **Important**: Bugs, performance issues, maintainability problems\n- **Suggestion**: Style improvements, minor optimizations, nice-to-haves\n\n## Review Best Practices\n\n1. Be specific and actionable in feedback\n2. Explain the \"why\" not just the \"what\"\n3. Suggest alternatives, don''t just criticize\n4. Acknowledge good code, not just problems\n5. Focus on the code, not the person\n6. Prioritize feedback by severity\n"},"lastSynced":"2026-03-08T02:09:26.693Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Analysis Agents specializing in software security and correctness validation.","zh":"非常适合专门从事软件安全和正确性验证的代码分析代理。","ja":"ソフトウェアのセキュリティと正しさの検証を専門とするコード分析エージェントに最適です。","ko":"소프트웨어 보안 및 올바름 검증을 전문으로 하는 코드 분석 에이전트에 적합합니다.","es":"Perfecto para Agentes de Análisis de Código especializados en seguridad y validación de corrección de software.","fr":"Parfait pour les Agents d''Analyse de Code spécialisés dans la sécurité et la validation de correction de logiciels.","de":"Perfekt für Code-Analyse-Agents, die auf Software-Sicherheit und Korrektheitsvalidierung spezialisiert sind.","pt":"Perfeito para Agentes de Análise de Código especializados em segurança de software e validação de correção.","ru":"Идеально подходит для агентов анализа кода, специализирующихся на безопасности программного обеспечения и проверке корректности.","ar":"مثالي للوكلاء قادرون على تحليل الشفرة المتخصصة في أمان البرمجيات والتحقق من الصحة."},"recommendation":{"en":"Provides comprehensive code review methodology ensuring correctness, security, and error handling. Specifically validates edge case handling, input validation, SQL injection prevention, and XSS prevention protocols.","zh":"提供全面性的代码审查方法，确保正确性、安全性和错误处理。特别验证边缘情况处理、输入验证、SQL 注入防护和 XSS 防护协议。","ja":"正しさ、セキュリティ、およびエラー処理を保証するための包括的なコードレビューメソッドを提供します。特に、エッジケースの処理、入力の検証、SQL インジェクション防止、およびXSS防止プロトコルを検証します。","ko":"올바름, 보안 및 오류 처리를 보장하는 포괄적인 코드 리뷰 방법을 제공합니다. 특히, 에지 케이스 처리, 입력 검증, SQL 인젝션 방지 및 XSS 방지 프로토콜을 검증합니다.","es":"Proporciona una metodología de revisión de código integral que garantiza la corrección, la seguridad y el control de errores. Valida específicamente el manejo de casos límite, la validación de entrada, la prevención de inyección SQL y los protocolos de prevención de XSS.","fr":"Fournit une méthodologie de revue de code globale garantissant la correction, la sécurité et la gestion des erreurs. Valide spécifiquement la gestion des cas limites, la validation des entrées, la prévention des injections SQL et les protocoles de prévention de XSS.","de":"Bietet eine umfassende Code-Review-Methodik, die Korrektheit, Sicherheit und Fehlerbehandlung gewährleistet. Validiert insbesondere die Behandlung von Randfällen, die Eingabevalidierung, die Verhinderung von SQL-Injection und die XSS-Präventionsprotokolle.","pt":"Fornece uma metodologia abrangente de revisão de código que garante a correção, a segurança e o tratamento de erros. Specificamente valida o tratamento de casos de bordo, a validação de entrada, a prevenção de injeção de SQL e os protocolos de prevenção de XSS.","ru":"Предоставляет комплексную методологию проверки кода, обеспечивающую правильность, безопасность и обработку ошибок. Конкретно проверяет обработку граничных случаев, проверку входных данных, предотвращение внедрения SQL и протоколы предотвращения XSS.","ar":"توفر منهجية شاملة لاستعراض الشفرة تضمن الصحة والأمان ومعالجة الأخطاء. تحقق بشكل خاص من معالجة الحالات الحدية وتصديق الإدخال ومنع حقن SQL وبروتوكولات منع XSS."},"useCases":{"en":["Validating AutoHotkey script security","Identifying hardcoded credentials in Windows 11 applications","Detecting SQL injection vulnerabilities in parameterized queries","Ensuring proper error condition handling"],"zh":["验证AutoHotkey脚本的安全性","在Windows 11应用程序中识别硬编码凭据","检测参数化查询中的SQL注入漏洞","确保正确的错误条件处理"],"ja":["AutoHotkeyスクリプトのセキュリティを検証する","Windows 11アプリケーションでハードコードされた資格情報を識別する","パラメータ化されたクエリでのSQLインジェクション脆弱性を検出する","適切なエラーコンディションの処理を確保する"],"ko":["AutoHotkey 스크립트의 보안을 검증하는 것","Windows 11 애플리케이션에서 하드코딩된 자격 증명을 식별하는 것","파라미터화된 쿼리에서 SQL 인젝션 취약점을 감지하는 것","적절한 오류 조건 처리를 보장하는 것"],"es":["Validar la seguridad de los scripts AutoHotkey","Identificar credenciales codificadas en aplicaciones de Windows 11","Detectar vulnerabilidades de inyección SQL en consultas parametrizadas","Garantizar el manejo adecuado de condiciones de error"],"fr":["Valider la sécurité des scripts AutoHotkey","Identifier les informations d''identification codées dans les applications Windows 11","Détecter les vulnérabilités d''injection SQL dans les requêtes paramétrées","Assurer une gestion appropriée des conditions d''erreur"],"de":["Die Sicherheit von AutoHotkey-Skripten überprüfen","Gehärtete Anmeldeinformationen in Windows 11-Anwendungen identifizieren","SQL-Injection-Schwachstellen in parametrisierten Abfragen erkennen","Eine ordnungsgemäße Fehlerzustandsbehandlung sicherstellen"],"pt":["Validar a segurança do script AutoHotkey","Identificar credenciais codificadas no Windows 11","Detectar vulnerabilidades de injeção de SQL em consultas parametrizadas","Garantir o tratamento adequado de condições de erro"],"ru":["Проверка безопасности скриптов AutoHotkey","Определение зашитых учетных данных в приложениях Windows 11","Обнаружение уязвимостей внедрения SQL в параметризованных запросах","Обеспечение правильной обработки условий ошибок"],"ar":["التحقق من أمان سكريبت AutoHotkey","تحديد بيانات تسجيل الدخول المدمجة في تطبيقات Windows 11","اكتشاف نقاط الضعف في حقن SQL في الاستفسارات المُقترنة","ضمان التعامل المناسب مع حالات الخطأ"]},"limitations":{"en":["Windows 11 and AutoHotkey specific optimizations","Requires complete codebase access for comprehensive review"],"zh":["仅针对Windows 11和AutoHotkey的优化","需要完整的代码库访问权限以进行全面审查"],"ja":["Windows 11およびAutoHotkey専用の最適化","包括的なレビューを行うにはコードベースへの完全なアクセスが必要"],"ko":["Windows 11 및 AutoHotkey 전용 최적화","포괄적인 검토를 수행하려면 코드베이스에 대한 완전한 액세스가 필요함"],"es":["Optimizaciones específicas de Windows 11 y AutoHotkey","Requiere acceso completo al código base para una revisión integral"],"fr":["Optimisations spécifiques à Windows 11 et AutoHotkey","Nécessite un accès complet au code base pour une revue globale"],"de":["Optimierungen speziell für Windows 11 und AutoHotkey","Benötigt vollen Zugriff auf den Codebase für eine umfassende Überprüfung"],"pt":["Otimizações específicas para Windows 11 e AutoHotkey","Requer acesso completo à base de código para revisão abrangente"],"ru":["Оптимизации, специфичные для Windows 11 и AutoHotkey","Требуется полный доступ к базе кода для всестороннего обзора"],"ar":["تحسينات محددة لويندوز 11 وأوتوهوتكيه","يتطلب الوصول الكامل إلى قاعدة الشفرة لاستعراض شامل"]},"version":4},"contentHash":"997cbd1f97e88dd31df3f82fc698b08ced8d2eb4379ad98b7d9c2a2118aaccfe","qualityScore":42}');
