INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('FinesseAC/windows-ai-dev-station/Code Review', 'Code Review', 'FinesseAC', 'windows-ai-dev-station', 'community', 'Code Review FinesseAC windows-ai-dev-station community The Code Review skill provides a comprehensive review methodology for AI agents, ensuring correctness, security, and error handling. This skill benefits developers working with Windows 11 and AutoHotkey. 代码审查是一种保证代码质量和安全性的方法，包括检查代码的正确性、安全性和错误处理等方面 コードレビューは、コードの品質とセキュリティを保証するための方法です。正しさ、セキュリティ、エラーハンドリングなどをチェックします 코드 리뷰는 코드의 품질과 보안을 보장하는 방법입니다. 올바름, 보안, 오류 처리 등을 확인합니다 La revisión de código es un proceso crucial para garantizar la calidad del software. Nuestra guía de configuración ayuda a los desarrolladores a configurar una estación de desarrollo eficaz La revue de code est un processus crucial pour garantir la qualité des logiciels. Notre guide de configuration aide les développeurs à configurer une station de développement efficace Die Code-Überprüfung ist ein entscheidender Prozess, um die Qualität der Software zu gewährleisten. Unser Einrichtungsleitfaden hilft Entwicklern, eine effektive Entwicklungsstation zu konfigurieren Revisão de código automatizada com AutoHotkey e scripts de automação para garantir a correção e segurança do código Автоматизированная проверка кода с помощью AutoHotkey и скриптов автоматизации для обеспечения корректности и безопасности кода مراجعة الكود الآلية باستخدام AutoHotkey وبرامج نصية للتحكم في ضمان صحة وسلامة الكود how to use Code Review what is Code Review Code Review protocol Code Review alternative Code Review vs manual review Code Review install guide Code Review setup for Windows 11 AutoHotkey hotkeys for Code Review MCP configs for Code Review automation 代码审查 AI代码审查工具 代码质量保证 代码安全性检查 AutoHotkey MCP配置 自动化脚本 代码正确性检查 安全性检查 Correctness review using a checklist with criteria for edge cases and error handling Security review with checks for hardcoded secrets, input validation, and SQL injection prevention Support for AutoHotkey hotkeys and MCP configs for automation scripts Error condition handling and logic validation for all inputs XSS prevention using output validation and parameterized queries Code Review is a systematic examination of code to detect errors, security vulnerabilities, and correctness issues, using a review checklist with criteria for correctness and security.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('weunica/payboxCLI-App/wds-docs', 'community', 'weunica', 'payboxCLI-App', 'weunica/payboxCLI-App', 'wds-docs', 0, 0, 42, '2026-03-08T01:57:15.470Z', '2026-03-08T02:09:33.899Z', 'd44ea78ed8f087f2064aa84f0a974ab133985d1440f8b9fc1ccd262e600c4b16', '{"id":"weunica/payboxCLI-App/wds-docs","name":"wds-docs","description":{"en":"The wds-docs skill enables developers to efficiently navigate WDS documentation by searching components using grep commands. It benefits developers working with WDS by providing a staged discovery flow.","zh":"WDS 文档导航器帮助开发者快速找到组件和功能，提高开发效率","ja":"WDS ドキュメントナビゲーターは、開発者がコンポーネントと機能を迅速に探し、開発効率を向上させるのに役立ちます","ko":"WDS 문서 네비게이터는 개발자가 컴포넌트와 기능을 빠르게 찾고 개발 효율성을 높이는 데 도움을 줍니다","es":"wds-docs es una herramienta de navegación de documentación que permite a los desarrolladores encontrar componentes por características o palabras clave.","fr":"wds-docs est un outil de navigation de documentation qui permet aux développeurs de trouver des composants par fonctionnalités ou mots clés.","de":"wds-docs ist ein Tool zur Navigation von Dokumentationen, mit dem Entwickler Komponenten nach Funktionen oder Schlüsselwörtern finden können.","pt":"O wds-docs é uma ferramenta de navegação de documentação que ajuda os desenvolvedores a encontrar componentes e recursos rapidamente","ru":"ИИ Агент wds-docs - это инструмент навигации по документации, который помогает разработчикам быстро находить компоненты и ресурсы","ar":"ووس-دوس هو أداة مُصممة للمطورين لتصفح الوثائق بسهولة وسرعة"},"seo":{"title":{"en":"wds-docs: WDS Documentation Navigator Setup Guide | AI Ag...","zh":"WDS 文档导航器快速入门","ja":"WDS ドキュメントナビゲーター設定ガイド - AIエージェント","ko":"WDS 문서 네비게이터 설정 가이드","es":"Guía de configuración de wds-docs para desarrolladores","fr":"Guide de démarrage rapide pour wds-docs pour les développ...","de":"Einrichtungsleitfaden für wds-docs: Beste Praktiken","pt":"Guia de Configuração do wds-docs: Navegação de Documentação","ru":"ИИ Агент wds-docs: Настройка и Навигация по Документации","ar":"إعداد وثائق ويس-دوس: دليل المطورين"},"description":{"en":"Discover how to navigate WDS documentation efficiently using the wds-docs skill. Learn to search components by feature and keyword with grep commands.","zh":"使用 WDS 文档导航器快速找到组件和功能，提高开发效率","ja":"WDS ドキュメントナビゲーターを使用してコンポーネントと機能を迅速に探し、開発効率を向上させる","ko":"WDS 문서 네비게이터를 사용하여 컴포넌트와 기능을 빠르게 찾고 개발 효율성을 높여보세요","es":"Descubre cómo configurar wds-docs para mejorar tu flujo de trabajo de desarrollo con las mejores prácticas","fr":"Découvrez comment configurer wds-docs pour améliorer votre flux de travail de développement avec les meilleures pratiques","de":"Erfahren Sie, wie Sie wds-docs einrichten, um Ihren Entwicklungsprozess mit den besten Praktiken zu optimieren","pt":"Aprenda a configurar e navegar pela documentação do wds-docs com nosso guia passo a passo para desenvolvedores","ru":"Узнайте, как настроить и ориентироваться в документации wds-docs с помощью нашего пошагового руководства для разработчиков","ar":"تعلم كيفية إعداد وثائق ويس-دوس وتصفحها باستخدام دليلنا المطور خطوة بخطوة"},"definition":{"en":"wds-docs is a WDS Documentation Navigator that facilitates searching components by feature or keyword, following a staged discovery flow to optimize documentation exploration.","zh":"WDS 文档导航器是一种用于快速查找和导航 WDS 组件和功能的工具","ja":"WDS ドキュメントナビゲーターは、WDS コンポーネントと機能を迅速に探索するためのツールです","ko":"WDS 문서 네비게이터는 WDS 컴포넌트와 기능을 빠르게 탐색하는 데 사용되는 도구입니다","es":"wds-docs es un agente de inteligencia artificial para la navegación de documentación de diseño de sistemas","fr":"wds-docs est un agent d''intelligence artificielle pour la navigation de documentation de conception de systèmes","de":"wds-docs ist ein künstliches Intelligenz-Tool für die Navigation von Design-Systemdokumentationen","pt":"O wds-docs é um agente de navegação de documentação que fornece acesso rápido a componentes e recursos de design","ru":"ИИ Агент wds-docs - это агент навигации по документации, который обеспечивает быстрый доступ к компонентам и ресурсам дизайна","ar":"ووس-دوس هو أداة تصفح وثائق تقدم الوصول السريع إلى مكونات و موارد التصميم"},"features":{"en":["Searches components by feature or keyword using grep commands","Follows a staged discovery flow to optimize documentation exploration","Navigates through WDS documentation files without reading entire files","Provides component name, description, and do/don''ts as output","Utilizes node_modules/@wix/design-system/dist/docs/ for documentation"],"zh":["支持 grep 命令快速查找组件","提供组件名称、描述和使用注意事项","支持多阶段发现流程","集成 WDS 文档和组件库"],"ja":["grep コマンドによるコンポーネントの迅速な検索","コンポーネント名、説明、使用注意事項の提供","マルチステージの発見プロセスのサポート","WDS ドキュメントとコンポーネントライブラリの統合"],"ko":["grep 명령을 통한 컴포넌트 빠른 검색","컴포넌트 이름, 설명, 사용 注意事項 제공","다단계 발견 프로세스 지원","WDS 문서와 컴포넌트 라이브러리 통합"],"es":["Búsqueda de componentes por características o palabras clave","Seguimiento del flujo de descubrimiento por etapas","Compatibilidad con comandos de grep para búsqueda avanzada","Salida de nombres de componentes, descripciones y recomendaciones","Integración con la ruta de documentos `node_modules/@wix/design-system/dist/docs/`"],"fr":["Recherche de composants par fonctionnalités ou mots clés","Suivi du flux de découverte par étapes","Compatibilité avec les commandes de grep pour une recherche avancée","Sortie des noms de composants, des descriptions et des recommandations","Intégration avec le chemin de documents `node_modules/@wix/design-system/dist/docs/`"],"de":["Suche nach Komponenten nach Funktionen oder Schlüsselwörtern","Verfolgung des Entdeckungsflusses in Stufen","Kompatibilität mit Grep-Befehlen für erweiterte Suche","Ausgabe von Komponentennamen, Beschreibungen und Empfehlungen","Integration mit dem Dokumentenpfad `node_modules/@wix/design-system/dist/docs/`"],"pt":["Navegação de documentação eficiente","Pesquisa de componentes por recurso ou palavra-chave","Saída de nome do componente, descrição e diretrizes de uso","Integração com CLI para grep e pesquisa","Suporte a arquivos de documentação de grande escala (200-900+ linhas)"],"ru":["Эффективная навигация по документации","Поиск компонентов по функции или ключевому слову","Выдача имени компонента, описания и руководства по использованию","Интеграция с CLI для grep и поиска","Поддержка документации крупномасштабных файлов (200-900+ строк)"],"ar":["التنقل في وثائق الكفاءة","البحث عن المكونات من خلال الميزة أو الكلمة الرئيسية","إخراج اسم المكون ووصفه وإرشادات الاستخدام","التكامل مع CLI من أجل grep والبحث","دعم ملفات الوثائق ذات الحجم الكبير (200-900+ سطر)"]},"keywords":{"en":["how to use wds-docs","wds-docs setup guide","wds-docs documentation navigator","wds-docs alternative","wds-docs vs design system documentation","wds-docs install","grep commands for wds-docs","wds-docs for developers","wds-docs staged discovery flow"],"zh":["WDS 文档导航器","AI 文档工具","组件快速查找","WDS 开发效率","grep 命令","WDS 文档库","AIエージェント"],"ja":["WDS ドキュメントナビゲーター","AI ドキュメントツール","コンポーネントの迅速な検索","WDS 開発効率","grep コマンド","WDS ドキュメントライブラリ","AIエージェント"],"ko":["WDS 문서 네비게이터","AI 문서 도구","컴포넌트 빠른 검색","WDS 개발 효율성","grep 명령","WDS 문서 라이브러리","AI 에이전트"],"es":["wds-docs","navegación de documentación","diseño de sistemas","agente de inteligencia artificial","herramienta de desarrollo","grep","búsqueda de componentes","flujo de descubrimiento"],"fr":["wds-docs","navigation de documentation","conception de systèmes","agent d''intelligence artificielle","outil de développement","grep","recherche de composants","flux de découverte"],"de":["wds-docs","Dokumentationsnavigation","Design-System","künstliches Intelligenz-Tool","Entwicklungstool","grep","Komponentensuche","Entdeckungsfluss"],"pt":["wds-docs","navegação de documentação","componentes de design","CLI","grep","pesquisa de componentes","desenvolvimento de software","ferramentas de desenvolvedor"],"ru":["ИИ Агенты","wds-docs","навигация по документации","компоненты дизайна","CLI","grep","поиск компонентов","разработка программного обеспечения","инструменты разработчика"],"ar":["أدوات الذكاء الاصطناعي","ووس-دوس","التنقل في الوثائق","مكونات التصميم","CLI","grep","بحث المكونات","تطوير البرمجيات","أدوات المطور"]}},"owner":"weunica","repo":"payboxCLI-App","repoPath":"weunica/payboxCLI-App","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.470Z","topics":[],"category":"community","skillMd":{"name":"wds-docs","description":"Wix Design System component reference. Use when building UI with @wix/design-system, choosing components, or checking props and examples. Triggers on what component, how do I make, WDS, show me props, or component names like Button, Card, Modal, Box, Text.","bodyPreview":"# WDS Documentation Navigator\n\n**Docs path:** `node_modules/@wix/design-system/dist/docs/`\n\n## CRITICAL: Never Read Entire Files\n\nFiles are 200-900+ lines. Follow the staged discovery flow below.\n\n---\n\n## Stage 1: Find Component\n\n**Goal:** Search for component by feature/keyword\n\n```bash\nGrep: \"table\" in components.md\nGrep: \"form\\|input\\|validation\" in components.md\nGrep: \"modal\\|dialog\\|popup\" in components.md\n```\n\n**Output:** Component name + description + do/don''ts\n\n**Next:** Go to Stage 2 wi","body":"# WDS Documentation Navigator\n\n**Docs path:** `node_modules/@wix/design-system/dist/docs/`\n\n## CRITICAL: Never Read Entire Files\n\nFiles are 200-900+ lines. Follow the staged discovery flow below.\n\n---\n\n## Stage 1: Find Component\n\n**Goal:** Search for component by feature/keyword\n\n```bash\nGrep: \"table\" in components.md\nGrep: \"form\\|input\\|validation\" in components.md\nGrep: \"modal\\|dialog\\|popup\" in components.md\n```\n\n**Output:** Component name + description + do/don''ts\n\n**Next:** Go to Stage 2 with component name\n\n---\n\n## Stage 2: Get Props + Example List\n\n**Goal:** Get props AND discover available examples\n\n```bash\n# 2a. Get props (small files OK to read, large files grep)\nRead: components/ButtonProps.md              # OK if <100 lines\nGrep: \"### disabled\" in components/BoxProps.md -A 3  # Box is huge\n\n# 2b. List available examples (ALWAYS grep, never read)\nGrep: \"^### \" in components/ButtonExamples.md -n\n```\n\n**Output from 2b:**\n```\n5:### Size\n17:### Skin\n71:### Affix\n123:### Disabled\n183:### Loading state\n```\n\n**Next:** Pick example(s) from list, go to Stage 3\n\n---\n\n## Stage 3: Fetch Specific Example\n\n**Goal:** Read only the example you need (~30-50 lines)\n\n```bash\n# Option A: Read with offset (line number from Stage 2)\nRead: components/ButtonExamples.md offset=183 limit=40\n\n# Option B: Grep with context\nGrep: \"### Loading state\" in components/ButtonExamples.md -A 40\n```\n\n**Output:** JSX code example for that specific feature\n\n---\n\n## Stage 4: Icons (when needed)\n\n```bash\nGrep: \"Add\\|Edit\\|Delete\\|Search\" in icons.md\n```\n\n---\n\n## Flow Summary\n\n```\n┌─────────────────────────────────────────────────────────┐\n│ Stage 1: Grep components.md for keyword                 │\n│          → finds: Button, Card, Table...                │\n└────────────────────┬────────────────────────────────────┘\n                     ↓\n┌─────────────────────────────────────────────────────────┐\n│ Stage 2a: Read/Grep {Component}Props.md                 │\n│           → gets: props with types & descriptions       │\n│                                                         │\n│ Stage 2b: Grep \"^### \" in {Component}Examples.md        │\n│           → gets: example names + line numbers          │\n│           \"5:### Size, 71:### Affix, 183:### Loading\"   │\n└────────────────────┬────────────────────────────────────┘\n                     ↓\n┌─────────────────────────────────────────────────────────┐\n│ Stage 3: Read offset=183 limit=40                       │\n│          → gets: specific example JSX code              │\n└────────────────────────────────────────────────────────┘\n```\n\n---\n\n## Example Session: Product Page\n\n```bash\n# Stage 1: Find components\nGrep: \"image\\|card\\|price\" in components.md\n→ Image, Card, Text found\n\n# Stage 2a: Get Card props\nRead: components/CardProps.md\n\n# Stage 2b: List Card examples\nGrep: \"^### \" in components/CardExamples.md -n\n→ 5:### Basic, 25:### With media, 60:### Clickable\n\n# Stage 3: Fetch \"With media\" example\nRead: components/CardExamples.md offset=25 limit=35\n→ Gets Card with Image example code\n\n# Repeat Stage 2-3 for other components as needed\n```\n\n**Result:** ~80 lines read instead of 1500+\n\n---\n\n## Quick Reference\n\n| Stage | Command | Output |\n|-------|---------|--------|\n| 1. Find | `Grep: \"keyword\" in components.md` | Component name |\n| 2a. Props | `Read: {Name}Props.md` | Props list |\n| 2b. Examples | `Grep: \"^### \" in {Name}Examples.md` | Example names + lines |\n| 3. Fetch | `Read: offset=N limit=40` | Example code |\n| 4. Icons | `Grep: \"IconName\" in icons.md` | Icon exists |\n\n---\n\n## File Sizes\n\n| File | Lines | Strategy |\n|------|-------|----------|\n| components.md | ~970 | Grep, never read fully |\n| icons.md | ~400 | Grep for specific icon |\n| Most Props.md | 30-100 | Read fully OK |\n| BoxProps.md | 8000+ | Grep only! |\n| Most Examples.md | 100-600 | Grep → offset read |\n| PageExamples.md | 940 | Grep → offset read |\n\n---\n\n## Grep Patterns by Use Case\n\n```bash\n# Forms\nGrep: \"form\\|input\\|validation\" in components.md\n\n# Layout\nGrep: \"layout\\|page\\|card\\|box\" in components.md\n\n# Data display\nGrep: \"table\\|list\\|badge\" in components.md\n\n# Feedback\nGrep: \"notification\\|toast\\|loader\" in components.md\n```\n\n---\n\n## Quick Component Mapping (Design → WDS)\n\n| Design Element | WDS Component | Notes |\n|----------------|---------------|-------|\n| Rectangle/container | `<Box>` | Layout wrapper |\n| Text button | `<TextButton>` | Secondary actions |\n| Input with label | `<FormField>` + `<Input>` | Wrap inputs |\n| Toggle | `<ToggleSwitch>` | On/off settings |\n| Modal | `<Modal>` + `<CustomModalLayout>` | Use together |\n| Grid | `<Layout>` + `<Cell>` | Responsive |\n\n---\n\n## Spacing (px → SP conversion)\n\nWhen designer specifies pixels, convert to the nearest SP token:\n\n| Token | Classic | Studio |\n|-------|---------|--------|\n| `SP1` | 6px | 4px |\n| `SP2` | 12px | 8px |\n| `SP3` | 18px | 12px |\n| `SP4` | 24px | 16px |\n| `SP5` | 30px | 20px |\n| `SP6` | 36px | 24px |\n\n```tsx\n<Box gap=\"SP2\" padding=\"SP3\">\n```\n\nOnly use SP tokens for `gap`, `padding`, `margin` - not for width/height.\n\n---\n\n## Imports\n\n```tsx\nimport { Button, Card, Image } from ''@wix/design-system'';\nimport { Add, Edit, Delete } from ''@wix/wix-ui-icons-common'';\n```\n"},"lastSynced":"2026-03-08T02:09:33.899Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing efficient WDS documentation navigation and grep command utilization.","zh":"非常适合需要高效的WDS文档导航和grep命令利用的开发代理。","ja":"WDSドキュメントのナビゲーションとgrepコマンドの利用が必要な開発エージェントに最適です。","ko":"WDS 문서 탐색 및 grep 명령 활용이 필요한 개발 에이전트에게 적합합니다.","es":"Perfecto para agentes de desarrollo que necesitan una navegación eficiente de la documentación de WDS y una utilización de comandos grep.","fr":"Parfait pour les agents de développement ayant besoin d''une navigation de documentation WDS efficace et d''une utilisation de commande grep.","de":"Perfekt für Entwicklungsmittel, die eine effiziente WDS-Dokumentationsnavigation und eine Verwendung von grep-Befehlen benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que precisam de navegação eficiente na documentação do WDS e utilização do comando grep.","ru":"Идеально подходит для агентов разработки, которым требуется эффективная навигация по документации WDS и использование команды grep.","ar":"مثالي لعمليات الوكيل التي تحتاج إلى التنقل الفعال في توثيق WDS واستخدام أمر grep."},"recommendation":{"en":"Empowers agents to efficiently search WDS components using grep commands, providing staged discovery flow and access to component descriptions, do''s and don''ts, leveraging `node_modules/@wix/design-system/dist/docs/` for comprehensive content analysis.","zh":"赋予代理高效地使用grep命令搜索WDS组件的能力，提供分阶段的发现流程和访问组件描述、注意事项等，利用`node_modules/@wix/design-system/dist/docs/`进行全面内容分析。","ja":"エージェントがgrepコマンドを使用してWDSコンポーネントを効率的に検索する機能を提供し、段階的な発見フローとコンポーネントの説明、注意事項へのアクセスを提供し、`node_modules/@wix/design-system/dist/docs/`を使用して包括的なコンテンツ分析を実行します。","ko":"에이전트가 grep 명령을 사용하여 WDS 컴포넌트를 효율적으로 검색할 수 있는 기능을 제공하며, 단계적인 발견 흐름과 컴포넌트 설명 및 주의事項에 대한 액세스를 제공하며, `node_modules/@wix/design-system/dist/docs/`를 사용하여 포괄적인 내용 분석을 수행합니다.","es":"Habilita a los agentes a buscar componentes de WDS de manera eficiente utilizando comandos grep, proporcionando un flujo de descubrimiento por etapas y acceso a descripciones de componentes, instrucciones y advertencias, aprovechando `node_modules/@wix/design-system/dist/docs/` para un análisis de contenido integral.","fr":"Permet aux agents de rechercher efficacement les composants WDS à l''aide de commandes grep, fournissant un flux de découverte par étapes et un accès aux descriptions de composants, aux instructions et aux mises en garde, en exploitant `node_modules/@wix/design-system/dist/docs/` pour une analyse de contenu complète.","de":"Ermächtigt die Agenten, WDS-Komponenten mithilfe von grep-Befehlen effizient zu suchen, wodurch ein gestaffelter Entdeckungsfluss und Zugriff auf Komponentenbeschreibungen, Anweisungen und Warnhinweise bereitgestellt werden, die `node_modules/@wix/design-system/dist/docs/` für eine umfassende Inhaltsanalyse nutzen.","pt":"Habilita os agentes a procurar componentes do WDS de forma eficiente usando comandos grep, fornecendo fluxo de descoberta por estágios e acesso a descrições de componentes, o que fazer e o que não fazer, aproveitando `node_modules/@wix/design-system/dist/docs/` para análise de conteúdo abrangente.","ru":"Наделяет агентов возможностью эффективно искать компоненты WDS с помощью команд grep, обеспечивая пошаговый поток открытия и доступ к описаниям компонентов, что делать и чего не делать, используя `node_modules/@wix/design-system/dist/docs/` для всестороннего анализа контента.","ar":"يتمكن العميل من البحث عن مكونات WDS بفعالية باستخدام أوامر grep، وتوفير تدفق اكتشاف مراحل الوصول إلى وصف المكونات، ما يجب فعله وما لا يجب فعله، بالاستفادة من `node_modules/@wix/design-system/dist/docs/` لتحليل المحتوى الشامل."},"useCases":{"en":["Searching components by feature or keyword","Navigating WDS documentation using staged discovery flow","Identifying component names and descriptions"],"zh":["根据功能或关键字搜索组件","使用分阶段的发现流程导航WDS文档","识别组件名称和描述"],"ja":["機能またはキーワードでコンポーネントを検索する","段階的な発見フローを使用してWDSドキュメントをナビゲートする","コンポーネント名と説明を識別する"],"ko":["기능 또는 키워드로 컴포넌트 검색","단계적인 발견 흐름을 사용한 WDS 문서 탐색","컴포넌트 이름 및 설명 식별"],"es":["Buscar componentes por característica o palabra clave","Navegar por la documentación de WDS utilizando un flujo de descubrimiento por etapas","Identificar nombres y descripciones de componentes"],"fr":["Rechercher des composants par fonctionnalité ou mot-clé","Naviguer dans la documentation WDS à l''aide d''un flux de découverte par étapes","Identifier les noms et les descriptions de composants"],"de":["Komponenten nach Funktion oder Schlüsselwort suchen","WDS-Dokumentation mithilfe eines gestaffelten Entdeckungsflusses navigieren","Komponentennamen und -beschreibungen identifizieren"],"pt":["Procurar componentes por recurso ou palavra-chave","Navegar pela documentação do WDS usando fluxo de descoberta por estágios","Identificar nomes e descrições de componentes"],"ru":["Поиск компонентов по функции или ключевому слову","Навигация по документации WDS с помощью пошагового потока открытия","Определение имен и описаний компонентов"],"ar":["ابحث عن المكونات من خلال الميزة أو الكلمة الرئيسية","تنقل عبر توثيق WDS باستخدام تدفق اكتشاف المراحل","تحديد أسماء وصفوف المكونات"]},"limitations":{"en":["Requires `node_modules/@wix/design-system/dist/docs/` access","Files are 200-900+ lines, necessitating staged discovery flow","CRITICAL: Never read entire files"],"zh":["需要访问`node_modules/@wix/design-system/dist/docs/`","文件为200-900+行，需要分阶段的发现流程","CRITICAL: 绝不读取整个文件"],"ja":["`node_modules/@wix/design-system/dist/docs/`へのアクセスが必要","ファイルは200-900+行で、段階的な発見フローが必要","CRITICAL: 絶対にファイル全体を読み取らない"],"ko":["`node_modules/@wix/design-system/dist/docs/`에 대한 액세스가 필요합니다.","파일은 200-900+ 행으로, 단계적인 발견 흐름이 필요합니다.","CRITICAL: 절대 파일 전체를 읽지 않음"],"es":["Requiere acceso a `node_modules/@wix/design-system/dist/docs/`","Los archivos tienen 200-900+ líneas, lo que requiere un flujo de descubrimiento por etapas","CRÍTICO: Nunca leer archivos completos"],"fr":["Nécessite l''accès à `node_modules/@wix/design-system/dist/docs/`","Les fichiers comportent 200-900+ lignes, ce qui nécessite un flux de découverte par étapes","CRITIQUE : Ne jamais lire les fichiers complets"],"de":["Erfordert Zugriff auf `node_modules/@wix/design-system/dist/docs/`","Dateien sind 200-900+ Zeilen lang, was einen gestaffelten Entdeckungsfluss erfordert","KRITISCH: Niemals ganze Dateien lesen"],"pt":["Exige acesso a `node_modules/@wix/design-system/dist/docs/`","Arquivos têm 200-900+ linhas, necessitando fluxo de descoberta por estágios","CRÍTICO: Nunca leia arquivos inteiros"],"ru":["Требует доступа к `node_modules/@wix/design-system/dist/docs/`","Файлы содержат 200-900+ строк, требующие пошагового потока открытия","КРИТИЧЕСКИ: Никогда не читайте файлы целиком"],"ar":["يتطلب الوصول إلى `node_modules/@wix/design-system/dist/docs/`","الملفات تحتوي على 200-900+ خطوط، تحتاج إلى تدفق اكتشاف المراحل","حرج: لا تقرأ أبدًا الملفات بالكامل"]},"version":4},"contentHash":"d44ea78ed8f087f2064aa84f0a974ab133985d1440f8b9fc1ccd262e600c4b16","qualityScore":42}');
