INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('weunica/payboxCLI-App/wds-docs', 'wds-docs', 'weunica', 'payboxCLI-App', 'community', 'wds-docs weunica payboxCLI-App community The wds-docs skill enables developers to efficiently navigate WDS documentation by searching components using grep commands. It benefits developers working with WDS by providing a staged discovery flow. WDS 文档导航器帮助开发者快速找到组件和功能，提高开发效率 WDS ドキュメントナビゲーターは、開発者がコンポーネントと機能を迅速に探し、開発効率を向上させるのに役立ちます WDS 문서 네비게이터는 개발자가 컴포넌트와 기능을 빠르게 찾고 개발 효율성을 높이는 데 도움을 줍니다 wds-docs es una herramienta de navegación de documentación que permite a los desarrolladores encontrar componentes por características o palabras clave. wds-docs est un outil de navigation de documentation qui permet aux développeurs de trouver des composants par fonctionnalités ou mots clés. wds-docs ist ein Tool zur Navigation von Dokumentationen, mit dem Entwickler Komponenten nach Funktionen oder Schlüsselwörtern finden können. O wds-docs é uma ferramenta de navegação de documentação que ajuda os desenvolvedores a encontrar componentes e recursos rapidamente ИИ Агент wds-docs - это инструмент навигации по документации, который помогает разработчикам быстро находить компоненты и ресурсы ووس-دوس هو أداة مُصممة للمطورين لتصفح الوثائق بسهولة وسرعة how to use wds-docs wds-docs setup guide wds-docs documentation navigator wds-docs alternative wds-docs vs design system documentation wds-docs install grep commands for wds-docs wds-docs for developers wds-docs staged discovery flow WDS 文档导航器 AI 文档工具 组件快速查找 WDS 开发效率 grep 命令 WDS 文档库 AIエージェント Searches components by feature or keyword using grep commands Follows a staged discovery flow to optimize documentation exploration Navigates through WDS documentation files without reading entire files Provides component name, description, and do/don''ts as output Utilizes node_modules/@wix/design-system/dist/docs/ for documentation wds-docs is a WDS Documentation Navigator that facilitates searching components by feature or keyword, following a staged discovery flow to optimize documentation exploration.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jorggerojas/next-skeleton-app/hierarchy', 'community', 'jorggerojas', 'next-skeleton-app', 'jorggerojas/next-skeleton-app', 'hierarchy', 0, 0, 42, '2026-03-08T01:57:15.482Z', '2026-03-08T02:09:57.162Z', 'bc785b079f6495a95f2a7b9570f42ece5c17d9b66e68f361596fd30a6032c5cf', '{"id":"jorggerojas/next-skeleton-app/hierarchy","name":"hierarchy","description":{"en":"Hierarchy is a Next.js App router repo template for simple clean architecture and MCP skills, benefiting developers who prioritize performance and SEO.","zh":"层次结构是一种优化 Next.js 应用路由的方法，采用服务器组件、原子设计和性能优化技术","ja":"階層構造は、Next.js アプリケーションルーターの最適化方法であり、サーバーコンポーネント、原子設計、パフォーマンス最適化技術を使用します","ko":"계층 구조는 Next.js 애플리케이션 라우터를 최적화하는 방법으로, 서버 컴포넌트, 원자적 설계, 성능 최적화 기술을 사용합니다","es":"La jerarquía en Next.js se basa en principios de diseño atómico y componentes de servidor para una arquitectura limpia","fr":"L''hierarchie dans Next.js repose sur des principes de conception atomique et des composants serveur pour une architecture propre","de":"Die Hierarchie in Next.js basiert auf atomaren Designprinzipien und Serverkomponenten für eine saubere Architektur","pt":"A hierarquia é fundamental para o desenvolvimento de aplicações Next.js. Aprenda a configurar a hierarquia certa com Server Components e Atomic Design.","ru":"Иерархия имеет решающее значение для разработки приложений Next.js. Узнайте, как настроить правильную иерархию с помощью Server Components и Atomic Design.","ar":"الترتيب الهرمي ضروري لتطوير تطبيقات Next.js. تعرف على كيفية تركيب هرمية مناسبة مع مكونات الخادم والتصميم الذري"},"seo":{"title":{"en":"Hierarchy: Next.js App Router Template Setup Guide | AI A...","zh":"层次结构 Setup Guide - 优化 Next.js 应用路由","ja":"階層構造 Setup Guide - Next.js アプリケーションルーターの最適化","ko":"계층 구조 Setup Guide - Next.js 애플리케이션 라우터 최적화","es":"Guía de configuración de jerarquía para Next.js","fr":"Guide de mise en place de l''hierarchie pour Next.js","de":"Einrichtungsleitfaden für Hierarchie in Next.js","pt":"Guia de Configuração de Hierarquia para Desenvolvedores","ru":"ИИ Агенты: Настройка Иерархии для Разработчиков","ar":"دليل تركيب هرمية للاعتمادات الاصطناعية"},"description":{"en":"Unlock faster development with Hierarchy''s clean architecture and MCP skills. Discover how to prioritize performance and SEO in your Next.js app.","zh":"了解如何使用层次结构优化 Next.js 应用路由，包括服务器组件、原子设计和性能优化","ja":"Next.js アプリケーションルーターの最適化方法を学びます。サーバーコンポーネント、原子設計、パフォーマンス最適化など","ko":"계층 구조를 사용하여 Next.js 애플리케이션 라우터를 최적화하는 방법을 알아보세요. 서버 컴포넌트, 원자적 설계, 성능 최적화 등","es":"Aprende a implementar una arquitectura limpia y simple en tu aplicación Next.js con nuestra guía de jerarquía","fr":"Découvrez comment mettre en place une architecture propre et simple dans votre application Next.js avec notre guide d''hierarchie","de":"Erfahren Sie, wie Sie eine saubere und einfache Architektur in Ihrer Next.js-Anwendung mit unserem Hierarchie-Leitfaden implementieren","pt":"Aprenda a configurar a hierarquia certa para o seu aplicativo Next.js com Server Components e Atomic Design","ru":"Узнайте, как настроить правильную иерархию для вашего приложения Next.js с помощью Server Components и Atomic Design","ar":"تعرف على كيفية تركيب هرمية مناسبة لتطبيقك Next.js مع مكونات الخادم والتصميم الذري"},"definition":{"en":"Hierarchy is a technical framework for building Next.js applications with a focus on server components, atomic design, and custom hooks.","zh":"层次结构是一种软件设计模式，用于优化 Next.js 应用路由","ja":"階層構造は、Next.js アプリケーションルーターの最適化に使用されるソフトウェア設計パターンです","ko":"계층 구조는 Next.js 애플리케이션 라우터를 최적화하는 데 사용되는 소프트웨어 설계 패턴입니다","es":"La jerarquía se refiere a la organización de componentes en una aplicación Next.js","fr":"L''hierarchie fait référence à l''organisation des composants dans une application Next.js","de":"Die Hierarchie bezieht sich auf die Organisation von Komponenten in einer Next.js-Anwendung","pt":"A hierarquia se refere à organização de componentes em um aplicativo Next.js, utilizando Server Components e Atomic Design","ru":"Иерархия относится к организации компонентов в приложении Next.js, используя Server Components и Atomic Design","ar":"الترتيب الهرمي يعتبر تنظيم مكونات في تطبيق Next.js، باستخدام مكونات الخادم والتصميم الذري"},"features":{"en":["Server Components fetch data directly","Builds using Atomic Design principles (atoms → molecules → organisms → pages)","Custom hooks belong in Client Components (organisms)","Prioritizes performance and SEO by default","Prohibits the use of `any` type"],"zh":["服务器组件直接获取数据","原子设计模式","客户端组件使用自定义钩子","性能优化和 SEO 优先","禁止使用 any 类型"],"ja":["サーバーコンポーネントが直接データを取得","原子設計パターン","クライアントコンポーネントでカスタムフックを使用","パフォーマンス最適化と SEO 優先","any 型の使用禁止"],"ko":["서버 컴포넌트가 직접 데이터를 가져옵니다","원자적 설계 패턴","클라이언트 컴포넌트에서 커스텀 훅을 사용","성능 최적화와 SEO 최적화","any 타입의 사용 금지"],"es":["Componentes de servidor que recuperan datos","Diseño atómico para una arquitectura modular","Uso de hooks en componentes de cliente","Priorización del rendimiento y el SEO","Evitación del uso de ''any''"],"fr":["Composants serveur qui récupèrent des données","Conception atomique pour une architecture modulaire","Utilisation de hooks dans les composants client","Priorisation des performances et du SEO","Évitement de l''utilisation de ''any''"],"de":["Serverkomponenten, die Daten abrufen","Atomares Design für eine modulare Architektur","Verwendung von Hooks in Clientkomponenten","Priorisierung von Leistung und SEO","Vermeidung der Verwendung von ''any''"],"pt":["Server Components para buscar dados","Atomic Design para construir componentes","Uso de Hooks em Client Components","Priorização de desempenho e SEO","Evitar o uso de ''any''"],"ru":["Server Components для получения данных","Atomic Design для построения компонентов","Использование Hooks в Client Components","Приоритизация производительности и SEO","Избегание использования ''any''"],"ar":["مكونات الخادم لاسترجاع البيانات","التصميم الذري لبناء المكونات","استخدام Hooks في مكونات العميل","أولوية الأداء والتحسين لBộ tìm kiếm","تجنب استخدام ''any''"]},"keywords":{"en":["how to use hierarchy in Next.js","hierarchy vs atomic design","hierarchy install guide","what is hierarchy in software development","hierarchy alternative for React apps","hierarchy setup for AI agents"],"zh":["Next.js 应用路由","服务器组件","原子设计","性能优化","SEO 优化","层次结构","AIエージェント","软件设计模式"],"ja":["Next.js アプリケーションルーター","サーバーコンポーネント","原子設計","パフォーマンス最適化","SEO 最適化","階層構造","AIエージェント","ソフトウェア設計パターン"],"ko":["Next.js 애플리케이션 라우터","서버 컴포넌트","원자적 설계","성능 최적화","SEO 최적화","계층 구조","AI 에이전트","소프트웨어 설계 패턴"],"es":["jerarquía en Next.js","arquitectura limpia","diseño atómico","componentes de servidor","hooks en componentes de cliente","rendimiento y SEO en Next.js","evitación de ''any''","guias de configuración para Next.js"],"fr":["hierarchie dans Next.js","architecture propre","conception atomique","composants serveur","hooks dans les composants client","performances et SEO dans Next.js","éviter ''any''","guides de configuration pour Next.js"],"de":["Hierarchie in Next.js","saubere Architektur","atomares Design","Serverkomponenten","Hooks in Clientkomponenten","Leistung und SEO in Next.js","Vermeidung von ''any''","Einrichtungsleitfäden für Next.js"],"pt":["hierarquia next.js","server components","atomic design","desenvolvimento de aplicações","otimização de desempenho","seo para desenvolvedores","guias de configuração"],"ru":["ИИ Агенты иерархия","server components","atomic design","разработка приложений","оптимизация производительности","seo для разработчиков","руководства по настройке"],"ar":["الاعتمادات الاصطناعية هرمية","مكونات الخادم","التصميم الذري","تطوير التطبيقات","تحسين الأداء","seo للاعتمادات الاصطناعية","دلائل التركيب"]}},"owner":"jorggerojas","repo":"next-skeleton-app","repoPath":"jorggerojas/next-skeleton-app","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.482Z","topics":[],"category":"community","skillMd":{"name":"hierarchy","description":"Define the components hierarchy, how to use components inside pages and how to mix components and when its needed to create new ones.","bodyPreview":"# Component Hierarchy\n\n## Core Principles\n\n1. **Server Components fetch data** - Server Components fetch data directly, Client Components receive data as props\n2. **Atomic Design** - Build from atoms → molecules → organisms → pages\n3. **Hooks in Client Components** - Custom hooks belong in Client Components (organisms), not Server Components\n4. **Performance & SEO first** - Always prioritize unless there''s an edge case\n5. **Never use `any`** - Under no circumstances\n\n## Atomic Design Hierarchy","body":"# Component Hierarchy\n\n## Core Principles\n\n1. **Server Components fetch data** - Server Components fetch data directly, Client Components receive data as props\n2. **Atomic Design** - Build from atoms → molecules → organisms → pages\n3. **Hooks in Client Components** - Custom hooks belong in Client Components (organisms), not Server Components\n4. **Performance & SEO first** - Always prioritize unless there''s an edge case\n5. **Never use `any`** - Under no circumstances\n\n## Atomic Design Hierarchy\n\n```txt\nPage (src/app/)\n└── Organism (large component with business logic)\n    └── Molecule (group of atoms with simple logic)\n        └── Atom (single UI element, no logic)\n```\n\n### Atoms\n\nSingle UI elements with no business logic. Receive props, render UI.\n\n```tsx\n// src/ui/custom/Button/Button.tsx\ninterface ButtonProps {\n  children: ReactNode;\n  onClick?: () => void;\n  variant?: \"primary\" | \"secondary\";\n  disabled?: boolean;\n}\n\nexport default function Button({ children, onClick, variant = \"primary\", disabled }: ButtonProps) {\n  return (\n    <button onClick={onClick} disabled={disabled} className={`btn btn-${variant}`}>\n      {children}\n    </button>\n  );\n}\n```\n\n```tsx\n// src/ui/custom/Input/Input.tsx\ninterface InputProps {\n  value: string;\n  onChange: (value: string) => void;\n  placeholder?: string;\n  type?: \"text\" | \"email\" | \"password\";\n}\n\nexport default function Input({ value, onChange, placeholder, type = \"text\" }: InputProps) {\n  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {\n    onChange(e.target.value);\n  };\n\n  return <input type={type} value={value} onChange={handleChange} placeholder={placeholder} />;\n}\n```\n\n### Molecules\n\nGroup of atoms with simple interaction logic. No hooks, no data fetching.\n\n```tsx\n// src/ui/custom/SearchInput/SearchInput.tsx\nimport Input from \"../Input\";\nimport Button from \"../Button\";\n\ninterface SearchInputProps {\n  value: string;\n  onChange: (value: string) => void;\n  onSearch: () => void;\n  placeholder?: string;\n}\n\nexport default function SearchInput({ value, onChange, onSearch, placeholder }: SearchInputProps) {\n  const handleKeyDown = (e: React.KeyboardEvent) => {\n    if (e.key === \"Enter\") {\n      onSearch();\n    }\n  };\n\n  return (\n    <div className=\"flex gap-2\" onKeyDown={handleKeyDown}>\n      <Input value={value} onChange={onChange} placeholder={placeholder} />\n      <Button onClick={onSearch}>Search</Button>\n    </div>\n  );\n}\n```\n\n```tsx\n// src/ui/custom/UserCard/UserCard.tsx\nimport Avatar from \"../Avatar\";\nimport Badge from \"../Badge\";\n\ninterface UserCardProps {\n  name: string;\n  email: string;\n  avatarUrl?: string;\n  role: \"admin\" | \"user\";\n}\n\nexport default function UserCard({ name, email, avatarUrl, role }: UserCardProps) {\n  return (\n    <div className=\"flex items-center gap-4 p-4 border rounded\">\n      <Avatar src={avatarUrl} alt={name} />\n      <div>\n        <h3 className=\"font-bold\">{name}</h3>\n        <p className=\"text-gray-500\">{email}</p>\n      </div>\n      <Badge variant={role === \"admin\" ? \"primary\" : \"secondary\"}>{role}</Badge>\n    </div>\n  );\n}\n```\n\n### Organisms\n\nLarge components with business logic. Can use hooks, stores, and handle complex interactions.\n\n```tsx\n// src/ui/custom/UserList/UserList.tsx\nimport { useState } from \"react\";\nimport { useDebounce } from \"@/hooks\";\nimport { useUIStore } from \"@/stores\";\nimport SearchInput from \"../SearchInput\";\nimport UserCard from \"../UserCard\";\n\ninterface User {\n  id: string;\n  name: string;\n  email: string;\n  avatarUrl?: string;\n  role: \"admin\" | \"user\";\n}\n\ninterface UserListProps {\n  users: User[];\n  onUserSelect: (user: User) => void;\n}\n\nexport default function UserList({ users, onUserSelect }: UserListProps) {\n  const [searchTerm, setSearchTerm] = useState(\"\");\n  const debouncedSearch = useDebounce(searchTerm, 300);\n  const { openModal } = useUIStore();\n\n  const filteredUsers = users.filter(\n    (user) =>\n      user.name.toLowerCase().includes(debouncedSearch.toLowerCase()) ||\n      user.email.toLowerCase().includes(debouncedSearch.toLowerCase())\n  );\n\n  const handleUserClick = (user: User) => {\n    onUserSelect(user);\n    openModal();\n  };\n\n  const handleSearch = () => {\n    // Optional: trigger immediate search\n  };\n\n  return (\n    <div className=\"space-y-4\">\n      <SearchInput\n        value={searchTerm}\n        onChange={setSearchTerm}\n        onSearch={handleSearch}\n        placeholder=\"Search users...\"\n      />\n      <div className=\"space-y-2\">\n        {filteredUsers.map((user) => (\n          <div key={user.id} onClick={() => handleUserClick(user)} className=\"cursor-pointer\">\n            <UserCard {...user} />\n          </div>\n        ))}\n      </div>\n    </div>\n  );\n}\n```\n\n### Pages (Server Components)\n\nServer Components fetch data directly. Client Components receive data as props.\n\n```tsx\n// src/app/users/page.tsx\nimport { UserList } from \"@/components\";\n\nasync function getUsers() {\n  const res = await fetch(\"https://api.example.com/users\", {\n    next: { revalidate: 60 },\n  });\n  return res.json();\n}\n\nexport default async function UsersPage() {\n  const users = await getUsers();\n\n  return (\n    <div>\n      <h1 className=\"text-2xl font-bold mb-4\">Users</h1>\n      <UserList users={users} />\n    </div>\n  );\n}\n```\n\n### Pages (Client Components)\n\nWhen you need interactivity, use Client Components:\n\n```tsx\n// src/app/users/page.tsx\n\"use client\";\n\nimport { UserList } from \"@/components\";\nimport { useUsers } from \"@/hooks/users\";\n\nexport default function UsersPage() {\n  const { data: users, isLoading } = useUsers();\n\n  const handleUserSelect = (user: { id: string; name: string }) => {\n    console.log(\"Selected user:\", user.id);\n  };\n\n  if (isLoading) return <div>Loading...</div>;\n\n  return (\n    <div>\n      <h1 className=\"text-2xl font-bold mb-4\">Users</h1>\n      <UserList users={users} onUserSelect={handleUserSelect} />\n    </div>\n  );\n}\n```\n\n## Data Flow\n\n```txt\nServer Data Flow (Server Components):\nAPI → Server Component (fetch) → Organism → Molecule → Atom\n                                 (props)    (props)   (props)\n\nClient Data Flow (Client Components):\nAPI → React Query Hook → Client Component → Organism → Molecule → Atom\n                         (props)           (props)    (props)   (props)\n\nClient State Flow:\nUser Action → Atom (onClick) → Molecule (handler) → Organism (hook/store) → UI Update\n```\n\n## When to Create a New Component\n\n| Scenario | Create New? | Level |\n|----------|-------------|-------|\n| Button with icon | No, add `icon` prop to Button | Atom |\n| Search bar (input + button) | Yes | Molecule |\n| Form with validation | Yes | Organism |\n| Repeating UI pattern (3+ times) | Yes | Appropriate level |\n| Single-use complex UI | Maybe, if >100 lines | Organism |\n\n## Hook Usage Rules\n\n| Component Level | Can Use Hooks? | Examples |\n|-----------------|----------------|----------|\n| Atom | No | Button, Input, Badge |\n| Molecule | Rarely (only `useState` for local UI) | SearchInput, FormField |\n| Organism | Yes | UserList, DataTable, Forms |\n| Page | Only for client-side mutations | useUsers.create() |\n\n```tsx\n// ❌ BAD: Hook in atom\nexport default function Button({ label }) {\n  const { isLoading } = useUIStore(); // DON''T\n  return <button>{label}</button>;\n}\n\n// ✅ GOOD: Props in atom\nexport default function Button({ label, isLoading }) {\n  return <button disabled={isLoading}>{label}</button>;\n}\n\n// ✅ GOOD: Hook in organism\nexport default function UserForm({ onSubmit }) {\n  const { isLoading, setLoading } = useUIStore();\n  const [formData, setFormData] = useState({});\n\n  const handleSubmit = async () => {\n    setLoading(true);\n    await onSubmit(formData);\n    setLoading(false);\n  };\n\n  return (\n    <form onSubmit={handleSubmit}>\n      <Input value={formData.name} onChange={(v) => setFormData({ ...formData, name: v })} />\n      <Button isLoading={isLoading}>Submit</Button>\n    </form>\n  );\n}\n```\n\n## Server vs Client Data\n\n```tsx\n// ✅ GOOD: Server Component fetches data directly\n// src/app/users/page.tsx\nasync function getUsers() {\n  const res = await fetch(\"https://api.example.com/users\");\n  return res.json();\n}\n\nexport default async function UsersPage() {\n  const users = await getUsers();\n  return <UserList users={users} />;\n}\n\n// ✅ GOOD: Client Component with hooks for interactivity\n// src/app/users/page.tsx\n\"use client\";\n\nimport { useUsers } from \"@/hooks/users\";\n\nexport default function UsersPage() {\n  const { data: users } = useUsers();\n  return <UserList users={users} />;\n}\n\n// Component receives data as props\nexport default function UserList({ users }: { users: User[] }) {\n  return <div>{users.map(...)}</div>;\n}\n```\n\n## Client-Side Mutations\n\nFor mutations (create, update, delete), use hooks in Client Components:\n\n```tsx\n// src/app/users/page.tsx\n\"use client\";\n\nimport { useUsers } from \"@/hooks/users\";\n\nexport default function UsersPage() {\n  const { data: users } = useUsers();\n  const createUser = useUsers.create();\n  const deleteUser = useUsers.delete();\n\n  const handleCreate = (data: CreateUserInput) => {\n    createUser.mutate(data);\n  };\n\n  const handleDelete = (id: string) => {\n    deleteUser.mutate(id);\n  };\n\n  return (\n    <div>\n      <UserForm onSubmit={handleCreate} />\n      <UserList users={users} onDelete={handleDelete} />\n    </div>\n  );\n}\n```\n\n## Important Notes\n\n- **Server Components fetch data directly** - No hooks needed\n- **Client Components use hooks** - For interactivity and mutations\n- **Props down, events up** - Data flows down, actions bubble up via callbacks\n- **Keep atoms pure** - No side effects, no hooks, just UI\n- **Organisms are the brain** - Business logic lives here\n- **Test at the right level** - Unit test atoms, integration test organisms\n- **Never use `any`** - Define proper types for all props and state\n- **Handler naming** - `handle*` inside components, `on*` for props from parents\n- **Prefer composition** - Build complex UIs by combining simple components\n"},"lastSynced":"2026-03-08T02:09:57.162Z","agentAnalysis":{"suitability":{"en":"Perfect for Next.js Agents needing a simple clean architecture and performance optimization skills","zh":"非常适合需要简单清晰架构和性能优化技能的 Next.js 代理","ja":"Next.js エージェントがシンプルでクリーンなアーキテクチャとパフォーマンス最適化スキルを必要とする場合に最適","ko":"단순하고 깨끗한 아키텍처 및 성능 최적화 기술이 필요한 Next.js 에이전트에 적합","es":"Perfecto para Agentes de Next.js que necesitan una arquitectura simple y limpia y habilidades de optimización de rendimiento","fr":"Parfait pour les Agents Next.js ayant besoin d''une architecture simple et propre et de compétences en optimisation des performances","de":"Perfekt für Next.js-Agents, die eine einfache, saubere Architektur und Leistungsoptimierungs-Fähigkeiten benötigen","pt":"Perfeito para Agentes Next.js que necessitam de uma arquitetura simples e limpa e habilidades de otimização de desempenho","ru":"Идеально подходит для агентов Next.js, которым необходима простая и чистая архитектура и навыки оптимизации производительности","ar":"مثالي للوكلاء Next.js الذين يحتاجون إلى هيكلة بسيطة ومتينة ومهارات تحسين الأداء"},"recommendation":{"en":"Empowers agents to build scalable applications using Server Components, Atomic Design, and custom Hooks, prioritizing performance and SEO with protocols like Next.js routing and file formats like .js","zh":"赋予代理构建可扩展应用的能力，使用 Server Components、Atomic Design 和自定义 Hooks，优先考虑性能和 SEO，使用 Next.js 路由和文件格式如 .js 的协议","ja":"Server Components、Atomic Design、カスタム Hooks を使用してスケーラブルなアプリケーションを構築するエージェントをエンパワーメントし、Next.js ルーティングや .js などのファイル形式などのプロトコルを使用してパフォーマンスと SEO を優先","ko":"서버 컴포넌트, 원자적 디자인, 커스텀 훅을 사용하여 확장 가능한 애플리케이션을 구축할 수 있는 에이전트를 강화하고, Next.js 라우팅 및 .js와 같은 파일 형식과 같은 프로토콜을 사용하여 성능과 SEO를 우선","es":"Habilita a los agentes a construir aplicaciones escalables utilizando Componentes del Servidor, Diseño Atómico y ganchos personalizados, priorizando el rendimiento y el SEO con protocolos como el enrutamiento de Next.js y formatos de archivo como .js","fr":"Permet aux agents de construire des applications évolutives en utilisant des Composants de Serveur, une Conception Atomique et des crochets personnalisés, en donnant la priorité aux performances et au SEO avec des protocoles comme le routage Next.js et des formats de fichier comme .js","de":"Ermächtigt Agents, skalierbare Anwendungen mit Server-Komponenten, Atomarem Design und benutzerdefinierten Hooks zu erstellen, wobei Leistung und SEO mit Protokollen wie Next.js-Routing und Dateiformaten wie .js priorisiert werden","pt":"Habilita os agentes a construir aplicações escaláveis usando Componentes de Servidor, Design Atômico e ganchos personalizados, priorizando o desempenho e o SEO com protocolos como roteamento do Next.js e formatos de arquivo como .js","ru":"Наделяет агентов возможностью создавать масштабируемые приложения, используя Компоненты Сервера, Атомарный Дизайн и пользовательские крючки, отдающие приоритет производительности и SEO с помощью протоколов, таких как маршрутизация Next.js и форматы файлов, такие как .js","ar":"يُتيح للوكلاء بناء تطبيقات قابلة للتوسعة باستخدام مكونات الخادم والتصميم الذري والسنارات المخصصة، مع تقديم الأفضلية للأداء والتحسين للحرarella باستخدام بروتوكولات مثل التوجيه في Next.js وأشكال الملفات مثل .js"},"useCases":{"en":["Building high-performance Server Components","Implementing Atomic Design principles for modular code","Optimizing application routing for better SEO"],"zh":["构建高性能 Server Components","实现 Atomic Design 原则以获得模块化代码","优化应用路由以获得更好的 SEO"],"ja":["高パフォーマンスの Server Components を構築する","Atomic Design の原則を実装してモジュール化されたコードを取得する","アプリケーションのルーティングを最適化して SEO を改善する"],"ko":["고성능 서버 컴포넌트 구축","모듈화된 코드를 위한 원자적 디자인 원칙 구현","SEO 개선을 위한 애플리케이션 라우팅 최적화"],"es":["Construir Componentes del Servidor de alto rendimiento","Implementar principios de Diseño Atómico para código modular","Optimizar el enrutamiento de la aplicación para un mejor SEO"],"fr":["Construire des Composants de Serveur à haute performance","Mettre en œuvre des principes de Conception Atomique pour un code modulaire","Optimiser le routage de l''application pour un meilleur SEO"],"de":["Erstellen von Server-Komponenten mit hoher Leistung","Implementieren von Prinzipien des Atomaren Designs für modulares Code","Optimieren des Anwendungs-Routings für ein besseres SEO"],"pt":["Construção de Componentes de Servidor de alto desempenho","Implementação de princípios de Design Atômico para código modular","Otimização do roteamento de aplicações para melhor SEO"],"ru":["Строительство Компонентов Сервера с высоким производительностью","Реализация принципов Атомарного Дизайна для модульного кода","Оптимизация маршрутизации приложений для лучшего SEO"],"ar":["بناء مكونات الخادم عالية الأداء","تنفيذ مبادئ التصميم الذري لكتابة شفرة متوافقة","تحسين توجيه التطبيقات من أجل تحسين جودة الحرarella"]},"limitations":{"en":["Requires Next.js environment","Must adhere to Atomic Design hierarchy","Cannot use ''any'' type"],"zh":["需要 Next.js 环境","必须遵循 Atomic Design 层次结构","不能使用 ''any'' 类型"],"ja":["Next.js 環境が必要","Atomic Design の階層構造に従う必要がある","''any'' タイプを使用できない"],"ko":["Next.js 환경 필요","원자적 디자인 계층 구조를 따라야 함","''any'' 유형을 사용할 수 없음"],"es":["Requiere entorno de Next.js","Debe adherirse a la jerarquía de Diseño Atómico","No se puede utilizar el tipo ''any''"],"fr":["Nécessite un environnement Next.js","Doit respecter la hiérarchie de la Conception Atomique","Ne peut pas utiliser le type ''any''"],"de":["Benötigt Next.js-Umgebung","Muss der Hierarchie des Atomaren Designs folgen","Kann den Typ ''any'' nicht verwenden"],"pt":["Requer ambiente Next.js","Deve aderir à hierarquia do Design Atômico","Não pode usar o tipo ''any''"],"ru":["Требует среды Next.js","Должно придерживаться иерархии Атомарного Дизайна","Не может использовать тип ''any''"],"ar":["يتطلب بيئة Next.js","يجب اتباع التسلسل الهرمي للتصميم الذري","لا يمكن استخدام نوع ''أي''"]},"version":4},"contentHash":"bc785b079f6495a95f2a7b9570f42ece5c17d9b66e68f361596fd30a6032c5cf","qualityScore":42}');
