INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jorggerojas/next-skeleton-app/hierarchy', 'hierarchy', 'jorggerojas', 'next-skeleton-app', 'community', 'hierarchy jorggerojas next-skeleton-app community Hierarchy is a Next.js App router repo template for simple clean architecture and MCP skills, benefiting developers who prioritize performance and SEO. 层次结构是一种优化 Next.js 应用路由的方法，采用服务器组件、原子设计和性能优化技术 階層構造は、Next.js アプリケーションルーターの最適化方法であり、サーバーコンポーネント、原子設計、パフォーマンス最適化技術を使用します 계층 구조는 Next.js 애플리케이션 라우터를 최적화하는 방법으로, 서버 컴포넌트, 원자적 설계, 성능 최적화 기술을 사용합니다 La jerarquía en Next.js se basa en principios de diseño atómico y componentes de servidor para una arquitectura limpia L''hierarchie dans Next.js repose sur des principes de conception atomique et des composants serveur pour une architecture propre Die Hierarchie in Next.js basiert auf atomaren Designprinzipien und Serverkomponenten für eine saubere Architektur A hierarquia é fundamental para o desenvolvimento de aplicações Next.js. Aprenda a configurar a hierarquia certa com Server Components e Atomic Design. Иерархия имеет решающее значение для разработки приложений Next.js. Узнайте, как настроить правильную иерархию с помощью Server Components и Atomic Design. الترتيب الهرمي ضروري لتطوير تطبيقات Next.js. تعرف على كيفية تركيب هرمية مناسبة مع مكونات الخادم والتصميم الذري how to use hierarchy in Next.js hierarchy vs atomic design hierarchy install guide what is hierarchy in software development hierarchy alternative for React apps hierarchy setup for AI agents Next.js 应用路由 服务器组件 原子设计 性能优化 SEO 优化 层次结构 AIエージェント 软件设计模式 Server Components fetch data directly Builds using Atomic Design principles (atoms → molecules → organisms → pages) Custom hooks belong in Client Components (organisms) Prioritizes performance and SEO by default Prohibits the use of `any` type Hierarchy is a technical framework for building Next.js applications with a focus on server components, atomic design, and custom hooks.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('zotoio/x-fidelity/xfi-create-plan', 'community', 'zotoio', 'x-fidelity', 'zotoio/x-fidelity', 'xfi-create-plan', 0, 0, 42, '2026-03-08T01:57:15.483Z', '2026-03-08T02:09:57.867Z', '97e1f300a443fead1a9626df29b522318bb85c95ee04cad32745fd3b326812e9', '{"id":"zotoio/x-fidelity/xfi-create-plan","name":"xfi-create-plan","description":{"en":"The xfi-create-plan skill guides the xfi-planner agent in creating comprehensive engineering plans for complex initiatives, requiring a clear understanding of the feature or initiative and access to the xfi-system-design agent.","zh":"xfi-create-plan技能用于创建综合工程计划，包括要求收集和子任务委托，使用CLI进行意见化框架检查","ja":"xfi-create-planスキルは、要求収集やサブタスクの委任を含む、包括的なエンジニアリングプランを作成するために使用されます","ko":"xfi-create-plan 스킬은 포괄적인 엔지니어링 계획을 생성하는 데 사용되며, 요구 사항 수집 및 하위 작업 위임을 포함하여 CLI를 사용하여 의견화 프레임워크를 확인합니다","es":"xfi-create-plan es un CLI para la verificación de la adherencia a marcos de trabajo, que ayuda a crear planes de ingeniería completos para iniciativas complejas","fr":"xfi-create-plan est un CLI pour la vérification de la conformité aux frameworks, qui aide à créer des plans d''ingénierie complets pour des initiatives complexes","de":"xfi-create-plan ist ein CLI für die Prüfung von Framework-Richtlinien, das dabei hilft, umfassende Ingenieurpläne für komplexe Initiativen zu erstellen","pt":"O xfi-create-plan é uma ferramenta de linha de comando que ajuda a garantir a adesão a frameworks, melhorando a eficiência do desenvolvimento.","ru":"xfi-create-plan - это инструмент командной строки, который помогает обеспечить соблюдение фреймворков, повышая эффективность разработки.","ar":"xfi-create-plan هو أداة سطر الأوامر تساعد على ضمان الامتثال لآراء الإطار، مما يحسن كفاءة التطوير."},"seo":{"title":{"en":"xfi-create-plan: Comprehensive Engineering Plan Setup Gui...","zh":"xfi-create-plan Setup Guide: CLI 工程计划创建","ja":"xfi-create-plan ベストプラクティス: AIエージェントによる工程計画作成","ko":"xfi-create-plan 사용자 가이드: CLI Opinionated Framework","es":"Guía de configuración de xfi-create-plan para verificació...","fr":"Guide de configuration de xfi-create-plan pour les vérifi...","de":"Einrichtungsleitfaden für xfi-create-plan zur Prüfung von...","pt":"Guia de Configuração do xfi-create-plan: CLI para Verific...","ru":"Настройка xfi-create-plan: ИИ Агенты для Проверки Соблюде...","ar":"دليل إعداد xfi-create-plan: واجهة سطر الأوامر للتحقق من ا..."},"description":{"en":"Streamline initiative planning with xfi-create-plan. Learn how to create detailed engineering plans and integrate with xfi-system-design agent for architectu...","zh":"了解如何使用xfi-create-plan技能创建综合工程计划，包括要求收集和子任务委托","ja":"xfi-create-planスキルを使用して複雑なイニシアチブのための包括的なエンジニアリングプランを作成する方法について学びます","ko":"xfi-create-plan 스킬을 사용하여 복잡한 이니셔티브를 위한 포괄적인 엔지니어링 계획을 생성하는 방법을 알아보세요","es":"Aprende a utilizar xfi-create-plan para crear planes de ingeniería completos y realizar verificaciones de marcos de trabajo con nuestra guía paso a paso","fr":"Découvrez comment utiliser xfi-create-plan pour créer des plans d''ingénierie complets et effectuer des vérifications de framework avec notre guide étape par ...","de":"Erfahren Sie, wie Sie xfi-create-plan verwenden, um umfassende Ingenieurpläne zu erstellen und Framework-Prüfungen durchzuführen, mit unserem Schritt-für-Sch...","pt":"Aprenda a configurar o xfi-create-plan, uma ferramenta de linha de comando para garantir a adesão a frameworks, e melhore a eficiência do seu desenvolvimento","ru":"Узнайте, как настроить xfi-create-plan, инструмент командной строки для проверки соблюдения фреймворков, и повысьте эффективность своего развития","ar":"تعرف على كيفية إعداد xfi-create-plan، أداة سطر الأوامر للتحقق من الامتثال لآراء الإطار، وادخل تحسينات على كفاءة التطوير الخاص بك"},"definition":{"en":"xfi-create-plan is a CLI-based skill for opinionated framework adherence checks, enabling the creation of detailed engineering plans through requirements gathering and subtask delegation.","zh":"xfi-create-plan是用于创建综合工程计划的技能，具有要求收集和子任务委托功能","ja":"xfi-create-planは、要求収集やサブタスクの委任機能を備えた、包括的なエンジニアリングプランを作成するためのスキルです","ko":"xfi-create-plan은 포괄적인 엔지니어링 계획을 생성하는 데 사용되는 스킬로, 요구 사항 수집 및 하위 작업 위임 기능을 갖추고 있습니다","es":"xfi-create-plan es una herramienta de agente de inteligencia artificial que ayuda a crear planes de ingeniería y verificar la adherencia a marcos de trabajo","fr":"xfi-create-plan est un outil d''agent d''intelligence artificielle qui aide à créer des plans d''ingénierie et à vérifier la conformité aux frameworks","de":"xfi-create-plan ist ein Werkzeug für künstliche Intelligenz-Agenten, das dabei hilft, Ingenieurpläne zu erstellen und die Einhaltung von Framework-Richtlinien zu prüfen","pt":"O xfi-create-plan é uma ferramenta de linha de comando para verificar a adesão a frameworks","ru":"xfi-create-plan - это инструмент командной строки для проверки соблюдения фреймворков","ar":"xfi-create-plan هو أداة سطر الأوامر للتحقق من الامتثال لآراء الإطار"},"features":{"en":["Performs requirements gathering through up to 10 questions","Integrates with xfi-system-design agent for architectural input","Delegates subtasks to appropriate subagents for efficient planning","Guides the xfi-planner agent through comprehensive engineering plan creation","Supports complex initiative planning through a structured workflow","Utilizes a CLI-based interface for opinionated framework adherence checks"],"zh":["CLI意见化框架检查","要求收集功能","子任务委托功能","xfi-system-design代理集成","支持复杂的工程计划创建"],"ja":["CLIによるオピニオン化フレームワークのチェック","要件収集機能","サブタスクの委任機能","xfi-system-designエージェントとの統合","複雑なエンジニアリングプランの作成をサポート"],"ko":["CLI를 사용한 의견화 프레임워크 확인","요구 사항 수집 기능","하위 작업 위임 기능","xfi-system-design 에이전트 통합","복잡한 엔지니어링 계획 생성 지원"],"es":["CLI para la verificación de la adherencia a marcos de trabajo","Creación de planes de ingeniería completos para iniciativas complejas","Recolección de requisitos mediante hasta 10 preguntas","Integración con el agente xfi-system-design para obtener información de diseño arquitectónico","Capacidad para delegar subtareas a subagentes adecuados"],"fr":["CLI pour la vérification de la conformité aux frameworks","Création de plans d''ingénierie complets pour des initiatives complexes","Collecte de requisitos via jusqu''à 10 questions","Intégration avec l''agent xfi-system-design pour obtenir des informations de conception architecturale","Capacité à déléguer des sous-tâches à des sous-agents appropriés"],"de":["CLI für die Prüfung von Framework-Richtlinien","Erstellung umfassender Ingenieurpläne für komplexe Initiativen","Erfassung von Anforderungen durch bis zu 10 Fragen","Integration mit dem xfi-system-design-Agenten für architektonische Designinformationen","Fähigkeit, Subaufgaben an geeignete Subagenten zu delegieren"],"pt":["CLI para verificar a adesão a frameworks","Integração com o xfi-system-design agent para entrada arquitetônica","Capacidade de delegar a subagentes para criação de subtarefas","Suporte a até 10 perguntas para coleta de requisitos","Melhoria da eficiência do desenvolvimento"],"ru":["CLI для проверки соблюдения фреймворков","Интеграция с xfi-system-design агентом для архитектурного ввода","Возможность делегировать субагентам для создания субзадач","Поддержка до 10 вопросов для сбора требований","Повышение эффективности разработки"],"ar":["واجهة سطر الأوامر للتحقق من الامتثال لآراء الإطار","التكامل مع وكيل التصميم الإطار xfi-system-design","القدرة على تفويض إلى وكلاء فرعيين لإنشاء مهام فرعية","دعم لما يصل إلى 10 أسئلة لجمع المتطلبات","تحسين كفاءة التطوير"]},"keywords":{"en":["how to use xfi-create-plan","xfi-create-plan setup guide","xfi-create-plan alternative","xfi-create-plan vs xfi-system-design","xfi-create-plan install","what is xfi-create-plan","xfi-create-plan tutorial","xfi-create-plan engineering plan creation","xfi-create-plan requirements gathering"],"zh":["xfi-create-plan","CLI工程计划","要求收集","子任务委托","xfi-system-design","AI工具","工程计划创建"],"ja":["xfi-create-plan","CLIエンジニアリングプラン","要件収集","サブタスクの委任","xfi-system-design","AIエージェント","エンジニアリングプランの作成"],"ko":["xfi-create-plan","CLI 엔지니어링 계획","요구 사항 수집","하위 작업 위임","xfi-system-design","AI 도구","엔지니어링 계획 생성"],"es":["xfi-create-plan","verificación de marcos de trabajo","planes de ingeniería","iniciativas complejas","CLI para ingenieros","herramientas de agente de inteligencia artificial","xfi-system-design","diseño arquitectónico"],"fr":["xfi-create-plan","vérification de la conformité aux frameworks","plans d''ingénierie","initiatives complexes","CLI pour les ingénieurs","outils d''agent d''intelligence artificielle","xfi-system-design","conception architecturale"],"de":["xfi-create-plan","Prüfung von Framework-Richtlinien","Ingenieurpläne","komplexe Initiativen","CLI für Ingenieure","Werkzeuge für künstliche Intelligenz-Agenten","xfi-system-design","architektonisches Design"],"pt":["xfi-create-plan","CLI","adesão a frameworks","desenvolvimento de software","eficiência no desenvolvimento","ferramentas de desenvolvimento","xfi-system-design","subagentes","coleta de requisitos"],"ru":["xfi-create-plan","CLI","соблюдение фреймворков","разработка программного обеспечения","эффективность разработки","инструменты разработки","xfi-system-design","субагенты","сбор требований"],"ar":["xfi-create-plan","واجهة سطر الأوامر","الامتثال لآراء الإطار","تطوير البرمجيات","كفاءة التطوير","أدوات التطوير","تصميم الإطار xfi-system-design","وكلاء فرعيون","جمع المتطلبات"]}},"owner":"zotoio","repo":"x-fidelity","repoPath":"zotoio/x-fidelity","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.483Z","topics":[],"category":"community","skillMd":{"name":"xfi-create-plan","description":"Guide for creating engineering plans through a structured workflow. Use when planning new features, coordinating multi-agent work, or breaking down complex initiatives.","bodyPreview":"# Creating X-Fidelity Engineering Plans\n\nThis skill guides the xfi-planner agent through creating comprehensive engineering plans for complex initiatives.\n\n## Prerequisites\n\n- Clear understanding of the feature/initiative to plan\n- Access to xfi-system-design agent for architectural input\n- Ability to delegate to appropriate subagents for subtask creation\n\n## Workflow Overview\n\n```\n┌─────────────────────────────────────────────────────────────┐\n│ 1. Requirements Gathering (up to 10 questions)","body":"# Creating X-Fidelity Engineering Plans\n\nThis skill guides the xfi-planner agent through creating comprehensive engineering plans for complex initiatives.\n\n## Prerequisites\n\n- Clear understanding of the feature/initiative to plan\n- Access to xfi-system-design agent for architectural input\n- Ability to delegate to appropriate subagents for subtask creation\n\n## Workflow Overview\n\n```\n┌─────────────────────────────────────────────────────────────┐\n│ 1. Requirements Gathering (up to 10 questions)             │\n├─────────────────────────────────────────────────────────────┤\n│ 2. Design Consultation (xfi-system-design agent)           │\n├─────────────────────────────────────────────────────────────┤\n│ 3. USER STOP: Confirm decisions                            │\n├─────────────────────────────────────────────────────────────┤\n│ 4. Create plan directory and index file                    │\n├─────────────────────────────────────────────────────────────┤\n│ 5. Delegate subtask file creation to subagents             │\n├─────────────────────────────────────────────────────────────┤\n│ 6. Review by xfi-code-reviewer and xfi-system-design       │\n├─────────────────────────────────────────────────────────────┤\n│ 7. USER STOP: Final review                                 │\n├─────────────────────────────────────────────────────────────┤\n│ 8. Declare plan ready with execution instructions          │\n└─────────────────────────────────────────────────────────────┘\n```\n\n## Step 1: Requirements Gathering\n\nAsk up to 10 clarifying questions, **one at a time**, building on previous answers.\n\n### Question Categories\n\n1. **Scope**: What is the scope of this initiative?\n2. **Goals**: What are the primary goals and success criteria?\n3. **Constraints**: Are there any constraints or limitations?\n4. **Dependencies**: What existing features/packages does this depend on?\n5. **Affected Packages**: Which packages will be impacted?\n6. **User Impact**: How will this affect end users?\n7. **Testing Strategy**: Any specific testing requirements?\n8. **Timeline Sensitivity**: Are there any deadlines or priorities?\n9. **Risks**: Any known risks or concerns?\n10. **Open Questions**: Anything unclear that needs investigation?\n\n### Question Guidelines\n\n- **STOP after each question** and wait for user response\n- **Build on previous answers** - adapt questions based on responses\n- **Skip unnecessary questions** if scope is already clear\n- **Aim for 5-7 questions** for most initiatives\n- **Document key decisions** as you go\n\n## Step 2: Design Consultation\n\nAfter gathering requirements, consult the **xfi-system-design agent**:\n\n```\nInvoke xfi-system-design subagent with:\n\n\"Provide architectural input for this initiative:\n\n[Summary of requirements gathered]\n\nKey questions:\n1. What packages need to be modified?\n2. What is the recommended architecture approach?\n3. Are there any design patterns we should follow?\n4. What are the main technical risks?\n5. Suggest a logical breakdown of subtasks\"\n```\n\nCapture the design agent''s recommendations.\n\n## Step 3: User Confirmation (MANDATORY STOP)\n\n**STOP and present to user:**\n\n```markdown\n## Plan Summary for Confirmation\n\n### Initiative: [Name]\n\n### Key Decisions Made:\n1. [Decision 1 with rationale]\n2. [Decision 2 with rationale]\n3. [Decision 3 with rationale]\n\n### Packages Affected:\n- [package 1] - [changes needed]\n- [package 2] - [changes needed]\n\n### Proposed Subtasks:\n1. [Subtask 1] - assigned to [subagent]\n2. [Subtask 2] - assigned to [subagent]\n\n### Architecture Approach:\n[Summary from xfi-system-design]\n\n### Risks Identified:\n- [Risk 1]\n- [Risk 2]\n\n---\n\nDo you approve these decisions? Any changes or questions?\n```\n\n**Wait for user confirmation before proceeding.**\n\n## Step 4: Create Plan Directory and Index File\n\nOnce confirmed, create the plan structure:\n\n### Directory Structure\n\n```bash\nknowledge/plans/[YYYYMMDD]-[feature-name]/\n```\n\n### Index File Template\n\nCreate `index-[feature-name]-[yyyymmdd].md`:\n\n```markdown\n# Plan: [Feature Name]\n\n## Status\nDraft\n\n## Overview\n[High-level description from requirements]\n\n## Key Decisions\n- [Decision 1]: [Rationale]\n- [Decision 2]: [Rationale]\n\n## Requirements\n[Numbered list of requirements gathered]\n\n## Design Notes\n[Summary from xfi-system-design consultation]\n\n## Subtask Dependency Graph\n\n```mermaid\ngraph TD\n    subgraph \"Phase 1 (Parallel)\"\n        A[subtask-01-setup]\n        B[subtask-02-types]\n    end\n    subgraph \"Phase 2\"\n        C[subtask-03-implementation]\n    end\n    subgraph \"Phase 3\"\n        D[subtask-04-testing]\n    end\n    A --> C\n    B --> C\n    C --> D\n```\n\n## Execution Order\n\n### Phase 1 (Parallel)\n| Subtask | Subagent | Description | Dependencies |\n|---------|----------|-------------|--------------|\n| 01 | xfi-engineer | [Description] | None |\n| 02 | xfi-engineer | [Description] | None |\n\n### Phase 2 (After Phase 1)\n| Subtask | Subagent | Description | Dependencies |\n|---------|----------|-------------|--------------|\n| 03 | xfi-engineer | [Description] | 01, 02 |\n\n### Phase 3 (After Phase 2)\n| Subtask | Subagent | Description | Dependencies |\n|---------|----------|-------------|--------------|\n| 04 | xfi-testing-expert | [Description] | 03 |\n\n## Global Definition of Done\n- [ ] All subtasks completed\n- [ ] All unit tests passing\n- [ ] Code review by xfi-code-reviewer completed\n- [ ] Architecture review by xfi-system-design completed\n- [ ] Global test suite passing (verified by xfi-testing-expert)\n- [ ] Documentation updated by xfi-docs-expert\n- [ ] Knowledge captured by xfi-system-design\n- [ ] User approval received\n\n## Execution Notes\n[To be filled during plan execution]\n\n## Completion Checklist\n- [ ] Subtask 01: Pending\n- [ ] Subtask 02: Pending\n- [ ] Subtask 03: Pending\n- [ ] Subtask 04: Pending\n- [ ] Final code review\n- [ ] Final architecture review\n- [ ] Global tests verified\n- [ ] Documentation updated\n- [ ] Knowledge captured\n```\n\n## Step 5: Delegate Subtask File Creation\n\nFor each subtask, invoke the appropriate subagent to create the subtask file.\n\n### Delegation Template\n\n```\nInvoke [subagent-name] subagent with:\n\n\"Create a subtask plan file for the following task.\n\n**File to create**: knowledge/plans/[yyyymmdd]-[feature-name]/subtask-[NN]-[feature]-[subtask-name]-[yyyymmdd].md\n\n**IMPORTANT**:\n- Only create/edit the subtask markdown file\n- Do NOT edit any code files\n- Do NOT run any tests\n- Include instruction in the file that executing agent should NOT trigger global tests\n\n**Subtask Details**:\n- Feature: [Feature name]\n- Subtask: [Subtask name]\n- Objective: [Clear objective]\n- Deliverables: [Expected deliverables]\n- Dependencies: [List of dependent subtask IDs or None]\n\n**File Template**:\n[Include the subtask file template from xfi-planner agent documentation]\n\nAfter creating the file, report back with:\n1. File path created\n2. Summary of deliverables defined\n3. Any concerns or questions about the subtask\"\n```\n\n### Subagent Selection Guide\n\n| Task Type | Subagent |\n|-----------|----------|\n| General implementation | xfi-engineer |\n| Plugin development | xfi-plugin-expert |\n| VSCode extension | xfi-vscode-expert |\n| Rule/archetype work | xfi-rules-expert |\n| Testing strategy | xfi-testing-expert |\n| Security-sensitive | xfi-security-expert |\n| Build/CI work | xfi-build-expert |\n\n### Collect Results\n\nAs each subagent completes:\n1. Verify the subtask file was created correctly\n2. Update the index file if any new information was discovered\n3. Note any concerns raised by subagents\n\n## Step 6: Plan Review\n\nInvoke reviewers in parallel:\n\n### xfi-code-reviewer\n\n```\nInvoke xfi-code-reviewer subagent with:\n\n\"Review the engineering plan files for completeness and quality:\n\nPlan directory: knowledge/plans/[yyyymmdd]-[feature-name]/\n\nCheck for:\n1. Clear and achievable deliverables\n2. Appropriate subagent assignments\n3. Correct dependency ordering\n4. Complete definition of done criteria\n5. Any gaps or concerns\n\nProvide suggestions for improvements.\"\n```\n\n### xfi-system-design\n\n```\nInvoke xfi-system-design subagent with:\n\n\"Review the engineering plan for architectural soundness:\n\nPlan directory: knowledge/plans/[yyyymmdd]-[feature-name]/\n\nCheck for:\n1. Alignment with X-Fidelity architecture\n2. Appropriate package assignments\n3. Completeness of scope\n4. Technical feasibility\n5. Risk coverage\n\nProvide suggestions for improvements.\"\n```\n\n### Incorporate Feedback\n\nUpdate plan files based on reviewer suggestions.\n\n## Step 7: User Final Review (MANDATORY STOP)\n\n**STOP and present to user:**\n\n```markdown\n## Plan Ready for Review\n\n### Plan Location\n`knowledge/plans/[yyyymmdd]-[feature-name]/`\n\n### Files Created\n- `index-[feature-name]-[yyyymmdd].md` (main plan)\n- `subtask-01-[feature]-[subtask-name]-[yyyymmdd].md`\n- `subtask-02-[feature]-[subtask-name]-[yyyymmdd].md`\n- ...\n\n### Review Feedback Incorporated\n- [Summary of changes from code reviewer]\n- [Summary of changes from system design]\n\n### Execution Summary\n- Total subtasks: [N]\n- Parallel phases: [N]\n- Estimated complexity: [Low/Medium/High]\n\n---\n\nPlease review the plan files. When ready to execute, use:\n`/xfi-plan-execute`\n\nAny changes needed before finalizing?\n```\n\n## Step 8: Finalize Plan\n\nOnce user approves:\n\n1. Update index file status to \"Ready for Review\"\n2. Document execution instructions:\n\n```markdown\n## Execution Instructions\n\nTo execute this plan in a new agent session:\n\n1. Start a new conversation\n2. Run: `/xfi-plan-execute`\n3. Select this plan: `[yyyymmdd]-[feature-name]`\n4. Confirm execution summary\n5. Monitor subtask progress\n6. Review final changes when prompted\n7. Approve documentation updates\n```\n\n## Critical Rules\n\n1. **NEVER edit code files** during planning\n2. **ALWAYS stop for user confirmation** at Steps 3 and 7\n3. **DELEGATE subtask creation** to appropriate subagents\n4. **INCLUDE testing restrictions** in all subtask files\n5. **CAPTURE all decisions** in the index file\n6. **UPDATE index** with discoveries from subagents\n\n## Troubleshooting\n\n### Subagent doesn''t create correct file\n- Verify the file path is correct\n- Ensure template was provided\n- Re-invoke with clearer instructions\n\n### Scope too large\n- Break into multiple plans\n- Phase the implementation\n- Prioritize critical subtasks\n\n### Unclear requirements\n- Ask additional clarifying questions\n- Consult xfi-system-design for guidance\n- Document assumptions clearly\n"},"lastSynced":"2026-03-08T02:09:57.867Z","agentAnalysis":{"suitability":{"en":"Perfect for Engineering Planning Agents needing comprehensive plan creation for complex initiatives.","zh":"非常适合需要全面计划创建的复杂工程规划代理","ja":"エンジニアリング計画エージェントが複雑なイニシアチブのための包括的な計画作成を必要とする場合に最適","ko":"복잡한 이니셔티브를 위한 포괄적인 계획 생성이 필요한 엔지니어링 계획 에이전트에 적합","es":"Perfecto para Agentes de Planificación de Ingeniería que necesitan creación de planes comprehensivos para iniciativas complejas.","fr":"Parfait pour les agents de planification d''ingénierie ayant besoin de création de plans complets pour des initiatives complexes.","de":"Perfekt für Engineering-Planungsagenten, die umfassende Planerstellung für komplexe Initiativen benötigen.","pt":"Perfeito para Agentes de Planejamento de Engenharia que necessitam de criação de planos abrangentes para iniciativas complexas.","ru":"Идеально подходит для агентов планирования инженерных работ, которым необходима комплексная разработка планов для сложных инициатив.","ar":"مثالي للوكلاء التخطيطيين الهندسيين الذين يحتاجون إلى إنشاء خطط شاملة لمبادرات معقدة."},"recommendation":{"en":"Empowers agents to generate detailed engineering plans by leveraging xfi-system-design agent for architectural input and delegating subtasks to appropriate subagents, utilizing a clear understanding of the feature or initiative and accessing system design information.","zh":"通过利用xfi-system-design代理获取架构输入并将子任务委托给适当的子代理，利用对功能或计划的明确理解并访问系统设计信息，从而使代理能够生成详细的工程计划","ja":"xfi-system-designエージェントを使用してアーキテクチャの入力を取得し、サブタスクを適切なサブエージェントに委託し、機能またはイニシアチブとシステム設計情報へのアクセスに対する明確な理解を利用して、詳細なエンジニアリング計画を生成することができる","ko":"xfi-system-design 에이전트를 사용하여 아키텍처 입력을 얻고 하위 태스크를 적절한 하위 에이전트에 위임하고 기능 또는 이니셔티브와 시스템 디자인 정보에 대한 明確한 이해를 활용하여 자세한 엔지니어링 계획을 생성할 수 있다","es":"Habilita a los agentes a generar planes de ingeniería detallados aprovechando el agente xfi-system-design para la entrada arquitectónica y delegando subtareas a subagentes apropiados, utilizando una comprensión clara de la característica o iniciativa y accediendo a la información de diseño del sistema.","fr":"Permet aux agents de générer des plans d''ingénierie détaillés en exploitant l''agent xfi-system-design pour les entrées architecturales et en déléguant des sous-tâches à des sous-agents appropriés, en utilisant une compréhension claire de la fonctionnalité ou de l''initiative et en accédant aux informations de conception du système.","de":"Ermächtigt die Agenten, detaillierte Ingenieurpläne zu erstellen, indem sie den xfi-system-design-Agent für architektonische Eingaben nutzen und Teilaufgaben an geeignete Unteragenten delegieren, wobei sie eine klare Vorstellung von der Funktion oder Initiative haben und auf Systemdesign-Informationen zugreifen.","pt":"Habilita os agentes a gerar planos de engenharia detalhados, aproveitando o agente xfi-system-design para entrada arquitetônica e delegando subtarefas a subagentes apropriados, utilizando uma compreensão clara da funcionalidade ou iniciativa e acessando informações de design do sistema.","ru":"Позволяет агентам генерировать подробные инженерные планы, используя агент xfi-system-design для архитектурного ввода и делегируя подзадачи соответствующим подагентам, используя четкое понимание функции или инициативы и получая доступ к информации о системном дизайне.","ar":"تمكّن الوكلاء من توليد خطط هندسية مفصلة من خلال الاستفادة من وكيل xfi-system-design لمدخلات الهيكل والتفويض الفرعي إلى وكلاء فرعيين مناسبين، باستخدام فهم واضح للميزة أو المبادرة والوصول إلى معلومات التصميم النظامي."},"useCases":{"en":["Creating comprehensive engineering plans for new feature rollouts","Delegating subtasks to subagents for efficient plan execution","Integrating with xfi-system-design agent for architectural insights"],"zh":["为新功能发布创建全面工程计划","将子任务委托给子代理以实现高效的计划执行","与xfi-system-design代理集成以获取架构见解"],"ja":["新機能のロールアウトのための包括的なエンジニアリング計画の作成","サブタスクをサブエージェントに委託して効率的な計画の実行","xfi-system-designエージェントとの統合によるアーキテクチャの洞察"],"ko":["새 기능 롤아웃을 위한 포괄적인 엔지니어링 계획 생성","하위 태스크를 하위 에이전트에 위임하여 효율적인 계획 실행","xfi-system-design 에이전트와의 통합을 통한 아키텍처 인사이트"],"es":["Crear planes de ingeniería comprehensivos para nuevos lanzamientos de funciones","Delegar subtareas a subagentes para una ejecución de planes eficiente","Integrarse con el agente xfi-system-design para obtener información arquitectónica"],"fr":["Créer des plans d''ingénierie complets pour les nouveaux lancements de fonctionnalités","Déleguer des sous-tâches à des sous-agents pour une exécution de plans efficace","Intégrer avec l''agent xfi-system-design pour obtenir des informations architecturales"],"de":["Umfassende Ingenieurpläne für neue Funktionsrollouts erstellen","Teilaufgaben an Unteragenten delegieren, um eine effiziente Planausführung zu ermöglichen","Integration mit dem xfi-system-design-Agent für architektonische Einblicke"],"pt":["Criar planos de engenharia abrangentes para novos lançamentos de recursos","Delegar subtarefas a subagentes para execução eficiente de planos","Integrar com o agente xfi-system-design para obter informações arquitetônicas"],"ru":["Создание комплексных инженерных планов для новых выпусков функций","Делегирование подзадач подагентам для эффективного выполнения планов","Интеграция с агентом xfi-system-design для получения архитектурных сведений"],"ar":["إنشاء خطط هندسية شاملة لإطلاقات الميزات الجديدة","تفويض المهام الفرعية إلى وكلاء فرعيين من أجل تنفيذ خطط فعال","التكامل مع وكيل xfi-system-design للحصول على informaciónات هيكلية"]},"limitations":{"en":["Requires clear understanding of the feature or initiative","Needs access to xfi-system-design agent","Limited to engineering planning use cases"],"zh":["需要对功能或计划有明确的理解","需要访问xfi-system-design代理","仅限于工程规划用例"],"ja":["機能またはイニシアチブに対する明確な理解が必要","xfi-system-designエージェントへのアクセスが必要","エンジニアリング計画のユースケースに限定"],"ko":["기능 또는 이니셔티브에 대한 明確한 이해가 필요","xfi-system-design 에이전트에 대한 액세스가 필요","엔지니어링 계획 유즈케이스에만 제한"],"es":["Requiere una comprensión clara de la característica o iniciativa","Necesita acceso al agente xfi-system-design","Limitado a casos de uso de planificación de ingeniería"],"fr":["Nécessite une compréhension claire de la fonctionnalité ou de l''initiative","Besoin d''accès à l''agent xfi-system-design","Limité aux cas d''utilisation de planification d''ingénierie"],"de":["Benötigt eine klare Vorstellung von der Funktion oder Initiative","Benötigt Zugriff auf den xfi-system-design-Agent","Begrenzt auf Ingenieurplanungs-Anwendungsfälle"],"pt":["Exige uma compreensão clara da funcionalidade ou iniciativa","Necessita acesso ao agente xfi-system-design","Limitado a casos de uso de planejamento de engenharia"],"ru":["Требует четкого понимания функции или инициативы","Требует доступа к агенту xfi-system-design","Ограничен случаи использования планирования инженерных работ"],"ar":["يتطلب فهمًا واضحًا للميزة أو المبادرة","يحتاج إلى الوصول إلى وكيل xfi-system-design","محدود لحالات استخدام تخطيط هندسي"]},"version":4},"contentHash":"97e1f300a443fead1a9626df29b522318bb85c95ee04cad32745fd3b326812e9","qualityScore":42}');
