INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('zzfancitizen/agent-skills-self-learning-sample/create-agent', 'create-agent', 'zzfancitizen', 'agent-skills-self-learning-sample', 'community', 'create-agent zzfancitizen agent-skills-self-learning-sample community The create-agent skill enables developers to create new AI agents by following a checklist of steps, including directory structure creation, writing SKILL.md, and registering the agent. It benefits AI developers and teams working on complex projects. 创建AI智能代理需要按照特定的步骤，包括创建目录结构、编写SKILL.md和agent.py等 AIエージェントを作成するには、ディレクトリ構造の作成、SKILL.mdとagent.pyの書き込みなどが必要 AI 에이전트를 생성하려면 디렉토리 구조 생성, SKILL.md와 agent.py 작성 등이 필요 El skill create-agent proporciona una guía para la creación de agentes de IA, incluyendo la estructura de directorios y el registro en el gráfico de flujo de trabajo. Le skill create-agent fournit un guide pour la création d''agents d''IA, y compris la structure de répertoire et l''enregistrement dans le graphique de workflow. Das Skill create-agent bietet eine Anleitung für die Erstellung von KI-Agents, einschließlich Verzeichnisstruktur und Registrierung im Workflow-Graphen. O create-agent é uma habilidade que permite criar agentes de aprendizado de máquina personalizados. Siga nosso guia para configurar o seu agente. Create-agent - это навык, который позволяет создавать пользовательских ИИ агентов. Следуйте нашему руководству для настройки вашего агента. إن create-agent هو مهارة يسمح بإنشاء وكلاء ذكاء اصطناعي مخصصين. اتبع دليلنا لإعداد وكيلك. how to use create-agent create-agent setup guide create-agent alternative create-agent vs agent-tool create-agent install what is create-agent create-agent tutorial create-agent documentation create-agent workflow AI智能代理 创建AI代理 AI代理设置 SKILL.md agent.py Python编程 AI开发 Creates directory structure for new agents Generates SKILL.md files for agent documentation Writes agent.py files for agent implementation Registers new agents in src/agents/__init__.py Updates workflow graph to include new agents Runs verification to ensure agent correctness create-agent is a skill that provides a structured approach to creating new AI agents, involving steps such as writing agent.py and updating the workflow graph.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('armanisadeghi/matrx-sandbox/docker-best-practices', 'community', 'armanisadeghi', 'matrx-sandbox', 'armanisadeghi/matrx-sandbox', 'docker-best-practices', 0, 0, 42, '2026-03-08T01:57:15.498Z', '2026-03-08T02:10:15.600Z', 'd3f54f1b8b6767d1d4896330ed17a532a642f33b0c3399b63496be1f13cfbcf6', '{"id":"armanisadeghi/matrx-sandbox/docker-best-practices","name":"docker-best-practices","description":{"en":"The docker-best-practices skill provides production-grade Docker patterns for developers, ensuring fast builds, minimal size, and robust security. It benefits developers seeking to optimize their container workflow.","zh":"Docker 最佳实践提供了生产级的 Docker 模式，优化了快速构建、最小化大小和安全性","ja":"Docker ベストプラクティスは、高速ビルド、サイズ最小化、セキュリティを最適化したプロダクションレベルの Docker パターンを提供します","ko":"Docker 최적화 설정은 빠른 빌드, 최소한의 크기 및 보안을 최적화한 프로덕션급 Docker 패턴을 제공합니다","es":"Docker Best Practices proporciona patrones de producción optimizados para construcciones rápidas, tamaño mínimo y seguridad a prueba de balas. Cada contenedor se inicia en segundos y sincroniza de manera eficiente.","fr":"Docker Best Practices fournit des modèles de production optimisés pour des constructions rapides, une taille minimale et une sécurité inattaquable. Chaque conteneur démarre en quelques secondes et synchronise de manière efficace.","de":"Docker Best Practices bietet produktionsoptimierte Muster für schnelle Builds, minimalen Speicherplatz und sichere Sicherheit. Jeder Container startet in Sekunden und synchronisiert effizient.","pt":"As melhores práticas para Docker incluem compilações multi-etapas, versões fixas e cache de camadas para construir contêineres rápidos e seguros","ru":"Лучшие практики для Docker включают многоэтапные сборки, фиксированные версии и кэширование слоев для создания быстрых и безопасных контейнеров","ar":"أفضل الممارسات لدوكير تشمل عمليات البناء متعددة المراحل ونسخ محددة وتخزين暂存 للطبقات لإنشاء حاويات سريعة وأمنة"},"seo":{"title":{"en":"Docker Best Practices: Optimized Container Setup Guide | ...","zh":"Docker 最佳实践设置指南","ja":"Docker ベストプラクティス設定ガイド","ko":"Docker 최적화 설정 가이드","es":"Guía de configuración de Docker Best Practices","fr":"Guide de mise en place des meilleures pratiques Docker","de":"Docker Best Practices Einrichtungsleitfaden","pt":"Melhores Práticas Docker: Guia de Configuração","ru":"ИИ Агенты: Лучшие Практики Docker для Продукции","ar":"أفضل الممارسات لدокر: دليل الإعداد"},"description":{"en":"Discover expert-approved Docker best practices for fast, secure, and efficient container builds - learn how to optimize your workflow today!","zh":"学习 Docker 最佳实践，优化容器性能和安全性，实现快速构建和最小化大小","ja":"Docker ベストプラクティスを学び、コンテナのパフォーマンスとセキュリティを最適化し、ビルドを高速化してサイズを最小化する","ko":"Docker 최적화 설정을 통해 컨테이너 성능과 보안을 개선하고 빠른 빌드와 최소한의 크기를实现하십시오","es":"Optimice sus contenedores con las mejores prácticas de Docker para construcciones rápidas, tamaño mínimo y seguridad a prueba de balas. Herramientas de intel...","fr":"Optimisez vos conteneurs avec les meilleures pratiques Docker pour des constructions rapides, une taille minimale et une sécurité inattaquable. Outils d''inte...","de":"Optimieren Sie Ihre Container mit den besten Docker-Praktiken für schnelle Builds, minimalen Speicherplatz und sichere Sicherheit. KI-Tools für Entwickler","pt":"Aprenda as melhores práticas para Docker, incluindo compilações multi-etapas, versões fixas e cache de camadas para construir contêineres rápidos e seguros","ru":"Узнайте лучшие практики для Docker, включая многоэтапные сборки, фиксированные версии и кэширование слоев для создания быстрых и безопасных контейнеров","ar":"تعلم أفضل الممارسات لدوكير، بما في ذلك عمليات البناء متعددة المراحل ونسخ محددة وتخزين暂存 للطبقات لإنشاء حاويات سريعة وأمنة"},"definition":{"en":"docker-best-practices is a set of guidelines for optimizing Docker container builds, focusing on multi-stage builds, pinned versions, layer caching, and minimal attack surface.","zh":"Docker 最佳实践是指一系列优化 Docker 容器性能和安全性的技术和方法","ja":"Docker ベストプラクティスとは、Docker コンテナのパフォーマンスとセキュリティを最適化する一連の技術と方法のこと","ko":"Docker 최적화 설정은 Docker 컨테이너의 성능과 보안을 최적화하는 기술 및 방법에 대한 일련의 지침입니다","es":"Docker Best Practices son patrones de producción optimizados para contenedores Docker que garantizan construcciones rápidas, tamaño mínimo y seguridad a prueba de balas.","fr":"Docker Best Practices sont des modèles de production optimisés pour les conteneurs Docker qui garantissent des constructions rapides, une taille minimale et une sécurité inattaquable.","de":"Docker Best Practices sind produktionsoptimierte Muster für Docker-Container, die schnelle Builds, minimalen Speicherplatz und sichere Sicherheit gewährleisten.","pt":"Melhores práticas para Docker são padrões de produção que visam construir contêineres rápidos, minimizar o tamanho e garantir a segurança","ru":"Лучшие практики для Docker - это производственные стандарты, направленные на создание быстрых контейнеров, минимизацию размера и обеспечение безопасности","ar":"أفضل الممارسات لدوكير هي معايير الإنتاج التي تهدف إلى إنشاء حاويات سريعة وتقليل الحجم وضمان الأمان"},"features":{"en":["Utilizes multi-stage builds to separate build dependencies from runtime","Employs pinned versions to avoid using :latest tags","Leverages layer caching to order instructions from least to most frequently changing","Minimizes attack surface using distroless or slim base images","Ensures efficient syncing and prevents bloat accumulation"],"zh":["多阶段构建","固定版本","层缓存","最小攻击面"],"ja":["マルチステージビルド","バージョン固定","レイヤーキャッシュ","最小攻撃面"],"ko":["다단계 빌드","고정 버전","레이어 캐싱","최소 공격 표면"],"es":["Construcciones multi-etapa para separar dependencias de compilación de tiempo de ejecución","Versiones fijas para evitar el uso de etiquetas '':latest''","Caché de capas para ordenar instrucciones desde las menos hasta las más frecuentemente cambiantes","Superficie de ataque mínima con imágenes base Distroless o Slim","Iniciación de contenedores en segundos y sincronización eficiente"],"fr":["Constructions multi-étapes pour séparer les dépendances de build du runtime","Versions épinglées pour éviter l''utilisation de balises '':latest''","Cache de couches pour ordonner les instructions depuis les moins jusqu''aux plus fréquemment changeantes","Surface d''attaque minimale avec des images de base Distroless ou Slim","Démarrage de conteneurs en quelques secondes et synchronisation efficace"],"de":["Mehrstufige Builds zum Trennen von Build-Abhängigkeiten vom Laufzeit-Code","Feste Versionen, um das Verwenden von '':latest''-Tags zu vermeiden","Layer-Caching, um Anweisungen von den am wenigsten bis zu den am häufigsten ändernden zu ordnen","Minimale Angriffsfläche mit Distroless- oder Slim-Basisbildern","Container-Start in Sekunden und effiziente Synchronisation"],"pt":["Compilações multi-etapas para separar dependências de construção do tempo de execução","Versões fixas para evitar a tag '':latest''","Cache de camadas para ordenar instruções de menos para mais frequentemente alteradas","Imagens base distroless ou slim para minimizar a superfície de ataque"],"ru":["Многоэтапные сборки для разделения сборочных зависимостей от времени выполнения","Фиксированные версии для избежания тега '':latest''","Кэширование слоев для упорядочения инструкций от наименее до наиболее часто изменяемых","Базовые образы distroless или slim для минимизации поверхности атаки"],"ar":["عمليات البناء متعددة المراحل لفصل الإعتماديات البناءية عن وقت التشغيل","نسخ محددة لتجنب علامة '':latest''","تخزين tạmست للطبقات لترتيب الإرشادات من الأقل إلى الأكثر تغييرًا","صور قاعدة خالية من التوزيعة أو رقيقة لتقليل سطح الهجوم"]},"keywords":{"en":["how to use docker best practices","docker best practices tutorial","docker best practices vs docker security","docker best practices install","docker best practices setup guide","what is docker best practices","docker best practices alternative","docker best practices for developers","optimizing docker container builds","docker security best practices"],"zh":["Docker 最佳实践","容器性能优化","Docker 安全性","docker 最佳实践设置","AI工具","容器化"],"ja":["Docker ベストプラクティス","コンテナパフォーマンス最適化","Docker セキュリティ","Docker ベストプラクティス設定","AIエージェント","コンテナ化"],"ko":["Docker 최적화 설정","컨테이너 성능 최적화","Docker 보안","Docker 최적화 설정 가이드","AI 에이전트","컨테이너화"],"es":["Docker Best Practices","mejores prácticas de Docker","construcciones rápidas","tamaño mínimo","seguridad a prueba de balas","Herramientas de inteligencia artificial para desarrolladores","optimización de contenedores"],"fr":["Docker Best Practices","meilleures pratiques Docker","constructions rapides","taille minimale","sécurité inattaquable","Outils d''intelligence artificielle pour les développeurs","optimisation de conteneurs"],"de":["Docker Best Practices","beste Docker-Praktiken","schnelle Builds","minimale Größe","sichere Sicherheit","KI-Tools für Entwickler","Container-Optimierung"],"pt":["melhores práticas docker","docker para produção","compilações multi-etapas","versões fixas","cache de camadas","segurança de contêineres","docker para desenvolvedores"],"ru":["лучшие практики docker","docker для производства","многоэтапные сборки","фиксированные версии","кэширование слоев","безопасность контейнеров","docker для разработчиков"],"ar":["أفضل الممارسات لدوكير","دوكير للاستخدام الإنتاجي","عمليات البناء متعددة المراحل","نسخ محددة","تخزين tạmست للطبقات","أمان الحاويات","دوكير للمطورين"]}},"owner":"armanisadeghi","repo":"matrx-sandbox","repoPath":"armanisadeghi/matrx-sandbox","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.498Z","topics":[],"category":"community","skillMd":{"name":"docker-best-practices","description":"Create production-grade Dockerfiles optimized for speed, security, and minimal size. Use when creating or reviewing Dockerfiles, docker-compose files, or when optimizing container images for Python, Node.js, or multi-runtime environments.","bodyPreview":"# Docker Best Practices\n\nProduction-grade Docker patterns optimized for fast builds, minimal size, and bulletproof security. Every container spins up in seconds, syncs efficiently, and never accumulates bloat.\n\n## Core Principles\n\n1. **Multi-stage builds** — Separate build dependencies from runtime\n2. **Pinned versions** — Never use `:latest` tags\n3. **Layer caching** — Order instructions from least to most frequently changing\n4. **Minimal attack surface** — Distroless or slim base images, non-r","body":"# Docker Best Practices\n\nProduction-grade Docker patterns optimized for fast builds, minimal size, and bulletproof security. Every container spins up in seconds, syncs efficiently, and never accumulates bloat.\n\n## Core Principles\n\n1. **Multi-stage builds** — Separate build dependencies from runtime\n2. **Pinned versions** — Never use `:latest` tags\n3. **Layer caching** — Order instructions from least to most frequently changing\n4. **Minimal attack surface** — Distroless or slim base images, non-root users\n5. **BuildKit features** — Cache mounts, secrets, multi-platform builds\n6. **Fast startup** — Eager dependencies, lazy application code\n\n## Quick Reference\n\n### Python API Services (FastAPI, Flask)\n\n```dockerfile\n# syntax=docker/dockerfile:1.7\nFROM python:3.11.11-slim AS base\n\nWORKDIR /app\n\n# Install system dependencies (cached unless changed)\nRUN apt-get update && apt-get install -y --no-install-recommends \\\n    ca-certificates \\\n    && rm -rf /var/lib/apt/lists/*\n\n# Create non-root user\nRUN groupadd -g 1000 app && \\\n    useradd -m -u 1000 -g app app\n\n# ─── Build stage ───\nFROM base AS builder\n\nRUN apt-get update && apt-get install -y --no-install-recommends \\\n    build-essential \\\n    && rm -rf /var/lib/apt/lists/*\n\n# Install dependencies with cache mount\nCOPY pyproject.toml ./\nRUN --mount=type=cache,target=/root/.cache/pip \\\n    pip install --no-cache-dir .\n\n# ─── Production stage ───\nFROM base AS production\n\nCOPY --from=builder /usr/local/lib/python3.11/site-packages /usr/local/lib/python3.11/site-packages\nCOPY --from=builder /usr/local/bin /usr/local/bin\n\nCOPY . .\n\nUSER app\nEXPOSE 8000\n\nHEALTHCHECK --interval=30s --timeout=5s --start-period=10s --retries=3 \\\n    CMD python -c \"import httpx; httpx.get(''http://localhost:8000/health'', timeout=2)\"\n\nCMD [\"uvicorn\", \"app.main:app\", \"--host\", \"0.0.0.0\", \"--port\", \"8000\"]\n```\n\n### Multi-Runtime Sandbox (Python + Node + Tools)\n\n```dockerfile\n# syntax=docker/dockerfile:1.7\nFROM ubuntu:22.04.5 AS base\n\nENV DEBIAN_FRONTEND=noninteractive \\\n    LANG=C.UTF-8 \\\n    LC_ALL=C.UTF-8\n\n# Single apt layer for all system packages\nRUN --mount=type=cache,target=/var/cache/apt,sharing=locked \\\n    --mount=type=cache,target=/var/lib/apt,sharing=locked \\\n    apt-get update && apt-get install -y --no-install-recommends \\\n    # Core utilities\n    bash curl wget git jq unzip ca-certificates \\\n    # Build tools (for native extensions)\n    build-essential libffi-dev libssl-dev \\\n    # FUSE for S3 mount\n    fuse libfuse2 \\\n    # Process management\n    tini \\\n    # Python\n    python3.11 python3.11-venv python3.11-dev python3-pip \\\n    && ln -sf /usr/bin/python3.11 /usr/bin/python3 \\\n    && ln -sf /usr/bin/python3.11 /usr/bin/python \\\n    && rm -rf /var/lib/apt/lists/*\n\n# Python package installs with cache mount\nRUN --mount=type=cache,target=/root/.cache/pip \\\n    python3 -m pip install --no-cache-dir --upgrade pip setuptools wheel\n\n# Node.js via official NodeSource script\nRUN curl -fsSL https://deb.nodesource.com/setup_20.x | bash - && \\\n    apt-get install -y --no-install-recommends nodejs && \\\n    rm -rf /var/lib/apt/lists/* && \\\n    npm install -g npm@latest\n\n# Create non-root user\nRUN groupadd -g 1000 agent && \\\n    useradd -m -u 1000 -g agent -s /bin/bash agent\n\nUSER agent\nWORKDIR /home/agent\n\nENTRYPOINT [\"tini\", \"--\"]\nCMD [\"/bin/bash\"]\n```\n\n### Development vs Production Patterns\n\n```dockerfile\n# ─── Development stage (hot reload, debug tools) ───\nFROM base AS development\n\nRUN --mount=type=cache,target=/root/.cache/pip \\\n    pip install --no-cache-dir -e \".[dev]\"\n\nCOPY . .\n\n# Mount source as volume for hot reload\nCMD [\"uvicorn\", \"app.main:app\", \"--host\", \"0.0.0.0\", \"--reload\"]\n\n# ─── Production stage (minimal, optimized) ───\nFROM base AS production\n\nCOPY --from=builder /usr/local/lib/python3.11/site-packages /usr/local/lib/python3.11/site-packages\nCOPY . .\n\nUSER app\n\nCMD [\"uvicorn\", \"app.main:app\", \"--host\", \"0.0.0.0\"]\n```\n\n## Essential Patterns\n\n### Version Pinning\n\n```dockerfile\n# ❌ NEVER use latest\nFROM python:3.11-slim\n\n# ✅ ALWAYS pin to patch version\nFROM python:3.11.11-slim\n\n# ✅ Pin all base images with digest for immutability\nFROM python:3.11.11-slim@sha256:abc123...\n```\n\nCheck latest versions:\n- Python: https://hub.docker.com/_/python/tags\n- Node: https://hub.docker.com/_/node/tags\n- Ubuntu: https://hub.docker.com/_/ubuntu/tags\n\n### BuildKit Cache Mounts\n\n```dockerfile\n# ❌ Old way — downloads every build\nRUN pip install -r requirements.txt\n\n# ✅ New way — reuses download cache\nRUN --mount=type=cache,target=/root/.cache/pip \\\n    pip install -r requirements.txt\n\n# ✅ npm cache mount\nRUN --mount=type=cache,target=/root/.npm \\\n    npm ci --prefer-offline\n\n# ✅ apt cache mount (shared across concurrent builds)\nRUN --mount=type=cache,target=/var/cache/apt,sharing=locked \\\n    --mount=type=cache,target=/var/lib/apt,sharing=locked \\\n    apt-get update && apt-get install -y package-name\n```\n\n### Layer Ordering for Optimal Caching\n\n```dockerfile\n# Install dependencies (rarely change) — cached ✅\nCOPY pyproject.toml ./\nRUN pip install .\n\n# Copy application code (changes often) — rebuilt on every change ✅\nCOPY . .\n```\n\n### Health Checks\n\n```dockerfile\n# Python API\nHEALTHCHECK --interval=30s --timeout=5s --start-period=10s --retries=3 \\\n    CMD python -c \"import httpx; httpx.get(''http://localhost:8000/health'')\"\n\n# Node.js API\nHEALTHCHECK --interval=30s --timeout=5s --start-period=10s --retries=3 \\\n    CMD node -e \"require(''http'').get(''http://localhost:3000/health'', (r) => process.exit(r.statusCode === 200 ? 0 : 1))\"\n\n# General process check\nHEALTHCHECK --interval=30s --timeout=5s CMD pgrep -x python3 || exit 1\n```\n\n### Security Hardening\n\n```dockerfile\n# 1. Non-root user\nRUN groupadd -g 1000 app && \\\n    useradd -m -u 1000 -g app app\nUSER app\n\n# 2. Read-only root filesystem (in docker-compose or k8s)\n# docker run --read-only --tmpfs /tmp ...\n\n# 3. Drop capabilities (in docker-compose)\n# security_opt:\n#   - no-new-privileges:true\n# cap_drop:\n#   - ALL\n\n# 4. Minimal base image (distroless for Python/Node)\nFROM gcr.io/distroless/python3-debian12:latest\n```\n\n## docker-compose.yml Best Practices\n\n```yaml\nservices:\n  api:\n    build:\n      context: .\n      dockerfile: Dockerfile\n      target: production  # Multi-stage target\n      cache_from:\n        - type=registry,ref=ghcr.io/org/api:buildcache\n    image: org/api:latest\n    restart: unless-stopped\n    \n    # Security\n    security_opt:\n      - no-new-privileges:true\n    cap_drop:\n      - ALL\n    read_only: true\n    tmpfs:\n      - /tmp\n    \n    # Resources\n    deploy:\n      resources:\n        limits:\n          cpus: ''2''\n          memory: 2G\n        reservations:\n          cpus: ''1''\n          memory: 1G\n    \n    # Health check\n    healthcheck:\n      test: [\"CMD\", \"curl\", \"-f\", \"http://localhost:8000/health\"]\n      interval: 30s\n      timeout: 5s\n      retries: 3\n      start_period: 10s\n    \n    # Env\n    env_file: .env\n    environment:\n      - NODE_ENV=production\n```\n\n## .dockerignore\n\n**CRITICAL**: Always create `.dockerignore` to exclude unnecessary files from build context.\n\n```\n# Version control\n.git/\n.github/\n.gitignore\n\n# Python\n__pycache__/\n*.pyc\n*.pyo\n*.pyd\n.Python\n*.so\n*.egg-info/\ndist/\nbuild/\n.venv/\nvenv/\n*.pytest_cache/\n.coverage\n\n# Node\nnode_modules/\nnpm-debug.log*\n.npm/\n\n# IDE\n.vscode/\n.idea/\n*.swp\n*.swo\n.DS_Store\n\n# Env files (never copy .env to image)\n.env\n.env.*\n!.env.example\n\n# CI/CD\n.github/\n*.md\n!README.md\n\n# Docs\ndocs/\n*.md\n```\n\n## Dockerfile Review Checklist\n\nWhen creating or reviewing a Dockerfile, verify:\n\n### Performance\n- [ ] Multi-stage build for services with build dependencies\n- [ ] `--mount=type=cache` for pip/npm/apt downloads\n- [ ] Layer ordering: system packages → language runtime → dependencies → app code\n- [ ] `.dockerignore` excludes unnecessary files\n- [ ] Single `apt-get update && install && rm -rf` per stage (not multiple RUN commands)\n\n### Security\n- [ ] Base image pinned to specific version (no `:latest`)\n- [ ] Non-root user for runtime\n- [ ] Minimal base image (slim, alpine, or distroless)\n- [ ] No secrets in ENV or build args (use `--mount=type=secret` instead)\n- [ ] Health check defined\n\n### Size\n- [ ] `--no-install-recommends` on apt-get\n- [ ] `rm -rf /var/lib/apt/lists/*` after apt-get\n- [ ] `--no-cache-dir` on pip installs\n- [ ] Multi-stage excludes build tools from final image\n- [ ] Production stage only includes runtime dependencies\n\n### Correctness\n- [ ] `WORKDIR` set before COPY\n- [ ] Correct user ownership for copied files if using non-root user\n- [ ] `EXPOSE` matches actual port\n- [ ] `CMD`/`ENTRYPOINT` is production-appropriate (no `--reload`)\n- [ ] Environment variables have sensible defaults\n\n## Common Mistakes to Avoid\n\n### ❌ Installing dev dependencies in production\n```dockerfile\nFROM python:3.11-slim\nRUN pip install -e \".[dev]\"  # Includes pytest, debug tools, etc.\n```\n\n### ✅ Separate dev and prod stages\n```dockerfile\nFROM base AS development\nRUN pip install -e \".[dev]\"\n\nFROM base AS production\nRUN pip install .  # Prod deps only\n```\n\n### ❌ Running as root\n```dockerfile\nCMD [\"uvicorn\", \"app:main\"]  # Runs as root\n```\n\n### ✅ Create and use non-root user\n```dockerfile\nRUN useradd -m app\nUSER app\nCMD [\"uvicorn\", \"app:main\"]\n```\n\n### ❌ Copying before installing dependencies\n```dockerfile\nCOPY . .  # Invalidates cache on every code change\nRUN pip install -r requirements.txt\n```\n\n### ✅ Install dependencies first\n```dockerfile\nCOPY requirements.txt .\nRUN pip install -r requirements.txt  # Cached unless requirements.txt changes\nCOPY . .\n```\n\n### ❌ Using `:latest` tags\n```dockerfile\nFROM python:3-slim  # Breaks reproducibility\n```\n\n### ✅ Pin to patch version\n```dockerfile\nFROM python:3.11.11-slim\n```\n\n### ❌ Multiple apt-get updates\n```dockerfile\nRUN apt-get update && apt-get install -y curl\nRUN apt-get update && apt-get install -y git  # Second update is wasted\n```\n\n### ✅ Single apt layer\n```dockerfile\nRUN apt-get update && apt-get install -y \\\n    curl \\\n    git \\\n    && rm -rf /var/lib/apt/lists/*\n```\n\n## Building Images\n\n### Enable BuildKit\n```bash\nexport DOCKER_BUILDKIT=1\n\n# Or in docker-compose.yml\nexport COMPOSE_DOCKER_CLI_BUILD=1\n```\n\n### Multi-platform builds\n```bash\n# For ARM64 Macs building x86_64 images\ndocker buildx build \\\n  --platform linux/amd64 \\\n  --tag org/app:latest \\\n  --push \\\n  .\n\n# Build for both platforms\ndocker buildx build \\\n  --platform linux/amd64,linux/arm64 \\\n  --tag org/app:latest \\\n  --push \\\n  .\n```\n\n### Cache optimization\n```bash\n# Use inline cache for CI\ndocker buildx build \\\n  --cache-from type=registry,ref=org/app:buildcache \\\n  --cache-to type=registry,ref=org/app:buildcache,mode=max \\\n  --tag org/app:latest \\\n  --push \\\n  .\n```\n\n## Additional Resources\n\n- For detailed explanations and edge cases, see [reference.md](reference.md)\n- For complete working examples, see [templates/](templates/)\n- For image size comparison and benchmarks, see [optimization.md](optimization.md)\n\n## When NOT to Use This Skill\n\n- Creating `docker-compose.yml` for simple local dev (just use official images)\n- Debugging running containers (use `docker logs`, `docker exec` instead)\n- Container orchestration at scale (Kubernetes/ECS patterns differ significantly)\n"},"lastSynced":"2026-03-08T02:10:15.600Z","agentAnalysis":{"suitability":{"en":"Perfect for Containerization Agents needing production-grade Docker optimization with minimal size and robust security","zh":"适用于需要生产级Docker优化的容器化代理，具有最小尺寸和强大的安全性","ja":"コンテナ化エージェントが生産品質のDocker最適化を必要とする場合に最適で、サイズは最小限でセキュリティは強固です","ko":"생산급 Docker 최적화를 필요로 하는 컨테이너화 에이전트에게 적합하며, 최소한의 크기와 강력한 보안을 제공합니다","es":"Perfecto para Agentes de Contenedorización que necesitan optimización de Docker de nivel de producción con tamaño mínimo y seguridad robusta","fr":"Parfait pour les agents de conteneurisation nécessitant une optimisation Docker de niveau de production avec une taille minimale et une sécurité robuste","de":"Perfekt für Containerisierungsagenten, die eine optimale Docker-Optimierung mit minimalem Größe und robuster Sicherheit benötigen","pt":"Perfeito para Agentes de Containerização que necessitam de otimização de produção de grade Docker com tamanho mínimo e segurança robusta","ru":"Идеально для агентов контейнеризации, которым необходима оптимизация производительности Docker с минимальным размером и надежной безопасностью","ar":"مثالي لعمليات एजنت الحاوية التي تحتاج إلى تحسين إنتاج Docker من الدرجة الأولى مع حجم صغير وأمان قوي"},"recommendation":{"en":"Empowers agents to create lightweight and secure Docker containers using multi-stage builds, pinned versions, and layer caching, ensuring fast builds and minimal attack surface with distroless or slim base images","zh":"赋予代理创建轻量级和安全的Docker容器的能力，使用多阶段构建、固定版本和层缓存，确保快速构建和最小的攻击面，使用distroless或slim基础镜像","ja":"マルチステージビルド、固定バージョン、レイヤーキャッシングを使用して、軽量でセキュアなDockerコンテナを作成するエージェントを可能にし、distrolessまたはslimベースイメージを使用して、高速なビルドと最小の攻撃面を確保します","ko":"다단계 빌드, 고정 버전 및 계층 캐싱을 사용하여 경량화되고 보안이 강화된 Docker 컨테이너를 생성할 수 있는 에이전트를 가능하게 하며, distroless 또는 slim 기본 이미지를 사용하여 빠른 빌드와 최소한의 공격 표면을 보장합니다","es":"Habilita a los agentes a crear contenedores Docker ligeros y seguros utilizando construcciones multietapa, versiones bloqueadas y caché de capas, lo que garantiza construcciones rápidas y una superficie de ataque mínima con imágenes base distroless o slim","fr":"Permet aux agents de créer des conteneurs Docker légers et sécurisés en utilisant des builds mult étapes, des versions épinglées et un cache de couches, garantissant ainsi des builds rapides et une surface d''attaque minimale avec des images de base distroless ou slim","de":"Ermöglicht es den Agenten, leichte und sichere Docker-Container mithilfe von Mehrstufen-Builds, festgelegten Versionen und Layer-Caching zu erstellen, was schnelle Builds und eine minimale Angriffsfläche mit distroless- oder slim-Basisbildern gewährleistet","pt":"Habilita os agentes a criar contêineres Docker leves e seguros usando compilações em várias etapas, versões fixadas, e cache de camadas, garantindo compilações rápidas e superfície de ataque mínima com imagens base distroless ou slim","ru":"Позволяет агентам создавать легкие и безопасные контейнеры Docker, используя многоэтапные сборки, закрепленные версии и кэширование слоев, обеспечивая быстрые сборки и минимальную поверхность атаки с помощью базовых изображений distroless или slim","ar":"يتمكن الوكلاء من إنشاء حاويات Docker خفيفة وآمنة باستخدام عمليات بناء متعددة المراحل وإصدارات مثبتة وتخزين مؤقت للطبقات، مما يضمن عمليات بناء سريعة وسطح هجوم أدنى مع صور قاعدة خفيفة أو رشيقة"},"useCases":{"en":["Optimizing Dockerfile configurations for faster builds","Minimizing container size using layer caching and minimal base images","Ensuring robust security with pinned versions and minimal attack surface"],"zh":["为更快的构建优化Dockerfile配置","使用层缓存和最小的基础镜像来最小化容器大小","使用固定版本和最小的攻击面来确保强大的安全性"],"ja":["より高速なビルドのためのDockerfile構成の最適化","レイヤーキャッシングと最小のベースイメージを使用してコンテナサイズを最小化する","固定バージョンと最小の攻撃面を使用して強固なセキュリティを確保する"],"ko":["더 빠른 빌드를 위한 Dockerfile 구성 최적화","계층 캐싱 및 최소한의 기본 이미지 사용으로 컨테이너 크기 최소화","고정 버전 및 최소한의 공격 표면 사용으로 강력한 보안 보장"],"es":["Optimizar configuraciones de Dockerfile para builds más rápidos","Minimizar el tamaño del contenedor utilizando caché de capas y imágenes base mínimas","Garantizar una seguridad robusta con versiones bloqueadas y superficie de ataque mínima"],"fr":["Optimiser les configurations de Dockerfile pour des builds plus rapides","Minimiser la taille du conteneur en utilisant le cache de couches et les images de base minimales","Assurer une sécurité robuste avec des versions épinglées et une surface d''attaque minimale"],"de":["Optimieren von Dockerfile-Konfigurationen für schnellere Builds","Minimieren der Containertgröße unter Verwendung von Layer-Caching und minimalen Basisbildern","Sicherstellen einer robusten Sicherheit mit festgelegten Versionen und minimalem Angriffspunkt"],"pt":["Otimizar configurações do Dockerfile para compilações mais rápidas","Minimizar o tamanho do contêiner usando cache de camadas e imagens base mínimas","Garantir segurança robusta com versões fixadas e superfície de ataque mínima"],"ru":["Оптимизировать конфигурации Dockerfile для более быстрых сборок","Минимизировать размер контейнера, используя кэширование слоев и минимальные базовые изображения","Обеспечить надежную безопасность с помощью закрепленных версий и минимальной поверхности атаки"],"ar":["تحسين تكوين Dockerfile لعمليات البناء الأسرع","تقليل حجم الحاوية باستخدام ذاكرة مؤقتة للطبقات والصور القاعدية الطفيفة","ضمان أمان قوي بإصدارات مثبتة وسطح هجوم أدنى"]},"limitations":{"en":["Requires Docker installation and configuration","Limited to Docker-based containerization"],"zh":["需要Docker的安装和配置","仅限于Docker基于的容器化"],"ja":["Dockerのインストールと構成が必要","Dockerベースのコンテナ化に限定される"],"ko":["Docker 설치 및 구성이 필요","Docker 기반 컨테이너화에만 제한됨"],"es":["Requiere instalación y configuración de Docker","Limitado a la contenedorización basada en Docker"],"fr":["Nécessite l''installation et la configuration de Docker","Limité à la conteneurisation basée sur Docker"],"de":["Benötigt Docker-Installation und -Konfiguration","Begrenzt auf Docker-basierte Containerisierung"],"pt":["Requer instalação e configuração do Docker","Limitado à containerização baseada em Docker"],"ru":["Требуется установка и конфигурация Docker","Ограничен контейнеризацией на основе Docker"],"ar":["يتطلب تثبيت وتكوين Docker","محدود بالحاويات القائمة على Docker"]},"version":4},"contentHash":"d3f54f1b8b6767d1d4896330ed17a532a642f33b0c3399b63496be1f13cfbcf6","qualityScore":42}');
