INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('armanisadeghi/matrx-sandbox/docker-best-practices', 'docker-best-practices', 'armanisadeghi', 'matrx-sandbox', 'community', 'docker-best-practices armanisadeghi matrx-sandbox community The docker-best-practices skill provides production-grade Docker patterns for developers, ensuring fast builds, minimal size, and robust security. It benefits developers seeking to optimize their container workflow. Docker 最佳实践提供了生产级的 Docker 模式，优化了快速构建、最小化大小和安全性 Docker ベストプラクティスは、高速ビルド、サイズ最小化、セキュリティを最適化したプロダクションレベルの Docker パターンを提供します Docker 최적화 설정은 빠른 빌드, 최소한의 크기 및 보안을 최적화한 프로덕션급 Docker 패턴을 제공합니다 Docker Best Practices proporciona patrones de producción optimizados para construcciones rápidas, tamaño mínimo y seguridad a prueba de balas. Cada contenedor se inicia en segundos y sincroniza de manera eficiente. Docker Best Practices fournit des modèles de production optimisés pour des constructions rapides, une taille minimale et une sécurité inattaquable. Chaque conteneur démarre en quelques secondes et synchronise de manière efficace. Docker Best Practices bietet produktionsoptimierte Muster für schnelle Builds, minimalen Speicherplatz und sichere Sicherheit. Jeder Container startet in Sekunden und synchronisiert effizient. As melhores práticas para Docker incluem compilações multi-etapas, versões fixas e cache de camadas para construir contêineres rápidos e seguros Лучшие практики для Docker включают многоэтапные сборки, фиксированные версии и кэширование слоев для создания быстрых и безопасных контейнеров أفضل الممارسات لدوكير تشمل عمليات البناء متعددة المراحل ونسخ محددة وتخزين暂存 للطبقات لإنشاء حاويات سريعة وأمنة how to use docker best practices docker best practices tutorial docker best practices vs docker security docker best practices install docker best practices setup guide what is docker best practices docker best practices alternative docker best practices for developers optimizing docker container builds docker security best practices Docker 最佳实践 容器性能优化 Docker 安全性 docker 最佳实践设置 AI工具 容器化 Utilizes multi-stage builds to separate build dependencies from runtime Employs pinned versions to avoid using :latest tags Leverages layer caching to order instructions from least to most frequently changing Minimizes attack surface using distroless or slim base images Ensures efficient syncing and prevents bloat accumulation docker-best-practices is a set of guidelines for optimizing Docker container builds, focusing on multi-stage builds, pinned versions, layer caching, and minimal attack surface.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('charlesmsiegel/tg/python-simplifier', 'community', 'charlesmsiegel', 'tg', 'charlesmsiegel/tg', 'python-simplifier', 0, 0, 42, '2026-03-08T01:57:15.501Z', '2026-03-08T02:10:18.611Z', 'b49df2fc820a27aacbbca7669c058d7efd4387161545999c87e82dc346c31737', '{"id":"charlesmsiegel/tg/python-simplifier","name":"python-simplifier","description":{"en":"The python-simplifier skill simplifies complex Python code for developers, making it more maintainable and readable. It provides analysis scripts to identify areas for improvement","zh":"python-simplifier 是一个 Python 代码简化工具，能够将复杂的代码转换为清晰、可读的代码","ja":"python-simplifier は Python コード簡素化ツールで、複雑なコードをクリーンで可読なコードに変換します","ko":"python-simplifier는 Python 코드 단순화 도구로 복잡한 코드를 깨끗하고 읽기 쉬운 코드로 변환합니다","es":"Python-simplifier es una herramienta que ayuda a transformar código Python complejo en soluciones limpias y mantenibles. Ofrece scripts de análisis para evaluar la complejidad y detectar problemas de código","fr":"Python-simplifier est un outil qui aide à transformer du code Python complexe en solutions propres et maintenables. Il propose des scripts d''analyse pour évaluer la complexité et détecter les problèmes de code","de":"Python-simplifier ist ein Tool, das dabei hilft, komplexen Python-Code in saubere und wartbare Lösungen umzuwandeln. Es bietet Analyse-Skripte, um die Komplexität zu bewerten und Codeprobleme zu erkennen","pt":"O python-simplifier é uma ferramenta que ajuda a transformar código Python complexo em soluções limpas e legíveis","ru":"ИИ Агент python-simplifier - это инструмент, который помогает упростить сложный код Python","ar":"python-simplifier هو أداة تساعد على تحويل código Python المعقد إلى حلول نظيفة وقابلة للقراءة"},"seo":{"title":{"en":"python-simplifier: Simplify Python Code | AI Agent Skill","zh":"Python 代码简化工具 - python-simplifier 设置指南","ja":"Python コード簡