INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Deadwood-ai/deadtrees/db-migration', 'db-migration', 'Deadwood-ai', 'deadtrees', 'community', 'db-migration Deadwood-ai deadtrees community The db-migration skill enables developers to safely create and validate database migrations in DeadTrees. It provides a workflow for MCP-first database operations. DeadTrees MCP-first 工作流用于安全地创建和验证数据库迁移，确保本地和生产数据库的一致性 DeadTrees MCP-first ワークフローは、データベース移行の安全な作成と検証を可能にし、ローカルとプロダクションのデータベースの一貫性を保証します DeadTrees MCP-first 워크플로우는 데이터베이스 마이그레이션의 안전한 생성과 검증을 가능하게 하며 로컬과 프로덕션 데이터베이스의 일관성을 보장합니다 db-migration es una herramienta para migrar bases de datos en DeadTrees de forma segura. Utiliza MCP para validar y crear migraciones db-migration est un outil pour migrer des bases de données dans DeadTrees de manière sécurisée. Il utilise MCP pour valider et créer des migrations db-migration ist ein Tool für die sichere Migration von Datenbanken in DeadTrees. Es verwendet MCP, um Migrations zu validieren und zu erstellen O db-migration é um workflow para criar e validar migrações de banco de dados de forma segura com FastAPI e MCP. ИИ Агент db-migration представляет собой рабочий процесс для безопасного создания и проверки миграций базы данных с FastAPI и MCP. db-migration هو سير عمل لإنشاء وتحقق هجرات قاعدة البيانات بطريقة آمنة مع FastAPI و MCP. how to use db-migration db-migration workflow MCP-first database operations db-migration install db-migration setup guide db-migration alternative what is db-migration db-migration vs traditional migration db-migration for DeadTrees 数据库迁移工具 DeadTrees MCP-first 数据库迁移工作流 Python 数据库迁移 FastAPI 数据库迁移 数据库同步检查 数据库迁移安全性 Uses local DB MCP (user-deadtrees-local) for schema changes and validation Verifies local and production DB are in sync using MCP-only checks Runs only relevant, quick tests before broader checks for fast test scope Ensures safe database migrations with MCP-first database operations Supports MCP tools for database operations db-migration is a workflow for safely creating and validating database migrations in DeadTrees using MCP tools and local DB MCP for schema changes and validation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('flavioGonz/pixelflow/mobile-touch', 'community', 'flavioGonz', 'pixelflow', 'flavioGonz/pixelflow', 'mobile-touch', 0, 0, 42, '2026-03-08T01:57:15.532Z', '2026-03-08T02:11:07.960Z', 'fd3c19bf58697c0e429aab4fd54055c7676da4f8477f17994c99ac83b0504506', '{"id":"flavioGonz/pixelflow/mobile-touch","name":"mobile-touch","description":{"en":"The mobile-touch skill applies Disney''s 12 animation principles to mobile gestures, haptics, and native app motion, benefiting developers who want to create engaging and intuitive mobile experiences.","zh":"移动触摸动画是通过应用Disney的12个动画原则来实现的，包括橡皮筋效果、预期动画和过渡效果等","ja":"モバイルタッチアニメーションは、Disneyの12原則を適用して実現される技術です","ko":"모바일 터치 애니메이션은 디즈니의 12가지 애니메이션 원칙을 적용하여 구현되는 기술입니다","es":"Aplicación de los 12 principios de animación de Disney a gestos móviles y motion de aplicaciones nativas","fr":"Application des 12 principes d''animation de Disney aux gestes mobiles et au mouvement d''applications natives","de":"Anwendung der 12 Animationprinzipien von Disney auf mobile Gesten und native App-Bewegungen","pt":"A animação de toque móvel com Pixelflow aplica os 12 princípios de animação da Disney em gestos móveis e movimento de aplicativos nativos","ru":"Анимация прикосновений для мобильных приложений с помощью Pixelflow применяет 12 принципов анимации Disney к мобильным жестам и движению родных приложений","ar":"حركة اللمس للأجهزة النقالة مع Pixelflow تطبق مبادئ الانیمیشن الـ 12 من ديزني على الإشارات الناقلة وحركة التطبيقات الأصلية"},"seo":{"title":{"en":"mobile-touch: Mastering Disney''s 12 Principles for AI Age...","zh":"移动触摸动画设置指南 - 应用Disney的12个动画原则","ja":"モバイルタッチアニメーションのベストプラクティス - Disneyの12原則を適用","ko":"모바일 터치 애니메이션 구축 가이드 - 디즈니의 12가지 애니메이션 원칙 적용","es":"Guía de Configuración de Animaciones de Toque Móvil con H...","fr":"Guide de Configuration des Animations de Touch Mobile ave...","de":"Einrichtungsleitfaden für Mobile Touch-Animationen mit KI...","pt":"Guia de Configuração de Animação de Toque Móvel com Pixel...","ru":"ИИ Агенты: Настройка Анимации Прикосновений для Мобильных...","ar":"دليل إعداد حركة اللمس للأجهزة النقالة باستخدام Pixelflow"},"description":{"en":"Unlock seamless mobile interactions with mobile-touch! Learn how to apply Disney''s 12 animation principles to gestures, haptics, and native app motion. Get s...","zh":"了解移动触摸动画的技术细节，包括橡皮筋效果、预期动画和过渡效果等","ja":"モバイルタッチアニメーションの技術詳細を学び、Disneyの12原則を適用して高品質なアニメーションを作成する","ko":"모바일 터치 애니메이션의 기술 세부 정보를 알아보고 디즈니의 12가지 원칙을 적용하여 고품질 애니메이션을 생성하는 방법","es":"Aprende a aplicar los 12 principios de animación de Disney a gestos móviles, hápticos y motion de aplicaciones nativas con herramientas de inteligencia artif...","fr":"Découvrez comment appliquer les 12 principes d''animation de Disney aux gestes mobiles, à l''haptique et au mouvement d''applications natives avec des outils d''...","de":"Erfahren Sie, wie Sie die 12 Animationprinzipien von Disney auf mobile Gesten, Haptik und native App-Bewegungen mit KI-Tools anwenden können","pt":"Aprenda a aplicar os 12 princípios de animação da Disney em gestos móveis, haptics e movimento de aplicativos nativos com Pixelflow","ru":"Изучите, как применять 12 принципов анимации Disney к мобильным жестам, хаптике и движению родных приложений с помощью Pixelflow","ar":"تعلم كيفية تطبيق مبادئ الانیمیشن الـ 12 من ديزني على الإشارات الناقلة، واللمس، وحركة التطبيقات الأصلية باستخدام Pixelflow"},"definition":{"en":"mobile-touch is a skill that brings Disney''s 12 animation principles to mobile interactions, enhancing gestures, haptics, and native app motion with techniques like rubber-banding and momentum scrolling.","zh":"移动触摸动画是指在移动设备上使用触摸手势、触觉和原生应用程序动画来创建高品质的用户体验","ja":"モバイルタッチアニメーションとは、モバイルデバイス上でタッチジェスチャ、ハプティクス、ネイティブアプリ動画を使用して高品質のユーザーエクスペリエンスを作成する技術です","ko":"모바일 터치 애니메이션은 모바일 장치에서 터치 제스처, 햅틱 및 네이티브 앱 애니메이션을 사용하여 고품질의 사용자 경험을 생성하는 기술입니다","es":"La animación de toque móvil es una técnica que aplica los principios de animación de Disney a interfaces móviles","fr":"L''animation de touch mobile est une technique qui applique les principes d''animation de Disney aux interfaces mobiles","de":"Die Mobile Touch-Animation ist eine Technik, die die Animationprinzipien von Disney auf mobile Schnittstellen anwendet","pt":"Animação de toque móvel é uma técnica que aplica os 12 princípios de animação da Disney em gestos móveis e movimento de aplicativos nativos","ru":"Анимация прикосновений - это техника, которая применяет 12 принципов анимации Disney к мобильным жестам и движению родных приложений","ar":"حركة اللمس هي تقنية تطبق مبادئ الانیمیشن الـ 12 من ديزني على الإشارات الناقلة وحركة التطبيقات الأصلية"},"features":{"en":["Applies Squash & Stretch principle with rubber-banding and bounce on scroll limits","Utilizes Anticipation principle with peek before reveal and long-press preview","Employs Staging principle with sheet presentations and focus states","Supports Straight Ahead and Pose to Pose principles with gesture-driven and preset transitions","Implements Follow Through and Overlapping principles with momentum scrolling"],"zh":["橡皮筋效果（Rubber-banding）","预期动画（Anticipation）","过渡效果（Straight Ahead / Pose to Pose）","动量滚动（Momentum scrolling）","焦点状态（Focus states）","手势驱动的动画（Gesture-driven animations）"],"ja":["ラバーバンディング（Rubber-banding）","予期アニメーション（Anticipation）","遷移効果（Straight Ahead / Pose to Pose）","モメンタムスクロール（Momentum scrolling）","フォーカス状態（Focus states）","ジェスチャードリブンのアニメーション（Gesture-driven animations）"],"ko":["고무 밴드 효과（Rubber-banding）","예상 애니메이션（Anticipation）","전환 효과（Straight Ahead / Pose to Pose）","모멘텀 스크롤（Momentum scrolling）","포커스 상태（Focus states）","제스처 기반 애니메이션（Gesture-driven animations）"],"es":["Aplicación de los principios de Squash y Stretch con rubber-banding y bounce on scroll limits","Implementación de Anticipation con peek before reveal y long-press preview","Uso de Staging con sheet presentations y focus states","Diseño de Straight Ahead y Pose to Pose con gesture-driven y preset transitions","Integración de Follow Through y Overlapping con momentum scroll"],"fr":["Application des principes de Squash et Stretch avec rubber-banding et bounce on scroll limits","Mise en œuvre de l''Anticipation avec peek before reveal et long-press preview","Utilisation de Staging avec sheet presentations et focus states","Conception de Straight Ahead et Pose to Pose avec gesture-driven et preset transitions","Intégration de Follow Through et Overlapping avec momentum scroll"],"de":["Anwendung der Prinzipien von Squash und Stretch mit Rubber-banding und Bounce on Scroll Limits","Implementierung von Anticipation mit Peek before Reveal und Long-Press-Preview","Verwendung von Staging mit Sheet-Präsentationen und Fokus-Zuständen","Entwurf von Straight Ahead und Pose to Pose mit Gesture-driven- und Preset-Transitions","Integration von Follow Through und Overlapping mit Momentum-Scroll"],"pt":["Aplicação dos 12 princípios de animação da Disney","Rubber-banding e bounce on scroll limits","Peek before reveal e long-press preview","Sheet presentations e focus states","Gesture-driven vs preset transitions"],"ru":["Применение 12 принципов анимации Disney","Rubber-banding и bounce on scroll limits","Peek before reveal и long-press preview","Sheet presentations и focus states","Gesture-driven vs preset transitions"],"ar":["تطبيق مبادئ الانیمیشن الـ 12 من ديزني","Rubber-banding و bounce on scroll limits","Peek before reveal و long-press preview","Sheet presentations و focus states","Gesture-driven vs preset transitions"]},"keywords":{"en":["how to use mobile-touch","what is mobile-touch","mobile-touch alternative","mobile-touch vs pixelflow","mobile-touch install","mobile-touch setup guide","Disney''s 12 principles for mobile","mobile gesture animation","haptics and native app motion"],"zh":["移动触摸动画","Disney的12个动画原则","触摸手势","触觉","原生应用程序动画","高品质用户体验","AIエージェント","移动开发"],"ja":["モバイルタッチアニメーション","Disneyの12原則","タッチジェスチャ","ハプティクス","ネイティブアプリ動画","高品質ユーザーエクスペリエンス","AIエージェント","モバイル開発"],"ko":["모바일 터치 애니메이션","디즈니의 12가지 애니메이션 원칙","터치 제스처","햅틱","네이티브 앱 애니메이션","고품질 사용자 경험","AI 에이전트","모바일 개발"],"es":["animación de toque móvil","principios de animación de Disney","gestos móviles","hápticos","motion de aplicaciones nativas","herramientas de inteligencia artificial","desarrollo de aplicaciones móviles","ux móvil","ui móvil"],"fr":["animation de touch mobile","principes d''animation de Disney","gestes mobiles","haptique","mouvement d''applications natives","outils d''intelligence artificielle","développement d''applications mobiles","ux mobile","ui mobile"],"de":["Mobile Touch-Animation","Animationprinzipien von Disney","mobile Gesten","Haptik","Bewegung von nativen Apps","KI-Tools","Entwicklung von mobilen Anwendungen","UX-Mobile","UI-Mobile"],"pt":["animação de toque móvel","Pixelflow","12 princípios de animação da Disney","gestos móveis","haptics","movimento de aplicativos nativos","desenvolvimento de aplicativos móveis","UI/UX"],"ru":["анимация прикосновений","Pixelflow","12 принципов анимации Disney","мобильные жесты","хаптика","движение родных приложений","разработка мобильных приложений","ИИ Агенты"],"ar":["حركة اللمس","Pixelflow","مبادئ الانیمیشن الـ 12 من ديزني","الإشارات الناقلة","اللمس","حركة التطبيقات الأصلية","تطوير التطبيقات النقالة","ادوات الذكاء الاصطناعي"]}},"owner":"flavioGonz","repo":"pixelflow","repoPath":"flavioGonz/pixelflow","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.532Z","topics":[],"category":"community","skillMd":{"name":"mobile-touch","description":"Use when designing iOS/Android gestures, haptic feedback, touch interactions, or native mobile animations.","bodyPreview":"# Mobile Touch Animation\n\nApply Disney''s 12 animation principles to mobile gestures, haptics, and native app motion.\n\n## Quick Reference\n\n| Principle | Mobile Implementation |\n|-----------|----------------------|\n| Squash & Stretch | Rubber-banding, bounce on scroll limits |\n| Anticipation | Peek before reveal, long-press preview |\n| Staging | Sheet presentations, focus states |\n| Straight Ahead / Pose to Pose | Gesture-driven vs preset transitions |\n| Follow Through / Overlapping | Momentum scr","body":"# Mobile Touch Animation\n\nApply Disney''s 12 animation principles to mobile gestures, haptics, and native app motion.\n\n## Quick Reference\n\n| Principle | Mobile Implementation |\n|-----------|----------------------|\n| Squash & Stretch | Rubber-banding, bounce on scroll limits |\n| Anticipation | Peek before reveal, long-press preview |\n| Staging | Sheet presentations, focus states |\n| Straight Ahead / Pose to Pose | Gesture-driven vs preset transitions |\n| Follow Through / Overlapping | Momentum scrolling, trailing elements |\n| Slow In / Slow Out | iOS spring animations, Material easing |\n| Arc | Swipe-to-dismiss curves, card throws |\n| Secondary Action | Haptic pulse with visual feedback |\n| Timing | Touch response <100ms, transitions 250-350ms |\n| Exaggeration | Bounce amplitude, haptic intensity |\n| Solid Drawing | Respect safe areas, consistent anchors |\n| Appeal | 60fps minimum, gesture continuity |\n\n## Principle Applications\n\n**Squash & Stretch**: Implement rubber-band effect at scroll boundaries. Pull-to-refresh should stretch content naturally. Buttons compress on touch.\n\n**Anticipation**: Long-press shows preview before full action. Drag threshold provides visual hint before item lifts. Swipe shows edge of destination content.\n\n**Staging**: Use sheet presentations to maintain context. Dim and scale background during modal focus. Hero transitions connect views meaningfully.\n\n**Straight Ahead vs Pose to Pose**: Gesture-following animations (drag, pinch) are straight ahead—driven by touch input. System transitions (push, present) are pose to pose—predefined keyframes.\n\n**Follow Through & Overlapping**: Content continues moving after finger lifts (momentum). Navigation bar elements animate slightly after main content. Lists items settle with stagger.\n\n**Slow In / Slow Out**: iOS uses spring physics—configure mass, stiffness, damping. Android Material uses standard easing: `FastOutSlowIn`. Never use linear for user-initiated motion.\n\n**Arc**: Thrown cards follow parabolic arcs. Swipe-to-dismiss curves based on velocity vector. FAB expand/collapse follows natural arc path.\n\n**Secondary Action**: Pair haptic feedback with visual response. Button ripple accompanies press. Success checkmark triggers light haptic.\n\n**Timing**: Touch acknowledgment: <100ms. Quick actions: 150-250ms. View transitions: 250-350ms. Complex animations: 350-500ms. Haptic should sync precisely with visual.\n\n**Exaggeration**: Pull-to-refresh stretches beyond natural—makes feedback clear. Error shake is pronounced. Success animations celebrate appropriately.\n\n**Solid Drawing**: Respect device safe areas during animation. Maintain consistent transform origins. Account for notch/dynamic island in motion paths.\n\n**Appeal**: Minimum 60fps, target 120fps on ProMotion displays. Gesture-driven animation must feel connected to finger. Interruptible animations essential.\n\n## Platform Patterns\n\n### iOS\n```swift\n// Spring animation with follow-through\nUIView.animate(withDuration: 0.5,\n               delay: 0,\n               usingSpringWithDamping: 0.7,\n               initialSpringVelocity: 0.5,\n               options: .curveEaseOut)\n\n// Haptic pairing\nlet feedback = UIImpactFeedbackGenerator(style: .medium)\nfeedback.impactOccurred()\n```\n\n### Android\n```kotlin\n// Material spring animation\nSpringAnimation(view, DynamicAnimation.TRANSLATION_Y)\n    .setSpring(SpringForce()\n        .setStiffness(SpringForce.STIFFNESS_MEDIUM)\n        .setDampingRatio(SpringForce.DAMPING_RATIO_MEDIUM_BOUNCY))\n    .start()\n```\n\n## Haptic Guidelines\n\n| Action | iOS | Android |\n|--------|-----|---------|\n| Selection | `.selection` | `EFFECT_TICK` |\n| Success | `.success` | `EFFECT_CLICK` |\n| Warning | `.warning` | `EFFECT_DOUBLE_CLICK` |\n| Error | `.error` | `EFFECT_HEAVY_CLICK` |\n\nHaptics are secondary action—always pair with visual confirmation.\n"},"lastSynced":"2026-03-08T02:11:07.960Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing to create engaging mobile experiences with Disney''s 12 animation principles.","zh":"非常适合需要创建吸引人移动体验的前端代理，特别是使用迪士尼的12个动画原则","ja":"フロントエンドエージェントがディズニーの12のアニメーション原則を使用して魅力的モバイル体験を作成する必要がある場合に最適","ko":"디즈니의 12가지 애니메이션 원리를 사용하여 매력적인 모바일 경험을 생성해야 하는 프론트엔드 에이전트에 적합","es":"Perfecto para agentes Frontend que necesitan crear experiencias móviles atractivas con los 12 principios de animación de Disney.","fr":"Parfait pour les agents Frontend qui ont besoin de créer des expériences mobiles engageantes avec les 12 principes d''animation de Disney.","de":"Perfekt für Frontend-Agents, die ansprechende mobile Erfahrungen mit Disneys 12 Animationsprinzipien erstellen möchten.","pt":"Perfeito para Agentes Frontend que precisam criar experiências móveis atraentes com os 12 princípios de animação da Disney.","ru":"Идеально подходит для агентов Frontend, которым необходимо создавать увлекательные мобильные trải nghiệm с 12 принципами анимации Disney.","ar":"مثالي للوكلاء الأماميين الذين يحتاجون إلى إنشاء تجارب محمولة جذابة مع مبادئ الرسوم المتحركة الـ 12 من ديزني."},"recommendation":{"en":"Empowers agents to design intuitive mobile interactions using rubber-banding, bounce on scroll limits, and gesture-driven transitions, while leveraging principles like Squash & Stretch, Anticipation, and Staging to enhance native app motion and haptics.","zh":"赋予代理设计直观的移动交互功能，使用橡胶带、滚动限制的反弹和手势驱动的过渡，同时利用压缩和拉伸、预期和舞台等原则来增强原生应用程序的运动和触觉反馈","ja":"エージェントが直感的なモバイルの相互作用を設計できるようにし、ゴム帯、スクロール制限のバウンド、ジェスチャ駆動の遷移を使用し、圧縮と伸張、予期、舞台などの原則を利用してネイティブアプリのモーションとハプティクスを強化","ko":"에이전트가 직관적인 모바일 상호 작용을 설계할 수 있도록 하며, 고무 밴드, 스크롤 제한의 바운스, 제스처 기반 전환을 사용하고,压缩과延장, 예상, 무대 등의 원리를 활용하여 네이티브 앱의 모션과 햅틱을 강화","es":"Permite a los agentes diseñar interacciones móviles intuitivas utilizando efectos de goma, rebote en los límites de desplazamiento y transiciones impulsadas por gestos, aprovechando principios como Squash & Stretch, Anticipation y Staging para mejorar el movimiento y la retroalimentación táctil de las aplicaciones nativas.","fr":"Permet aux agents de concevoir des interactions mobiles intuitives en utilisant des effets de caoutchouc, un rebond sur les limites de défilement et des transitions pilotées par des gestes, en exploitant des principes tels que Squash & Stretch, Anticipation et Staging pour améliorer le mouvement et les effets haptiques des applications natives.","de":"Ermöglicht es Agents, intuitive mobile Interaktionen zu entwerfen, indem sie Gummieffekte, Rückprall bei Scrollbegrenzungen und gestengesteuerte Übergänge verwenden, während sie Prinzipien wie Squash & Stretch, Anticipation und Staging nutzen, um die Bewegung und Haptik von nativen Apps zu verbessern.","pt":"Habilita os agentes a projetar interações móveis intuitivas usando rubber-banding, bounce on scroll limits e transições baseadas em gestos, aproveitando princípios como Squash & Stretch, Anticipation e Staging para melhorar o movimento e a haptics de aplicativos nativos.","ru":"Наделяет агентов возможностью проектировать интуитивные мобильные взаимодействия с использованием rubber-banding, bounce on scroll limits и жестовых переходов, используя принципы như Squash & Stretch, Anticipation и Staging для улучшения движения и тактильной обратной связи в родных приложениях.","ar":"تمكّن الوكلاء من تصميم تفاعلات محمولة直ميمية باستخدام rubber-banding وbounce on scroll limits وانتقالات مدفوعة بالإشارات، مستفيدة من مبادئ مثل Squash & Stretch وAnticipation وStaging لتحسين حركة والتأثيرات الحسية في التطبيقات الأصلية."},"useCases":{"en":["Implementing squash and stretch effects for mobile gestures","Creating anticipation animations for peek before reveal and long-press preview interactions","Designing staging presentations for sheet presentations and focus states"],"zh":["