INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('flavioGonz/pixelflow/mobile-touch', 'mobile-touch', 'flavioGonz', 'pixelflow', 'community', 'mobile-touch flavioGonz pixelflow community The mobile-touch skill applies Disney''s 12 animation principles to mobile gestures, haptics, and native app motion, benefiting developers who want to create engaging and intuitive mobile experiences. 移动触摸动画是通过应用Disney的12个动画原则来实现的，包括橡皮筋效果、预期动画和过渡效果等 モバイルタッチアニメーションは、Disneyの12原則を適用して実現される技術です 모바일 터치 애니메이션은 디즈니의 12가지 애니메이션 원칙을 적용하여 구현되는 기술입니다 Aplicación de los 12 principios de animación de Disney a gestos móviles y motion de aplicaciones nativas Application des 12 principes d''animation de Disney aux gestes mobiles et au mouvement d''applications natives Anwendung der 12 Animationprinzipien von Disney auf mobile Gesten und native App-Bewegungen A animação de toque móvel com Pixelflow aplica os 12 princípios de animação da Disney em gestos móveis e movimento de aplicativos nativos Анимация прикосновений для мобильных приложений с помощью Pixelflow применяет 12 принципов анимации Disney к мобильным жестам и движению родных приложений حركة اللمس للأجهزة النقالة مع Pixelflow تطبق مبادئ الانیمیشن الـ 12 من ديزني على الإشارات الناقلة وحركة التطبيقات الأصلية how to use mobile-touch what is mobile-touch mobile-touch alternative mobile-touch vs pixelflow mobile-touch install mobile-touch setup guide Disney''s 12 principles for mobile mobile gesture animation haptics and native app motion 移动触摸动画 Disney的12个动画原则 触摸手势 触觉 原生应用程序动画 高品质用户体验 AIエージェント 移动开发 Applies Squash & Stretch principle with rubber-banding and bounce on scroll limits Utilizes Anticipation principle with peek before reveal and long-press preview Employs Staging principle with sheet presentations and focus states Supports Straight Ahead and Pose to Pose principles with gesture-driven and preset transitions Implements Follow Through and Overlapping principles with momentum scrolling mobile-touch is a skill that brings Disney''s 12 animation principles to mobile interactions, enhancing gestures, haptics, and native app motion with techniques like rubber-banding and momentum scrolling.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('consuelohq/openengineer/github-dev', 'community', 'consuelohq', 'openengineer', 'consuelohq/openengineer', 'github-dev', 0, 0, 42, '2026-03-08T01:57:15.542Z', '2026-03-08T02:11:16.994Z', '5f3799534ac12c4a3713c627dc87679e7d84832e4290894768c659fe10f69609', '{"id":"consuelohq/openengineer/github-dev","name":"github-dev","description":{"en":"The github-dev skill enables autonomous AI agents to develop features entirely through GitHub''s API, creating branches, writing code, and auto-syncing task status. This benefits developers working on multiple projects simultaneously.","zh":"github-dev技能允许通过GitHub API进行远程开发，实现自动化构建和部署，提高开发效率","ja":"github-devスキルはGitHub APIを使用してリモート開発を実現し、自動化されたビルドとデプロイを可能にします","ko":"github-dev 스킬은 GitHub API를 사용하여 원격 개발을 구현하고 자동화된 빌드 및 배포를 가능하게 합니다","es":"github-dev es un agente de desarrollo autónomo que utiliza la API de GitHub para crear características sin necesidad de clonar localmente","fr":"github-dev est un agent de développement autonome qui utilise l''API GitHub pour créer des fonctionnalités sans besoin de clone local","de":"github-dev ist ein autonomer Entwicklungsagent, der die GitHub-API nutzt, um Funktionen ohne lokales Klonen zu erstellen","pt":"O github-dev permite o desenvolvimento de recursos através da API do GitHub, sem a necessidade de clonar o repositório localmente. Isso inclui a capacidade de criar branches, escrever código e criar solicitações de pull","ru":"github-dev позволяет разрабатывать функции через API GitHub, без необходимости локального клонирования репозитория. Это включает в себя возможность создавать ветки, писать код и создавать запросы на принятие","ar":"يسمح github-dev بتطوير الميزات من خلال واجهة برمجة التطبيقات GitHub، دون الحاجة إلى استنساخ المستودع محليًا. وهذا يشمل القدرة على إنشاء الفروع وكتابه الشفرة وإنشاء طلبات السحب"},"seo":{"title":{"en":"github-dev: Autonomous Development Automation for AI Agen...","zh":"GitHub开发自动化技能：github-dev Setup Guide","ja":"GitHub開発自動化ツール：github-dev ベストプラクティス","ko":"GitHub 개발 자동화 스킬: github-dev 설정 가이드","es":"Guía de configuración de github-dev para desarrollo autónomo","fr":"Guide de mise en place de github-dev pour l''automatisatio...","de":"Einrichtungsleitfaden für github-dev zur autonomen Entwic...","pt":"Guia de Configuração do github-dev: Automação de Desenvol...","ru":"Настройка github-dev: Автоматизация разработки с помощью ...","ar":"دليل إعداد github-dev: автоматизация التطوير باستخدام أدو..."},"description":{"en":"Unlock parallel development with github-dev. Discover how to automate GitHub workflows and integrate with Linear for seamless task management. Get started now!","zh":"通过github-dev技能实现GitHub远程开发自动化，使用GitHub API构建功能，无需本地克隆，提高开发效率","ja":"github-devスキルを使用してGitHubリモート開発の自動化を実現し、GitHub APIで機能を構築して開発効率を向上させます","ko":"github-dev 스킬을 사용하여 GitHub 원격 개발 자동화를 구현하고 GitHub API로 기능을 구축하여 개발 효율성을 향상합니다","es":"Descubre cómo github-dev permite el desarrollo autónomo a través de la API de GitHub, sin necesidad de clonar localmente","fr":"Découvrez comment github-dev permet le développement autonome via l''API GitHub, sans besoin de clone local","de":"Erfahren Sie, wie github-dev das autonome Entwickeln über die GitHub-API ermöglicht, ohne lokales Klonen","pt":"Aprenda a configurar o github-dev para automação de desenvolvimento e GTM com templates de agentes de IA autônomos","ru":"Узнайте, как настроить github-dev для автоматизации разработки и GTM с помощью шаблонов автономных ИИ Агентов","ar":"تعرف على كيفية إعداد github-dev لتحقيق التطوير والجاهزية للتسويق مع قوالب وكلاء الذكاء الاصطناعي المستقلة"},"definition":{"en":"github-dev is an autonomous AI agent template for automating development and go-to-market workflows through GitHub''s API, enabling parallel development without local clone requirements.","zh":"github-dev技能是一种通过GitHub API实现远程开发自动化的AI工具","ja":"github-devスキルはGitHub APIを使用してリモート開発の自動化を実現するAIエージェントの一種です","ko":"github-dev 스킬은 GitHub API를 사용하여 원격 개발 자동화를 구현하는 AI 에이전트의 일종입니다","es":"github-dev es un agente de desarrollo autónomo que utiliza la API de GitHub para crear características y automatizar tareas","fr":"github-dev est un agent de développement autonome qui utilise l''API GitHub pour créer des fonctionnalités et automatiser des tâches","de":"github-dev ist ein autonomer Entwicklungsagent, der die GitHub-API nutzt, um Funktionen zu erstellen und Aufgaben zu automatisieren","pt":"O github-dev é um conjunto de modelos de agentes de IA autônomos para automação de desenvolvimento e GTM","ru":"github-dev - это набор шаблонов автономных ИИ Агентов для автоматизации разработки и GTM","ar":"github-dev هو مجموعة من قوالب وكلاء الذكاء الاصطناعي المستقلة لتطوير التطبيقات والجاهزية للتسويق"},"features":{"en":["Build features entirely through GitHub''s API","Pull tasks from Linear for integrated task management","Create branches and write code autonomously","Batch commit and create PRs for streamlined workflows","Auto-sync task status for real-time project updates"],"zh":["使用GitHub API进行远程开发","自动化构建和部署","支持Linear任务管理","自动创建分支和PR","批量提交和自动同步任务状态"],"ja":["GitHub APIを使用したリモート開発","自動化されたビルドとデプロイ","Linearタスク管理のサポート","自動ブランチとPRの作成","バッチコミットと自動タスクステータス同期"],"ko":["GitHub API를 사용한 원격 개발","자동화된 빌드 및 배포","Linear 태스크 관리 지원","자동 분기 및 PR 생성","배치 커밋 및 자동 태스크 상태 동기화"],"es":["Desarrollo de características a través de la API de GitHub","Creación de ramas y confirmación de cambios en lote","Sincronización automática del estado de las tareas","Integración con Linear para la gestión de tareas","Posibilidad de trabajar en paralelo en diferentes características"],"fr":["Développement de fonctionnalités via l''API GitHub","Création de branches et de validations de modifications en lot","Synchronisation automatique de l''état des tâches","Intégration avec Linear pour la gestion des tâches","Possibilité de travailler en parallèle sur différentes fonctionnalités"],"de":["Entwicklung von Funktionen über die GitHub-API","Erstellung von Branches und Batch-Commits","Automatische Synchronisation des Aufgabenstatus","Integration mit Linear für die Aufgabenverwaltung","Möglichkeit, parallel an verschiedenen Funktionen zu arbeiten"],"pt":["Desenvolvimento de recursos através da API do GitHub","Criação de branches e solicitações de pull","Escrita de código e commit em batch","Sincronização automática do status da tarefa","Integração com Linear para pull de tarefas"],"ru":["Разработка функций через API GitHub","Создание веток и запросов на принятие","Написание кода и пакетный коммит","Автоматическая синхронизация статуса задачи","Интеграция с Linear для вытягивания задач"],"ar":["تطوير الميزات من خلال واجهة برمجة التطبيقات GitHub","إنشاء الفروع وطلبات السحب","كتابة الشفرة والالتزام الدفع","مزامنة автомática لحالة المهمة","التكامل مع Linear لجلب المهام"]},"keywords":{"en":["github-dev setup guide","how to use github-dev for automation","github-dev vs gitflow","github-dev alternative for AI agents","github-dev install for Linear integration","automating github workflows with github-dev"],"zh":["GitHub远程开发","GitHub API","自动化构建","自动化部署","Linear任务管理","AI工具","github-dev技能"],"ja":["GitHubリモート開発","GitHub API","自動化されたビルド","自動化されたデプロイ","Linearタスク管理","AIエージェント","github-devスキル"],"ko":["GitHub 원격 개발","GitHub API","자동화된 빌드","자동화된 배포","Linear 태스크 관리","AI 에이전트","github-dev 스킬"],"es":["github-dev","desarrollo autónomo","API de GitHub","automatización de tareas","Linear","desarrollo de características","agente de desarrollo","herramientas de desarrollo","desarrollo en paralelo"],"fr":["github-dev","développement autonome","API GitHub","automatisation de tâches","Linear","développement de fonctionnalités","agent de développement","outils de développement","développement en parallèle"],"de":["github-dev","autonomes Entwickeln","GitHub-API","Automatisierung von Aufgaben","Linear","Funktionenentwicklung","Entwicklungsagent","Entwicklertools","paralleles Entwickeln","künstliche Intelligenz Agenten"],"pt":["github-dev","automação de desenvolvimento","GTM","IA","agentes de IA","desenvolvimento de software","API do GitHub","Linear","desenvolvimento remoto"],"ru":["github-dev","автоматизация разработки","GTM","ИИ Агенты","разработка программного обеспечения","API GitHub","Linear","удаленная разработка","ИИ инструменты"],"ar":["github-dev","تطوير التطبيقات","الجاهزية للتسويق","أدوات الذكاء الاصطناعي","وكلاء الذكاء الاصطناعي","تطوير البرمجيات","واجهة برمجة التطبيقات GitHub","Linear","التطوير عن بعد","أدوات الذكاء الاصطناعي"]}},"owner":"consuelohq","repo":"openengineer","repoPath":"consuelohq/openengineer","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.542Z","topics":[],"category":"community","skillMd":{"name":"github-dev","description":"Remote development via GitHub API. Write code, create branches, commit files, and create PRs — all without a local clone. Pull tasks from Linear and implement them entirely through GitHub. Use when Ko wants features built remotely while working locally on other things.","bodyPreview":"# GitHub Remote Development\n\nBuild features entirely through GitHub''s API — no local clone needed. Pull tasks from Linear, create branches, write code, batch commit, create PRs, and auto-sync task status.\n\n**Why this exists:** Ko works on multiple things at once. When coming to this project, he''s already working on something locally. This skill lets the agent develop features in parallel without touching the local machine. You could have 10 sessions each working on different features simultaneou","body":"# GitHub Remote Development\n\nBuild features entirely through GitHub''s API — no local clone needed. Pull tasks from Linear, create branches, write code, batch commit, create PRs, and auto-sync task status.\n\n**Why this exists:** Ko works on multiple things at once. When coming to this project, he''s already working on something locally. This skill lets the agent develop features in parallel without touching the local machine. You could have 10 sessions each working on different features simultaneously.\n\n## Default Repo\n\n`kokayicobb/consuelo_on_call_coaching`\n\nOverride with `--repo owner/name` on any command.\n\n## Prerequisites\n\n- `gh` CLI installed at `/opt/homebrew/bin/gh` and authenticated\n- `LINEAR_API_KEY` set as env var (or available in `.agent/linear-api.sh`)\n- `requests` Python library (for Linear API calls)\n\n## Two Workflows\n\n### Workflow 1: From Linear Task (default)\n\nKo says something like \"pull task CON-456 and implement it\" or \"work on the auth feature from Linear.\"\n\n**Steps:**\n\n1. **Fetch the task spec** — run `fetch_task.py` to pull the task from Linear and save as markdown\n2. **Read the markdown spec** — understand requirements, acceptance criteria, comments\n3. **Start the dev session** — this creates a branch and updates Linear status\n4. **Write code** — use the GitHub API to read existing files, write new files, update files\n5. **Commit** — batch commit all changes atomically\n6. **Create PR** — auto-generates body with Linear linking, moves task to \"In Review\"\n\n**Python usage (in agent context):**\n\n```python\nimport sys\nsys.path.insert(0, \"/Users/kokayi/Dev/claude-agent-workflow/.opencode/skills/github-dev\")\nfrom github_dev import RemoteDev\n\ndev = RemoteDev()\n\n# Start from a Linear task\nsummary = dev.start_task(\"CON-456\")\n# This: fetches task → saves spec → creates branch → updates Linear\n\n# Read the saved spec to understand what to build\n# The spec file is at: .opencode/skills/github-dev/tasks/CON-456.md\n\n# Read existing code to understand the codebase\ncontent = dev.read_file(\"src/components/Auth.tsx\")\ntree = dev.get_repo_structure(\"src/components/\")\n\n# Write new code (staged for batch commit)\ndev.write_file(\"src/components/NewFeature.tsx\", new_component_code)\ndev.write_file(\"src/utils/helper.ts\", helper_code)\ndev.write_file(\"src/tests/NewFeature.test.tsx\", test_code)\n\n# Commit all staged files atomically\ndev.commit(\"feat: implement new feature with helper utils and tests\")\n\n# Maybe write more code and commit again\ndev.write_file(\"src/styles/NewFeature.css\", css_code)\ndev.commit(\"style: add styling for new feature\")\n\n# Create PR when done (auto-links to Linear, moves task to \"In Review\")\npr = dev.create_pr()\n```\n\n**CLI usage:**\n\n```bash\n# Fetch task spec (saves to tasks/CON-456.md)\npython3 .opencode/skills/github-dev/fetch_task.py CON-456\n\n# Start a dev session\npython3 .opencode/skills/github-dev/dev task CON-456\n\n# Create a branch without a Linear task\npython3 .opencode/skills/github-dev/dev create-branch \"add user auth flow\"\n\n# Read files, list directories\npython3 .opencode/skills/github-dev/dev read src/file.tsx\npython3 .opencode/skills/github-dev/dev ls src/components/\npython3 .opencode/skills/github-dev/dev tree src/\n\n# Write/stage files for commit\necho ''file content'' | python3 .opencode/skills/github-dev/dev write src/new.tsx\npython3 .opencode/skills/github-dev/dev write src/file.tsx --content-file /tmp/code.tsx\npython3 .opencode/skills/github-dev/dev write src/quick.tsx --content \"const x = 1;\" --immediate\n\n# See what''s staged\npython3 .opencode/skills/github-dev/dev staged\n\n# Commit all staged files (atomic batch via Git Trees API)\npython3 .opencode/skills/github-dev/dev commit \"feat: add new component\"\n\n# Create a PR for the current branch\npython3 .opencode/skills/github-dev/dev create-pr --label kiro --label enhancement\npython3 .opencode/skills/github-dev/dev create-pr --title \"feat: user auth\" --label kiro\n\n# Check session status\npython3 .opencode/skills/github-dev/dev status\n\n# Resume a previous session\npython3 .opencode/skills/github-dev/dev resume\n```\n\n### Workflow 2: From Existing PR\n\nKo says something like \"work on PR #789, fix the review comments\" or \"push changes to that PR.\"\n\n**Steps:**\n\n1. **Attach to the PR** — fetches PR info, sets the branch\n2. **Read the PR diff** — understand what''s already changed\n3. **Make changes** — read/write files on the PR''s branch\n4. **Commit** — push changes to the PR\n\n```python\ndev = RemoteDev()\n\n# Attach to existing PR\ndev.work_on_pr(789)\n\n# Read the current state\ncontent = dev.read_file(\"src/fix-me.tsx\")\n\n# Make changes\ndev.write_file(\"src/fix-me.tsx\", fixed_content)\ndev.commit(\"fix: address review comments\")\n```\n\n## Branch Naming Convention\n\n`remote/{repo_name}-{4char_hash}--{kebab-description}`\n\nExample: `remote/consuelo_on_call_coaching-a3f2--implement-user-auth-flow`\n\nThe `remote/` prefix distinguishes these from the `agent/` prefix used by the local agent workflow.\n\n## File Operations\n\n### Reading Files\n\n```python\n# Single file\ncontent = dev.read_file(\"src/components/Auth.tsx\")\n\n# Directory listing\nitems = dev.list_files(\"src/components/\")\n# Returns: [{\"name\": \"Auth.tsx\", \"type\": \"file\", \"size\": 1234}, ...]\n\n# Full repo tree (filtered)\nfiles = dev.get_repo_structure(\"src/\")\n# Returns: [\"src/app.tsx\", \"src/index.tsx\", ...]\n```\n\n### Writing Files (Staging)\n\nFiles are staged by default and committed as a batch:\n\n```python\n# Stage files\ndev.write_file(\"src/new.tsx\", code)\ndev.write_file(\"src/utils.ts\", utils)\n\n# Check what''s staged\ndev.staged_files()  # [\"src/new.tsx\", \"src/utils.ts\"]\n\n# Unstage a file\ndev.unstage(\"src/utils.ts\")\n\n# Commit all staged files\ndev.commit(\"feat: add new component\")\n```\n\nFor single-file immediate commits:\n\n```python\ndev.write_file(\"src/quick-fix.tsx\", code, stage=False)\n# Committed immediately\n```\n\n### Deleting Files\n\n```python\ndev.delete_file(\"src/old-file.tsx\")  # Staged\ndev.commit(\"chore: remove old file\")\n\ndev.delete_file(\"src/old-file.tsx\", stage=False)  # Immediate\n```\n\n## Batch Commits (Git Trees API)\n\nThe `commit()` method uses the Git Trees API for atomic multi-file commits. This means:\n\n- All files are committed in a single operation (no partial commits)\n- Much more efficient than one-file-at-a-time for real coding work\n- Creates proper git history (one commit per logical change)\n\n## Linear Integration\n\n### Auto-Status Sync\n\n| Event | Linear Status | Action |\n|-------|---------------|--------|\n| `start_task()` called | In Progress | Adds comment with branch name |\n| `create_pr()` called | In Review | Adds comment with PR link |\n\n### Task Spec Files\n\nFetched tasks are saved as markdown in `tasks/`:\n\n```\n.opencode/skills/github-dev/tasks/\n├── CON-456.md      # Full spec with description, criteria, comments\n├── CON-789.md\n└── .session-state.json  # Current session state for resumption\n```\n\nEach task file includes:\n- Metadata (priority, state, labels, dates)\n- Full description from Linear\n- Acceptance criteria\n- All comments (with authors and dates)\n- Subtasks (if any)\n- Attachments/links\n\n## Session Persistence\n\nThe skill saves session state to `.session-state.json` so you can resume:\n\n```python\ndev = RemoteDev()\nif dev.resume():\n    # Picks up where you left off (same branch, task, PR)\n    dev.write_file(\"src/more-code.tsx\", code)\n    dev.commit(\"feat: continue implementation\")\n```\n\n## Important Notes\n\n### When to Ask Ko\n\nIf Ko''s instructions are ambiguous about which workflow to use:\n\n- **\"Work on CON-456\"** → Workflow 1 (Linear task)\n- **\"Fix PR #789\"** → Workflow 2 (existing PR)\n- **\"Implement the auth feature\"** → Ask: \"should I pull from a specific Linear task or create a fresh branch?\"\n- **\"Push changes to the feature branch\"** → Ask: \"which PR or branch?\"\n\n### Rate Limits\n\nGitHub API has rate limits (5,000 requests/hour for authenticated users). Each file read/write is 1-2 API calls. Batch commits are more efficient (1 call per file for blobs + 3 fixed calls). For a typical feature (reading 10 files, writing 5), that''s ~25 API calls — well within limits.\n\n### File Size Limits\n\nThe Contents API has a 100MB limit per file. Normal source code files are well within this. If you need to handle binary files or very large files, use the Git Blobs API directly (already used in batch_commit).\n\n### Error Handling\n\n- If a branch creation fails (name conflict), the error is printed and `start_task()` raises\n- If a file write fails, the error is printed but other staged files can still be committed\n- If Linear API is unavailable, the GitHub operations still work (just no status sync)\n\n## Architecture\n\n```\ngithub-dev/\n├── SKILL.md            # This file — instructions for the agent\n├── github_api.py       # GitHub API client (gh CLI + gh api hybrid)\n├── linear_api.py       # Linear GraphQL client\n├── fetch_task.py       # CLI: pull task → markdown\n├── github_dev.py       # Main orchestrator (RemoteDev class)\n├── dev                 # Entry point script\n└── tasks/              # Saved task specs and session state\n```\n\n### Component Responsibilities\n\n- **github_api.py** — All GitHub operations. Uses `gh` CLI for PRs/reviews and `gh api` for file CRUD, branches, and batch commits. No Linear awareness.\n- **linear_api.py** — All Linear operations. Fetches tasks by ID, updates status, adds comments. No GitHub awareness.\n- **fetch_task.py** — Standalone CLI script. Pulls a task and writes a markdown file. Designed to be called before the agent starts reading (saves context window).\n- **github_dev.py** — The brain. Ties GitHub + Linear together. Manages staging, session state, and the two workflows.\n"},"lastSynced":"2026-03-08T02:11:16.994Z","agentAnalysis":{"suitability":{"en":"Ideal for Autonomous AI Agents needing seamless GitHub API integration for remote development and task automation.","zh":"适用于需要无缝集成GitHub API的自治AI代理，用于远程开发和任务自动化。","ja":"GitHub APIをシームレスに統合する必要がある自律型AIエージェントに適しています。リモート開発とタスクの自動化に使用されます。","ko":"원활한 GitHub API 통합이 필요한 자율형 AI 에이전트에게 적합합니다. 원격 개발 및 작업 자동화에 사용됩니다.","es":"Ideal para Agentes de IA Autónomos que necesitan una integración perfecta con la API de GitHub para el desarrollo remoto y la automatización de tareas.","fr":"Idéal pour les agents d''IA autonomes ayant besoin d''une intégration transparente de l''API GitHub pour le développement à distance et l''automatisation des tâches.","de":"Ideal für autonome KI-Agents, die eine nahtlose GitHub-API-Integration für die Remote-Entwicklung und die Aufgabenautomatisierung benötigen.","pt":"Ideal para Agentes Autônomos de IA que necessitam de integração de API do GitHub sem interrupções para desenvolvimento remoto e automação de tarefas.","ru":"Идеально для автономных агентов ИИ, требующих бесшовной интеграции с GitHub API для удаленной разработки и автоматизации задач.","ar":"مثالي لعمليات الويب الذكية التي تحتاج إلى دمج واجهة برمجة التطبيقات GitHub دون انقطاع لتنمية وautomazione عن بعد"},"recommendation":{"en":"Empowers agents to develop features entirely through GitHub''s API, creating branches, writing code, and auto-syncing task status using protocols like Git and APIs like Linear, enabling parallel development on multiple projects simultaneously without local clone requirements.","zh":"赋予代理通过GitHub的API开发功能，创建分支，编写代码，并使用Git和Linear等API的协议自动同步任务状态，实现多个项目的并行开发，无需本地克隆。","ja":"エージェントがGitHubのAPIを通じて機能を開発できるようにし、ブランチを作成し、コードを記述し、GitやLinearなどのAPIのプロトコルを使用してタスクのステータスを自動同期します。複数のプロジェクトを同時に開発できるようになり、ローカルクローンの必要性がなくなります。","ko":"에이전트가 GitHub의 API를 통해 기능을 개발할 수 있도록 하며, 브랜치를 생성하고 코드를 작성하며 Git 및 Linear와 같은 API의 프로토콜을 사용하여 작업 상태를 자동 동기화합니다. 여러 프로젝트를 동시에 개발할 수 있으며 로컬 복제의 필요성이 없습니다.","es":"Permite a los agentes desarrollar características enteramente a través de la API de GitHub, creando ramas, escribiendo código y auto-sincronizando el estado de las tareas utilizando protocolos como Git y APIs como Linear, lo que permite el desarrollo paralelo en varios proyectos simultáneamente sin requisitos de clonación local.","fr":"Permet aux agents de développer des fonctionnalités entièrement à travers l''API GitHub, en créant des branches, en écrivant du code et en auto-synchronisant le statut des tâches en utilisant des protocoles comme Git et des API comme Linear, ce qui permet le développement parallèle sur plusieurs projets simultanément sans nécessité de clonage local.","de":"Ermächtigt Agents, Funktionen vollständig über die GitHub-API zu entwickeln, indem sie Zweige erstellen, Code schreiben und den Aufgabenstatus mithilfe von Protokollen wie Git und APIs wie Linear auto-synchronisieren, was es ermöglicht, parallel an mehreren Projekten ohne lokale Klonanforderungen zu arbeiten.","pt":"Habilita os agentes a desenvolver recursos inteiramente por meio da API do GitHub, criando branches, escrevendo código e auto-sincronizando o status da tarefa usando protocolos como Git e APIs como Linear, permitindo o desenvolvimento paralelo em vários projetos simultaneamente sem requisitos de clonagem local.","ru":"Наделяет агентов возможностью разрабатывать функции полностью через API GitHub, создавая ветки, записывая код и автоматически синхронизируя статус задачи с помощью протоколов, таких как Git, и API, таких как Linear, что позволяет выполнять параллельную разработку в нескольких проектах одновременно без необходимости локального клонирования.","ar":"تمكين الوكيل من تطوير الميزات بالكامل من خلال واجهة برمجة التطبيقات GitHub ، وخلق الفروع ، وكتابة الشفرة ، وتحديث حالة المهمة تلقائيًا باستخدام بروتوكولات مثل Git وواجهات برمجة التطبيقات مثل Linear ، مما يسمح بالتنمية الموازية في عدة مشاريع في نفس الوقت دون الحاجة إلى متطلبات الاستنساخ المحلي."},"useCases":{"en":["Automating feature development through GitHub API","Creating branches and pulling tasks from Linear for streamlined project management","Batch committing and creating PRs for efficient code review and merge processes"],"zh":["通过GitHub API自动化功能开发","创建分支并从Linear拉取任务以实现流畅的项目管理","批量提交和创建PR以实现高效的代码审查和合并过程"],"ja":["GitHub APIを使用した機能開発の自動化","Linearからタスクをプルしてブランチを作成し、プロジェクト管理をストリームライン化する","バッチコミットとPRの作成により、コードレビューとマージプロセスを効率化する"],"ko":["GitHub API를 사용한 기능 개발 자동화","Linear에서 작업을 끌어오고 브랜치를 생성하여 프로젝트 관리를 원활하게 하는 것","バッチ 커밋 및 PR 생성을 통해 코드 검토 및 병합 프로세스를 효율화하는 것"],"es":["Automatizar el desarrollo de características a través de la API de GitHub","Crear ramas y extraer tareas de Linear para una gestión de proyectos optimizada","Confirmar por lotes y crear PR para procesos de revisión y fusión de código eficientes"],"fr":["Automatiser le développement de fonctionnalités via l''API GitHub","Créer des branches et récupérer des tâches à partir de Linear pour une gestion de projet rationalisée","Valider par lot et créer des PR pour des processus de révision et de fusion de code efficaces"],"de":["Automatisieren der Entwicklung von Funktionen über die GitHub-API","Erstellen von Zweigen und Abrufen von Aufgaben aus Linear für eine optimierte Projektverwaltung","Bestätigen in Batches und Erstellen von PR für effiziente Code-Überprüfungs- und -Zusammenführungsprozesse"],"pt":["Automatizar o desenvolvimento de recursos por meio da API do GitHub","Criar branches e puxar tarefas do Linear para gerenciamento de projetos simplificado","Compromisso em lotes e criação de PRs para processos de revisão e mesclagem de código eficientes"],"ru":["Автоматизировать разработку функций через API GitHub","Создавать ветки и извлекать задачи из Linear для упрощенного управления проектами","Пакетная фиксация и создание запросов на слияние для эффективных процессов проверки и слияния кода"],"ar":["تحسين تطور الميزات من خلال واجهة برمجة التطبيقات GitHub","إنشاء الفروع وسحب المهام من Linear لإدارة المشاريع المبسطة","التعهد بشكل مجموعات وإنشاء طلبات الدمج للعمليات الفعالة لمراجعة ودمج الشفرة"]},"limitations":{"en":["Requires GitHub API access and authentication","Dependent on Linear API for task integration","Needs auto-sync capabilities for task status updates"],"zh":["需要GitHub API访问和身份验证","依赖于Linear API进行任务集成","需要自动同步功能以更新任务状态"],"ja":["GitHub APIへのアクセスと認証が必要","タスク統合のためにLinear APIに依存する","タスクのステータスを更新するために自動同期機能が必要"],"ko":["GitHub API 액세스 및 인증이 필요합니다.","Linear API에 의존하여 작업 통합","작업 상태를 업데이트하는 자동 동기화 기능이 필요합니다."],"es":["Requiere acceso y autenticación a la API de GitHub","Depende de la API de Linear para la integración de tareas","Necesita capacidades de auto-sincronización para actualizaciones de estado de tareas"],"fr":["Nécessite un accès et une authentification à l''API GitHub","Dépend de l''API Linear pour l''intégration des tâches","Nécessite des capacités d''auto-synchronisation pour les mises à jour de statut des tâches"],"de":["Benötigt Zugriff und Authentifizierung auf die GitHub-API","Hängt von der Linear-API für die Aufgabenintegration ab","Benötigt Auto-Synchronisierungsfähigkeiten für Aufgabenstatus-Updates"],"pt":["Requer acesso à API do GitHub e autenticação","Dependente da API do Linear para integração de tarefas","Necessita de capacidades de auto-sincronização para atualizações de status de tarefas"],"ru":["Требует доступа к API GitHub и аутентификации","Зависит от API Linear для интеграции задач","Требует возможностей автосинхронизации для обновлений статуса задач"],"ar":["يتطلب الوصول إلى واجهة برمجة التطبيقات GitHub والتحقق","يعتمد على واجهة برمجة التطبيقات Linear لتكامل المهام","يتطلب القدرات التلقائية للتزامن لتحديث حالة المهمة"]},"version":4},"contentHash":"5f3799534ac12c4a3713c627dc87679e7d84832e4290894768c659fe10f69609","qualityScore":42}');
