INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('consuelohq/openengineer/github-dev', 'github-dev', 'consuelohq', 'openengineer', 'community', 'github-dev consuelohq openengineer community The github-dev skill enables autonomous AI agents to develop features entirely through GitHub''s API, creating branches, writing code, and auto-syncing task status. This benefits developers working on multiple projects simultaneously. github-dev技能允许通过GitHub API进行远程开发，实现自动化构建和部署，提高开发效率 github-devスキルはGitHub APIを使用してリモート開発を実現し、自動化されたビルドとデプロイを可能にします github-dev 스킬은 GitHub API를 사용하여 원격 개발을 구현하고 자동화된 빌드 및 배포를 가능하게 합니다 github-dev es un agente de desarrollo autónomo que utiliza la API de GitHub para crear características sin necesidad de clonar localmente github-dev est un agent de développement autonome qui utilise l''API GitHub pour créer des fonctionnalités sans besoin de clone local github-dev ist ein autonomer Entwicklungsagent, der die GitHub-API nutzt, um Funktionen ohne lokales Klonen zu erstellen O github-dev permite o desenvolvimento de recursos através da API do GitHub, sem a necessidade de clonar o repositório localmente. Isso inclui a capacidade de criar branches, escrever código e criar solicitações de pull github-dev позволяет разрабатывать функции через API GitHub, без необходимости локального клонирования репозитория. Это включает в себя возможность создавать ветки, писать код и создавать запросы на принятие يسمح github-dev بتطوير الميزات من خلال واجهة برمجة التطبيقات GitHub، دون الحاجة إلى استنساخ المستودع محليًا. وهذا يشمل القدرة على إنشاء الفروع وكتابه الشفرة وإنشاء طلبات السحب github-dev setup guide how to use github-dev for automation github-dev vs gitflow github-dev alternative for AI agents github-dev install for Linear integration automating github workflows with github-dev GitHub远程开发 GitHub API 自动化构建 自动化部署 Linear任务管理 AI工具 github-dev技能 Build features entirely through GitHub''s API Pull tasks from Linear for integrated task management Create branches and write code autonomously Batch commit and create PRs for streamlined workflows Auto-sync task status for real-time project updates github-dev is an autonomous AI agent template for automating development and go-to-market workflows through GitHub''s API, enabling parallel development without local clone requirements.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mgd34msu/goodvibes-gemini/netlify', 'community', 'mgd34msu', 'goodvibes-gemini', 'mgd34msu/goodvibes-gemini', 'netlify', 0, 0, 42, '2026-03-08T01:57:15.549Z', '2026-03-08T02:11:25.280Z', '12801267febb6803d269096af6d9e493c1754abf6b439fb24c6302606d718708', '{"id":"mgd34msu/goodvibes-gemini/netlify","name":"netlify","description":{"en":"The Netlify skill enables developers to deploy and host websites using the Netlify CLI. It supports features like Git repository connection and drag-and-drop deployment.","zh":"Netlify是一种现代的网页开发平台，提供了便捷的部署和托管功能","ja":"Netlifyは、ウェブ開発者向けのモダンなプラットフォームで、デプロイとホスティングを簡単に行える","ko":"Netlify는 웹 개발자를 위한 최신 플랫폼으로, 배포와 호스팅을 간단하게 할 수 있습니다","es":"Netlify es una plataforma de desarrollo web que permite a los desarrolladores deployar y alojar sitios web de manera sencilla","fr":"Netlify est une plateforme de développement web qui permet aux développeurs de déployer et d''héberger des sites web de manière simple","de":"Netlify ist eine Webentwicklungsplattform, die es Entwicklern ermöglicht, Websites einfach zu deployen und zu hosten","pt":"O Netlify é uma plataforma de desenvolvimento web moderna para deploy e hospedagem de sites. Aprenda a configurá-lo com nossa guia.","ru":"Netlify — современная платформа веб-разработки для развертывания и хостинга сайтов. Узнайте, как ее настроить с нашей помощью.","ar":"Netlify هو منصة تطوير ويب حديثة لتنفيذ وتخزين المواقع. تعلم كيفية إعدادها مع دليلنا."},"seo":{"title":{"en":"Netlify: Deployment Setup Guide for AI Agents | AI Agent ...","zh":"Netlify部署指南 - 快速开始您的项目","ja":"Netlifyセットアップガイド - AIエージェントを使用した効率的なウェブ開発","ko":"Netlify 설정 가이드 - 개발자들을 위한 빠른 시작","es":"Guía de configuración de Netlify para desarrolladores","fr":"Guide de configuration Netlify pour les développeurs","de":"Netlify-Konfigurationsleitfaden für Entwickler","pt":"Guia de Configuração do Netlify para Desenvolvedores","ru":"Настройка Netlify для разработчиков: лучшие практики","ar":"إعداد Netlify للبرمجة: دليل تشغيل سريع"},"description":{"en":"Discover how to deploy and host websites with Netlify. Learn to install the Netlify CLI, login, and deploy your site with ease. Get started now!","zh":"了解Netlify的强大功能和CLI命令，快速部署和托管您的网站","ja":"Netlifyの機能とCLIコマンドをマスターして、ウェブ開発を効率化する","ko":"Netlify의 기능과 CLI 명령어를 익혀서 웹 개발을 간소화하세요","es":"Aprende a configurar y deployar sitios web con Netlify, la plataforma de desarrollo web moderna","fr":"Découvrez comment configurer et déployer des sites web avec Netlify, la plateforme de développement web moderne","de":"Erfahren Sie, wie Sie Netlify, die moderne Webentwicklungsplattform, konfigurieren und bereitstellen","pt":"Aprenda a configurar o Netlify para deploy e hospedagem de sites com nossa guia passo a passo para desenvolvedores","ru":"Узнайте, как настроить Netlify для развертывания и хостинга сайтов с нашей пошаговой инструкцией для разработчиков","ar":"تعلم كيفية إعداد Netlify لتنفيذ وتخزين المواقع مع دليلنا خطوة بخطوة للمطورين"},"definition":{"en":"Netlify is a modern web development platform for deploying and hosting websites, providing a seamless experience for developers.","zh":"Netlify是一种基于云的平台，用于构建、部署和管理网站","ja":"Netlifyは、クラウドベースのプラットフォームで、ウェブサイトの構築、デプロイ、管理を行う","ko":"Netlify는 클라우드 기반 플랫폼으로, 웹사이트의 구축, 배포, 관리를 수행합니다","es":"Netlify es una plataforma de desarrollo web que ofrece herramientas para deployar y alojar sitios web","fr":"Netlify est une plateforme de développement web qui propose des outils pour déployer et héberger des sites web","de":"Netlify ist eine Webentwicklungsplattform, die Tools für das Deployen und Hosten von Websites bietet","pt":"O Netlify é uma plataforma de desenvolvimento web que permite deploy e hospedagem de sites de forma eficiente","ru":"Netlify — платформа веб-разработки, позволяющая эффективно развертывать и хостить сайты","ar":"Netlify هو منصة تطوير ويب تسمح بتشغيل وتخزين المواقع بفعالية"},"features":{"en":["Installs Netlify CLI using npm install -g netlify-cli","Supports login functionality with netlify login","Deploys websites using netlify deploy and netlify deploy --prod","Connects Git repositories for automated deployment","Allows drag-and-drop deployment from the Netlify app"],"zh":["支持CLI命令行部署","提供快速的登录和部署功能","支持Git仓库连接","提供Drag and Drop功能","支持生产环境部署","提供构建设置配置"],"ja":["CLIコマンドラインによるデプロイをサポート","迅速なログインとデプロイ機能を提供","Gitリポジトリ接続をサポート","Drag and Drop機能を提供","生産環境へのデプロイをサポート","ビルド設定のコンフィグを提供"],"ko":["CLI 명령어를 통한 배포 지원","빠른 로그인과 배포 기능 제공","Git 저장소 연결 지원","Drag and Drop 기능 제공","생산 환경 배포 지원","빌드 설정 구성 제공"],"es":["Instalación de CLI con npm","Conexión de repositorios Git","Configuración de entornos de construcción","Despliegue de sitios web con un solo comando","Soporte para despliegue en producción"],"fr":["Installation de la CLI avec npm","Connexion de répertoires Git","Configuration des environnements de construction","Déploiement de sites web avec une seule commande","Prise en charge du déploiement en production"],"de":["Installation der CLI mit npm","Verbindung von Git-Repositorys","Konfiguration von Build-Umgebungen","Bereitstellung von Websites mit einem einzigen Befehl","Unterstützung für die Bereitstellung in Produktion"],"pt":["Instalação do CLI do Netlify com npm","Conexão de repositórios Git para deploy automático","Configuração de build settings para projetos","Deploy para produção com um comando simples","Uso do Netlify para hospedagem de sites estáticos"],"ru":["Установка CLI Netlify с помощью npm","Подключение репозиториев Git для автоматического развертывания","Настройка параметров сборки для проектов","Развертывание в производство с помощью одной команды","Использование Netlify для хостинга статических сайтов"],"ar":["تثبيت CLI Netlify باستخدام npm","ربط مستودعات Git لتنفيذ تلقائي","تكوين إعدادات البناء لمشاريع","تنفيذ إلى الإنتاج باستخدام أمر بسيط","استخدام Netlify لتخزين المواقع الثابتة"]},"keywords":{"en":["how to use netlify","netlify setup guide","netlify alternative","netlify vs vercel","netlify install","netlify deployment tutorial","what is netlify","netlify cli commands","netlify git repository connection"],"zh":["Netlify","网页开发平台","部署","托管","CLI命令","Git仓库","Drag and Drop","生产环境","构建设置"],"ja":["Netlify","ウェブ開発プラットフォーム","デプロイ","ホスティング","CLIコマンド","Gitリポジトリ","Drag and Drop","生産環境","ビルド設定"],"ko":["Netlify","웹 개발 플랫폼","배포","호스팅","CLI 명령어","Git 저장소","Drag and Drop","생산 환경","빌드 설정"],"es":["Netlify","desarrollo web","deployar sitios web","alojar sitios web","CLI","Git","construcción de sitios web","despliegue en producción"],"fr":["Netlify","développement web","déployer des sites web","héberger des sites web","CLI","Git","construction de sites web","déploiement en production"],"de":["Netlify","Webentwicklung","Deployen von Websites","Hosten von Websites","CLI","Git","Website-Build","Bereitstellung in Produktion"],"pt":["Netlify para desenvolvedores","Guia de configuração do Netlify","Deploy de sites com Netlify","Hospedagem de sites estáticos","CLI do Netlify","Conexão de repositórios Git","Configuração de build settings","Desenvolvimento web com Netlify"],"ru":["Netlify для разработчиков","Настройка Netlify","Развертывание сайтов с Netlify","Хостинг статических сайтов","CLI Netlify","Подключение репозиториев Git","Настройка параметров сборки","Веб-разработка с Netlify"],"ar":["Netlify للمطورين","إعداد Netlify","تنفيذ مواقع مع Netlify","تخزين مواقع ثابتة","CLI Netlify","ربط مستودعات Git","تكوين إعدادات البناء","تطوير ويب مع Netlify"]}},"owner":"mgd34msu","repo":"goodvibes-gemini","repoPath":"mgd34msu/goodvibes-gemini","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.549Z","topics":[],"category":"community","skillMd":{"name":"netlify","description":"Deploys applications to Netlify including functions, forms, redirects, and edge functions. Use when deploying static sites, JAMstack applications, or serverless functions.","bodyPreview":"# Netlify\n\nThe modern web development platform for deploying and hosting websites.\n\n## Quick Start\n\n**Install CLI:**\n```bash\nnpm install -g netlify-cli\n```\n\n**Login:**\n```bash\nnetlify login\n```\n\n**Deploy:**\n```bash\nnetlify deploy\n```\n\n**Deploy to production:**\n```bash\nnetlify deploy --prod\n```\n\n## Project Setup\n\n### Connect Git Repository\n\n1. Go to app.netlify.com\n2. Add new site > Import from Git\n3. Select repository\n4. Configure build settings\n5. Deploy\n\n### Drag and Drop\n\nVisit `https://app.n","body":"# Netlify\n\nThe modern web development platform for deploying and hosting websites.\n\n## Quick Start\n\n**Install CLI:**\n```bash\nnpm install -g netlify-cli\n```\n\n**Login:**\n```bash\nnetlify login\n```\n\n**Deploy:**\n```bash\nnetlify deploy\n```\n\n**Deploy to production:**\n```bash\nnetlify deploy --prod\n```\n\n## Project Setup\n\n### Connect Git Repository\n\n1. Go to app.netlify.com\n2. Add new site > Import from Git\n3. Select repository\n4. Configure build settings\n5. Deploy\n\n### Drag and Drop\n\nVisit `https://app.netlify.com/drop` and drag your build folder.\n\n### netlify.toml Configuration\n\n```toml\n[build]\n  command = \"npm run build\"\n  publish = \"dist\"\n  functions = \"netlify/functions\"\n\n[build.environment]\n  NODE_VERSION = \"18\"\n\n# Production context\n[context.production]\n  command = \"npm run build:prod\"\n\n# Preview context (branch deploys)\n[context.deploy-preview]\n  command = \"npm run build:preview\"\n\n# Branch-specific\n[context.staging]\n  command = \"npm run build:staging\"\n\n# Dev settings\n[dev]\n  command = \"npm run dev\"\n  port = 3000\n  targetPort = 5173\n\n# Headers\n[[headers]]\n  for = \"/*\"\n  [headers.values]\n    X-Frame-Options = \"DENY\"\n    X-XSS-Protection = \"1; mode=block\"\n\n# Redirects\n[[redirects]]\n  from = \"/api/*\"\n  to = \"/.netlify/functions/:splat\"\n  status = 200\n\n[[redirects]]\n  from = \"/*\"\n  to = \"/index.html\"\n  status = 200\n```\n\n## Environment Variables\n\n### Setting Variables\n\n**Via Dashboard:**\nSite settings > Environment variables > Add variable\n\n**Via CLI:**\n```bash\nnetlify env:set MY_VAR \"value\"\nnetlify env:list\nnetlify env:get MY_VAR\nnetlify env:unset MY_VAR\n```\n\n### Context-Specific Variables\n\n```toml\n# netlify.toml\n[context.production.environment]\n  API_URL = \"https://api.example.com\"\n\n[context.deploy-preview.environment]\n  API_URL = \"https://staging-api.example.com\"\n\n[context.branch-deploy.environment]\n  API_URL = \"https://dev-api.example.com\"\n```\n\n### Using Variables\n\n```javascript\n// In build process\nconst apiUrl = process.env.API_URL;\n\n// In functions\nexport async function handler(event, context) {\n  const secret = process.env.API_SECRET;\n}\n```\n\n## Serverless Functions\n\n### Basic Function\n\n```javascript\n// netlify/functions/hello.js\nexport async function handler(event, context) {\n  return {\n    statusCode: 200,\n    body: JSON.stringify({ message: ''Hello, World!'' }),\n  };\n}\n```\n\n### TypeScript Function\n\n```typescript\n// netlify/functions/users.ts\nimport type { Handler, HandlerEvent, HandlerContext } from ''@netlify/functions'';\n\ninterface User {\n  id: string;\n  name: string;\n}\n\nconst handler: Handler = async (event: HandlerEvent, context: HandlerContext) => {\n  const { httpMethod, body, queryStringParameters } = event;\n\n  if (httpMethod === ''GET'') {\n    const users: User[] = await getUsers();\n    return {\n      statusCode: 200,\n      headers: { ''Content-Type'': ''application/json'' },\n      body: JSON.stringify(users),\n    };\n  }\n\n  if (httpMethod === ''POST'') {\n    const data = JSON.parse(body || ''{}'');\n    const user = await createUser(data);\n    return {\n      statusCode: 201,\n      body: JSON.stringify(user),\n    };\n  }\n\n  return {\n    statusCode: 405,\n    body: ''Method Not Allowed'',\n  };\n};\n\nexport { handler };\n```\n\n### Scheduled Functions\n\n```typescript\n// netlify/functions/scheduled.ts\nimport { schedule } from ''@netlify/functions'';\n\nconst handler = async () => {\n  console.log(''Running scheduled task'');\n  await runTask();\n  return { statusCode: 200 };\n};\n\n// Run every day at midnight\nexport const handler = schedule(''0 0 * * *'', handler);\n```\n\n### Background Functions\n\n```javascript\n// netlify/functions/background-task-background.js\n// Suffix with -background for async processing\nexport async function handler(event, context) {\n  // Long-running task (up to 15 minutes)\n  await processLargeDataset();\n\n  return {\n    statusCode: 200,\n  };\n}\n```\n\n## Edge Functions\n\n### Basic Edge Function\n\n```typescript\n// netlify/edge-functions/geo.ts\nimport type { Context } from ''@netlify/edge-functions'';\n\nexport default async (request: Request, context: Context) => {\n  const country = context.geo.country?.code ?? ''Unknown'';\n  const city = context.geo.city ?? ''Unknown'';\n\n  return new Response(\n    JSON.stringify({\n      message: `Hello from ${city}, ${country}!`,\n    }),\n    {\n      headers: { ''Content-Type'': ''application/json'' },\n    }\n  );\n};\n\nexport const config = { path: ''/api/geo'' };\n```\n\n### Edge Function with Middleware Pattern\n\n```typescript\n// netlify/edge-functions/auth.ts\nimport type { Context } from ''@netlify/edge-functions'';\n\nexport default async (request: Request, context: Context) => {\n  const token = request.headers.get(''Authorization'');\n\n  if (!token) {\n    return new Response(''Unauthorized'', { status: 401 });\n  }\n\n  // Validate token\n  const user = await validateToken(token);\n\n  if (!user) {\n    return new Response(''Invalid token'', { status: 403 });\n  }\n\n  // Continue to origin\n  return context.next();\n};\n\nexport const config = { path: ''/api/*'' };\n```\n\n### Edge Function Declaration\n\n```toml\n# netlify.toml\n[[edge_functions]]\n  path = \"/api/geo\"\n  function = \"geo\"\n\n[[edge_functions]]\n  path = \"/api/*\"\n  function = \"auth\"\n```\n\n## Redirects & Rewrites\n\n### _redirects File\n\n```\n# Simple redirect\n/old-page /new-page 301\n\n# Wildcard redirect\n/blog/* /posts/:splat 301\n\n# Rewrite (proxy)\n/api/* /.netlify/functions/:splat 200\n\n# SPA fallback\n/* /index.html 200\n\n# Conditional redirect\n/country/* /us/:splat 200 Country=us\n/country/* /uk/:splat 200 Country=gb\n```\n\n### netlify.toml Redirects\n\n```toml\n[[redirects]]\n  from = \"/old\"\n  to = \"/new\"\n  status = 301\n\n[[redirects]]\n  from = \"/api/*\"\n  to = \"https://api.example.com/:splat\"\n  status = 200\n  force = true\n\n[[redirects]]\n  from = \"/*\"\n  to = \"/index.html\"\n  status = 200\n  conditions = { Role = [\"admin\"] }\n```\n\n## Forms\n\n### HTML Form\n\n```html\n<form name=\"contact\" method=\"POST\" data-netlify=\"true\">\n  <input type=\"hidden\" name=\"form-name\" value=\"contact\" />\n  <input type=\"text\" name=\"name\" required />\n  <input type=\"email\" name=\"email\" required />\n  <textarea name=\"message\" required></textarea>\n  <button type=\"submit\">Send</button>\n</form>\n```\n\n### React Form\n\n```tsx\nfunction ContactForm() {\n  const [status, setStatus] = useState('''');\n\n  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {\n    e.preventDefault();\n    const form = e.currentTarget;\n    const formData = new FormData(form);\n\n    try {\n      await fetch(''/'', {\n        method: ''POST'',\n        headers: { ''Content-Type'': ''application/x-www-form-urlencoded'' },\n        body: new URLSearchParams(formData as any).toString(),\n      });\n      setStatus(''success'');\n    } catch (error) {\n      setStatus(''error'');\n    }\n  };\n\n  return (\n    <form\n      name=\"contact\"\n      method=\"POST\"\n      data-netlify=\"true\"\n      onSubmit={handleSubmit}\n    >\n      <input type=\"hidden\" name=\"form-name\" value=\"contact\" />\n      <input type=\"text\" name=\"name\" required />\n      <input type=\"email\" name=\"email\" required />\n      <button type=\"submit\">Send</button>\n    </form>\n  );\n}\n```\n\n### Form Notifications\n\nConfigure in Dashboard: Forms > [Form Name] > Settings > Notifications\n\n## Identity (Auth)\n\n### Setup\n\n```html\n<!-- Add to HTML -->\n<script src=\"https://identity.netlify.com/v1/netlify-identity-widget.js\"></script>\n```\n\n### JavaScript API\n\n```javascript\nimport netlifyIdentity from ''netlify-identity-widget'';\n\nnetlifyIdentity.init();\n\n// Open modal\nnetlifyIdentity.open();\n\n// Login\nnetlifyIdentity.on(''login'', user => {\n  console.log(''Logged in:'', user);\n});\n\n// Logout\nnetlifyIdentity.on(''logout'', () => {\n  console.log(''Logged out'');\n});\n\n// Get current user\nconst user = netlifyIdentity.currentUser();\n```\n\n## Large Media (Git LFS)\n\n```bash\n# Install\nnetlify lm:install\n\n# Setup\nnetlify lm:setup\n\n# Track files\ngit lfs track \"*.jpg\" \"*.png\" \"*.gif\"\n```\n\n## Blobs (Storage)\n\n```typescript\n// netlify/functions/upload.ts\nimport { getStore } from ''@netlify/blobs'';\n\nexport async function handler(event) {\n  const store = getStore(''uploads'');\n\n  // Store blob\n  await store.set(''file-key'', event.body, {\n    metadata: { contentType: ''image/png'' },\n  });\n\n  // Get blob\n  const blob = await store.get(''file-key'');\n\n  // Delete blob\n  await store.delete(''file-key'');\n\n  return { statusCode: 200 };\n}\n```\n\n## Local Development\n\n```bash\n# Start dev server\nnetlify dev\n\n# Start with specific port\nnetlify dev --port 3000\n\n# Link to site\nnetlify link\n\n# Pull environment variables\nnetlify env:pull\n```\n\n## Best Practices\n\n1. **Use netlify.toml** - Version control your config\n2. **Set up branch deploys** - Preview before production\n3. **Use context-specific vars** - Different values per environment\n4. **Enable form spam filtering** - Protect forms\n5. **Use edge functions** - For low-latency operations\n\n## Common Mistakes\n\n| Mistake | Fix |\n|---------|-----|\n| Missing form-name input | Add hidden input with form name |\n| Wrong publish directory | Check framework output folder |\n| Functions not found | Use netlify/functions directory |\n| Redirects not working | Check order (first match wins) |\n| Build failures | Check build logs, Node version |\n\n## Reference Files\n\n- [references/functions.md](references/functions.md) - Function patterns\n- [references/forms.md](references/forms.md) - Form handling\n- [references/edge.md](references/edge.md) - Edge functions\n"},"lastSynced":"2026-03-08T02:11:25.280Z","agentAnalysis":{"suitability":{"en":"Perfect for Full Stack Agents needing streamlined web deployment and hosting capabilities via Netlify CLI","zh":"非常适合需要通过Netlify CLI简化Web部署和托管能力的全栈代理","ja":"Netlify CLIを使用してWebデプロイとホスティングをストリームライン化する必要があるフルスタックエージェントに最適","ko":"Netlify CLI를 통해 웹 배포 및 호스팅 기능을 간소화해야 하는 풀스택 에이전트에 적합","es":"Perfecto para Agentes de Full Stack que necesitan una implementación y capacidades de alojamiento web simplificadas a través de Netlify CLI","fr":"Parfait pour les agents Full Stack ayant besoin d''un déploiement et d''hébergement web simplifiés via Netlify CLI","de":"Perfekt für Full-Stack-Agents, die eine gestreamte Webbereitstellung und -hosting-Fähigkeiten über Netlify CLI benötigen","pt":"Perfeito para Agentes Full Stack que necessitam de implantação e capacidades de hospedagem web otimizadas via Netlify CLI","ru":"Идеально подходит для агентов Full Stack, которым необходимы оптимизированные возможности развертывания и размещения веб-сайтов через Netlify CLI","ar":"مثالي لعميل.Full Stack الذي يحتاج إلى نشر ويب مبسط وقدرات استضافة عبر Netlify CLI"},"recommendation":{"en":"Empowers agents to deploy and host websites using Git repository connections and drag-and-drop deployments, leveraging features like Netlify CLI and support for production environments via --prod flag","zh":"赋予代理部署和托管网站的能力，使用Git仓库连接和拖拽式部署，利用Netlify CLI和--prod标志支持生产环境等功能","ja":"Gitリポジトリ接続やドラッグアンドドロップデプロイを使用してWebサイトをデプロイおよびホストするエージェントを可能にし、Netlify CLIや--prodフラグによる生产環境サポートなどの機能を利用","ko":"Git 저장소 연결 및 끌고 놓기 배포를 사용하여 웹 사이트를 배포 및 호스팅할 수 있는 에이전트를 가능하게 하며, Netlify CLI 및 --prod 플래그를 통한 프로덕션 환경 지원 등의 기능을 활용","es":"Habilita a los agentes a implementar y alojar sitios web utilizando conexiones de repositorios Git y despliegues de arrastrar y soltar, aprovechando características como Netlify CLI y soporte para entornos de producción a través de la bandera --prod","fr":"Permet aux agents de déployer et d''héberger des sites web en utilisant des connexions de référentiels Git et des déploiements par glisser-déposer, en exploitant des fonctionnalités comme Netlify CLI et un support pour les environnements de production via le flag --prod","de":"Ermöglicht es Agents, Websites bereitzustellen und zu hosten, indem sie Git-Repository-Verbindungen und Drag-and-Drop-Bereitstellungen verwenden, wobei Funktionen wie Netlify CLI und Unterstützung für Produktionsumgebungen über die --prod-Flag genutzt werden","pt":"Habilita os agentes a implantar e hospedar sites usando conexões de repositório Git e implantações de arrastar-e-soltar, aproveitando recursos como Netlify CLI e suporte a ambientes de produção via flag --prod","ru":"Наделяет агентов возможностью развертывать и размещать веб-сайты, используя подключения к репозиториям Git и перетаскивания для развертывания, используя функции, такие как Netlify CLI и поддержку производственных сред с помощью флага --prod","ar":"يمكّن العميل من نشر المواقع الإلكترونية واستضافتها باستخدام اتصالات مستودع جيت وتنزيلات السحب والإفلات ، واستخدام ميزات مثل Netlify CLI ودعم بيئات الإنتاج عبر علم --prod"},"useCases":{"en":["Deploying web applications to production environments","Connecting Git repositories for automated deployment","Configuring build settings for optimized website performance"],"zh":["将Web应用程序部署到生产环境","连接Git仓库以实现自动化部署","配置构建设置以优化网站性能"],"ja":["Webアプリケーションを生产環境にデプロイする","Gitリポジトリを接続して自動デプロイを実現する","ビルド設定を構成してWebサイトのパフォーマンスを最適化する"],"ko":["웹 애플리케이션을 프로덕션 환경에 배포하는 것","Git 저장소를 연결하여 자동 배포를 구현하는 것","빌드 설정을 구성하여 웹 사이트 성능을 최적화하는 것"],"es":["Implementar aplicaciones web en entornos de producción","Conectar repositorios Git para un despliegue automatizado","Configurar la configuración de compilación para un rendimiento de sitio web optimizado"],"fr":["Déployer des applications web dans des environnements de production","Se connecter à des référentiels Git pour un déploiement automatisé","Configurer les paramètres de build pour des performances de site web optimisées"],"de":["Bereitstellen von Webanwendungen in Produktionsumgebungen","Verbindung von Git-Repositorys für automatisierte Bereitstellung","Konfigurieren der Build-Einstellungen für optimierte Website-Leistung"],"pt":["Implantação de aplicações web em ambientes de produção","Conexão de repositórios Git para implantação automatizada","Configuração de configurações de compilação para desempenho de site otimizado"],"ru":["Развертывание веб-приложений в производственных средах","Подключение репозиториев Git для автоматического развертывания","Настройка параметров сборки для оптимизированного производительности веб-сайта"],"ar":["نشر التطبيقات الويب في بيئات الإنتاج","اتصال مستودعات جيت لنشر آلي","تكوين إعدادات البناء لأداء موقع محسّن"]},"limitations":{"en":["Requires Netlify CLI installation","Needs active Git repository connection","Dependent on Netlify platform features and limitations"],"zh":["需要安装Netlify CLI","需要活跃的Git仓库连接","依赖于Netlify平台的功能和限制"],"ja":["Netlify CLIのインストールが必要","アクティブなGitリポジトリ接続が必要","Netlifyプラットフォームの機能と制限に依存"],"ko":["Netlify CLI 설치가 필요","활성 Git 저장소 연결이 필요","Netlify 플랫폼의 기능 및 제한에 의존"],"es":["Requiere la instalación de Netlify CLI","Necesita una conexión de repositorio Git activa","Dependiente de las características y limitaciones de la plataforma Netlify"],"fr":["Nécessite l''installation de Netlify CLI","Besoin d''une connexion de référentiel Git active","Dépend des fonctionnalités et des limitations de la plateforme Netlify"],"de":["Erfordert die Installation von Netlify CLI","Benötigt eine aktive Git-Repository-Verbindung","Abhängig von den Funktionen und Einschränkungen der Netlify-Plattform"],"pt":["Exige instalação do Netlify CLI","Necessita conexão ativa de repositório Git","Dependente de recursos e limitações da plataforma Netlify"],"ru":["Требует установки Netlify CLI","Требует активного подключения к репозиторию Git","Зависит от функций и ограничений платформы Netlify"],"ar":["يتطلب تثبيت Netlify CLI","يحتاج اتصال نشط بمستودع جيت","يعتمد على ميزات وقيود منصة Netlify"]},"version":4},"contentHash":"12801267febb6803d269096af6d9e493c1754abf6b439fb24c6302606d718708","qualityScore":42}');
