INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mgd34msu/goodvibes-gemini/netlify', 'netlify', 'mgd34msu', 'goodvibes-gemini', 'community', 'netlify mgd34msu goodvibes-gemini community The Netlify skill enables developers to deploy and host websites using the Netlify CLI. It supports features like Git repository connection and drag-and-drop deployment. Netlify是一种现代的网页开发平台，提供了便捷的部署和托管功能 Netlifyは、ウェブ開発者向けのモダンなプラットフォームで、デプロイとホスティングを簡単に行える Netlify는 웹 개발자를 위한 최신 플랫폼으로, 배포와 호스팅을 간단하게 할 수 있습니다 Netlify es una plataforma de desarrollo web que permite a los desarrolladores deployar y alojar sitios web de manera sencilla Netlify est une plateforme de développement web qui permet aux développeurs de déployer et d''héberger des sites web de manière simple Netlify ist eine Webentwicklungsplattform, die es Entwicklern ermöglicht, Websites einfach zu deployen und zu hosten O Netlify é uma plataforma de desenvolvimento web moderna para deploy e hospedagem de sites. Aprenda a configurá-lo com nossa guia. Netlify — современная платформа веб-разработки для развертывания и хостинга сайтов. Узнайте, как ее настроить с нашей помощью. Netlify هو منصة تطوير ويب حديثة لتنفيذ وتخزين المواقع. تعلم كيفية إعدادها مع دليلنا. how to use netlify netlify setup guide netlify alternative netlify vs vercel netlify install netlify deployment tutorial what is netlify netlify cli commands netlify git repository connection Netlify 网页开发平台 部署 托管 CLI命令 Git仓库 Drag and Drop 生产环境 构建设置 Installs Netlify CLI using npm install -g netlify-cli Supports login functionality with netlify login Deploys websites using netlify deploy and netlify deploy --prod Connects Git repositories for automated deployment Allows drag-and-drop deployment from the Netlify app Netlify is a modern web development platform for deploying and hosting websites, providing a seamless experience for developers.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('netalertx/NetAlertX/mcp-activation', 'community', 'netalertx', 'NetAlertX', 'netalertx/NetAlertX', 'mcp-activation', 0, 0, 42, '2026-03-08T01:57:15.562Z', '2026-03-08T02:11:36.418Z', '5b1e1812ef8e15fac079329b80fcad19bbd93e01bdaf05c4725128db12ae17f6', '{"id":"netalertx/NetAlertX/mcp-activation","name":"mcp-activation","description":{"en":"The mcp-activation skill configures the NetAlertX development environment to expose the Model Context Protocol (MCP) server to AI agents, enabling dynamic actions and continuous asset discovery.","zh":"MCP Activation技能配置NetAlertX开发环境，以实现AIエージェント的动态操作和数据库查询。通过MCP，实现设备列表、事件和网络扫描等功能","ja":"MCP Activationスキルは、NetAlertX開発環境を設定し、AIエージェントの動的アクションとデータベースの検索を可能にします。MCPを使用して、デバイスリスト、イベント、ネットワークスキャンなどの機能を実現します","ko":"MCP Activation 스킬은 NetAlertX 개발 환경을 설정하여 AI 에이전트의 동적 작동과 데이터베이스 쿼리를 가능하게 합니다. MCP를 사용하여 디바이스 목록, 이벤트, 네트워크 스캔 등의 기능을 구현합니다","es":"El skill de MCP Activation habilita la visibilidad de la red y la detección de activos en tiempo real para agentes de IA","fr":"Le skill MCP Activation permet la visibilité du réseau et la découverte d''actifs en temps réel pour les outils d''IA","de":"Das MCP Activation-Skill ermöglicht die Netzwerk-Sichtbarkeit und die Asset-Erkennung in Echtzeit für KI-Agents","pt":"O MCP Activation permite a visibilidade da rede centralizada e a descoberta contínua de ativos, permitindo que os desenvolvedores monitorem dispositivos e detectem alterações","ru":"MCP Activation обеспечивает централизованную видимость сети и непрерывное обнаружение активов, позволяя разработчикам контролировать устройства и обнаруживать изменения","ar":"يسمح MCP Activation بالرؤية المركزية للشبكة واكتشاف الأصول المستمر، مما يسمح للمطوّرين بمراقبة الأجهزة واكتشاف التغييرات"},"seo":{"title":{"en":"mcp-activation: Setup Guide for AI Agents","zh":"MCP Activation Setup Guide - AIエージェント动态操作","ja":"MCP Activation ベストプラクティス - AIエージェントの動的アクション","ko":"MCP Activation 설정 가이드 - AI 에이전트 동적 작동","es":"Guía de configuración de MCP Activation para Agentes de IA","fr":"Guide de configuration de MCP Activation pour Outils d''IA","de":"Konfigurationsleitfaden für MCP Activation für KI-Agents","pt":"Guia de Configuração do MCP Activation para Desenvolvedores","ru":"Настройка ИИ Агентов с помощью MCP Activation","ar":"إعداد MCP Activation للوكلاء الذكيين"},"description":{"en":"Unlock dynamic actions with mcp-activation. Learn how to configure NetAlertX for AI agents and enable querying databases, triggering actions, and validating ...","zh":"了解MCP Activation技能如何配置NetAlertX开发环境以实现动态操作和数据库查询","ja":"MCP Activationスキルの機能と、NetAlertX開発環境での動的アクションとデータベースの検索方法を学ぶ","ko":"MCP Activation 스킬이 NetAlertX 개발 환경에서 동적 작동과 데이터베이스 쿼리를 어떻게 설정하는지 알아보세요","es":"Configura el entorno de desarrollo de NetAlertX para exponer el servidor MCP a agentes de IA y habilita la visibilidad de la red y la detección de activos","fr":"Configurez l''environnement de développement NetAlertX pour exposer le serveur MCP aux outils d''IA et activez la visibilité du réseau et la découverte d''actifs","de":"Konfigurieren Sie die NetAlertX-Entwicklungsumgebung, um den MCP-Server für KI-Agents zu exponieren und aktivieren Sie die Netzwerk-Sichtbarkeit und die Asse...","pt":"Aprenda a configurar o MCP Activation para expor o servidor MCP para agentes AI e melhorar a visibilidade da rede","ru":"Узнайте, как настроить MCP Activation для предоставления доступа к серверу MCP для ИИ Агентов","ar":"تعرف على كيفية إعداد MCP Activation لجعل خادم MCP متاحًا للوكلاء الذكيين"},"definition":{"en":"mcp-activation is a skill that enables AI agents to access the Model Context Protocol (MCP) server, allowing for dynamic actions and real-time monitoring across distributed networks.","zh":"MCP Activation是配置NetAlertX开发环境以实现AIエージェント动态操作的技能","ja":"MCP Activationは、NetAlertX開発環境を設定し、AIエージェントの動的アクションを可能にするスキルです","ko":"MCP Activation은 NetAlertX 개발 환경을 설정하여 AI 에이전트의 동적 작동을 가능하게 하는 스킬입니다","es":"MCP Activation es un skill que configura el entorno de desarrollo de NetAlertX para exponer el servidor MCP a agentes de IA","fr":"MCP Activation est un skill qui configure l''environnement de développement NetAlertX pour exposer le serveur MCP aux outils d''IA","de":"MCP Activation ist ein Skill, der die NetAlertX-Entwicklungsumgebung konfiguriert, um den MCP-Server für KI-Agents zu exponieren","pt":"MCP Activation é uma habilidade que configura o ambiente de desenvolvimento NetAlertX para expor o servidor MCP para agentes AI","ru":"MCP Activation - это навык, который настраивает среду разработки NetAlertX для предоставления доступа к серверу MCP для ИИ Агентов","ar":"MCP Activation هو مهارة تُقنّن بيئة التطوير NetAlertX لجعل خادم MCP متاحًا للوكلاء الذكيين"},"features":{"en":["Exposes the Model Context Protocol (MCP) server to AI agents","Enables querying the database for device lists and events","Triggers actions such as network scans and Wake-on-LAN","Validates runtime state to ensure fixes are effective","Configures the NetAlertX development environment for dynamic actions"],"zh":["配置NetAlertX开发环境","实现AIエージェント动态操作","数据库查询（设备列表、事件）","触发动作（网络扫描、Wake-on-LAN）","验证运行时状态"],"ja":["NetAlertX開発環境の設定","AIエージェントの動的アクションの実現","データベースの検索（デバイスリスト、イベント）","動的アクションのトリガー（ネットワークスキャン、Wake-on-LAN）","ランタイム状態の検証"],"ko":["NetAlertX 개발 환경 설정","AI 에이전트 동적 작동 구현","데이터베이스 쿼리（디바이스 목록, 이벤트）","동적 작동 트리거（네트워크 스캔, Wake-on-LAN）","런타임 상태 검증"],"es":["Visibilidad de la red centralizada","Detección de activos en tiempo real","Acceso a la base de datos para consultar listas de dispositivos y eventos","Activación de acciones como escaneos de red y Wake-on-LAN","Validación del estado de ejecución en tiempo real"],"fr":["Visibilité du réseau centralisée","Découverte d''actifs en temps réel","Accès à la base de données pour interroger les listes de dispositifs et les événements","Activation d''actions comme les analyses de réseau et Wake-on-LAN","Validation de l''état d''exécution en temps réel"],"de":["Zentralisierte Netzwerk-Sichtbarkeit","Asset-Erkennung in Echtzeit","Zugriff auf die Datenbank zum Abfragen von Geräte- und Ereignislisten","Aktivierung von Aktionen wie Netzwerk-Scans und Wake-on-LAN","Validierung des Laufzeit-Zustands in Echtzeit"],"pt":["Visibilidade da rede centralizada","Descoberta contínua de ativos","Monitoramento de dispositivos","Detecção de alterações","Acesso ao servidor MCP para agentes AI","Suporte a ações dinâmicas, como consultas de banco de dados e acionamento de ações"],"ru":["Централизованная видимость сети","Непрерывное обнаружение активов","Контроль устройств","Обнаружение изменений","Доступ к серверу MCP для ИИ Агентов","Поддержка динамических действий, таких как запросы к базе данных и запуск действий"],"ar":["رؤية مركزية للشبكة","اكتشاف الأصول المستمر","مراقبة الأجهزة","اكتشاف التغييرات","دعم إجراءات ديناميكية، مثل استفسارات قاعدة البيانات وتحفيز الإجراءات","إتاحة خادم MCP للوكلاء الذكيين"]},"keywords":{"en":["how to use mcp-activation","mcp-activation setup guide","what is mcp-activation","mcp-activation alternative","mcp-activation vs NetAlertX","mcp-activation install","Model Context Protocol","NetAlertX development environment","AI agent skills"],"zh":["MCP Activation","AIエージェント","NetAlertX","动态操作","数据库查询","网络扫描","Wake-on-LAN","AI开发工具"],"ja":["MCP Activation","AIエージェント","NetAlertX","動的アクション","データベースの検索","ネットワークスキャン","Wake-on-LAN","AI開発ツール"],"ko":["MCP Activation","AI 에이전트","NetAlertX","동적 작동","데이터베이스 쿼리","네트워크 스캔","Wake-on-LAN","AI 개발 도구"],"es":["MCP Activation","Agentes de IA","Visibilidad de la red","Detección de activos","NetAlertX","Base de datos","Escaneos de red","Wake-on-LAN","Validación del estado de ejecución"],"fr":["MCP Activation","Outils d''IA","Visibilité du réseau","Découverte d''actifs","NetAlertX","Base de données","Analyses de réseau","Wake-on-LAN","Validation de l''état d''exécution"],"de":["MCP Activation","KI-Agents","Netzwerk-Sichtbarkeit","Asset-Erkennung","NetAlertX","Datenbank","Netzwerk-Scans","Wake-on-LAN","Validierung des Laufzeit-Zustands"],"pt":["MCP Activation","visibilidade da rede","descoberta de ativos","agentes AI","desenvolvimento NetAlertX","servidor MCP","consultas de banco de dados","acionamento de ações"],"ru":["MCP Activation","ИИ Агенты","видимость сети","обнаружение активов","среда разработки NetAlertX","сервер MCP","запросы к базе данных","динамические действия"],"ar":["MCP Activation","الوكلاء الذكيين","رؤية الشبكة","اكتشاف الأصول","بيئة التطوير NetAlertX","خادم MCP","استفسارات قاعدة البيانات","إجراءات ديناميكية"]}},"owner":"netalertx","repo":"NetAlertX","repoPath":"netalertx/NetAlertX","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.562Z","topics":[],"category":"community","skillMd":{"name":"mcp-activation","description":"Enables live interaction with the NetAlertX runtime. This skill configures the Model Context Protocol (MCP) connection, granting full API access for debugging, troubleshooting, and real-time operations including database queries, network scans, and device management.","bodyPreview":"# MCP Activation Skill\n\nThis skill configures the NetAlertX development environment to expose the Model Context Protocol (MCP) server to AI agents.\n\n## Why use this?\n\nBy default, agents only have access to the static codebase (files). To perform dynamic actions—such as:\n- **Querying the database** (e.g., getting device lists, events)\n- **Triggering actions** (e.g., network scans, Wake-on-LAN)\n- **Validating runtime state** (e.g., checking if a fix actually works)\n\n...you need access to the **MCP","body":"# MCP Activation Skill\n\nThis skill configures the NetAlertX development environment to expose the Model Context Protocol (MCP) server to AI agents.\n\n## Why use this?\n\nBy default, agents only have access to the static codebase (files). To perform dynamic actions—such as:\n- **Querying the database** (e.g., getting device lists, events)\n- **Triggering actions** (e.g., network scans, Wake-on-LAN)\n- **Validating runtime state** (e.g., checking if a fix actually works)\n\n...you need access to the **MCP Server** running inside the container. This skill sets up the necessary authentication tokens and connection configs to bridge your agent to that live server.\n\n## Prerequisites\n\n1.  **Devcontainer:** You must be connected to the NetAlertX devcontainer.\n2.  **Server Running:** The backend server must be running (to generate `app.conf` with the API token).\n\n## Activation Steps\n\n1.  **Activate Devcontainer Skill:**\n    If you are not already inside the container, activate the management skill:\n    ```text\n    activate_skill(\"devcontainer-management\")\n    ```\n\n2.  **Generate Configurations:**\n    Run the configuration generation script *inside* the container. This script extracts the API Token and creates the necessary settings files (`.gemini/settings.json` and `.vscode/mcp.json`).\n\n    ```bash\n    # Run inside the container\n    /workspaces/NetAlertX/.devcontainer/scripts/generate-configs.sh\n    ```\n\n3.  **Apply Changes:**\n\n    *   **For Gemini CLI:**\n        The agent session must be **restarted** to load the new `.gemini/settings.json`.\n        > \"I have generated the MCP configuration. Please **restart this session** to activate the `netalertx-devcontainer` tools.\"\n\n    *   **For VS Code (GitHub Copilot / Cline):**\n        The VS Code window must be **reloaded** to pick up the new `.vscode/mcp.json`.\n        > \"I have generated the MCP configuration. Please run **''Developer: Reload Window''** in VS Code to activate the MCP server.\"\n\n## Verification\n\nAfter restarting, you should see new tools available (e.g., `netalertx-devcontainer__get_devices`).\n"},"lastSynced":"2026-03-08T02:11:36.418Z","agentAnalysis":{"suitability":{"en":"Perfect for Advanced AI Agents needing dynamic asset discovery and Model Context Protocol (MCP) server access","zh":"适合需要动态资产发现和Model Context Protocol (MCP)服务器访问的高级AI代理","ja":"動的アセット発見とModel Context Protocol (MCP)サーバーへのアクセスを必要とする高度なAIエージェントに適しています","ko":"동적 자산 발견 및 Model Context Protocol (MCP) 서버 액세스가 필요한 고급 AI 에이전트에 적합합니다","es":"Perfecto para Agentes de IA Avanzados que necesitan descubrimiento de activos dinámicos y acceso al servidor de Protocolo de Contexto de Modelo (MCP)","fr":"Parfait pour les Agents d''IA Avancés ayant besoin de découverte d''actifs dynamique et d''accès au serveur de Protocole de Contexte de Modèle (MCP)","de":"Perfekt für erweiterte KI-Agents, die dynamische Asset-Erkennung und Zugriff auf den Model Context Protocol (MCP)-Server benötigen","pt":"Perfeito para Agentes de IA Avançados que necessitam de descoberta de ativos dinâmicos e acesso ao servidor do Protocolo de Contexto de Modelo (MCP)","ru":"Идеально подходит для продвинутых агентов ИИ, которым требуется динамическое обнаружение активов и доступ к серверу Протокола контекста модели (MCP)","ar":"مثالي لعمليات وكيل ذكاء اصطناعي المتقدمة التي تحتاج إلى اكتشاف أصول ديناميكي ووصول إلى خادم بروتوكول سياق النموذج (MCP)"},"recommendation":{"en":"Empowers agents to perform dynamic actions, such as querying databases, triggering network scans, and validating runtime state, using the Model Context Protocol (MCP) server and enabling continuous asset discovery","zh":"能够让代理执行动态操作，例如查询数据库，触发网络扫描和验证运行时状态，使用Model Context Protocol (MCP)服务器并实现持续的资产发现","ja":"エージェントが動的な操作を実行できるようにし、データベースの問い合わせ、ネットワークスキャンのトリガー、ランタイム状態の検証など、Model Context Protocol (MCP)サーバーを使用し、継続的なアセット発見を可能にします","ko":"에이전트가 동적인 작업을 수행할 수 있도록 하여 데이터베이스 쿼리, 네트워크 스캔 트리거, 런타임 상태 검증 등을 Model Context Protocol (MCP) 서버를 사용하여 연속적인 자산 발견을 가능하게 합니다","es":"Habilita a los agentes a realizar acciones dinámicas, como consultar bases de datos, desencadenar análisis de red y validar el estado de ejecución, utilizando el servidor de Protocolo de Contexto de Modelo (MCP) y permitiendo la continua descubrimiento de activos","fr":"Permet aux agents d''effectuer des actions dynamiques, telles que l''interrogation de bases de données, le déclenchement d''analyses de réseau et la validation de l''état d''exécution, en utilisant le serveur de Protocole de Contexte de Modèle (MCP) et en permettant la découverte continue d''actifs","de":"Ermöglicht es Agents, dynamische Aktionen durchzuführen, wie z.B. das Abfragen von Datenbanken, das Auslösen von Netzwerkscans und das Validieren des Laufzeitstatus, unter Verwendung des Model Context Protocol (MCP)-Servers und der Ermöglichung der kontinuierlichen Asset-Erkennung","pt":"Habilita os agentes a realizar ações dinâmicas, como consultar bancos de dados, disparar varreduras de rede e validar o estado de execução, usando o servidor do Protocolo de Contexto de Modelo (MCP) e permitindo a descoberta contínua de ativos","ru":"Позволяет агентам выполнять динамические действия, такие как запрос баз данных, запуск сканирования сети и проверка состояния выполнения, используя сервер Протокола контекста модели (MCP) и обеспечивая непрерывное обнаружение активов","ar":"يتمكن الوكيل من تنفيذ إجراءات ديناميكية، مثل استفسار قواعد البيانات، وتحفيز فحوصات الشبكة، وتصديق حالة التشغيل، باستخدام خادم بروتوكول سياق النموذج (MCP) وتمكين اكتشاف الأصول المستمر"},"useCases":{"en":["Querying the database for device lists and events","Triggering actions like network scans and Wake-on-LAN","Validating runtime state to check if a fix actually works"],"zh":["查询数据库以获取设备列表和事件","触发网络扫描和Wake-on-LAN等操作","验证运行时状态以检查修复是否生效"],"ja":["デバイスリストやイベントのデータベースの問い合わせ","ネットワークスキャンやWake-on-LANなどのアクションのトリガー","修復が実際に機能するかどうかを確認するためのランタイム状態の検証"],"ko":["장치 목록 및 이벤트를 위한 데이터베이스 쿼리","네트워크 스캔 및 Wake-on-LAN 등의 작업 트리거","실제로 수정이 작동하는지 확인하기 위한 런타임 상태 검증"],"es":["Consultar la base de datos para obtener listas de dispositivos y eventos","Desencadenar acciones como análisis de red y Wake-on-LAN","Validar el estado de ejecución para comprobar si una solución funciona realmente"],"fr":["Interroger la base de données pour obtenir des listes d''appareils et d''événements","Déclencher des actions comme des analyses de réseau et Wake-on-LAN","Valider l''état d''exécution pour vérifier si une solution fonctionne réellement"],"de":["Abfragen der Datenbank für Geräte- und Ereignislisten","Auslösen von Aktionen wie Netzwerkscans und Wake-on-LAN","Validieren des Laufzeitstatus, um zu überprüfen, ob eine Lösung tatsächlich funktioniert"],"pt":["Consultar o banco de dados para obter listas de dispositivos e eventos","Disparar ações como varreduras de rede e Wake-on-LAN","Validar o estado de execução para verificar se uma correção funciona"],"ru":["Запрос базы данных для получения списков устройств и событий","Запуск действий, таких как сканирование сети и Wake-on-LAN","Проверка состояния выполнения, чтобы проверить, работает ли исправление"],"ar":["استفسار قاعدة البيانات للحصول على قوائم الأجهزة والأحداث","تحفيز إجراءات مثل فحوصات الشبكة و Wake-on-LAN","تصديق حالة التشغيل للتحقق من WHETHER تعمل الإصلاحات"]},"limitations":{"en":["Requires NetAlertX development environment","MCP server exposure necessary"],"zh":["需要NetAlertX开发环境","需要MCP服务器暴露"],"ja":["NetAlertX開発環境が必要","MCPサーバーの公開が必要"],"ko":["NetAlertX 개발 환경이 필요합니다","MCP 서버 노출이 필요합니다"],"es":["Requiere entorno de desarrollo NetAlertX","Exposición del servidor MCP necesaria"],"fr":["Nécessite un environnement de développement NetAlertX","Exposition du serveur MCP nécessaire"],"de":["Benötigt NetAlertX-Entwicklungsumgebung","MCP-Server-Exposition erforderlich"],"pt":["Requer ambiente de desenvolvimento NetAlertX","Exposição do servidor MCP necessária"],"ru":["Требуется среда разработки NetAlertX","Необходимо раскрытие сервера MCP"],"ar":["يتطلب بيئة تطوير NetAlertX","يجب الكشف عن خادم MCP"]},"version":4},"contentHash":"5b1e1812ef8e15fac079329b80fcad19bbd93e01bdaf05c4725128db12ae17f6","qualityScore":42}');
