INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('shinpr/claude-code-workflows/coding-principles', 'coding-principles', 'shinpr', 'claude-code-workflows', 'community', 'coding-principles shinpr claude-code-workflows community Coding-principles provides production-ready development workflows for AI agents, focusing on maintainability, simplicity, and explicit code. This skill benefits developers seeking efficient coding practices. Coding Principles提供了生产就绪的开发工作流，为Claude Code提供了强大的支持，专注于可维护性、简单性和显式性 Coding Principlesは、Claude Codeにパワフルなサポートを提供する生産性の高い開発ワークフローを提供し、メンテナンス性、シンプルさ、明示性に焦点を当てています 코딩 원칙은 클라우드 코드에 강력한 지원을 제공하는 생산성 높은 개발 워크플로우를 제공하며, 유지 보수성, 단순성, 명시성을 중점으로 합니다 Los principios de codificación para Agentes de IA mejoran la calidad y mantenibilidad del código a través de la simplicidad y la claridad Les principes de codage pour les Outils d''IA améliorent la qualité et la maintenabilité du code grâce à la simplicité et à la clarté Die Codierprinzipien für KI-Agents verbessern die Qualität und Wartbarkeit des Codes durch Einfachheit und Klarheit Princípios de codificação para desenvolvedores, com foco em manutenção e simplicidade, utilizando agentes de IA especializados Принципы кодирования для разработчиков, с акцентом на поддержку и простоту, с использованием специализированных ИИ агентов مبادئ الترميز لمطوري البرمجيات, مع التركيز على الصيانة و البساطة, باستخدام وكلاء الذكاء الاصطناعي المتخصصين how to use coding-principles coding-principles best practices coding-principles alternative coding-principles vs clean code coding-principles setup guide coding-principles for AI agents AI智能代理 Coding Principles 可维护性 简单性 显式性 删除无用代码 持续改进 AI开发最佳实践 Prioritizes maintainability over initial development velocity Applies YAGNI principle for simplicity-first approach Emphasizes explicit code intentions through structure and naming Adopts delete-over-comment approach for cleaner code Supports continuous improvement through refactoring Coding-principles is a set of language-agnostic guidelines emphasizing maintainability, simplicity, and explicit code structure for optimal development workflows.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('VibiumDev/vibium/vibe-check', 'community', 'VibiumDev', 'vibium', 'VibiumDev/vibium', 'vibe-check', 0, 0, 42, '2026-03-08T01:57:15.578Z', '2026-03-08T02:11:50.404Z', 'ec10454cf8bcdd175887851144faaddcabe7476792c36e5b0d6543114e8d4b3f', '{"id":"VibiumDev/vibium/vibe-check","name":"vibe-check","description":{"en":"vibe-check automates Chrome via the command line, benefiting AI agents and humans. It enables core workflow patterns like navigate, map, and interact.","zh":"Vibe-check 是一个浏览器自动化工具，通过 CLI 命令自动化 Chrome 浏览器。它支持导航、映射和交互等功能","ja":"Vibe-check はブラウザ自動化ツールで、CLI コマンドで Chrome ブラウザを自動化します。ナビゲーション、マッピング、インタラクション等の機能をサポート","ko":"Vibe-check는 브라우저 자동화 도구로, CLI 명령으로 Chrome 브라우저를 자동화합니다. 네비게이션, 매핑, 상호작용 등 기능을 지원","es":"vibe-check es una herramienta de automatización de navegador que utiliza comandos de CLI para interactuar con el navegador","fr":"vibe-check est un outil d''automatisation du navigateur qui utilise des commandes CLI pour interagir avec le navigateur","de":"vibe-check ist ein Tool zur Browser-Automatisierung, das CLI-Befehle verwendet, um mit dem Browser zu interagieren","pt":"O Vibe-Check é uma ferramenta de automação de navegadores que utiliza comando CLI para interagir com elementos da web","ru":"Vibe-Check — это инструмент для автоматизации браузеров, который использует командную строку для взаимодействия с веб-элементами","ar":"Vibe-Check هو أداة للتحكم الآلي في المتصفحات التي تستخدم واجهة سطر الأوامر للتفاعل مع عناصر الويب"},"seo":{"title":{"en":"vibe-check: Browser Automation Setup Guide | AI Agent Skill","zh":"Vibe-check 浏览器自动化设置指南","ja":"Vibe-check ブラウザ自動化ベストプラクティス","ko":"Vibe-check 브라우저 자동화 설정 가이드","es":"Guía de configuración de vibe-check para automatización d...","fr":"Guide de mise en route de vibe-check pour l''automatisatio...","de":"Setup-Anleitung für vibe-check zur Browser-Automatisierung","pt":"Guia de Configuração do Vibe-Check para Automação de Nave...","ru":"Настройка Vibe-Check для автоматизации браузеров с ИИ Аге...","ar":"دليل إعداد Vibe-Check للتحكم الآلي في المتصفحات مع أدوات ..."},"description":{"en":"Unlock efficient browser automation with vibe-check. Learn how to navigate, map, and interact with web elements using the vibium CLI. Get started now!","zh":"使用 Vibe-check 实现浏览器自动化，通过 CLI 命令自动化 Chrome 浏览器","ja":"Vibe-check を使用してブラウザ自動化を実現します。CLI コマンドで Chrome ブラウザを自動化","ko":"Vibe-check를 사용하여 브라우저 자동화를 구현합니다. CLI 명령으로 Chrome 브라우저를 자동화","es":"Automatice tareas en el navegador con vibe-check, utilizando comandos de CLI como vibium go y vibium map","fr":"Automatisez des tâches dans le navigateur avec vibe-check, en utilisant des commandes CLI comme vibium go et vibium map","de":"Automatisieren Sie Aufgaben im Browser mit vibe-check, indem Sie CLI-Befehle wie vibium go und vibium map verwenden","pt":"Aprenda a configurar o Vibe-Check para automação de navegadores com comando CLI e interação com elementos da web","ru":"Узнайте, как настроить Vibe-Check для автоматизации браузеров с помощью командной строки и взаимодействия с веб-элементами","ar":"تعلم كيفية إعداد Vibe-Check للتحكم الآلي في المتصفحات باستخدام واجهة سطر الأوامر وتفاعل مع عناصر الويب"},"definition":{"en":"vibe-check is a browser automation skill that utilizes the vibium CLI to automate Chrome, supporting daemon mode and element reference mapping.","zh":"Vibe-check 是一个通过 CLI 命令自动化 Chrome 浏览器的浏览器自动化工具","ja":"Vibe-check は、CLI コマンドで Chrome ブラウザを自動化するブラウザ自動化ツール","ko":"Vibe-check는 CLI 명령으로 Chrome 브라우저를 자동화하는 브라우저 자동화 도구","es":"vibe-check es una herramienta de automatización de navegador que utiliza comandos de CLI para interactuar con el navegador, ideal para agentes de inteligencia artificial","fr":"vibe-check est un outil d''automatisation du navigateur qui utilise des commandes CLI pour interagir avec le navigateur, idéal pour les outils d''intelligence artificielle","de":"vibe-check ist ein Tool zur Browser-Automatisierung, das CLI-Befehle verwendet, um mit dem Browser zu interagieren, ideal für KI-Agents","pt":"O Vibe-Check é uma ferramenta de automação de navegadores que permite interagir com elementos da web via comando CLI","ru":"Vibe-Check — это инструмент для автоматизации браузеров, который позволяет взаимодействовать с веб-элементами через командную строку","ar":"Vibe-Check هو أداة للتحكم الآلي في المتصفحات التي تتيح التفاعل مع عناصر الويب عبر واجهة سطر الأوامر"},"features":{"en":["Automates Chrome via the command line using the vibium CLI","Supports daemon mode to keep the browser running between commands","Provides element reference mapping using the `vibium map` command","Enables navigation to specific URLs using `vibium go <url>`","Allows interaction with web elements using refs, such as `vibium click @e1`"],"zh":["支持导航功能，通过 `vibium go <url>` 命令访问指定 URL","支持映射功能，通过 `vibium map` 命令获取元素引用","支持交互功能，通过 `vibium click @e1` 命令模拟鼠标点击","支持 CLI 命令，方便快捷地自动化浏览器操作","支持 daemon 模式，保持浏览器在后台运行","支持元素引用，通过 `@e1` 等符号引用元素"],"ja":["ナビゲーション機能をサポート、`vibium go <url>` コマンドで指定 URL にアクセス","マッピング機能をサポート、`vibium map` コマンドで要素参照を取得","インタラクション機能をサポート、`vibium click @e1` コマンドでマウスクリックを模擬","CLI コマンドをサポート、ブラウザ操作を自動化する","デーモン モードをサポート、ブラウザをバックグラウンドで実行","要素参照をサポート、`@e1` などの記号で要素を参照"],"ko":["네비게이션 기능을 지원، `vibium go <url>` 명령으로 지정 URL에 접근","매핑 기능을 지원， `vibium map` 명령으로 요소 참조를 얻음","상호작용 기능을 지원， `vibium click @e1` 명령으로 마우스 클릭을 시뮬레이션","CLI 명령을 지원， 브라우저操作을 자동화","데몬 모드를 지원， 브라우저를 백그라운드에서 실행","요소 참조를 지원， `@e1` 등의 기호로 요소를 참조"],"es":["Automatización de navegador mediante comandos de CLI","Uso de vibium go para navegar a URLs","Uso de vibium map para obtener referencias de elementos","Interacción con elementos mediante comandos como vibium click","Soporte para daemon mode para mantener el navegador abierto entre comandos"],"fr":["Automatisation du navigateur via des commandes CLI","Utilisation de vibium go pour naviguer vers des URLs","Utilisation de vibium map pour obtenir des références d''éléments","Interaction avec des éléments via des commandes comme vibium click","Prise en charge du mode daemon pour maintenir le navigateur ouvert entre les commandes"],"de":["Browser-Automatisierung über CLI-Befehle","Verwendung von vibium go zur Navigation zu URLs","Verwendung von vibium map zur Erfassung von Element-Referenzen","Interaktion mit Elementen über Befehle wie vibium click","Unterstützung für den Daemon-Modus, um den Browser zwischen Befehlen geöffnet zu halten"],"pt":["Automação de navegadores via comando CLI","Interação com elementos da web utilizando referências como @e1 e @e2","Navigação para URLs específicas com `vibium go <url>`","Mapeamento de elementos da web com `vibium map`","Clique em elementos da web com `vibium click @e1`"],"ru":["Автоматизация браузеров через командную строку","Взаимодействие с веб-элементами с помощью ссылок như @e1 и @e2","Переход к конкретным URL-адресам с помощью `vibium go <url>`","Картографирование веб-элементов с помощью `vibium map`","Клик на веб-элементах с помощью `vibium click @e1`"],"ar":["التحكم الآلي في المتصفحات عبر واجهة سطر الأوامر","التفاعل مع عناصر الويب باستخدام مراجع مثل @e1 و @e2","التنقل إلى عناوين URL محددة باستخدام `vibium go <url>`","تعيين عناصر الويب باستخدام `vibium map`","النقر على عناصر الويب باستخدام `vibium click @e1`"]},"keywords":{"en":["how to use vibe-check","vibe-check alternative","vibe-check setup guide","vibe-check install","vibium CLI tutorial","browser automation with vibe-check","what is vibe-check","vibe-check vs Selenium"],"zh":["Vibe-check","浏览器自动化","CLI 命令","Chrome 自动化","AIエージェント","浏览器自动化工具","自动化测试","Web 自动化"],"ja":["Vibe-check","ブラウザ自動化","CLI コマンド","Chrome 自動化","AIエージェント","ブラウザ自動化ツール","自動化テスト","Web 自動化"],"ko":["Vibe-check","브라우저 자동화","CLI 명령","Chrome 자동화","AI 에이전트","브라우저 자동화 도구","자동화 테스트","Web 자동화"],"es":["vibe-check","automatización de navegador","CLI","vibium go","vibium map","agentes de inteligencia artificial","herramientas de automatización","navegador automático"],"fr":["vibe-check","automatisation du navigateur","CLI","vibium go","vibium map","outils d''intelligence artificielle","outils d''automatisation","navigateur automatique"],"de":["vibe-check","Browser-Automatisierung","CLI","vibium go","vibium map","KI-Agents","Automatisierungstools","automatischer Browser"],"pt":["automação de navegadores","comando CLI","interação com elementos da web","vibium","navegação para URLs","mapeamento de elementos da web","clique em elementos da web","ferramentas de automação","desenvolvimento web"],"ru":["автоматизация браузеров","командная строка","взаимодействие с веб-элементами","vibium","переход к URL-адресам","картографирование веб-элементов","клик на веб-элементах","инструменты автоматизации","веб-разработка"],"ar":["التحكم الآلي في المتصفحات","واجهة سطر الأوامر","التفاعل مع عناصر الويب","vibium","التنقل إلى عناوين URL","تعيين عناصر الويب","النقر على عناصر الويب","أدوات التحكم الآلي","تطوير الويب"]}},"owner":"VibiumDev","repo":"vibium","repoPath":"VibiumDev/vibium","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.578Z","topics":[],"category":"community","skillMd":{"name":"vibe-check","description":"Browser automation for AI agents. Use when the user needs to navigate websites, read page content, fill forms, click elements, take screenshots, or manage browser tabs.","bodyPreview":"# Vibium Browser Automation — CLI Reference\n\nThe `vibium` CLI automates Chrome via the command line. The browser auto-launches on first use (daemon mode keeps it running between commands).\n\n```\nvibium go <url> && vibium map && vibium click @e1 && vibium map\n```\n\n## Core Workflow\n\nEvery browser automation follows this pattern:\n\n1. **Navigate**: `vibium go <url>`\n2. **Map**: `vibium map` (get element refs like `@e1`, `@e2`)\n3. **Interact**: Use refs to click, fill, select — e.g. `vibium click @e1`","body":"# Vibium Browser Automation — CLI Reference\n\nThe `vibium` CLI automates Chrome via the command line. The browser auto-launches on first use (daemon mode keeps it running between commands).\n\n```\nvibium go <url> && vibium map && vibium click @e1 && vibium map\n```\n\n## Core Workflow\n\nEvery browser automation follows this pattern:\n\n1. **Navigate**: `vibium go <url>`\n2. **Map**: `vibium map` (get element refs like `@e1`, `@e2`)\n3. **Interact**: Use refs to click, fill, select — e.g. `vibium click @e1`\n4. **Re-map**: After navigation or DOM changes, get fresh refs with `vibium map`\n\n## Binary Resolution\n\nBefore running any commands, resolve the `vibium` binary path once:\n\n1. Try `vibium` directly (works if globally installed via `npm install -g vibium`)\n2. Fall back to `./clicker/bin/vibium` (dev environment, in project root)\n3. Fall back to `./node_modules/.bin/vibium` (local npm install)\n\nRun `vibium --help` (or the resolved path) to confirm. Use the resolved path for all subsequent commands.\n\n**Windows note:** Use forward slashes in paths (e.g. `./clicker/bin/vibium.exe`) and quote paths containing spaces.\n\n## Command Chaining\n\nChain commands with `&&` to run them sequentially. The chain stops on first error:\n\n```sh\nvibium go https://example.com && vibium map && vibium click @e3 && vibium diff map\n```\n\n**When to chain:** Use `&&` for sequences that should happen back-to-back (navigate → interact → verify). Run commands separately when you need to inspect output between steps.\n\n**When NOT to chain:** Don''t chain commands that depend on parsing the previous output (e.g. reading map output to decide what to click). Run those separately so you can analyze the result first.\n\n## Commands\n\n### Discovery\n- `vibium map` — map interactive elements with @refs (recommended before interacting)\n- `vibium map --selector \"nav\"` — scope map to elements within a CSS subtree\n- `vibium diff map` — compare current vs last map (see what changed)\n\n### Navigation\n- `vibium go <url>` — go to a page\n- `vibium back` — go back in history\n- `vibium forward` — go forward in history\n- `vibium reload` — reload the current page\n- `vibium url` — print current URL\n- `vibium title` — print page title\n\n### Reading Content\n- `vibium text` — get all page text\n- `vibium text \"<selector>\"` — get text of a specific element\n- `vibium html` — get page HTML (use `--outer` for outerHTML)\n- `vibium find \"<selector>\"` — find element, return `@e1` ref (clickable with `vibium click @e1`)\n- `vibium find --text \"Sign In\"` — find element by text content → `@e1`\n- `vibium find --label \"Email\"` — find input by label → `@e1`\n- `vibium find --placeholder \"Search\"` — find by placeholder → `@e1`\n- `vibium find --testid \"submit-btn\"` — find by data-testid → `@e1`\n- `vibium find --xpath \"//div[@class]\"` — find by XPath → `@e1`\n- `vibium find --alt \"Logo\"` — find by alt attribute → `@e1`\n- `vibium find --title \"Settings\"` — find by title attribute → `@e1`\n- `vibium find-all \"<selector>\"` — find all matching elements → `@e1`, `@e2`, ... (`--limit N`)\n- `vibium find --role <role>` — find element by ARIA role → `@e1` (combine with `--text`, `--label`, etc.)\n- `vibium eval \"<js>\"` — run JavaScript and print result (`--stdin` to read from stdin)\n- `vibium count \"<selector>\"` — count matching elements\n- `vibium screenshot -o file.png` — capture screenshot (`--full-page`, `--annotate`)\n- `vibium a11y-tree` — accessibility tree (`--everything` for all nodes)\n\n### Interaction\n- `vibium click \"<selector>\"` — click an element (also accepts `@ref` from map)\n- `vibium dblclick \"<selector>\"` — double-click an element\n- `vibium type \"<selector>\" \"<text>\"` — type into an input (appends to existing value)\n- `vibium fill \"<selector>\" \"<text>\"` — clear field and type new text (replaces value)\n- `vibium press <key> [selector]` — press a key on element or focused element\n- `vibium focus \"<selector>\"` — focus an element\n- `vibium hover \"<selector>\"` — hover over an element\n- `vibium scroll [direction]` — scroll page (`--amount N`, `--selector`)\n- `vibium scroll-into-view \"<selector>\"` — scroll element into view (centered)\n- `vibium keys \"<combo>\"` — press keys (Enter, Control+a, Shift+Tab)\n- `vibium select \"<selector>\" \"<value>\"` — pick a dropdown option\n- `vibium check \"<selector>\"` — check a checkbox/radio (idempotent)\n- `vibium uncheck \"<selector>\"` — uncheck a checkbox (idempotent)\n\n### Mouse Primitives\n- `vibium mouse-click [x] [y]` — click at coordinates or current position (`--button 0|1|2`)\n- `vibium mouse-move <x> <y>` — move mouse to coordinates\n- `vibium mouse-down` — press mouse button (`--button 0|1|2`)\n- `vibium mouse-up` — release mouse button (`--button 0|1|2`)\n- `vibium drag \"<source>\" \"<target>\"` — drag from one element to another\n\n### Element State\n- `vibium value \"<selector>\"` — get input/textarea/select value\n- `vibium attr \"<selector>\" \"<attribute>\"` — get HTML attribute value\n- `vibium is-visible \"<selector>\"` — check if element is visible (true/false)\n- `vibium is-enabled \"<selector>\"` — check if element is enabled (true/false)\n- `vibium is-checked \"<selector>\"` — check if checkbox/radio is checked (true/false)\n\n### Waiting\n- `vibium wait \"<selector>\"` — wait for element (`--state visible|hidden|attached`, `--timeout ms`)\n- `vibium wait-for-url \"<pattern>\"` — wait until URL contains substring (`--timeout ms`)\n- `vibium wait-for-load` — wait until page is fully loaded (`--timeout ms`)\n- `vibium wait-for-text \"<text>\"` — wait until text appears on page (`--timeout ms`)\n- `vibium wait-for-fn \"<expression>\"` — wait until JS expression returns truthy (`--timeout ms`)\n- `vibium sleep <ms>` — pause execution (max 30000ms)\n\n### Capture\n- `vibium screenshot -o file.png` — capture screenshot (`--full-page`, `--annotate`)\n- `vibium pdf -o file.pdf` — save page as PDF\n\n### Dialogs\n- `vibium dialog accept [text]` — accept dialog (optionally with prompt text)\n- `vibium dialog dismiss` — dismiss dialog\n\n### Emulation\n- `vibium set-viewport <width> <height>` — set viewport size (`--dpr` for device pixel ratio)\n- `vibium viewport` — get current viewport dimensions\n- `vibium window` — get OS browser window dimensions and state\n- `vibium set-window <width> <height> [x] [y]` — set window size and position (`--state`)\n- `vibium emulate-media` — override CSS media features (`--color-scheme`, `--reduced-motion`, `--forced-colors`, `--contrast`, `--media`)\n- `vibium set-geolocation <lat> <lng>` — override geolocation (`--accuracy`)\n- `vibium set-content \"<html>\"` — replace page HTML (`--stdin` to read from stdin)\n\n### Frames\n- `vibium frames` — list all iframes on the page\n- `vibium frame \"<nameOrUrl>\"` — find a frame by name or URL substring\n\n### File Upload\n- `vibium upload \"<selector>\" <files...>` — set files on input[type=file]\n\n### Tracing\n- `vibium trace start` — start recording (`--screenshots`, `--snapshots`, `--name`)\n- `vibium trace stop` — stop recording and save ZIP (`-o path`)\n\n### Cookies\n- `vibium cookies` — list all cookies\n- `vibium cookies set <name> <value>` — set a cookie\n- `vibium cookies clear` — clear all cookies\n\n### Storage State\n- `vibium storage-state` — export cookies + localStorage + sessionStorage (`-o state.json`)\n- `vibium restore-storage <path>` — restore state from JSON file\n\n### Downloads\n- `vibium download set-dir <path>` — set download directory\n\n### Tabs\n- `vibium tabs` — list open tabs\n- `vibium tab-new [url]` — open new tab\n- `vibium tab-switch <index|url>` — switch tab\n- `vibium tab-close [index]` — close tab\n\n### Debug\n- `vibium highlight \"<selector>\"` — highlight element visually (3 seconds)\n\n### Session\n- `vibium close` — close the browser (daemon keeps running)\n- `vibium daemon start` — start background browser\n- `vibium daemon status` — check if running\n- `vibium daemon stop` — stop daemon\n- `vibium connect <url>` — connect to a remote browser (stops local daemon, starts in connect mode)\n- `vibium disconnect` — disconnect from remote browser (stops daemon; next command auto-starts local)\n\n## Common Patterns\n\n### Ref-based workflow (recommended for AI)\n```sh\nvibium go https://example.com\nvibium map\nvibium click @e1\nvibium map  # re-map after interaction\n```\n\n### Verify action worked\n```sh\nvibium map\nvibium click @e3\nvibium diff map  # see what changed\n```\n\n### Read a page\n```sh\nvibium go https://example.com && vibium text\n```\n\n### Fill a form (end-to-end)\n```sh\nvibium go https://example.com/login\nvibium map\n# Look at map output to identify form fields\nvibium fill @e1 \"user@example.com\"\nvibium fill @e2 \"secret\"\nvibium click @e3\nvibium wait-for-url \"/dashboard\"\nvibium screenshot -o after-login.png\n```\n\n### Scoped map (large pages)\n```sh\nvibium map --selector \"nav\"        # Only map elements in <nav>\nvibium map --selector \"#sidebar\"   # Only map elements in #sidebar\nvibium map --selector \"form\"       # Only map form controls\n```\n\n### Semantic find (no CSS selectors needed)\n```sh\nvibium find --text \"Sign In\"           # → @e1 [button] \"Sign In\"\nvibium find --label \"Email\"            # → @e1 [input] placeholder=\"Email\"\nvibium click @e1                       # Click the found element\nvibium find --placeholder \"Search...\"  # → @e1 [input] placeholder=\"Search...\"\nvibium find --testid \"submit-btn\"      # → @e1 [button] \"Submit\"\nvibium find --alt \"Company logo\"       # → @e1 [img] alt=\"Company logo\"\nvibium find --title \"Close\"            # → @e1 [button] title=\"Close\"\nvibium find --xpath \"//a[@href=''/about'']\"  # → @e1 [a] \"About\"\n```\n\n### Authentication with state persistence\n```sh\n# Log in once and save state\nvibium go https://app.example.com/login\nvibium fill \"input[name=email]\" \"user@example.com\"\nvibium fill \"input[name=password]\" \"secret\"\nvibium click \"button[type=submit]\"\nvibium wait-for-url \"/dashboard\"\nvibium storage-state -o auth.json\n\n# Restore in a later session (skips login)\nvibium restore-storage auth.json\nvibium go https://app.example.com/dashboard\n```\n\n### Extract structured data\n```sh\nvibium go https://example.com\nvibium eval \"JSON.stringify([...document.querySelectorAll(''a'')].map(a => ({text: a.textContent.trim(), href: a.href})))\"\n```\n\n### Check page structure without rendering\n```sh\nvibium go https://example.com && vibium a11y-tree\n```\n\n### Remote browser\n```sh\nvibium connect ws://remote-host:9515/session\nvibium go https://example.com\nvibium map\nvibium disconnect\n```\n\n### Multi-tab workflow\n```sh\nvibium tab-new https://docs.example.com\nvibium text \"h1\"\nvibium tab-switch 0\n```\n\n### Annotated screenshot\n```sh\nvibium screenshot -o annotated.png --annotate\n```\n\n### Inspect an element\n```sh\nvibium attr \"a\" \"href\"\nvibium value \"input[name=email]\"\nvibium is-visible \".modal\"\n```\n\n### Save as PDF\n```sh\nvibium go https://example.com && vibium pdf -o page.pdf\n```\n\n## Eval / JavaScript\n\n`vibium eval` is the escape hatch for any DOM query or mutation the CLI doesn''t cover directly.\n\n**Simple expressions** — use single quotes:\n```sh\nvibium eval ''document.title''\nvibium eval ''document.querySelectorAll(\"li\").length''\n```\n\n**Complex scripts** — use `--stdin` with a heredoc:\n```sh\nvibium eval --stdin <<''EOF''\nconst rows = [...document.querySelectorAll(''table tbody tr'')];\nJSON.stringify(rows.map(r => {\n  const cells = r.querySelectorAll(''td'');\n  return { name: cells[0].textContent.trim(), price: cells[1].textContent.trim() };\n}));\nEOF\n```\n\n**JSON output** — use `--json` to get machine-readable output:\n```sh\nvibium eval --json ''JSON.stringify({url: location.href, title: document.title})''\n```\n\n**Important:** `eval` returns the expression result. If your script doesn''t return a value, you''ll get `null`. Always make sure the last expression evaluates to the data you want.\n\n## Timeouts and Waiting\n\nAll interaction commands (`click`, `fill`, `type`, etc.) auto-wait for the target element to be actionable. You usually don''t need explicit waits.\n\nUse explicit waits when:\n- **Waiting for navigation:** `vibium wait-for-url \"/dashboard\"` — after clicking a link that navigates\n- **Waiting for content:** `vibium wait-for-text \"Success\"` — after form submission, wait for confirmation\n- **Waiting for element:** `vibium wait \".modal\"` — wait for a modal to appear\n- **Waiting for page load:** `vibium wait-for-load` — after navigation to a slow page\n- **Waiting for JS condition:** `vibium wait-for-fn \"window.appReady === true\"` — wait for app initialization\n- **Fixed delay (last resort):** `vibium sleep 2000` — only when no better signal exists (max 30s)\n\nAll wait commands accept `--timeout <ms>` (default varies by command).\n\n## Ref Lifecycle\n\nRefs (`@e1`, `@e2`) are invalidated when the page changes. Always re-map after:\n- Clicking links or buttons that navigate\n- Form submissions\n- Dynamic content loading (dropdowns, modals)\n\n## Global Flags\n\n| Flag | Description |\n|------|-------------|\n| `--headless` | Hide browser window |\n| `--json` | Output as JSON |\n| `-v, --verbose` | Debug logging |\n\n## Tips\n\n- All click/type/hover/fill actions auto-wait for the element to be actionable\n- All selector arguments also accept `@ref` from `vibium map`\n- Use `vibium map` before interacting to discover interactive elements\n- Use `vibium map --selector` to reduce noise on large pages\n- Use `vibium fill` to replace a field''s value, `vibium type` to append to it\n- Use `vibium find --text` / `--label` / `--testid` for semantic element lookup (more reliable than CSS selectors)\n- Use `vibium find --role` for ARIA-role-based lookup\n- Use `vibium a11y-tree` to understand page structure without visual rendering\n- Use `vibium text \"<selector>\"` to read specific sections\n- Use `vibium diff map` after interactions to see what changed\n- `vibium eval` is the escape hatch for complex DOM queries\n- `vibium check`/`vibium uncheck` are idempotent — safe to call without checking state first\n- Screenshots save to the current directory by default (`-o` to change)\n- Use `vibium storage-state` / `vibium restore-storage` to persist auth across sessions\n"},"lastSynced":"2026-03-08T02:11:50.404Z","agentAnalysis":{"suitability":{"en":"Perfect for Automation Agents needing advanced browser interaction capabilities via Chrome CLI automation","zh":"适合需要通过Chrome CLI自动化实现高级浏览器交互功能的自动化代理","ja":"Chrome CLI自動化を介した高度なブラウザインタラクション機能を必要とする自動化エージェントに適しています","ko":"Chrome CLI 자동화를 통한 고급 브라우저 상호작용 기능이 필요한 자동화 에이전트에 적합합니다","es":"Perfecto para Agentes de Automatización que necesitan capacidades de interacción avanzada con el navegador a través de la automatización de Chrome CLI","fr":"Parfait pour les Agents d''Automatisation nécessitant des capacités d''interaction avancée avec le navigateur via l''automatisation de Chrome CLI","de":"Perfekt für Automatisierungsagenten, die erweiterte Browser-Interaktionsfunktionen über die Chrome-CLI-Automatisierung benötigen","pt":"Perfeito para Agentes de Automação que necessitam de capacidades avançadas de interação com o navegador via automação do Chrome CLI","ru":"Идеально подходит для агентов автоматизации, которым требуются расширенные возможности взаимодействия с браузером через автоматизацию Chrome CLI","ar":"مثالي للوكلاء الآليين الذين يحتاجون إلى إمكانيات متقدمة للتفاعل مع المتصفح عبر أتمتة Chrome CLI"},"recommendation":{"en":"Empowers agents to automate Chrome workflows using daemon mode, enabling seamless navigation, element mapping, and interaction via protocols like CLI commands, and supports core workflow patterns like navigate, map, and interact","zh":"赋予代理自动化Chrome工作流的能力，使用守护进程模式，实现无缝导航、元素映射和交互，通过诸如CLI命令的协议，并支持核心工作流模式，如导航、映射和交互","ja":"エージェントにChromeワークフローを自動化する能力を与え、デーモン模式を使用してシームレスなナビゲーション、要素マッピング、インタラクションを実現し、CLIコマンドなどのプロトコルを介してコアワークフローパターンをサポートします","ko":"에이전트가 Chrome 워크플로를 자동화 할 수 있는 능력을 부여하여 데몬 모드를 사용하여 무결점 탐색, 요소 매핑 및 상호 작용을实现하고, CLI 명령과 같은 프로토콜을 통해 핵심 워크플로 패턴을 지원합니다","es":"Habilita a los agentes a automatizar flujos de trabajo de Chrome utilizando el modo daemon, lo que permite una navegación sin problemas, mapeo de elementos e interacción a través de protocolos como comandos de CLI, y admite patrones de flujo de trabajo básicos como navegar, mapear e interactuar","fr":"Permet aux agents d''automatiser les flux de travail Chrome en utilisant le mode daemon, permettant ainsi une navigation sans accroc, un mappage d''éléments et une interaction via des protocoles tels que des commandes CLI, et prend en charge les modèles de flux de travail de base tels que naviguer, mapper et interagir","de":"Ermöglicht es den Agenten, Chrome-Workflows mit Hilfe des Daemon-Modus zu automatisieren, wodurch eine reibungslose Navigation, Elementzuordnung und Interaktion über Protokolle wie CLI-Befehle ermöglicht wird und unterstützt grundlegende Workflowmuster wie Navigieren, Zuordnen und Interagieren","pt":"Habilita os agentes a automatizar fluxos de trabalho do Chrome usando modo daemon, permitindo navegação sem interrupções, mapeamento de elementos e interação via protocolos como comandos CLI, e suporta padrões de fluxo de trabalho principais como navegar, mapear e interagir","ru":"Позволяет агентам автоматизировать рабочие процессы Chrome с помощью режима демона, обеспечивая бесшовную навигацию, сопоставление элементов и взаимодействие через протоколы, такие как команды CLI, и поддерживает основные шаблоны рабочих процессов, такие как навигация, сопоставление и взаимодействие","ar":"تمكّن الوكلاء من توفير سير عمل Chrome باستخدام وضع الدايمون، وتمكّن من التنقل السلس، وربط العناصر، والتفاعل عبر بروتوكولات مثل أوامر CLI، ودعم أنماط سير العمل الأساسية مثل التنقل، وربط العناصر، والتفاعل"},"useCases":{"en":["Automating browser interactions for data scraping","Generating element references for click and fill actions","Debugging browser-based workflows using vibium CLI"],"zh":["自动化浏览器交互以进行数据抓取","生成元素引用以进行点击和填充操作","使用vibium CLI调试基于浏览器的工作流"],"ja":["データスクラブのためにブラウザのインタラクションを自動化する","クリックとフィル操作のために要素リファレンスを生成する","vibium CLIを使用してブラウザベースのワークフローをデバッグする"],"ko":["데이터 스크래핑을 위한 브라우저 상호작용 자동화","클릭 및 채우기 동작을 위한 요소 참조 생성","vibium CLI를 사용하여 브라우저 기반 워크플로를 디버깅하는"],"es":["Automatizar interacciones del navegador para el scraping de datos","Generar referencias de elementos para acciones de clic y relleno","Depurar flujos de trabajo basados en el navegador utilizando vibium CLI"],"fr":["Automatiser les interactions du navigateur pour le scraping de données","Générer des références d''éléments pour les actions de clic et de remplissage","Déboguer les flux de travail basés sur le navigateur en utilisant vibium CLI"],"de":["Automatisieren von Browser-Interaktionen für das Scraping von Daten","Erstellen von Elementreferenzen für Klick- und Füllaktionen","Debuggen von browserbasierten Workflows mit Hilfe von vibium CLI"],"pt":["Automatizar interações do navegador para extração de dados","Gerar referências de elementos para ações de clique e preenchimento","Depurar fluxos de trabalho baseados em navegador usando vibium CLI"],"ru":["Автоматизировать взаимодействия браузера для сбора данных","Генерировать ссылки на элементы для действий клика и заполнения","Отлаживать рабочие процессы на основе браузера с помощью vibium CLI"],"ar":["أتمتة تفاعلات المتصفح لاستخراج البيانات","توليد مراجع العناصر لأفعال النقر والأدخال","تصحيح أخطاء سير العمل المعتمد على المتصفح باستخدام vibium CLI"]},"limitations":{"en":["Requires Chrome browser installation","CLI access needed","Daemon mode required for persistent browser sessions"],"zh":["需要安装Chrome浏览器","需要CLI访问","需要守护进程模式以实现持久的浏览器会话"],"ja":["Chromeブラウザのインストールが必要","CLIアクセスが必要","デーモン模式が必要であることによるブラウザセッションの永続化"],"ko":["Chrome 브라우저 설치가 필요합니다","CLI 액세스가 필요합니다","데몬 모드가 필요하여 브라우저 세션이 지속됩니다"],"es":["Requiere la instalación del navegador Chrome","Se necesita acceso a CLI","Se requiere el modo daemon para sesiones de navegador persistentes"],"fr":["Nécessite l''installation du navigateur Chrome","L''accès à CLI est nécessaire","Le mode daemon est requis pour les sessions de navigateur persistantes"],"de":["Benötigt die Installation des Chrome-Browsers","CLI-Zugriff erforderlich","Daemon-Modus erforderlich für persistente Browser-Sitzungen"],"pt":["Requer instalação do navegador Chrome","Acesso ao CLI necessário","Modo daemon necessário para sessões de navegador persistentes"],"ru":["Требуется установка браузера Chrome","Необходим доступ к CLI","Требуется режим демона для постоянных сессий браузера"],"ar":["يتطلب تثبيت متصفح Chrome","مطلوب الوصول إلى CLI","يتطلب وضع الدايمون لجلسات المتصفح المستمرة"]},"version":4},"contentHash":"ec10454cf8bcdd175887851144faaddcabe7476792c36e5b0d6543114e8d4b3f","qualityScore":42}');
