INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('bearbinary/Jarvy/agentic-jumpstart-architecture', 'agentic-jumpstart-architecture', 'bearbinary', 'Jarvy', 'community', 'agentic-jumpstart-architecture bearbinary Jarvy community The agentic-jumpstart-architecture skill provides comprehensive architecture guidance for the Jarvy CLI project, benefiting developers who need to provision development environments from a jarvy.toml config file. agentic-jumpstart-architecture提供了Jarvy CLI项目的综合架构指导，包括目录结构和配置文件 agentic-jumpstart-architectureは、Jarvy CLIプロジェクトの包括的なアーキテクチャガイダンスを提供し、ディレクトリ構造と設定ファイルを含む agentic-jumpstart-architecture는 Jarvy CLI 프로젝트에 대한 포괄적인 아키텍처 가이드를 제공하며, 디렉토리 구조와 설정 파일을 포함합니다 Agentic Jumpstart es una herramienta de línea de comandos que proporciona una arquitectura de referencia para provisionar entornos de desarrollo Agentic Jumpstart est un outil en ligne de commande qui fournit une architecture de référence pour provisionner des environnements de développement Agentic Jumpstart ist ein Kommandozeilen-Tool, das eine Referenzarchitektur für die Bereitstellung von Entwicklungsumgebungen bietet A arquitetura Agentic-Jumpstart fornece orientação abrangente para o projeto Jarvy CLI, provisionando ambientes de desenvolvimento. Архитектура Agentic-Jumpstart обеспечивает комплексное руководство для проекта Jarvy CLI, обеспечивающего среды разработки. توفير هندسة Agentic-Jumpstart إرشادات شاملة لمشروع Jarvy CLI ، لتوفير بيئات التطوير. how to use agentic-jumpstart-architecture what is agentic-jumpstart-architecture agentic-jumpstart-architecture alternative agentic-jumpstart-architecture vs Jarvy agentic-jumpstart-architecture install agentic-jumpstart-architecture setup guide Jarvy CLI project setup native package manager integration jarvy.toml config file AI开发工具 Jarvy CLI agentic-jumpstart-architecture 跨平台开发环境 native package managers 配置文件 CLI入口点 Provides comprehensive architecture guidance for the Jarvy CLI project Supports provisioning development environments from a jarvy.toml config file Utilizes native package managers such as Homebrew, apt/dnf, and winget Follows a specific directory structure for organization and maintainability Includes a CLI entry point using clap derive macros in main.rs Offers public re-exports for integration tests in lib.rs agentic-jumpstart-architecture is a skill that offers guidelines for the Jarvy CLI project, including directory structure and native package manager integration');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('farmanlab/ai_agent_orchestra/extracting-interactions', 'community', 'farmanlab', 'ai_agent_orchestra', 'farmanlab/ai_agent_orchestra', 'extracting-interactions', 0, 0, 42, '2026-03-08T01:57:15.585Z', '2026-03-08T02:11:55.748Z', 'ac8a70f435b75019dadea86d94129da1c07b42fdb4641d28eb48d3e40b941f0c', '{"id":"farmanlab/ai_agent_orchestra/extracting-interactions","name":"extracting-interactions","description":{"en":"The extracting-interactions skill extracts interaction specifications from Figma designs, benefiting developers and designers. It supports tasks like component state extraction and transition definition.","zh":"交互作用抽取是一种自动化 Figma 设计中的交互行为的技术，支持组件状态、过渡定义、触发器整理和屏幕过渡规范","ja":"extracting-interactions は Figma デザインからインタラクション仕様を抽出するスキルで、コンポーネント状態、トランジション定義、トリガー整理、画面遷移仕様をサポート","ko":"상호작용 추출은 피그마 디자인에서 상호작용 규격을 추출하는 기술로, 컴포넌트 상태, 전환 정의, 트리거 정리 및 화면 전환 사양을 지원","es":"La extracción de interacciones es una habilidad que permite extraer especificaciones de interacción de diseños Figma, incluyendo estados de componentes y transiciones","fr":"L''extraction d''interactions est une compétence qui permet d''extraire des spécifications d''interaction à partir de conceptions Figma, y compris les états de composants et les transitions","de":"Die Interaktionsextraktion ist eine Fähigkeit, die es ermöglicht, Interaktionsvorschriften aus Figma-Entwürfen zu extrahieren, einschließlich Komponentenzustände und Übergänge","pt":"O extrator de interações é uma habilidade que extrai especificações de interação de designs Figma, incluindo estados de componentes e transições.","ru":"Извлекатель взаимодействий - это навык, который извлекает спецификации взаимодействия из дизайна Figma, включая состояния компонентов и переходы.","ar":"مستخلص التفاعلات هو مهارة تقوم باستخراج مواصفات التفاعل من التصاميم Figma، بما في ذلك حالات المكونات وال