INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('farmanlab/ai_agent_orchestra/extracting-interactions', 'extracting-interactions', 'farmanlab', 'ai_agent_orchestra', 'community', 'extracting-interactions farmanlab ai_agent_orchestra community The extracting-interactions skill extracts interaction specifications from Figma designs, benefiting developers and designers. It supports tasks like component state extraction and transition definition. 交互作用抽取是一种自动化 Figma 设计中的交互行为的技术，支持组件状态、过渡定义、触发器整理和屏幕过渡规范 extracting-interactions は Figma デザインからインタラクション仕様を抽出するスキルで、コンポーネント状態、トランジション定義、トリガー整理、画面遷移仕様をサポート 상호작용 추출은 피그마 디자인에서 상호작용 규격을 추출하는 기술로, 컴포넌트 상태, 전환 정의, 트리거 정리 및 화면 전환 사양을 지원 La extracción de interacciones es una habilidad que permite extraer especificaciones de interacción de diseños Figma, incluyendo estados de componentes y transiciones L''extraction d''interactions est une compétence qui permet d''extraire des spécifications d''interaction à partir de conceptions Figma, y compris les états de composants et les transitions Die Interaktionsextraktion ist eine Fähigkeit, die es ermöglicht, Interaktionsvorschriften aus Figma-Entwürfen zu extrahieren, einschließlich Komponentenzustände und Übergänge O extrator de interações é uma habilidade que extrai especificações de interação de designs Figma, incluindo estados de componentes e transições. Извлекатель взаимодействий - это навык, который извлекает спецификации взаимодействия из дизайна Figma, включая состояния компонентов и переходы. مستخلص التفاعلات هو مهارة تقوم باستخراج مواصفات التفاعل من التصاميم Figma، بما في ذلك حالات المكونات والتحولات. how to use extracting-interactions extracting-interactions setup guide Figma design interaction extraction extracting-interactions alternative extracting-interactions vs Adobe XD extracting-interactions install what is extracting-interactions extracting-interactions tutorial interaction specification extraction AIエージェント Figma 设计自动化 交互作用抽取 组件状态抽取 过渡定义 触发器整理 屏幕过渡规范 Extracts component states, such as hover, active, disabled, and focused Defines transitions between states with animation specifications Organizes triggers and corresponding actions for user operations Specifies screen transition details, including navigation and animations Extracting-interactions is a skill that extracts interaction specifications, including hover states, transitions, and animations, from Figma designs.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Cyronlee/TransFlow/github-release', 'community', 'Cyronlee', 'TransFlow', 'Cyronlee/TransFlow', 'github-release', 0, 0, 42, '2026-03-08T01:57:15.588Z', '2026-03-08T02:11:58.639Z', '968edf87dd2a922cef2b6f62ab36d822f8138cec224a283e1e894086ecb4c4bd', '{"id":"Cyronlee/TransFlow/github-release","name":"github-release","description":{"en":"The github-release skill automates the process of publishing new TransFlow versions to GitHub Releases with DMG attachments, benefiting developers who need to manage their releases efficiently.","zh":"github-release是一个用于发布新版本到GitHub Releases的工具，支持DMG附件，需要gh CLI、create-dmg和Xcode Command Line Tools","ja":"github-releaseは、GitHub Releasesに新しいバージョンを公開するためのツールです。DMGアタッチメントをサポートし、gh CLI、create-dmg、Xcode Command Line Toolsが必要です","ko":"github-release는 GitHub Releases에 새로운 버전을 배포하는 도구로 DMG附件를 지원하며 gh CLI, create-dmg 및 Xcode Command Line Tools가 필요합니다","es":"github-release es una herramienta para publicar versiones de TransFlow en GitHub con attachments DMG. Requiere gh CLI y create-dmg","fr":"github-release est un outil pour publier des versions de TransFlow sur GitHub avec des attachments DMG. Il nécessite gh CLI et create-dmg","de":"github-release ist ein Tool zum Veröffentlichen von TransFlow-Versionen auf GitHub mit DMG-Anhängen. Es erfordert gh CLI und create-dmg","pt":"O github-release é uma ferramenta para publicar novas versões do TransFlow no GitHub com anexo DMG, utilizando o CLI gh e create-dmg.","ru":"github-release — это инструмент для публикации новых версий TransFlow на GitHub с вложением DMG, используя CLI gh и create-dmg.","ar":"github-release هو أداة لنشر إصدارات جديدة من TransFlow على GitHub مع مرفق DMG، باستخدام CLI gh و create-dmg."},"seo":{"title":{"en":"github-release: Automated GitHub Release Setup Guide | AI...","zh":"github-release Setup Guide - AI工具发布新版本","ja":