INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Dwamenachrist/DISAL-Tunnel-Refactored/3d-web-experience', '3d-web-experience', 'Dwamenachrist', 'DISAL-Tunnel-Refactored', 'community', '3d-web-experience Dwamenachrist DISAL-Tunnel-Refactored community The 3d-web-experience skill enables developers to create immersive web applications with optimized 3D visuals. It benefits developers and designers seeking to enhance user engagement with interactive 3D models and product configurators. 3D Web Experience是一种使用Three.js、React Three Fiber和WebGL优化来创建交互式3D场景的技术 3D Web Experienceは、Three.js、React Three Fiber、WebGL最適化を使用してインタラクティブな3Dシーンを作成する技術です 3D Web Experience는 Three.js, React Three Fiber 및 WebGL 최적화를 사용하여 인터랙티브한 3D 장면을 생성하는 기술입니다 El 3D Web Experience es una habilidad que permite crear experiencias web 3D accesibles y con gran impacto visual. Se utiliza Three.js y React Three Fiber para lograr esto. L''expérience Web 3D est une compétence qui permet de créer des expériences web 3D interactives et performantes. Elle utilise Three.js et React Three Fiber. Die 3D-Web-Erfahrung ist eine Fähigkeit, die es ermöglicht, zugängliche und visuell ansprechende 3D-Web-Erfahrungen zu schaffen. Sie verwendet Three.js und React Three Fiber. A 3D Web Experience é uma arquitetura que traz a terceira dimensão para a web, com foco em desempenho e acessibilidade. 3D Веб Опыт - это архитектура, которая приносит третью размерность в веб, с фокусом на производительности и доступности. تجربه الويب ثلاثية الأبعاد هي هندسة تحتوي على بعد ثالث للويب، مع التركيز على الأداء والوصول. how to use 3d-web-experience what is 3d-web-experience 3d-web-experience alternative 3d-web-experience vs a-frame 3d-web-experience install 3d-web-experience setup guide 3d web development tutorial three.js tutorial react three fiber documentation 3D Web Experience Three.js React Three Fiber WebGL优化 3D模型集成 AIエージェント 3D Web开发 交互式3D场景 3D产品配置器 Three.js implementation for 3D rendering React Three Fiber integration for efficient rendering WebGL optimization for improved performance 3D model integration for interactive experiences Spline workflows for streamlined development 3D product configurators for enhanced user engagement 3d-web-experience is a skill that enables the creation of immersive web applications with optimized 3D visuals, using technologies like Three.js, React Three Fiber, and WebGL.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('involvex/vscode-npm-package-manager/vscode-extension-dev', 'community', 'involvex', 'vscode-npm-package-manager', 'involvex/vscode-npm-package-manager', 'vscode-extension-dev', 0, 0, 42, '2026-03-08T01:57:15.608Z', '2026-03-08T02:13:10.374Z', 'd507eb365cec4c5735271a216c3c78b738d66503be339fe633dd4b0353b85e34', '{"id":"involvex/vscode-npm-package-manager/vscode-extension-dev","name":"vscode-extension-dev","description":{"en":"The vscode-extension-dev skill enables developers to create, enhance, and publish Visual Studio Code extensions, leveraging advanced Node.js package management and manifest configuration.","zh":"VS Code扩展开发专家技能，涵盖项目结构、manifest文件和激活事件等","ja":"VS Code拡張機能開発の専門家スキル。プロジェクト構造、マニフェストファイル、Activation Eventsなど","ko":"VS Code 확장 개발을 위한 전문가 스킬입니다. 프로젝트 구조, 매니페스트 파일, 활성화 이벤트 등","es":"Desarrolla extensiones de VS Code con nuestra guía experta, que cubre Node.js y gestión de paquetes con npm, yarn, pnpm y bun","fr":"Développez des extensions VS Code avec notre guide expert, qui couvre Node.js et la gestion de paquets avec npm, yarn, pnpm et bun","de":"Entwickeln Sie VS Code-Erweiterungen mit unserer Experten-Anleitung, die Node.js und Paketverwaltung mit npm, yarn, pnpm und bun abdeckt","pt":"Desenvolva extensões para VS Code com suporte a gerenciamento de pacotes Node.js avançado","ru":"Разрабатывайте расширения для VS Code с поддержкой продвинутого управления пакетами Node.js","ar":"طور إضافات لآلة الكتابة البصرية مع دعم إدارة حزم Node.js متقدمة"},"seo":{"title":{"en":"vscode-extension-dev: Advanced Extension Development Setu...","zh":"VS Code 扩展开发最佳实践 - AIエージェント","ja":"VS Code 拡張機能開発ガイド - AIエージェント","ko":"VS Code 확장 개발 설정 가이드 - AI 에이전트","es":"Guía de configuración para desarrolladores de extensiones...","fr":"Guide de mise en place pour les développeurs d''extensions...","de":"Einrichtungsleitfaden für VS Code-Erweiterungsentwickler","pt":"Guia de Configuração para Desenvolvedores de Extensões VS...","ru":"Руководство по настройке расширений VS Code для ИИ Агентов","ar":"دليل إعداد مطورو الإضافات لآلة الكتابة البصرية"},"description":{"en":"Unlock expert-level VS Code extension development with activationEvents and engines.vscode. Learn how to create and publish extensions with ease.","zh":"了解如何创建和发布VS Code扩展，包括项目结构、manifest文件和激活事件","ja":"VS Code拡張機能の作成と公開方法を学びます。プロジェクト構造、マニフェストファイル、Activation Eventsなど","ko":"VS Code 확장 개발을 위한 프로젝트 구조, 매니페스트 파일, 활성화 이벤트 등에 대한 정보","es":"Aprende a crear y publicar extensiones de VS Code con nuestro experto en desarrollo de extensiones de VS Code, incluyendo Node.js y gestión de paquetes","fr":"Découvrez comment créer et publier des extensions VS Code avec notre expert en développement d''extensions VS Code, y compris Node.js et gestion de paquets","de":"Erfahren Sie, wie Sie VS Code-Erweiterungen erstellen und veröffentlichen können, mit unserem Experten für VS Code-Erweiterungsentwicklung, einschließlich No...","pt":"Aprenda a criar e publicar extensões para VS Code com suporte a npm, yarn, pnpm e bun","ru":"Узнайте, как создавать и публиковать расширения для VS Code с поддержкой npm, yarn, pnpm и bun для ИИ Агентов","ar":"تعلم كيفية إنشاء ونشر الإضافات لآلة الكتابة البصرية مع دعم npm و yarn و pnpm و bun"},"definition":{"en":"vscode-extension-dev is a skill for expert Visual Studio Code extension development, covering project structure, manifest configuration, and extension lifecycle management.","zh":"VS Code扩展开发是指创建和发布可以增强VS Code功能的扩展","ja":"VS Code拡張機能開発とは、VS Codeの機能を拡張する拡張機能を作成・公開すること","ko":"VS Code 확장 개발은 VS Code의 기능을 확장할 수 있는 확장을 만들고 배포하는 것을 말합니다","es":"Un desarrollador de extensiones de VS Code es un experto en crear y publicar extensiones para Visual Studio Code","fr":"Un développeur d''extensions VS Code est un expert dans la création et la publication d''extensions pour Visual Studio Code","de":"Ein VS Code-Erweiterungsentwickler ist ein Experte für die Erstellung und Veröffentlichung von Erweiterungen für Visual Studio Code","pt":"Desenvolvedor de extensões VS Code é um especialista em criar e publicar extensões para o editor de código","ru":"Разработчик расширений VS Code - это специалист, создающий и публикующий расширения для редактора кода для ИИ Агентов","ar":"مطور الإضافات لآلة الكتابة البصرية هو خبير في إنشاء ونشر الإضافات لآلة الكتابة البصرية"},"features":{"en":["Configures project structure and manifest files (package.json) for VS Code extensions","Specifies minimum compatible VS Code version using engines.vscode","Defines activationEvents for triggering extension activation","Supports advanced Node.js package management with npm, yarn, pnpm, and bun","Guides users through the extension lifecycle, from creation to publication"],"zh":["支持npm、yarn、pnpm和bun的高级Node.js包管理","项目结构和manifest文件（package.json）","激活事件（activationEvents）","指定最低兼容VS Code版本（engines.vscode）"],"ja":["npm、yarn、pnpm、bunをサポートした高級Node.jsパッケージ管理","プロジェクト構造とマニフェストファイル（package.json）","Activation Events","最低互換VS Codeバージョンの指定（engines.vscode）"],"ko":["npm, yarn, pnpm, bun을 지원하는 고급 Node.js 패키지 관리","프로젝트 구조와 매니페스트 파일（package.json）","활성화 이벤트（activationEvents）","최저 호환 VS Code 버전 지정（engines.vscode）"],"es":["Soporte para Node.js y gestión de paquetes con npm, yarn, pnpm y bun","Configuración de la estructura de proyectos y archivos de manifiesto (`package.json`)","Especificación de la versión mínima compatible de VS Code con `engines.vscode`","Definición de eventos de activación con `activationEvents`","Creación y publicación de extensiones de VS Code","Gestión de dependencias y paquetes con npm, yarn, pnpm y bun"],"fr":["Prise en charge de Node.js et de la gestion de paquets avec npm, yarn, pnpm et bun","Configuration de la structure de projets et des fichiers de manifeste (`package.json`)","Spécification de la version minimale compatible de VS Code avec `engines.vscode`","Définition des événements d''activation avec `activationEvents`","Création et publication d''extensions VS Code","Gestion des dépendances et des paquets avec npm, yarn, pnpm et bun"],"de":["Unterstützung für Node.js und Paketverwaltung mit npm, yarn, pnpm und bun","Konfiguration der Projektstruktur und der Manifest-Datei (`package.json`)","Spezifikation der minimalen kompatiblen Version von VS Code mit `engines.vscode`","Definition von Aktivierungsereignissen mit `activationEvents`","Erstellung und Veröffentlichung von VS Code-Erweiterungen","Verwaltung von Abhängigkeiten und Paketen mit npm, yarn, pnpm und bun"],"pt":["Suporte a npm, yarn, pnpm e bun para gerenciamento de pacotes Node.js","Criação de estrutura de projeto e arquivo de manifesto (`package.json`)","Especificação de eventos de ativação (`activationEvents`)","Definição de versão mínima compatível do VS Code (`engines.vscode`)"],"ru":["Поддержка npm, yarn, pnpm и bun для управления пакетами Node.js","Создание структуры проекта и файла манифеста (`package.json`)","Указание событий активации (`activationEvents`)","Определение минимальной совместимой версии VS Code (`engines.vscode`)"],"ar":["دعم npm و yarn و pnpm و bun لإدارة حزم Node.js","إنشاء هيكل المشروع وملف الإعلان (`package.json`)","تحديد أحداث التنشيط (`activationEvents`)","تحديد الإصدار الأدنى المتوافق من VS Code (`engines.vscode`)"]},"keywords":{"en":["how to develop vscode extensions","vscode extension development tutorial","vscode-extension-dev alternative","vscode-extension-dev vs vscode extension manager","vscode-extension-dev setup guide","vscode-extension-dev install and configure","what is vscode-extension-dev","vscode-extension-dev documentation","vscode extension development best practices"],"zh":["VS Code扩展开发","AIエージェント","Node.js包管理","npm","yarn","pnpm","bun","项目结构","manifest文件"],"ja":["VS Code拡張機能開発","AIエージェント","Node.jsパッケージ管理","npm","yarn","pnpm","bun","プロジェクト構造","マニフェストファイル"],"ko":["VS Code 확장 개발","AI 에이전트","Node.js 패키지 관리","npm","yarn","pnpm","bun","프로젝트 구조","매니페스트 파일"],"es":["desarrollo de extensiones de VS Code","Node.js","gestión de paquetes","npm","yarn","pnpm","bun","VS Code","extensiones de VS Code","desarrollo de software","herramientas de desarrollo"],"fr":["développement d''extensions VS Code","Node.js","gestion de paquets","npm","yarn","pnpm","bun","VS Code","extensions VS Code","développement de logiciels","outils de développement"],"de":["Entwicklung von VS Code-Erweiterungen","Node.js","Paketverwaltung","npm","yarn","pnpm","bun","VS Code","VS Code-Erweiterungen","Softwareentwicklung","Entwicklungstools"],"pt":["desenvolvedor de extensões VS Code","gerenciamento de pacotes Node.js","criação de extensões VS Code","npm","yarn","pnpm","bun","VS Code"],"ru":["разработчик расширений VS Code","управление пакетами Node.js","создание расширений VS Code","npm","yarn","pnpm","bun","VS Code","ИИ Агенты"],"ar":["مطور الإضافات لآلة الكتابة البصرية","إدارة حزم Node.js","إنشاء إضافات لآلة الكتابة البصرية","npm","yarn","pnpm","bun","آلة الكتابة البصرية"]}},"owner":"involvex","repo":"vscode-npm-package-manager","repoPath":"involvex/vscode-npm-package-manager","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.608Z","topics":[],"category":"community","skillMd":{"name":"vscode-extension-dev","description":"Expert guidance for developing, testing, and publishing Visual Studio Code extensions. Use when building or modifying VS Code extensions.","bodyPreview":"# VS Code Extension Developer Skill\n\nYou are an expert in Visual Studio Code extension development. Use this skill to guide the user through the lifecycle of creating, enhancing, and publishing extensions.\n\n## 1. Project Structure & Manifest (`package.json`)\n\nThe `package.json` is the manifest file and is crucial for VS Code extensions.\n\n- **`engines.vscode`**: Specifies the minimum compatible version of VS Code.\n- **`activationEvents`**: Array of events that trigger your extension''s activation","body":"# VS Code Extension Developer Skill\n\nYou are an expert in Visual Studio Code extension development. Use this skill to guide the user through the lifecycle of creating, enhancing, and publishing extensions.\n\n## 1. Project Structure & Manifest (`package.json`)\n\nThe `package.json` is the manifest file and is crucial for VS Code extensions.\n\n- **`engines.vscode`**: Specifies the minimum compatible version of VS Code.\n- **`activationEvents`**: Array of events that trigger your extension''s activation (e.g., `onCommand:id`, `onLanguage:id`, `workspaceContains:**\\/package.json`, or `*`). _Note: VS Code 1.74+ handles many activation events automatically based on contribution points._\n- **`contributes`**: The core configuration for UI elements and capabilities.\n  - `commands`: Register commands visible in the Command Palette.\n  - `menus`: Add commands to menus (e.g., `editor/context`, `view/title`).\n  - `viewsContainers`: Add custom sidebars/activity bars.\n  - `views`: Add tree views to containers.\n  - `configuration`: Define user settings.\n  - `keybindings`: Bind commands to keyboard shortcuts.\n- **`main`**: The entry point file (e.g., `./out/extension.js`).\n\n## 2. Development Workflow\n\n- **Setup**: Ensure `vscode` module is installed (`npm install vscode`). _Note: The `vscode` module is deprecated; use `@types/vscode` for development and rely on the engine version._\n- **Running**: Press `F5` in VS Code to launch the **Extension Development Host**. This opens a new window with your extension loaded.\n- **Reloading**: Use `Ctrl+R` (or `Cmd+R` on Mac) in the Extension Development Host to reload changes.\n- **Debugging**: Set breakpoints in your source code. Use the Debug Console to inspect variables.\n\n## 3. The `vscode` API\n\n- **`vscode.commands`**: `registerCommand` to bind logic to command IDs.\n- **`vscode.window`**:\n  - `showInformationMessage`, `showErrorMessage` for notifications.\n  - `createStatusBarItem` for status bar entries.\n  - `createTreeView` for custom views.\n  - `activeTextEditor` for the current editor.\n- **`vscode.workspace`**:\n  - `getConfiguration` for settings.\n  - `workspaceFolders` for open folders.\n  - `fs` for file system operations (use this over Node''s `fs` when possible for remote support).\n- **`vscode.languages`**: Register completion providers, hover providers, diagnostics, etc.\n\n## 4. Best Practices\n\n- **Lazy Activation**: Only activate your extension when necessary. Avoid using `*` activation unless absolutely required.\n- **Disposables**: Always push created resources (commands, listeners) to `context.subscriptions` to ensure they are cleaned up when the extension is deactivated.\n  ```typescript\n  context.subscriptions.push(disposable);\n  ```\n- **Webviews**: Use strict Content Security Policy (CSP). Use `asWebviewUri` to load local resources.\n- **Performance**: Do not block the main thread. Use `async/await` for I/O and heavy operations.\n\n## 5. Testing\n\n- Use `@vscode/test-electron` or `@vscode/test-cli` for integration tests.\n- Tests run inside a special instance of VS Code.\n\n## 6. Packaging and Publishing\n\n- **Tool**: `vsce` (Visual Studio Code Extensions CLI).\n- **Install**: `npm install -g @vscode/vsce`.\n- **Package**: `vsce package` creates a `.vsix` file.\n- **Publish**: `vsce publish` uploads to the Marketplace (requires a Personal Access Token).\n- **Files**: Ensure `.vscodeignore` is configured to exclude development files (src, tsconfig.json, etc.) from the package.\n\n## 7. Common Tasks\n\n### Registering a Command\n\n```typescript\nimport * as vscode from \"vscode\";\n\nexport function activate(context: vscode.ExtensionContext) {\n  let disposable = vscode.commands.registerCommand(\n    \"myExtension.helloWorld\",\n    () => {\n      vscode.window.showInformationMessage(\"Hello World!\");\n    },\n  );\n\n  context.subscriptions.push(disposable);\n}\n```\n\n### Tree View Provider\n\nImplement `vscode.TreeDataProvider<T>`.\n\n- `getTreeItem(element: T): vscode.TreeItem`\n- `getChildren(element?: T): ProviderResult<T[]>`\n\n### Configuration\n\nAccess settings defined in `package.json`:\n\n```typescript\nconst config = vscode.workspace.getConfiguration(\"myExtension\");\nconst value = config.get(\"mySetting\");\n```\n"},"lastSynced":"2026-03-08T02:13:10.374Z","agentAnalysis":{"suitability":{"en":"Perfect for Developer Agents needing advanced Visual Studio Code extension creation capabilities.","zh":"非常适合需要高级Visual Studio Code扩展创建功能的开发者代理。","ja":"Visual Studio Code拡張機能の高度な作成機能を必要とする開発者エージェントに最適です。","ko":"고급 Visual Studio Code 확장 기능 생성 기능이 필요한 개발자 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Desarrollador que necesitan capacidades avanzadas de creación de extensiones de Visual Studio Code.","fr":"Parfait pour les agents de développement nécessitant des capacités avancées de création d''extensions Visual Studio Code.","de":"Perfekt für Developer-Agents, die erweiterte Visual Studio Code-Erweiterungsfunktionen benötigen.","pt":"Perfeito para Agentes de Desenvolvedor que necessitam de capacidades avançadas de criação de extensões do Visual Studio Code.","ru":"Идеально для агентов разработчиков, которые нуждаются в расширенных возможностях создания расширений для Visual Studio Code.","ar":"مثالي لعمليات وكيل المطور التي تحتاج إلى إمكانات متقدمة لإنشاء امتدادات Visual Studio Code."},"recommendation":{"en":"Empowers agents to create, enhance, and publish VS Code extensions, leveraging advanced Node.js package management and manifest configuration through `package.json` files, specifying `engines.vscode` and `activationEvents`.","zh":"赋予代理创建、增强和发布VS Code扩展的能力，利用高级Node.js包管理和通过`package.json`文件指定`engines.vscode`和`activationEvents`的清单配置。","ja":"エージェントがVS Code拡張機能を作成、強化、および公開する能力を付与し、高度なNode.jsパッケージ管理と`package.json`ファイルを介した`engines.vscode`および`activationEvents`のマニフェスト構成を利用します。","ko":"에이전트가 VS Code 확장 기능을 생성, 강화 및 게시할 수 있는 기능을 부여하며, 고급 Node.js 패키지 관리와 `package.json` 파일을 통해 `engines.vscode` 및 `activationEvents`를 지정하는 매니페스트 구성도 활용합니다.","es":"Habilita a los agentes a crear, mejorar y publicar extensiones de VS Code, aprovechando la gestión avanzada de paquetes Node.js y la configuración de manifiestos a través de archivos `package.json`, especificando `engines.vscode` y `activationEvents`.","fr":"Permet aux agents de créer, d''améliorer et de publier des extensions VS Code, en exploitant la gestion avancée des packages Node.js et la configuration des manifestes via des fichiers `package.json`, en spécifiant `engines.vscode` et `activationEvents`.","de":"Ermöglicht es Agenten, VS Code-Erweiterungen zu erstellen, zu verbessern und zu veröffentlichen, indem sie erweiterte Node.js-Paketverwaltung und Manifestkonfiguration über `package.json`-Dateien nutzen, wobei `engines.vscode` und `activationEvents` angegeben werden.","pt":"Habilita os agentes a criar, aprimorar e publicar extensões do VS Code, aproveitando a gestão avançada de pacotes Node.js e a configuração de manifesto por meio de arquivos `package.json`, especificando `engines.vscode` e `activationEvents`.","ru":"Позволяет агентам создавать, улучшать и публиковать расширения VS Code, используя расширенное управление пакетами Node.js и конфигурацию манифеста через файлы `package.json`, указывая `engines.vscode` и `activationEvents`.","ar":"تمكّن الوكلاء من إنشاء وتحسين ونشر امتدادات VS Code، مستفيدةً من إدارة الحزم Node.js المتقدمة وتكوين البيان من خلال ملفات `package.json`، مع تحديد `engines.vscode` و `activationEvents`."},"useCases":{"en":["Creating custom extensions for specific development workflows","Enhancing existing extensions with new features and functionalities","Publishing extensions to the VS Code marketplace for public use"],"zh":["为特定开发工作流程创建自定义扩展","使用新功能和功能增强现有扩展","将扩展发布到VS Code市场以供公开使用"],"ja":["特定の開発ワークフロー用のカスタム拡張機能を作成する","新しい機能と機能を使用して既存の拡張機能を強化する","拡張機能をVS Codeマーケットプレイスに公開する"],"ko":["특정 개발 워크플로우를 위한 사용자 정의 확장 기능을 생성하는 것","새로운 기능 및 기능을 사용하여 기존 확장 기능을 강화하는 것","확장 기능을 VS Code 마켓플레이스에 공개하여 사용하는 것"],"es":["Creación de extensiones personalizadas para flujos de trabajo de desarrollo específicos","Mejora de extensiones existentes con nuevas características y funcionalidades","Publicación de extensiones en el mercado de VS Code para su uso público"],"fr":["Création d''extensions personnalisées pour des flux de travail de développement spécifiques","Amélioration d''extensions existantes avec de nouvelles fonctionnalités et caractéristiques","Publication d''extensions sur le marché VS Code pour une utilisation publique"],"de":["Erstellung von benutzerdefinierten Erweiterungen für spezifische Entwicklungsworkflows","Verbesserung bestehender Erweiterungen mit neuen Funktionen und Funktionalitäten","Veröffentlichung von Erweiterungen auf dem VS Code-Marktplatz für den öffentlichen Gebrauch"],"pt":["Criar extensões personalizadas para fluxos de trabalho de desenvolvimento específicos","Aprimorar extensões existentes com novos recursos e funcionalidades","Publicar extensões no mercado VS Code para uso público"],"ru":["Создание пользовательских расширений для конкретных рабочих процессов разработки","Улучшение существующих расширений с новыми функциями и возможностями","Публикация расширений на рынке VS Code для общего использования"],"ar":["إنشاء امتدادات مخصصة لتدفقات العمل التطويرية المحددة","تحسين الامتدادات الحالية مع ميزات ووظائف جديدة","نشر الامتدادات في سوق VS Code للاستخدام العام"]},"limitations":{"en":["Requires Node.js knowledge and VS Code extension development experience","Limited to VS Code extensions only"],"zh":["需要Node.js知识和VS Code扩展开发经验","仅限于VS Code扩展"],"ja":["Node.jsの知識とVS Code拡張機能の開発経験が必要","VS Code拡張機能のみに限定される"],"ko":["Node.js 지식과 VS Code 확장 기능 개발 경험이 필요함","VS Code 확장 기능만으로 제한됨"],"es":["Requiere conocimientos de Node.js y experiencia en desarrollo de extensiones de VS Code","Limitado solo a extensiones de VS Code"],"fr":["Nécessite des connaissances en Node.js et une expérience dans le développement d''extensions VS Code","Limité aux extensions VS Code uniquement"],"de":["Benötigt Node.js-Kenntnisse und Erfahrung in der Entwicklung von VS Code-Erweiterungen","Begrenzt auf VS Code-Erweiterungen nur"],"pt":["Exige conhecimento de Node.js e experiência no desenvolvimento de extensões do VS Code","Limitado a extensões do VS Code apenas"],"ru":["Требует знания Node.js и опыта разработки расширений VS Code","Ограничен только расширениями VS Code"],"ar":["يتطلب معرفة Node.js وخبرة في تطوير امتدادات VS Code","محدود بامتدادات VS Code فقط"]},"version":4},"contentHash":"d507eb365cec4c5735271a216c3c78b738d66503be339fe633dd4b0353b85e34","qualityScore":42}');
