INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('involvex/vscode-npm-package-manager/vscode-extension-dev', 'vscode-extension-dev', 'involvex', 'vscode-npm-package-manager', 'community', 'vscode-extension-dev involvex vscode-npm-package-manager community The vscode-extension-dev skill enables developers to create, enhance, and publish Visual Studio Code extensions, leveraging advanced Node.js package management and manifest configuration. VS Code扩展开发专家技能，涵盖项目结构、manifest文件和激活事件等 VS Code拡張機能開発の専門家スキル。プロジェクト構造、マニフェストファイル、Activation Eventsなど VS Code 확장 개발을 위한 전문가 스킬입니다. 프로젝트 구조, 매니페스트 파일, 활성화 이벤트 등 Desarrolla extensiones de VS Code con nuestra guía experta, que cubre Node.js y gestión de paquetes con npm, yarn, pnpm y bun Développez des extensions VS Code avec notre guide expert, qui couvre Node.js et la gestion de paquets avec npm, yarn, pnpm et bun Entwickeln Sie VS Code-Erweiterungen mit unserer Experten-Anleitung, die Node.js und Paketverwaltung mit npm, yarn, pnpm und bun abdeckt Desenvolva extensões para VS Code com suporte a gerenciamento de pacotes Node.js avançado Разрабатывайте расширения для VS Code с поддержкой продвинутого управления пакетами Node.js طور إضافات لآلة الكتابة البصرية مع دعم إدارة حزم Node.js متقدمة how to develop vscode extensions vscode extension development tutorial vscode-extension-dev alternative vscode-extension-dev vs vscode extension manager vscode-extension-dev setup guide vscode-extension-dev install and configure what is vscode-extension-dev vscode-extension-dev documentation vscode extension development best practices VS Code扩展开发 AIエージェント Node.js包管理 npm yarn pnpm bun 项目结构 manifest文件 Configures project structure and manifest files (package.json) for VS Code extensions Specifies minimum compatible VS Code version using engines.vscode Defines activationEvents for triggering extension activation Supports advanced Node.js package management with npm, yarn, pnpm, and bun Guides users through the extension lifecycle, from creation to publication vscode-extension-dev is a skill for expert Visual Studio Code extension development, covering project structure, manifest configuration, and extension lifecycle management.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('australia/mobtranslate.com/visual-audit', 'community', 'australia', 'mobtranslate.com', 'australia/mobtranslate.com', 'visual-audit', 0, 0, 42, '2026-03-08T01:57:15.616Z', '2026-03-08T02:13:22.443Z', 'b5a9d1bba559c73410b9e46b0fb5ea64573d62370aa2503390bd438a2b0c0f1b', '{"id":"australia/mobtranslate.com/visual-audit","name":"visual-audit","description":{"en":"The visual-audit skill enables senior design engineers to conduct a meticulous visual audit of web applications, envisioning and implementing optimal design solutions. It benefits developers seeking to enhance their application''s visual design","zh":"Visual Audit技能帮助开发人员进行网页应用的视觉设计审计，确保设计的一致性和质量","ja":"Visual Auditスキルは、開発者がWebアプリケーションのビジュアルデザインを監査し、デザインのの一貫性と品質を確保するのに役立ちます","ko":"Visual Audit 스킬은 개발자가 웹 애플리케이션의 시각적 디자인을 감사하여 디자인의 일관성과 품질을 보장하는 데 도움이 됩니다","es":"Visual-audit es una herramienta para auditar el diseño visual de aplicaciones web, utilizando tecnologías como pnpm y agent-browser","fr":"Visual-audit est un outil pour auditer la conception visuelle des applications web, utilisant des technologies comme pnpm et agent-browser","de":"Visual-audit ist ein Tool zur Überprüfung der visuellen Gestaltung von Webanwendungen, das Technologien wie pnpm und agent-browser verwendet","pt":"O visual-audit é uma ferramenta de auditoria visual que ajuda a melhorar a experiência do usuário","ru":"ИИ Агент visual-audit - это инструмент визуального аудита, который помогает улучшить пользовательский опыт","ar":"visual-audit هي أداة تدقيق بصرية تساعد على تحسين تجربة المستخدم"},"seo":{"title":{"en":"visual-audit: Comprehensive Visual Design Audit Setup Gui...","zh":"视觉审计设置指南 - Visual Audit","ja":"ビジュアル監査設定ガイド - Visual Audit","ko":"시각적 감사 설정 가이드 - Visual Audit","es":"Guía de configuración para visual-audit: Auditoría de dis...","fr":"Guide de configuration pour visual-audit: Audit de concep...","de":"Konfigurationsleitfaden für visual-audit: Visuelle Design...","pt":"Guia de Configuração do visual-audit: Ferramentas de Audi...","ru":"Настройка ИИ Агента visual-audit: Руководство по визуальн...","ar":"دليل إعداد visual-audit: أدوات تدقيق بصرية"},"description":{"en":"Discover how to perform a thorough visual design audit with the visual-audit skill. Learn how to setup and utilize this AI agent to elevate your web applicat...","zh":"使用Visual Audit技能，高效地进行网页应用的视觉设计审计，确保最佳的用户体验","ja":"Visual Auditスキルを使用して、Webアプリケーションのビジュアルデザインを徹底的に監査し、最高のユーザーエクスペリエンスを実現する","ko":"Visual Audit 스킬을 사용하여 웹 애플리케이션의 시각적 디자인을 철저하게 감사하여 최고의 사용자 경험을 구현합니다","es":"Aprende a configurar y utilizar visual-audit para auditar el diseño visual de aplicaciones web con herramientas como pnpm y agent-browser","fr":"Découvrez comment configurer et utiliser visual-audit pour auditer la conception visuelle des applications web avec des outils comme pnpm et agent-browser","de":"Erfahren Sie, wie Sie visual-audit konfigurieren und verwenden, um die visuelle Gestaltung von Webanwendungen mit Tools wie pnpm und agent-browser zu überprüfen","pt":"Aprenda a configurar o visual-audit para melhorar a experiência do usuário com nossa ferramenta de auditoria visual","ru":"Узнайте, как настроить ИИ Агент visual-audit для улучшения пользовательского опыта с помощью нашего руководства","ar":"تعرف على كيفية إعداد visual-audit لتحسين تجربة المستخدم مع أداتنا لتدقيق بصرية"},"definition":{"en":"visual-audit is a comprehensive visual design audit skill that enables design engineers to meticulously review and improve web application design","zh":"视觉审计是一种使用AIエージェント对网页应用的视觉设计进行检查和优化的过程","ja":"ビジュアル監査は、Webアプリケーションのビジュアルデザインをチェックして最適化するためにAIエージェントを使用するプロセスです","ko":"시각적 감사는 웹 애플리케이션의 시각적 디자인을 확인하고 최적화하기 위해 AI 에이전트를 사용하는 프로세스입니다","es":"Visual-audit es una herramienta de auditoría de diseño visual que utiliza tecnologías como pnpm y agent-browser","fr":"Visual-audit est un outil d''audit de conception visuelle qui utilise des technologies comme pnpm et agent-browser","de":"Visual-audit ist ein Tool zur visuellen Design-Audit, das Technologien wie pnpm und agent-browser verwendet","pt":"O que é visual-audit? É uma ferramenta de auditoria visual que verifica a consistência do design","ru":"Что такое ИИ Агент visual-audit? Это инструмент визуального аудита, который проверяет последовательность дизайна","ar":"ما هي visual-audit؟ هي أداة تدقيق بصرية تتحقق من συνέافة التصميم"},"features":{"en":["Ensures dev server is running via pnpm dev or curl commands","Launches agent-browser to inspect web application design","Creates screenshot output directory for design audit purposes","Utilizes HTTP protocol to verify server status","Supports local development via localhost:3000"],"zh":["使用pnpm dev启动开发服务器","通过agent-browser open URL启动代理浏览器","创建屏幕截图输出目录","支持curl命令行工具","确保设计的一致性和质量"],"ja":["pnpm devで開発サーバーを起動する","agent-browser open URLでプロキシブラウザを起動する","スクリーンショット出力ディレクトリを作成する","curlコマンドラインツールをサポートする","デザインの一貫性と品質を確保する"],"ko":["pnpm dev를 사용하여 개발 서버를 시작합니다","agent-browser open URL을 사용하여 프록시 브라우저를 시작합니다","스크린샷 출력 디렉토리를 생성합니다","curl 명령줄 도구를 지원합니다","디자인의 일관성과 품질을 보장합니다"],"es":["Utiliza pnpm para ejecutar el servidor de desarrollo","Lanzar agent-browser para abrir la URL de la aplicación","Crea un directorio de salida para las capturas de pantalla","Realiza auditorías visuales de aplicaciones web","Utiliza tecnologías como curl para verificar el estado de la aplicación"],"fr":["Utilise pnpm pour exécuter le serveur de développement","Lance agent-browser pour ouvrir l''URL de l''application","Crée un répertoire de sortie pour les captures d''écran","Effectue des audits visuels d''applications web","Utilise des technologies comme curl pour vérifier l''état de l''application"],"de":["Verwendet pnpm, um den Entwicklungsserver auszuführen","Startet agent-browser, um die URL der Anwendung zu öffnen","Erstellt ein Ausgabeverzeichnis für Screenshots","Führt visuelle Audits von Webanwendungen durch","Verwendet Technologien wie curl, um den Status der Anwendung zu überprüfen"],"pt":["Execução do servidor de desenvolvimento com pnpm dev","Abertura do navegador do agente com agent-browser open","Criação de diretório de saída de capturas de tela","Verificação da consistência do design","Análise de bugs e melhorias de design"],"ru":["Запуск сервера разработки с помощью pnpm dev","Открытие браузера агента с помощью agent-browser open","Создание директории для вывода скриншотов","Проверка последовательности дизайна","Анализ ошибок и улучшений дизайна"],"ar":["تشغيل خادم التطوير مع pnpm dev","فتح متصفح العميل مع agent-browser open","إنشاء دليل لإخراج لقطات الشاشة","التحقق من συνέافة التصميم","تحليل الأخطاء وتحسينات التصميم"]},"keywords":{"en":["how to use visual-audit","visual-audit setup guide","visual design audit tools","visual-audit vs design audit software","visual-audit install","what is visual-audit","visual-audit alternative","visual-audit for web development","visual design audit best practices"],"zh":["视觉审计","AIエージェント","网页应用设计","用户体验","开发服务器","代理浏览器","スクリーンショット","curl命令行工具"],"ja":["ビジュアル監査","AIエージェント","Webアプリケーションデザイン","ユーザーエクスペリエンス","開発サーバー","プロキシブラウザ","スクリーンショット","curlコマンドラインツール"],"ko":["시각적 감사","AI 에이전트","웹 애플리케이션 디자인","사용자 경험","개발 서버","프록시 브라우저","스크린샷","curl 명령줄 도구"],"es":["visual-audit","auditoría de diseño visual","herramientas de desarrollo web","pnpm","agent-browser","diseño de aplicaciones web","auditoría de aplicaciones web","desarrollo de software","herramientas de desarrollo"],"fr":["visual-audit","audit de conception visuelle","outils de développement web","pnpm","agent-browser","conception d''applications web","audit d''applications web","développement de logiciels","outils de développement"],"de":["visual-audit","visuelle Design-Audit","Webentwicklungstools","pnpm","agent-browser","Webanwendungsdesign","Webanwendungs-Audit","Softwareentwicklung","Entwicklungstools"],"pt":["visual-audit","ferramentas de auditoria visual","design de interface do usuário","pnpm dev","agent-browser","capturas de tela","consistência do design"],"ru":["ИИ Агент visual-audit","инструменты визуального аудита","дизайн интерфейса пользователя","pnpm dev","agent-browser","скриншоты","последовательность дизайна"],"ar":["visual-audit","أدوات تدقيق بصرية","تصميم واجهة المستخدم","pnpm dev","agent-browser","لقطات الشاشة","سنعة التصميم"]}},"owner":"australia","repo":"mobtranslate.com","repoPath":"australia/mobtranslate.com","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.616Z","topics":[],"category":"community","skillMd":{"name":"visual-audit","description":"Comprehensive visual design audit using agent-browser. Takes screenshots of every page across desktop/mobile viewports and light/dark modes, analyzes design quality, identifies issues, and proposes creative improvements. Use when reviewing design, checking dark mode, or auditing UI quality.","bodyPreview":"# Visual Design Audit\n\nYou are a senior design engineer performing a comprehensive visual audit of a web application. You are meticulous, creative, and opinionated about good design. You don''t just find bugs - you envision how things *should* look and make it happen.\n\n## Setup\n\n1. Ensure the dev server is running (`pnpm dev` or check `curl -s -o /dev/null -w \"%{http_code}\" http://localhost:3000`)\n2. Launch agent-browser: `agent-browser open <url>`\n3. Create screenshot output directory:\n   ```","body":"# Visual Design Audit\n\nYou are a senior design engineer performing a comprehensive visual audit of a web application. You are meticulous, creative, and opinionated about good design. You don''t just find bugs - you envision how things *should* look and make it happen.\n\n## Setup\n\n1. Ensure the dev server is running (`pnpm dev` or check `curl -s -o /dev/null -w \"%{http_code}\" http://localhost:3000`)\n2. Launch agent-browser: `agent-browser open <url>`\n3. Create screenshot output directory:\n   ```\n   mkdir -p /tmp/visual-audit/{desktop-light,desktop-dark,mobile-light,mobile-dark,components,interactions}\n   ```\n\n## Audit Process\n\n### Phase 1: Discovery\n\nDiscover all routes in the application:\n\n- Read `apps/web/app/**/page.tsx` to find all routes\n- Check navigation components for link lists\n- Check for dynamic routes (e.g., `/dictionaries/[language]`)\n- Build a complete route manifest\n\n### Phase 2: Screenshot Matrix\n\nCapture every page across **4 viewport/mode combinations**:\n\n| Combo | Viewport | Media |\n|-------|----------|-------|\n| Desktop Light | `agent-browser set viewport 1440 900` | `agent-browser set media light` |\n| Desktop Dark | `agent-browser set viewport 1440 900` | `agent-browser set media dark` |\n| Mobile Light | `agent-browser set viewport 390 844` | `agent-browser set media light` |\n| Mobile Dark | `agent-browser set viewport 390 844` | `agent-browser set media dark` |\n\nFor each combination, capture full-page screenshots:\n```bash\nagent-browser open <url>\nsleep 1\nagent-browser screenshot /tmp/visual-audit/<combo>/<NN>-<page-name>.png\n```\n\nUse `agent-browser screenshot --full-page` for long pages when available.\n\n### Phase 3: Visual Review\n\nReview EVERY screenshot using the Read tool. For each screenshot, evaluate:\n\n**Layout & Spacing**\n- Consistent padding/margins\n- Proper content width constraints (watch for Tailwind v4 `max-w-*` mapping to breakpoints instead of container sizes)\n- Grid alignment and responsiveness\n- No horizontal overflow on mobile\n\n**Typography**\n- Heading hierarchy makes sense\n- Body text is readable (size, line-height, contrast)\n- Font weights are consistent\n- No orphaned words or awkward line breaks\n\n**Color & Theming**\n- Dark mode actually works (not just light mode with dark background)\n- Sufficient contrast ratios (WCAG AA minimum)\n- Consistent use of design tokens (not hardcoded colors)\n- Interactive states visible (hover, focus, active)\n\n**Components**\n- Cards have consistent styling\n- Buttons use the design system properly\n- Forms are properly sized (auth forms ~450px max, not stretching to breakpoint widths)\n- Badges/tags are readable and appropriately sized\n- Empty states are handled gracefully\n\n**Navigation**\n- Header looks good on all viewports\n- Mobile menu works\n- Footer is consistent\n- Breadcrumbs render properly\n\n**Interactions** (test these too)\n- Click through navigation links\n- Test form inputs\n- Try search functionality\n- Check hover states with `agent-browser hover`\n\n### Phase 4: Issue Tracking\n\nDocument every issue found in a structured format:\n\n```\nISSUE: [Brief description]\nSEVERITY: critical | major | minor | nitpick\nPAGE: [route]\nVIEWPORT: desktop | mobile | both\nMODE: light | dark | both\nSCREENSHOT: [path]\nFIX: [Proposed solution]\n```\n\n### Phase 5: Creative Redesign\n\nDon''t just fix bugs. Be imaginative:\n\n- If a page looks boring, propose a more engaging layout\n- If components are inconsistent, design a unified approach\n- If dark mode is an afterthought, make it a first-class experience\n- If mobile feels cramped, rethink the information hierarchy\n- If animations are missing, suggest tasteful motion\n- If empty states are bare, design helpful ones\n\nWhen proposing changes:\n1. Read the existing component code\n2. Check the `@mobtranslate/ui` package for available components\n3. Create new components in `packages/ui/src/components/` if needed\n4. Use existing design tokens from `packages/ui/src/tokens/tokens.css`\n\n### Phase 6: Implementation\n\nFix everything you find:\n\n1. Start with critical issues (broken layouts, unreadable text)\n2. Then major issues (inconsistent spacing, wrong max-widths)\n3. Then improvements (better empty states, micro-interactions)\n4. Create new UI components where the design system has gaps\n\nAfter each fix, re-screenshot to verify.\n\n## Important Notes\n\n### Tailwind v4 Gotcha\nIn Tailwind v4, `max-w-sm`, `max-w-md`, `max-w-lg` etc. map to `--container-*` CSS variables which are **breakpoint values** (640px, 768px, 1024px), NOT the old Tailwind v3 container sizes (384px, 448px, 512px). Use explicit values like `max-w-[28rem]` when you need the old behavior.\n\n### agent-browser Quick Reference\n```bash\nagent-browser open <url>          # Navigate\nagent-browser screenshot [path]   # Capture\nagent-browser set viewport W H    # Resize\nagent-browser set media dark      # Dark mode\nagent-browser set media light     # Light mode\nagent-browser click @ref          # Click element\nagent-browser hover @ref          # Hover element\nagent-browser snapshot            # Get accessibility tree with refs\nagent-browser eval <js>           # Run JavaScript\nagent-browser scroll down 500     # Scroll\nagent-browser close               # Close browser\n```\n\n### Dark Mode Testing\nThe app uses `.dark` class on `<html>` toggled via JS. `agent-browser set media dark` sets `prefers-color-scheme` which works via CSS `@media` fallback. For thorough testing:\n1. Test with `set media dark` (CSS media query path)\n2. Also test by clicking the toggle button (JS class path)\n3. Verify both paths produce the same result\n\n## Target URL\n\n$ARGUMENTS\n\nIf no URL provided, default to `http://localhost:3000` and audit all pages.\n"},"lastSynced":"2026-03-08T02:13:22.443Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing meticulous visual design analysis and optimization capabilities.","zh":"非常适合需要精确的视觉设计分析和优化能力的前端代理。","ja":"フロントエンドエージェントが正確な視覚デザイン分析と最適化機能を必要とする場合に最適です。","ko":"정확한 시각적 디자인 분석 및 최적화 기능이 필요한 프론트엔드 에이전트에 적합합니다.","es":"Perfecto para Agentes Frontend que necesitan un análisis y capacidades de optimización de diseño visual meticulosos.","fr":"Parfait pour les agents Frontend ayant besoin d''une analyse et de capacités d''optimisation de conception visuelle méticuleuses.","de":"Perfekt für Frontend-Agents, die eine sorgfältige visuelle Gestaltungsanalyse und Optimierungsfähigkeiten benötigen.","pt":"Perfeito para Agentes Frontend que necessitam de análise e capacidades de otimização de design visual meticulosas.","ru":"Идеально для агентов Frontend, которым необходимы тщательный анализ и возможности оптимизации визуального дизайна.","ar":"مثالي لعميل الواجهة الأمامية الذي يحتاج إلى تحليل وظيفة التصميم المرئي الدقيق والقدرات الامتيازية."},"recommendation":{"en":"Empowers agents to conduct comprehensive visual audits of web applications, utilizing protocols like HTTP and tools like `curl`, to envision and implement optimal design solutions, including screenshot analysis and dev server interactions.","zh":"赋予代理进行全面视觉审计的网页应用的能力，利用像HTTP这样的协议和像`curl`这样的工具，设想并实施最佳设计解决方案，包括截图分析和开发服务器交互。","ja":"HTTPなどのプロトコルや`curl`などのツールを使用して、ウェブアプリケーションの包括的な視覚的監査を実行するエージェントを可能にし、最適な設計ソリューションを設計して実装する、スクリーンショット分析や開発サーバーのやりとりなどを含む。","ko":"HTTP와 같은 프로토콜 및 `curl`와 같은 도구를 사용하여 웹 애플리케이션의 포괄적인 시각적 감사 수행을 가능하게 하는 에이전트를 권장하며, 최적의 디자인 솔루션을 설계하고 구현하도록 하며, 스크린샷 분석 및 개발 서버 상호 작용과 같은 기능을 포함합니다.","es":"Habilita a los agentes a realizar auditorías visuales integrales de aplicaciones web, utilizando protocolos como HTTP y herramientas como `curl`, para concebir e implementar soluciones de diseño óptimas, incluyendo análisis de capturas de pantalla y interacciones con el servidor de desarrollo.","fr":"Permet aux agents de réaliser des audits visuels complets d''applications web, en utilisant des protocoles comme HTTP et des outils comme `curl`, pour concevoir et mettre en œuvre des solutions de conception optimales, y compris l''analyse de captures d''écran et les interactions avec le serveur de développement.","de":"Ermöglicht es den Agenten, umfassende visuelle Audits von Webanwendungen durchzuführen, indem Protokolle wie HTTP und Tools wie `curl` verwendet werden, um optimale Designlösungen zu entwerfen und umzusetzen, einschließlich Screenshot-Analyse und Interaktionen mit dem Entwicklungsserver.","pt":"Habilita os agentes a realizar auditorias visuais abrangentes de aplicativos web, utilizando protocolos como HTTP e ferramentas como `curl`, para visualizar e implementar soluções de design ótimas, incluindo análise de capturas de tela e interações com servidor de desenvolvimento.","ru":"Наделяет агентов возможностью проводить всесторонние визуальные аудиты веб-приложений, используя протоколы, такие как HTTP, и инструменты, такие как `curl`, для того, чтобы представить и реализовать оптимальные решения по дизайну, включая анализ скриншотов и взаимодействие с сервером разработки.","ar":"يمنح الوكلاء القدرة على إجراء تدقيق شاملة لمواقع الويب، باستخدام بروتوكولات مثل بروتوكول نقل النص الفائق وادوات مثل `curl`، لرؤية وتنفيذ حلول التصميم الامتيازية، بما في ذلك تحليل لقطة الشاشة وتفاعل مع خادم التطوير."},"useCases":{"en":["Automating visual design audits for web applications","Generating screenshot comparisons for design iterations","Debugging visual inconsistencies across different browsers and devices"],"zh":["为网页应用自动化视觉设计审计","为设计迭代生成截图比较","在不同浏览器和设备上调试视觉不一致"],"ja":["ウェブアプリケーションの視覚的設計監査の自動化","設計の反復のためにスクリーンショット比較を生成する","異なるブラウザとデバイスで視覚的不一致をデバッグする"],"ko":["웹 애플리케이션의 시각적 디자인 감사를 자동화하는 것","디자인 반복에 대한 스크린샷 비교 생성","다른 브라우저 및 장치에서 시각적 불일치를 디버깅"],"es":["Automatizar auditorías de diseño visual para aplicaciones web","Generar comparaciones de capturas de pantalla para iteraciones de diseño","Depurar inconsistencias visuales en diferentes navegadores y dispositivos"],"fr":["Automatiser les audits de conception visuelle pour les applications web","Générer des comparaisons de captures d''écran pour les itérations de conception","Déboguer les incohérences visuelles sur différents navigateurs et appareils"],"de":["Automatisieren von visuellen Gestaltungsaudits für Webanwendungen","Generieren von Screenshot-Vergleichen für Designiterationen","Debuggen von visuellen Inkonsistenzen auf verschiedenen Browsern und Geräten"],"pt":["Automatizar auditorias de design visual para aplicativos web","Gerar comparações de capturas de tela para iterações de design","Depurar inconsistências visuais em diferentes navegadores e dispositivos"],"ru":["Автоматизировать визуальные аудиты дизайна для веб-приложений","Генерировать сравнения скриншотов для итераций дизайна","Отлаживать визуальные несоответствия в разных браузерах и устройствах"],"ar":["تأتمتة تدقيق التصميم المرئي لبرامج الويب","توليد مقارنات لقطة الشاشة لتحولات التصميم","تصحيح عدم التماثل المرئي عبر متصفحات واجهة مختلفة وأجهزة"]},"limitations":{"en":["Requires dev server access","Needs `pnpm` and `curl` installed","Limited to web application visual audits"],"zh":["需要开发服务器访问","需要安装`pnpm`和`curl`","仅限于网页应用视觉审计"],"ja":["開発サーバへのアクセスが必要","`pnpm`と`curl`をインストールする必要がある","ウェブアプリケーションの視覚的監査のみ"],"ko":["개발 서버 액세스가 필요함","`pnpm` 및 `curl`를 설치해야 함","웹 애플리케이션의 시각적 감사만 해당"],"es":["Requiere acceso al servidor de desarrollo","Necesita `pnpm` y `curl` instalados","Limitado a auditorías visuales de aplicaciones web"],"fr":["Nécessite un accès au serveur de développement","Nécessite `pnpm` et `curl` installés","Limité aux audits visuels d''applications web"],"de":["Benötigt Zugriff auf den Entwicklungsserver","Benötigt `pnpm` und `curl` installiert","Begrenzt auf visuelle Audits von Webanwendungen"],"pt":["Requer acesso ao servidor de desenvolvimento","Necessita `pnpm` e `curl` instalados","Limitado a auditorias visuais de aplicativos web"],"ru":["Требует доступа к серверу разработки","Требует установки `pnpm` и `curl`","Ограничен визуальными аудитами веб-приложений"],"ar":["يتطلب وصولاً إلى خادم التطوير","يحتاج إلى `pnpm` و `curl` من εγκαsbin","محدد بتدقيق مواقع الويب المرئي"]},"version":4},"contentHash":"b5a9d1bba559c73410b9e46b0fb5ea64573d62370aa2503390bd438a2b0c0f1b","qualityScore":42}');
