INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('australia/mobtranslate.com/visual-audit', 'visual-audit', 'australia', 'mobtranslate.com', 'community', 'visual-audit australia mobtranslate.com community The visual-audit skill enables senior design engineers to conduct a meticulous visual audit of web applications, envisioning and implementing optimal design solutions. It benefits developers seeking to enhance their application''s visual design Visual Audit技能帮助开发人员进行网页应用的视觉设计审计，确保设计的一致性和质量 Visual Auditスキルは、開発者がWebアプリケーションのビジュアルデザインを監査し、デザインのの一貫性と品質を確保するのに役立ちます Visual Audit 스킬은 개발자가 웹 애플리케이션의 시각적 디자인을 감사하여 디자인의 일관성과 품질을 보장하는 데 도움이 됩니다 Visual-audit es una herramienta para auditar el diseño visual de aplicaciones web, utilizando tecnologías como pnpm y agent-browser Visual-audit est un outil pour auditer la conception visuelle des applications web, utilisant des technologies comme pnpm et agent-browser Visual-audit ist ein Tool zur Überprüfung der visuellen Gestaltung von Webanwendungen, das Technologien wie pnpm und agent-browser verwendet O visual-audit é uma ferramenta de auditoria visual que ajuda a melhorar a experiência do usuário ИИ Агент visual-audit - это инструмент визуального аудита, который помогает улучшить пользовательский опыт visual-audit هي أداة تدقيق بصرية تساعد على تحسين تجربة المستخدم how to use visual-audit visual-audit setup guide visual design audit tools visual-audit vs design audit software visual-audit install what is visual-audit visual-audit alternative visual-audit for web development visual design audit best practices 视觉审计 AIエージェント 网页应用设计 用户体验 开发服务器 代理浏览器 スクリーンショット curl命令行工具 Ensures dev server is running via pnpm dev or curl commands Launches agent-browser to inspect web application design Creates screenshot output directory for design audit purposes Utilizes HTTP protocol to verify server status Supports local development via localhost:3000 visual-audit is a comprehensive visual design audit skill that enables design engineers to meticulously review and improve web application design');
